import requests
from jsonschema import validate as validate_input
from jsonschema.exceptions import ValidationError

def update_user_profile(username, new_email, new_phone):
    user_schema = {
        'type': 'object',
        'properties': {
            'email': {'type': 'string', 'format': 'email'},
            'phone': {'type': 'string', 'pattern': r'^\d{3}-\d{3}-\d{4}$'}
        },
        'required': ['email', 'phone']
    }

    try:
        user_data = {'username': username, 'email': new_email, 'phone': new_phone}
        validate_input(user_data, user_schema)

        response = requests.put(f'https://api.example.com/users/{username}', json=user_data)
        response.raise_for_status()
        print(f'Updated {username}\'s profile successfully.')
    except ValidationError as e:
        print(f'Failed to update {username}\'s profile due to invalid input: {e}')
    except requests.exceptions.RequestException as e:
        if e.response.status_code == 429:
            print('API rate limit exceeded. Please try again later.')
        else:
            print(f'Failed to update {username}\'s profile due to a network error: {e}')
