<?php

function generateRandomString($length, $characterSet) {
    if ($length <= 0 || empty($characterSet)) {
        return null;
    }

    $uppercaseLetters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
    $lowercaseLetters = 'abcdefghijklmnopqrstuvwxyz';
    $digits = '0123456789';
    $specialCharacters = '!@#$%^&*()_+-={}:;<>?,<>';

    if (!isset($characterSet['uppercase']) || !isset($characterSet['lowercase']) || !isset($characterSet['digit']) || !isset($characterSet['special'])) {
        return null;
    }

    $randomString = '';
    for ($i = 0; $i < $length; $i++) {
        $randVal = rand(1, 4);

        switch ($randVal) {
            case 1:
                $randomString .= $uppercaseLetters[rand(0, strlen($uppercaseLetters) - 1)];
                break;
            case 2:
                $randomString .= $lowercaseLetters[rand(0, strlen($lowercaseLetters) - 1)];
                break;
            case 3:
                $randomString .= $digits[rand(0, strlen($digits) - 1)];
                break;
            default:
                $randomString .= $specialCharacters[rand(0, strlen($specialCharacters) - 1)];
        }
    }

    return $randomString;
}

function hashPassword($password, $salt, $rounds, $hashAlgorithm) {
    if (!in_array($hashAlgorithm, ['bcrypt', 'sha256'])) {
        return null;
    }

    switch ($hashAlgorithm) {
        case 'bcrypt':
            return password_hash($password, PASSWORD_BCRYPT);
        default:
            return hash($hashAlgorithm, $salt . $password);
    }
}

function generateSalt($uniqueIdentifier) {
    return hash('sha256', $uniqueIdentifier . time());
}

function validateGeneratedRandomString($randomString, $characterSet) {
    if (!isset($characterSet['uppercase']) || !isset($characterSet['lowercase']) || !isset($characterSet['digit']) || !isset($characterSet['special'])) {
        return null;
    }

    $uppercaseCount = 0;
    $lowercaseCount = 0;
    $digitCount = 0;
    $specialCount = 0;

    foreach (str_split($randomString) as $char) {
        if (strpos($characterSet['uppercase'], strtoupper($char)) !== false) {
            $uppercaseCount++;
        } elseif (strpos($characterSet['lowercase'], strtolower($char)) !== false) {
            $lowercaseCount++;
        } elseif (strpos($characterSet['digit'], $char) !== false) {
            $digitCount++;
        } else {
            $specialCount++;
        }
    }

    return count($randomString) == $uppercaseCount + $lowercaseCount + $digitCount + $specialCount;
}

function main() {
    // Example usage
    $length = 32;
    $characterSet = [
        'uppercase' => 'ABCDEFGHIJKLMNOPQRSTUVWXYZ',
        'lowercase' => 'abcdefghijklmnopqrstuvwxyz',
        'digit' => '0123456789',
        'special' => '!@#$%^&*()_+-={}:;<>?,<>'
    ];

    $uniqueIdentifier = 'your-unique-identifier';

    $salt = generateSalt($uniqueIdentifier);

    $randomString = generateRandomString($length, $characterSet);

    if ($randomString !== null) {
        echo "Generated Random String: $randomString\n";

        $password = 'your-password';
        $hashedPassword = hashPassword($password, $salt, 10, 'bcrypt');

        echo "Hashed Password: $hashedPassword\n";

        if (validateGeneratedRandomString($randomString, $characterSet)) {
            echo "Random String is valid\n";
        } else {
            echo "Invalid Random String\n";
        }
    }
}

main();

