#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* validateFilePath(char* filePath, int maxSize, bool isAbsolute, char* errMsg) {
    size_t len = strlen(filePath);

    if (len >= maxSize) {
        sprintf(errMsg, "Path '%s' exceeds maximum buffer size of %d.", filePath, maxSize);
        free(filePath);
        return NULL;
    }

    if (!isAbsolute && filePath[0] != '/') {
        char* cwd = getenv("PWD");
        char* fullpath = (char*) malloc((len + strlen(cwd) + 2)*sizeof(char));
        strcpy(fullpath, cwd);
        strcat(fullpath, "/");
        strcat(fullpath, filePath);

        free(filePath);
        filePath = fullpath;
    }

    return filePath;
}
