        int bucketSize;
        int maxEntriesPerBucket;
        std::vector<std::pair<float, int>> entries;  // <x, index>
    };

    std::vector<GridCell*> cells;
};

void SpatialHashGrid::init(int width, int height, int depth, int bucketSize,
                             int maxEntriesPerBucket, std::vector<float>* data) {
    // Calculate the total number of grid cells
    int gridSize = width * height * depth;

    // Allocate memory for the grid cells
    cells.resize(gridSize);

    // Initialize each grid cell with its dimensions and maximum entries per bucket
    for (int i = 0; i < gridSize; ++i) {
        GridCell* cell = &cells[i];
        cell->bucketSize = bucketSize;
        cell->maxEntriesPerBucket = maxEntriesPerBucket;
        cell->entries.clear();
    }
}

void SpatialHashGrid::insert(float x, float y, float z) {
    // Calculate the grid coordinates for the point
    int widthIndex = x / bucketSize;
    int heightIndex = y / bucketSize;
    int depthIndex = z / bucketSize;

    // Find the corresponding grid cell and insert the point
    GridCell* cell = &cells[widthIndex * height * depth + heightIndex * depth + depthIndex];
