using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Builder;
using System.Threading.Tasks;
using System.Text.Json;
using System.Net.Http;
using System.Net.Http.Headers;

public class UpdateElementMiddleware
{
    private readonly RequestDelegate _next;
    private readonly HttpClient _httpClient;
    private readonly string _cmsApiEndpoint;
    private readonly string _cmsApiKey;

    public UpdateElementMiddleware(RequestDelegate next, 
                                    HttpClient httpClient, 
                                    string cmsApiEndpoint, 
                                    string cmsApiKey)
    {
        _next = next;
        _httpClient = httpClient;
        _cmsApiEndpoint = cmsApiEndpoint;
        _cmsApiKey = cmsApiKey;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        if (!context.Request.Method == HttpMethods.Post)
            return;

        var requestBody = await new StreamReader(context.Request.Body).ReadToEnd();
        var requestJson = JsonSerializer.Deserialize<UpdateElementRequest>(requestBody);

        try
        {
            // Fetch updated HTML content from CMS
            HttpResponseMessage response = _httpClient.GetAsync($"{_cmsApiEndpoint}/elements/{requestJson.PageSectionId}/{requestJson.ElementId}?key={_cmsApiKey}").Result;
            response.EnsureSuccessStatusCode();

            var htmlContent = await response.Content.ReadAsStringAsync();
            // Apply updated HTML content to the webpage

            context.Response.StatusCode = 200;
            await context.Response.WriteAsync(htmlContent);
        }
        catch (HttpRequestException ex)
        {
            // Handle network errors
            context.Response.StatusCode = 500;
            await context.Response.WriteAsync("Error updating element: " + ex.Message);
        }
        catch (JsonException ex)
        {
            // Handle invalid JSON input
            context.Response.StatusCode = 400;
            await context.Response.WriteAsync("Invalid request format: " + ex.Message);
        }
    }
}

public class UpdateElementRequest
{
    public string PageSectionId { get; set; }
    public string ElementId { get; set; }
    public string HtmlContent { get; set; }
}
