    private Function<ByteBuffer, ?> getDeserializer(Class<?> clazz) {
        Function<ByteBuffer, ?> deserializer = cache.get(clazz);
        if (deserializer == null) {
            synchronized (lock) {
                deserializer = cache.computeIfAbsent(clazz, c -> createDeserializer(c));
            }
        }
        return deserializer;
    }

    private Function<ByteBuffer, ?> createDeserializer(Class<?> clazz) throws ClassNotFoundException {
        ClassProvider.ClassDefinition definition = classProvider.getClassDefinition(clazz.getName());
