```
import hashlib
import os
import requests

def calculate_sha256_hash(file_path, expected_checksum=None):
    hash_object = hashlib.sha256()

    try:
        with open(file_path, 'rb') as f:
            while chunk := f.read(4096):
                hash_object.update(chunk)

        actual_checksum = hash_object.hexdigest()

        if expected_checksum is not None and actual_checksum != expected_checksum:
            return "Checksum mismatch: expected {} but got {}".format(expected_checksum, actual_checksum)

    except Exception as e:
        return str(e)

    return "SHA-256 hash calculated successfully: {}".format(actual_checksum)

def get_file_content(file_path):
    if os.path.exists(file_path):
        with open(file_path, 'rb') as f:
            return f.read()

    if file_path.startswith('http'):
        response = requests.get(file_path)
        return response.content

    return None

def calculate_sha256_hash_from_url(url, expected_checksum=None):
    file_content = get_file_content(url)

    if file_content is None:
        return "Failed to access the file"

    hash_object = hashlib.sha256()
    hash_object.update(file_content)
    actual_checksum = hash_object.hexdigest()

    if expected_checksum is not None and actual_checksum != expected_checksum:
        return "Checksum mismatch: expected {} but got {}".format(expected_checksum, actual_checksum)

    return "SHA-256 hash calculated successfully from URL: {}".format(actual_checksum)
