#include <stdio.h>
#include <string.h>
#include <json-c/json.h>

#define JSON_ERROR_MAX 1024
#define MAX_TOKEN_LENGTH 256
#define TOKEN_TYPE "Bearer"

void validate_oauth_token(char* json_string) {
    json_object *jobj = json_object_from_json_string(json_string);

    if (!jobj || json_object_get_type(jobj) != json_type_object) {
        printf("Invalid JSON format\n");
        return;
    }

    char *token_type = json_object_get_string_value(jobj, "token_type");
    if (!token_type || strcmp(token_type, TOKEN_TYPE) != 0) {
        printf("Token type mismatch: Expected %s, got %s\n", TOKEN_TYPE, token_type);
        return;
    }

    int expires_in = json_object_get_int_value(jobj, "expires_in");
    if (expires_in < 1) {
        printf("Invalid expiration time\n");
        return;
    }

    char *access_token = json_object_get_string_value(jobj, "access_token");
    if (!access_token || strlen(access_token) > MAX_TOKEN_LENGTH) {
        printf("Invalid access token length\n");
        return;
    }

    char *refresh_token = json_object_get_string_value(jobj, "refresh_token");
    if (refresh_token && strlen(refresh_token) > MAX_TOKEN_LENGTH) {
        printf("Invalid refresh token length\n");
        return;
    }

    char *scope = json_object_get_string_value(jobj, "scope");
    if (scope && strlen(scope) > MAX_TOKEN_LENGTH) {
        printf("Invalid scope string length\n");
        return;
    }
}
