#include <nlohmann/json.hpp>
#include <unordered_map>
#include <variant>

std::unordered_map<std::string, std::variant<int, double, std::string, bool>>
readConfig(const std::string& filePath) {
    std::unordered_map<std::string, std::variant<int, double, std::string, bool>> config;
    try {
        nlohmann::json jsonData = nlohmann::json::parseFile(filePath);
        for (const auto& [key, value] : jsonData.items()) {
            if (value.is_integer())
                config[key] = value.get<int>();
            else if (value.is_number())
                config[key] = value.get<double>();
            else if (value.is_string())
                config[key] = value.get<std::string>();
            else if (value.is_bool())
                config[key] = value.get<bool>();
        }
    } catch (const nlohmann::json::parse_error& e) {
        throw std::runtime_error("Error parsing JSON file: " + filePath);
    } catch (const std::exception& e) {
        throw std::runtime_error("Unexpected error occurred while reading config: " + filePath);
    }
    return config;
}
