namespace RandomGenerator {
    class MT19937Generator {
    private:
        std::mt19937 engine_;
        int min_, max_;
        std::mutex mtx_;

    public:
        MT19937Generator(int seed) : engine_(seed) {}

        ~MT19937Generator() = default;

        void setRange(int min, int max) {
            if (min > max) {
                throw std::invalid_argument("Invalid range");
            }
            min_ = min;
            max_ = max;
        }

        int generateRandomNumber() {
            std::lock_guard<std::mutex> lock(mtx_);
            return min_ + engine_.next<int>() % (max_ - min_ + 1);
        }
    };

