using UnityEngine;
using System;

public class ValueGenerator
{
    private float minRange;
    private float maxRange;

    public ValueGenerator(float min, float max)
    {
        if (min > max)
            throw new ArgumentException("Minimum value must be less than or equal to maximum value");

        this.minRange = min;
        this.maxRange = max;
    }

    public float GenerateFloat()
    {
        return UnityEngine.Random.Range(minRange, maxRange + 1);
    }

    public int GenerateInt()
    {
        return (int)GenerateFloat();
    }

    public void SetDistribution(string distributionName)
    {
        // Implement logic to set different distributions based on the provided name
        // For demonstration purposes, let's assume we have a Gaussian and Uniform distribution
        if (distributionName == "Gaussian")
        {
            // Initialize Gaussian distribution parameters
            float mean = 0;
            float stdDeviation = 1;

            // Update min and max range based on the Gaussian distribution
            this.minRange = mean - 3 * stdDeviation;
            this.maxRange = mean + 3 * stdDeviation;
        }
        else if (distributionName == "Uniform")
        {
            // Initialize Uniform distribution parameters
            float start = 0;
            float stop = 1;

            // Update min and max range based on the Uniform distribution
            this.minRange = start;
            this.maxRange = stop;
        }
        else
        {
            throw new ArgumentException("Invalid distribution name");
        }
    }

    public override string ToString()
    {
        return $"Value Generator: Range ({minRange}, {maxRange})";
    }
}
