    @Autowired
    private PokemonApiClient pokemonApiClient;

    @GetMapping("/pokemon/{pokemonId}/weaknesses")
    public ResponseEntity<PokemonWeaknessResponse> getPokemonWeaknesses(@PathVariable String pokemonId) {
        Pokemon poke = pokemonApiClient.getPokemon(pokemonId);
        List<String> weaknesses = new ArrayList<>();
        for (Type type : poke.getTypes()) {
            weaknesses.addAll(type.getWeaknesses());
        }

        WeatherData weatherData = pokemonApiClient.getWeatherData();
        TerrainData terrainData = pokemonApiClient.getTerrainData();

        PokemonWeaknessResponse response = new PokemonWeaknessResponse(
                poke.getName(),
                poke.getType().getName(),
                weaknesses,
                weatherData.getEffects(),
                terrainData.getEffects()
        );

        return ResponseEntity.status(HttpStatus.OK).body(response);
    }
}

class PokemonWeaknessResponse {
    private String name;
    private String type;
    private List<String> weaknesses;
    private List<WeatherEffect> weatherEffects;
    private List<TerrainEffect> terrainEffects;

