function updateClinicStatus($clinic_id, $new_status, $last_modified_ip) {
    require_once 'db.php';

    $db = new Database();

    // Get the current time
    $now = date('Y-m-d H:i:s');

    // Check if the IP address is within the allowed rate limit
    $rate_limiter = new RateLimiter();
    if (!$rate_limiter->canUpdate($last_modified_ip)) {
        return 'Rate limit exceeded. Please try again after a minute.';
    }

    // Prepare the update statement
    $stmt = $db->prepare('UPDATE clinics SET status = ?, last_modified_ip = ?, last_modified_date = ? WHERE id = ?');

    // Execute the update
    if ($stmt->execute(array($new_status, $last_modified_ip, $now, $clinic_id))) {
        return 'Clinic status updated successfully.';
    } else {
        // Log any errors that occur during the update process
        error_log('Error updating clinic status: ' . $stmt->error());
        return 'Failed to update clinic status. Please try again later.';
    }
}
