import java.util.*;

public class DisjointPairFinder {
    private UnionFind unionFind;

    public DisjointPairFinder(int[] arr) {
        this.unionFind = new UnionFind(arr.length);
        for (int i : arr) {
            unionFind.makeSet(i);
        }
    }

    public boolean areDisjoint(int i, int j) {
        long startTime = System.nanoTime();
        boolean result = !unionFind.find(i) == unionFind.find(j);
        long endTime = System.nanoTime();
        long timeTaken = (endTime - startTime);
        System.out.println("Time taken to find disjoint: " + timeTaken + " nanoseconds");
        return result;
    }

