#include <iostream>
#include <fstream>
#include <ctime>
#include <cstdlib>

class Character {
public:
    // Add properties and methods as needed
};

void characterAttack(Character& character) {
    std::string attacks[] = {"Slash", "Fireball", "Poison Dart"};
    int cooldowns[] = {6, 12, 3};
    int currentCooldowns[3] = {0, 0, 0}; // initialize to 0 for each attack

    srand(time(0)); // seed the random number generator
    std::string previousAttack;

    while (true) {
        std::string currentAttack;
        if (currentCooldowns[0] > 0 || previousAttack == "Slash") {
            currentAttack = (previousAttack != "Slash" ? (previousAttack == "Fireball" ? "Poison Dart" : "Slash") : attacks[rand() % 3]);
            currentCooldowns[0] = --currentCooldowns[0];
        } else if (currentCooldowns[1] > 0 || previousAttack == "Fireball") {
            currentAttack = (previousAttack != "Fireball" ? (previousAttack == "Slash" ? "Poison Dart" : "Fireball") : attacks[rand() % 3]);
            currentCooldowns[1] = --currentCooldowns[1];
        } else if (currentCooldowns[2] > 0 || previousAttack == "Poison Dart") {
            currentAttack = (previousAttack != "Poison Dart" ? (previousAttack == "Slash" ? "Fireball" : "Poison Dart") : attacks[rand() % 3]);
            currentCooldowns[2] = --currentCooldowns[2];
        } else {
            currentAttack = attacks[rand() % 3];
            if (currentAttack == previousAttack) {
                for (int i = 0; i < 3; ++i) {
                    if (cooldowns[i] <= currentCooldowns[i]) {
                        currentAttack = attacks[i];
                        break;
                    }
                }
            }
        }

        // write to log file
        std::ofstream logFile("attack_log.txt");
        try {
            logFile << "Character used: " << currentAttack << "\n";
        } catch (const std::exception& e) {
            std::cerr << "Error writing to log file: " << e.what() << '\n';
        }

        previousAttack = currentAttack;

        // wait for cooldown
        if (currentAttack != previousAttack) {
            int cooldownIndex = 0;
            switch (currentAttack[0]) {
                case 'S':
                    cooldownIndex = 0;
                    break;
                case 'F':
                    cooldownIndex = 1;
                    break;
                default:
                    cooldownIndex = 2;
                    break;
            }
            while (currentCooldowns[cooldownIndex] > 0) {
                // wait
                std::this_thread::sleep_for(std::chrono::seconds(cooldowns[cooldownIndex]));
                --currentCooldowns[cooldownIndex];
            }
        }
    }
}
