app.use(express.json());

const weatherAPI = 'https://api.openweathermap.org/data/2.5/weather';
const forecastAPI = 'https://api.openweathermap.org/data/2.5/forecast';
const climateAPI = 'https://climate-api.example.com/v1/climate';

app.get('/weather/:location', async (req, res) => {
  const location = req.params.location;
  try {
    // Get current weather data from OpenWeatherMap
    const currentWeather = await axios.get(`${weatherAPI}?q=${location}&units=imperial`);

    // Get forecasted weather for the next 7 days from OpenWeatherMap
    const forecast = await axios.get(`${forecastAPI}?q=${location}&units=imperial&cnt=7`);

    // Get average temperature statistics for each month over the past year from Climate API
    const monthlyStatistics = await axios.get(`${climateAPI}/stats?location=${location}&year=2022`);

    // Get historical climate events (e.g., heatwaves, cold spells) from Climate API
    const historicalEvents = await axios.get(`${climateAPI}/events?location=${location}`);

    res.json({
      current_weather: {
        temperature: currentWeather.data.main.temp,
        humidity: currentWeather.data.main.humidity,
        precipitation: currentWeather.data.clouds.all
      },
      forecast: forecast.data.list.map((day) => ({
        date: day.dt_txt,
        high_temp: day.main.temp_max,
        low_temp: day.main.temp_min,
        chance_precipitation: day.pop * 100,
        weather_condition: day.weather[0].description
      })),
      monthly_statistics: monthlyStatistics.data.map((month) => ({
        month: month.month,
        average_temperature: month.average_temperature
      })),
      historical_events: historicalEvents.data.map((event) => ({
        date: event.date,
        type: event.type,
        description: event.description
      }))
    });
  } catch (error) {
    res.status(500).send({ message: 'Error retrieving weather and climate data' });
  }
});

app.listen(3000, () => {
  console.log('Weather service listening on port 3000');
});
