#include <stdio.h>
#include <stdlib.h>

// Function to read integers from file and store them in an array
int* readIntegersFromFile(const char* filename, int* size) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        printf("Error opening file.\n");
        return NULL;
    }

    *size = 0;
    int max_size = 10; // Initial array size
    int* arr = (int*)malloc(max_size * sizeof(int));
    int i = 0;

    while (fscanf(file, "%d", &arr[i]) == 1) {
        if (i >= max_size) {
            max_size *= 2;
            int* temp = (int*)realloc(arr, max_size * sizeof(int));
            arr = temp;
        }
        i++;
    }

    fclose(file);

    // Add null terminator to array
    arr[i] = -1;

    return arr;
}

// Function to sort an array in ascending order
void sortArray(int* arr, int size) {
    for (int i = 0; i < size; i++) {
        for (int j = i + 1; j < size; j++) {
            if (arr[i] > arr[j]) {
                // Swap elements
                int temp = arr[i];
                arr[i] = arr[j];
                arr[j] = temp;
            }
        }
    }
}

// Function to find the largest integer in an array
int findLargest(int* arr, int size) {
    if (size == 0) {
        printf("Array is empty.\n");
        return -1; // Return invalid value
    }

    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }

    return max;
}

// Main function
int main() {
    const char* filename = "input.txt"; // Replace with your file name
    int size;

    int* arr = readIntegersFromFile(filename, &size);

    if (!arr) {
        return 1; // Return non-zero exit status on error
    }

    sortArray(arr, size);
    printf("Largest integer in the array is: %d\n", findLargest(arr, size));

    free(arr); // Free dynamically allocated memory

    return 0;
}
