const { Transform, stream } = require('stream');
const { AES } = require('pycryptodome.cipher');
const crypto = require('crypto');

function collectAndEncrypt(stream, commandLineOption) {
  let encryptedData = [];
  let iv;

  const encryptStream = new Transform({
    transform(chunk, encoding, callback) {
      if (commandLineOption.encrypt) {
        chunk = aesEncrypt(chunk);
      }
      encryptedData.push(chunk.toString());
      callback(null, chunk);
    },
    flush(callback) {
      if (commandLineOption.encrypt) {
        iv = crypto.randomBytes(16).toString('hex');
      }
      callback();
    },
  });

  stream.pipe(encryptStream);

  const pauseResumeStream = new Transform({
    transform(chunk, encoding, callback) {
      this.push(chunk);
      callback();
    },
    pipe(input) {
      input.on('pause', () => {
        this.emit('pause');
      });
      input.on('resume', () => {
        this.emit('resume');
      });
    },
  });

  stream.pipe(pauseResumeStream);

  return [encryptedData, iv];
}

function aesEncrypt(chunk) {
  const key = crypto.randomBytes(32).toString('hex');
  const cipher = new AES(new Uint8Array(Buffer.from(key, 'hex')), 'AES-256-CBC');
  const encryptedChunk = Buffer.concat([cipher.update(chunk), cipher.final()]);
  return encryptedChunk;
}

module.exports = collectAndEncrypt;
