import json
import requests
from urllib.parse import urlparse

class Configuration:
    def __init__(self):
        self.settings = {}

    def get(self, key):
        return self.settings.get(key)

    def set(self, key, value):
        self.settings[key] = value


def load_configuration_file(filename: str) -> Configuration:
    config = Configuration()
    try:
        with open(filename, 'r') as file:
            data = json.load(file)
            for key, value in data.items():
                if isinstance(value, dict):
                    config.set(key, load_configuration_file(json.dumps(value)))
                else:
                    config.set(key, value)
    except FileNotFoundError as e:
        print(f"Error: {e}")
    except json.JSONDecodeError as e:
        print(f"Error parsing JSON file: {e}")
    return config


def update_configuration_from_api(config: Configuration) -> None:
    try:
        response = requests.get('https://example.com/api/config')
        if response.status_code == 200:
            data = response.json()
            for key, value in data.items():
                if isinstance(value, dict):
                    config.set(key, load_configuration_file(json.dumps(value)))
                else:
                    config.set(key, value)
        else:
            print(f"Failed to fetch updated configuration: {response.status_code}")
    except requests.exceptions.RequestException as e:
        print(f"Error updating configuration from API: {e}")


def main():
    filename = 'config.json'
    config = load_configuration_file(filename)
    update_configuration_from_api(config)

if __name__ == "__main__":
    main()
