import java.io.IOException;
import java.util.Properties;

import org.apache.kafka.clients.producer.KafkaProducer;
import org.apache.kafka.clients.producer.ProducerConfig;
import org.apache.kafka.clients.producer.ProducerRecord;
import org.apache.kafka.common.serialization.StringSerializer;
import org.apache.kafka.common.utils.Bytes;
import org.json.JSONObject;
import org.json.JSONString;

public class SensorDataProcessor {

    private static final String KAFKA_BOOTSTRAP_SERVERS = "localhost:9092";
    private static final String CASSANDRA_HOST = "localhost";

    public void processSensorDataStream(String data) throws IOException {
        JSONObject json = new JSONObject(data);

        // Validate JSON format against specified schema
        if (!json.getString("device").matches("^[a-zA-Z0-9]{3}$")) {
            System.out.println("Invalid device ID");
            return;
        }

        // Create a Kafka producer to send data to Apache Kafka
        Properties props = new Properties();
        props.put(ProducerConfig.BOOTSTRAP_SERVERS, KAFKA_BOOTSTRAP_SERVERS);
        props.put(ProducerConfig.KEY_SERIALIZER_CLASS_CONFIG, StringSerializer.class.getName());
        props.put(ProducerConfig.VALUE_SERIALIZER_CLASS_CONFIG, StringSerializer.class.getName());
        KafkaProducer<String, String> producer = new KafkaProducer<>(props);

        // Send the validated data to Apache Kafka
        try {
            producer.send(new ProducerRecord<>("iot_data", json.toString()));
        } catch (Exception e) {
            System.out.println("Error sending data to Apache Kafka: " + e.getMessage());
        }

        // Close the Kafka producer
        producer.close();
    }
}
