import java.util.*;

public class DynamicNestedDeserializer {
    private static final int MAX_CACHE_ENTRIES = 1000;
    private static final int LRU_CACHE_SIZE = 100;

    private Map<String, Constructor<?>> classCache = new HashMap<>();
    private Map<String, List<Constructor<?>>> nestedClassCache = new HashMap<>();

    public void deserialize(byte[] data) throws DeserializationException {
        if (data == null || data.length == 0) {
            throw new DeserializationException("Invalid byte array");
        }

        try (ByteArrayInputStream byteArrayStream = new ByteArrayInputStream(data);
             ObjectInputStream objectStream = new ObjectInputStream(byteArrayStream)) {

            Object rootObject = objectStream.readObject();

            validateRootObject(rootObject);

            processNestedObjects(rootObject, objectStream);

        } catch (ClassNotFoundException | IOException e) {
            throw new DeserializationException("Error deserializing byte array", e);
        }
    }

    private void validateRootObject(Object object) throws DeserializationException {
        if (!isInstantiable(object)) {
            throw new DeserializationException("Invalid root object");
        }
    }

    private boolean isInstantiable(Object object) {
        // Implement your custom logic to check if the object can be instantiated
        return true;
    }

    private void processNestedObjects(Object parent, ObjectInputStream objectStream) throws DeserializationException {
        try {
            Class<?> parentClass = parent.getClass();
            List<Constructor<?>> nestedConstructors = getNestedConstructors(parentClass.getName());

            for (Object child : objectStream.readObject()) {
                Constructor<?> constructor = nestedConstructors.get(0);
                constructor.newInstance(child);

                processNestedObjects(child, objectStream);
            }
        } catch (InstantiationException | IllegalAccessException e) {
            throw new DeserializationException("Error processing nested objects", e);
        }
    }

    private List<Constructor<?>> getNestedConstructors(String parentClassName) throws ClassNotFoundException {
        return nestedClassCache.computeIfAbsent(parentClassName, this::loadNestedConstructors);
    }

    private List<Constructor<?>> loadNestedConstructors(String parentClassName) throws ClassNotFoundException {
        // Implement your custom logic to retrieve the nested class constructors
        return new ArrayList<>();
    }
