const { EventEmitter } = require('events');
const { Logger } = require('./logger');

class AsyncReducer {
  constructor(logger) {
    this.logger = logger;
    this.eventEmitter = new EventEmitter();
  }

  async reduce(arr, initialValues, reducerCallback) {
    const resultPromises = initialValues.map((initialValue) => {
      return Promise.all(
        arr.map((num, index) => {
          let promise;
          try {
            promise = new Promise((resolve) => {
              setTimeout(() => {
                resolve(reducerCallback(num, initialValue));
              }, 10);
            });
          } catch (error) {
            this.logger.error(`Error during reduction: ${error}`);
            promise = new Promise((resolve, reject) => {
              setTimeout(() => {
                resolve(initialValue);
              }, 10);
            });
          }
          return promise;
        })
      )
    .then((results) => {
      return results.reduce((acc, cur) => acc + cur, 0);
    }));

    const result = await Promise.all(resultPromises);

    this.logger.info('Reduction completed');
    return result;
  }

  cancel() {
    this.eventEmitter.emit('cancel');
  }
}

const logger = new Logger();
const asyncReducer = new AsyncReducer(logger);

async function testReduce() {
  try {
    const arr = [1, 2, 3];
    const initialValues = [0, 10];
    const result = await asyncReducer.reduce(arr, initialValues, (num, initialValue) => num + initialValue);
    console.log(result); // Output: 18
  } catch (error) {
    console.error(error);
  }
}

testReduce();

// Example usage for cancellation:
const cancelTokenSource = new AbortController();
const token = cancelTokenSource.signal;

async function testCancel() {
  try {
    const arr = [1, 2, 3];
    const initialValues = [0, 10];
    const asyncReducer = new AsyncReducer(logger);
    await asyncReducer.reduce(arr, initialValues, (num, initialValue) => num + initialValue, token);
  } catch (error) {
    if (error.name === 'AbortError') {
      console.log('Reduction canceled');
    }
  }
}

testCancel();
