    private static final List<Thread> threads = new ArrayList<>();

    public static void generateReport(JSONObject request) {
        // Get report template and data sources from request
        String templateName = request.getString("template");
        List<String> databaseNames = request.getJSONArray("databases").toList();

        // Create PDF document
        Document pdfDoc = new Document();
        try (PdfWriter writer = PdfWriter.getInstance(pdfDoc, System.out)) {
            // Initialize connections for each database
            for (String dbName : databaseNames) {
                Connection conn;
                if (!connections.containsKey(dbName)) {
                    switch (dbName) {
                        case "mysql":
                            conn = DriverManager.getConnection("jdbc:mysql://localhost:3306/" + dbName, "user", "password");
                            break;
                        case "postgres":
                            conn = DriverManager.getConnection("jdbc:postgresql://localhost:5432/" + dbName, "user", "password");
                            break;
                        case "mongodb":
                            // Initialize MongoDB connection
                            break;
                        default:
                            throw new Exception("Unsupported database type: " + dbName);
                    }
                    connections.put(dbName, conn);
                }
            }

            // Perform data aggregation and transformation
            // ...

            // Format results into PDF report using the template
            pdfDoc.open();
            for (String field : request.getJSONArray("fields").toList()) {
                Paragraph paragraph = new Paragraph(field + ": " + /* perform some computation */);
                pdfDoc.add(paragraph);
            }
        } catch (DocumentException | Exception e) {
            // Handle exceptions gracefully
            System.out.println("Error generating report: " + e.getMessage());
        } finally {
            // Close connections and threads
            for (Connection conn : connections.values()) {
                try {
                    conn.close();
                } catch (Exception e) {
                    // Handle connection close errors
                }
            }
            for (Thread thread : threads) {
                try {
                    thread.join();
                } catch (InterruptedException e) {
                    // Handle thread join errors
                }
            }
        }
    }

    public static void main(String[] args) {
        // Start a new thread to handle each request concurrently
        Thread thread = new Thread(() -> generateReport(new JSONObject()));
        thread.start();
        threads.add(thread);

        // Update report templates and data sources dynamically
