    public static async Task<string> AddAndStartWebsite(string directoryPath, string siteName)
    {
        if (!Directory.Exists(directoryPath))
        {
            return "Error: Directory not found";
        }

        if (!File.Exists(Path.Combine(directoryPath, "web.config")))
        {
            return "Error: Web.config file is missing";
        }

        try
        {
            using var client = new HttpClient();
            string url = "https://api.example.com/websites";
            HttpResponseMessage response = await client.PostAsync(url, new StringContent($"{{\"name\":\"{siteName}\", \"directory\":\"{directoryPath}\"}}", Encoding.UTF8, "application/json"));
            if (!response.IsSuccessStatusCode)
            {
                return $"Error: {response.StatusCode} - {response.ReasonPhrase}";
            }
        }
        catch (HttpRequestException ex)
        {
            return $"Error: {ex.Message}";
        }

        try
        {
            using var client = new HttpClient();
            string url = "https://api.example.com/websites/start";
            HttpResponseMessage response = await client.PostAsync(url, new StringContent($"{{\"name\":\"{siteName}\"}}", Encoding.UTF8, "application/json"));
