using System;
using System.IO;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class FileHasher
{
    public async Task<string> ComputeMd5Hash(string filePath)
    {
        using (var md5 = MD5.Create())
        {
            using (var fileStream = new FileStream(filePath, FileMode.Open))
            {
                byte[] buffer = new byte[1024 * 16];
                int read;
                MD5CryptoServiceProvider hashProvider = new MD5CryptoServiceProvider();

                try
                {
                    while ((read = fileStream.Read(buffer, 0, buffer.Length)) > 0)
                    {
                        using (var hashStream = new MemoryStream())
                        {
                            hashStream.Write(buffer, 0, read);
                            var hashValue = hashProvider.ComputeHash(hashStream.ToArray());
                            md5.TransformBlock(hashValue, 0, hashValue.Length, hashValue);
                        }
                    }

                    var finalHash = md5.ComputeFinalHash();
                    return BitConverter.ToString(finalHash).Replace("-", "").ToLowerInvariant();
                }
                catch (Exception ex)
                {
                    Console.WriteLine("Error encountered during file processing: " + ex.Message);
                    return null;
                }
            }
        }
    }
}
