const fs = require('fs');
const axios = require('axios');

function readFileSyncAndFetchMetadata(filePath) {
  if (typeof filePath !== 'string') {
    throw new Error('Invalid file path: expected a string value');
  }

  const validExtensions = ['.txt', '.md', '.json'];
  const extension = filePath.substring(filePath.lastIndexOf('.') + 1).toLowerCase();

  if (!validExtensions.includes(extension)) {
    throw new Error(`Unsupported file type: ${extension}`);
  }

  try {
    const fileMetadata = await axios.get(`https://file-management-service.com/api/files/${filePath}`);
    const fileSize = fileMetadata.data.size;
    const creationDate = fileMetadata.data.creationTime;

    return fs.readFileSync(filePath, 'utf8')
      .then((content) => ({ content, fileSize, creationDate }));
  } catch (error) {
    if (error.code === 'ENOENT') {
      throw new Error(`File not found: ${filePath}`);
    }
    if (error.code === 'EACCES') {
      throw new Error(`Permission denied for file: ${filePath}`);
    }
    throw new Error('Failed to read or fetch metadata');
  } finally {
    fs.closeSync(fd);
  }
}

module.exports = readFileSyncAndFetchMetadata;
