            // Update preferences list based on the deserialized data.

            string firstString = "";
            int firstIndex = -1;

            foreach ((int i, string s) in EnumerateStringList(preferencesList))
            {
                if (s == firstString)
                {
                    firstIndex = i;
                    break;
