            }

            if (firstIndex != -1)
            {
                preferencesList.Insert(firstIndex + 1, secondString);
            }
            else
                preferencesList.Add(secondString);

            // Update the database with the deserialized data.
        }
    }
    catch (Exception ex)
    {
        _logger.LogError(ex, "Error while loading and deserializing binary file.");
    }
}

private IEnumerable<(int i, string s)> EnumerateStringList(List<string> list)
{
    for (int i = 0; i < list.Count; i++)
