struct TrafficStats {
    uint32_t incoming;
    uint32_t outgoing;
};

struct UserSession {
    int userId;
    char sessionId[16];
    struct TrafficStats stats;
};

void populateUserSessions(int N, int MAX_SESSIONS, struct UserSession **sessions) {
    int i;
    for (i = 0; i < N && *sessions != NULL; i++) {
        if (*sessions == NULL || (*sessions)->userId != -1) {
            break;
        }
    }
    if (i >= MAX_SESSIONS) {
        printf("Exceeded maximum sessions\n");
        return;
    }

    for (; i < N; i++) {
        struct UserSession* session = malloc(sizeof(struct UserSession));
        if (session == NULL) {
            printf("Memory allocation failed\n");
            return;
        }
        time_t now = time(NULL);
        int userId = rand() % 1000;
        char sessionId[16];
        sprintf(sessionId, "sess-%04d", userId);
        session->userId = userId;
        strcpy(session->sessionId, sessionId);
        session->stats.incoming = (uint32_t)rand();
        session->stats.outgoing = (uint32_t)rand();

        if (*sessions != NULL) {
            *sessions = realloc(*sessions, (i + 1) * sizeof(struct UserSession));
            if (*sessions == NULL) {
                printf("Memory reallocation failed\n");
                for (int j = i; j > 0; j--) {
                    free((*sessions)[j - 1]);
                }
                return;
            }
        } else {
            *sessions = malloc(i + 1 * sizeof(struct UserSession));
            if (*sessions == NULL) {
                printf("Memory allocation failed\n");
                return;
            }
        }

        (*sessions)[i] = session;
    }
}

