import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.SQLException;

public class DisjointPairCounter {
    private static Map<String, Long> disjointPairs = new HashMap<>();
    private static final String DB_URL = "jdbc:mysql://localhost:3306/disjoint_pairs";
    private static final String USER = "root";
    private static final String PASS = "password";

    public static long countDisjointPairs(int[] arr, boolean removeDuplicates) {
        long start = System.currentTimeMillis();

        if (removeDuplicates) {
            arr = removeDuplicates(arr);
        }

        UnionFind uf = new UnionFind(arr.length);
        for (int i : arr) {
            uf.makeSet(i);
        }

        int pairCount = 0;
        for (int i = 0; i < arr.length; i++) {
            for (int j = i + 1; j < arr.length; j++) {
                if (!uf.isConnected(arr[i], arr[j])) {
                    uf.union(arr[i], arr[j]);
                    pairCount++;
                }
                System.out.println("Time taken: " + (System.currentTimeMillis() - start) + " ms");
            }
        }

        long end = System.currentTimeMillis();
        System.out.println("Total time taken: " + (end - start) + " ms");

        try (Connection conn = DriverManager.getConnection(DB_URL, USER, PASS);
             PreparedStatement ps = conn.prepareStatement("INSERT INTO disjoint_pairs VALUES (?, ?)")) {
            for (Map.Entry<String, Long> entry : disjointPairs.entrySet()) {
                ps.setString(1, entry.getKey());
                ps.setLong(2, entry.getValue());
                ps.executeUpdate();
            }
        } catch (SQLException e) {
            System.err.println("Error while storing results: " + e.getMessage());
        }

        return pairCount;
    }

    private static int[] removeDuplicates(int[] arr) {
        Arrays.sort(arr);
        int uniqueLength = 1;
        for (int i = 1; i < arr.length; i++) {
            if (arr[i] != arr[uniqueLength - 1]) {
                uniqueLength++;
            }
        }
        return Arrays.copyOfRange(arr, 0, uniqueLength);
    }

    public static class UnionFind {
        private int[] parent;
        private int[] rank;

        public UnionFind(int n) {
            parent = new int[n];
            rank = new int[n];

            for (int i = 0; i < n; i++) {
                parent[i] = i;
                rank[i] = 0;
            }
        }

        public void makeSet(int x) {
            parent[x] = x;
        }

        public boolean isConnected(int x, int y) {
            return find(x) == find(y);
        }

        public void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);

            if (rootX != rootY) {
                if (rank[rootX] < rank[rootY]) {
                    parent[rootX] = rootY;
                } else if (rank[rootX] > rank[rootY]) {
                    parent[rootY] = rootX;
                } else {
                    parent[rootY] = rootX;
                    rank[rootX]++;
                }
            }
        }

        private int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }
    }
}
