<?php

function updateClinicStatus($clinic_id, $new_status, $last_modified_ip, $stakeholder_api_key) {
    // Initialize rate limiter
    $rate_limiter = new RateLimiter();

    if (!$rate_limiter->allow()) {
        return 'Rate limit exceeded. Please try again after 1 minute.';
    }

    // Validate stakeholder API key
    if (!validateApiKey($stakeholder_api_key)) {
        return 'Invalid stakeholder API key';
    }

    $db = new Database();

    try {
        // Start transaction
        $db->beginTransaction();

        // Update clinic status in database
        $query = "UPDATE clinics SET status = ?, last_modified_ip = ?, last_modified_date = ? WHERE id = ?";
        $stmt = $db->prepare($query);
        $stmt->execute(array($new_status, $last_modified_ip, date('Y-m-d H:i:s'), $clinic_id));

        // Commit transaction
        $db->commit();

        // Notify stakeholders via API
        notifyStakeholders($clinic_id, $new_status);

        return 'Clinic status updated successfully';

    } catch (PDOException $e) {
        // Rollback transaction on error
        $db->rollBack();
        logError('PDO error: ' . $e->getMessage());
        return 'Error updating clinic status';
    }
}

class RateLimiter {
    private $ip_addresses;
    private $rate_limits;

    public function __construct() {
        $this->ip_addresses = array();
        $this->rate_limits = array(1 => 5); // 5 updates per minute
    }

    public function allow() {
        $current_time = time();
        foreach ($this->ip_addresses as $ip => $last_update) {
            if ($last_update + (60 / $this->rate_limits[1]) < $current_time) {
                unset($this->ip_addresses[$ip]);
            }
        }

