<?php

class PasswordGenerator {
    private $characterSet;
    private $password;

    public function __construct($characterSet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()_+', $length = 12) {
        $this->characterSet = $characterSet;
        $this->password = '';
    }

    public function generatePassword() {
        for ($i = 0; $i < strlen($this->characterSet); $i++) {
            $char = substr($this->characterSet, mt_rand(0, strlen($this->characterSet) - 1), 1);
            if (ctype_upper($char)) {
                $this->password .= $char;
                break;
            } elseif (ctype_lower($char)) {
                $this->password .= $char;
                break;
            } elseif (ctype_digit($char)) {
                $this->password .= $char;
                break;
            } else {
                $this->password .= $char;
                break;
            }
        }

        for ($i = 1; $i < $length - 3; $i++) {
            $this->password .= substr($this->characterSet, mt_rand(0, strlen($this->characterSet) - 1), 1);
        }

        $this->password .= '!';

        for ($i = 0; $i < 2; $i++) {
            $this->password .= substr($this->characterSet, mt_rand(0, strlen($this->characterSet) - 1), 1);
        }
    }

    public function getPassword() {
        return $this->password;
    }
}

class Hasher {
    private $password;
    private $hash;

    public function __construct($password) {
        $this->password = $password;
    }

    public function generateHash($rounds = 10000) {
        $this->hash = hash_pbkdf2('sha256', $this->password, 'salt', 128, $rounds);
    }

    public function getHash() {
        return $this->hash;
    }
}

class Authenticator {
    private $service;

    public function __construct($service) {
        $this->service = $service;
    }

    public function authenticate($username, $password) {
        // API call to the authentication service
        $response = $this->service->authenticate($username, $password);

        if ($response['status'] === 'success') {
            return true;
        } else {
            return false;
        }
    }
}

