from flask import request, jsonify
from flask_sqlalchemy import SQLAlchemy
import logging

app = Flask(__name__)
app.config["SQLALCHEMY_DATABASE_URI"] = "sqlite:///resources.db"
db = SQLAlchemy(app)

class Resource(db.Model):
    __tablename__ = "resources"

    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(100), nullable=False)
    description = db.Column(db.String(200))

@app.route('/resources/<int:resource_id>', methods=['PUT'])
def update_resource(resource_id):
    resource = Resource.query.get_or_404(resource_id)

    if request.is_json:
        data = request.get_json()
        for key, value in data.items():
            setattr(resource, key, value)
        db.session.commit()

    return jsonify({'id': resource.id, 'name': resource.name, 'description': resource.description})

@app.route('/resources/<int:resource_id>', methods=['DELETE'])
def delete_resource(resource_id):
    resource = Resource.query.get_or_404(resource_id)

    try:
        if resource.related_resources:
            for related_resource in resource.related_resources:
                db.session.delete(related_resource)
        db.session.delete(resource)
        db.session.commit()
    except Exception as e:
        logging.error(f"Error deleting resource: {e}")
        return jsonify({'error': 'Failed to delete the resource'}), 500

    # If deletion is successful, create a new resource with default values
    try:
        new_resource = Resource(name='New Resource', description='')
        db.session.add(new_resource)
        db.session.commit()
        return jsonify({'id': new_resource.id})
    except Exception as e:
        logging.error(f"Error creating new resource: {e}")
        return jsonify({'error': 'Failed to create a new resource'}), 500

if __name__ == '__main__':
    app.run(debug=True)
