using System;
using System.Threading.Tasks;

public async Task<IActionResult> UpdateElement(string pageSectionId, string elementId, string htmlContent)
{
    if (string.IsNullOrEmpty(pageSectionId) || string.IsNullOrEmpty(elementId))
    {
        return BadRequest("Invalid input IDs");
    }

    try
    {
        // Validate user permissions
        if (!await HasUpdatePermission(pageSectionId, elementId))
        {
            return Unauthorized();
        }

        // Update the element's HTML content using a service class
        await UpdateElementService.UpdateHtmlContent(elementId, htmlContent);

        // Ensure updates are atomic to prevent partial updates and race conditions
        await using (var transaction = await DatabaseConnection.GetTransaction())
        {
            try
            {
                await DatabaseConnection.UpdateElement(elementId, htmlContent);
                await transaction.Commit();
            }
            catch (Exception ex)
            {
                await transaction.Rollback();
                await LoggingService.LogError(ex, "Failed to update element");
                return StatusCode(500, "Internal Server Error");
            }
        }

        // Return a response indicating that the page should be refreshed
        return Ok("Page updated successfully. Please refresh for changes to take effect.");
    }
    catch (Exception ex)
    {
        await LoggingService.LogError(ex, "Error updating element");
        return StatusCode(500, "Internal Server Error");
    }
}
