def read_file_sort_lines_extract_sequence(file_name):
    try:
        with open(file_name, 'r') as file:
            lines = [line.strip() for line in file.readlines()]
            sorted_lines = sorted(lines)
            last_line = sorted_lines[-1]
            sequence_number = int(''.join(filter(str.isdigit, last_line)))
            return sequence_number
    except FileNotFoundError:
        print(f"File '{file_name}' not found.")
        return None
    except ValueError:
        print(f"'{file_name}' contains non-numeric characters in the last line.")
        return None

