using System;
using System.IO;
using System.Security.Cryptography;
using System.Threading.Tasks;

namespace AESCBCFileDecryptionModule
{
    public class DecryptionService
    {
        private readonly string _connectionString;
        private readonly int _paddingScheme;

        public DecryptionService(string connectionString, int paddingScheme)
        {
            _connectionString = connectionString;
            _paddingScheme = paddingScheme;
        }

        public async Task<byte[]> DecryptFileAsync(string fileId)
        {
            // Retrieve ciphertext, encryption key, and IV from remote database service
            var dbService = new DatabaseService(_connectionString);
            var ciphertext = await dbService.GetCiphertextAsync(fileId);
            var key = await dbService.GetKeyAsync(fileId);
            var iv = await dbService.GetIvAsync(fileId);

            // Initialize AES-CBC decryption algorithm with chosen padding scheme
            using var aes = Aes.Create();
            aes.Key = Convert.FromBase64String(key);
            aes.IV = Convert.FromBase64String(iv);
            aes.Padding = GetPaddingScheme(_paddingScheme);

            // Decrypt file in parallel chunks for large files
            const int chunkSize = 1024 * 1024; // 1 MB
            using var ms = new MemoryStream();
            await DecryptFileInParallelAsync(ciphertext, aes, ms, chunkSize);

            // Return decrypted file data
            return ms.ToArray();
        }

        private static PaddingMode GetPaddingScheme(int paddingScheme)
        {
            switch (paddingScheme)
            {
                case 1:
                    return PaddingMode.PKCS7;
                case 2:
                    return PaddingMode.ANSIX923;
                default:
                    return PaddingMode.None;
            }
        }

        private async Task DecryptFileInParallelAsync(byte[] ciphertext, Aes aes, MemoryStream ms, int chunkSize)
        {
            const int numThreads = Environment.ProcessorCount; // Use multiple threads for parallel decryption
            var tasks = new Task[numThreads];
            var chunkIndex = 0;

            foreach (var _ in Enumerable.Range(0, numThreads))
            {
                tasks[_] = DecryptFileChunkAsync(ciphertext, aes, ms, chunkSize, ref chunkIndex);
            }

            await Task.WhenAll(tasks);
        }

        private async Task DecryptFileChunkAsync(byte[] ciphertext, Aes aes, MemoryStream ms, int chunkSize, ref int chunkIndex)
        {
            while (true)
            {
                var start = chunkIndex * chunkSize;
                var end = Math.Min((chunkIndex + 1) * chunkSize, ciphertext.Length);

                using var cs = new CryptoStream(ms, aes.CreateDecryptor(), CryptoStreamMode.Write);
                await cs.WriteAsync(ciphertext.AsSpan(start, end - start));
                await cs.FlushAsync();

                if (end >= ciphertext.Length)
                    break;

                chunkIndex++;
            }
        }

        public void LogDecryptionOperation(string fileId, long fileSize, int durationMs)
        {
            // Implement logging and metrics for decryption operations
        }
    }
}
