using System;
using System.Xml.Linq;
using System.Net.Http;
using System.IO;
using System.Threading.Tasks;

public class XmlParser
{
    private const int DEFAULT_CACHE_SIZE = 1000;
    private const int DEFAULT_CACHE_DURATION = 60; // minutes
    private readonly HttpClient _httpClient;
    private readonly CacheManager _cacheManager;

    public XmlParser(HttpClient httpClient, CacheManager cacheManager)
    {
        _httpClient = httpClient;
        _cacheManager = cacheManager;
    }

    public async Task<XElement> GetFirstMatchingElement(string url, string xPathExpression)
    {
        if (string.IsNullOrEmpty(url) || string.IsNullOrEmpty(xPathExpression))
            throw new ArgumentException("Invalid input");

        try
        {
            // Check cache first
            if (_cacheManager.ContainsKey(url))
            {
                var cachedXml = _cacheManager.Get(url);
                return ParseXml(cachedXml, xPathExpression);
            }

            // Fetch XML content from remote server
            using (var response = await _httpClient.GetAsync(url))
            {
                response.EnsureSuccessStatusCode();
                var xmlContent = await response.Content.ReadAsStringAsync();

                // Cache the fetched XML content
                _cacheManager.Set(url, xmlContent, DEFAULT_CACHE_DURATION * 60); // cache for an hour

                return ParseXml(xmlContent, xPathExpression);
            }
        }
        catch (HttpRequestException ex)
        {
            LogError($"Failed to fetch XML from {url}: {ex.Message}");
            throw;
        }
        catch (XDocumentException ex)
        {
            LogError($"Invalid XML format: {ex.Message}");
            return null; // or handle this case as needed
        }
    }

    private XElement ParseXml(string xmlContent, string xPathExpression)
    {
        try
        {
            var xmlDoc = XDocument.Parse(xmlContent);
            return xmlDoc.XPathSelectElement(xPathExpression);
        }
        catch (XPathException ex)
        {
            LogError($"Failed to evaluate XPath expression '{xPathExpression}': {ex.Message}");
            return null; // or handle this case as needed
        }
    }

    private void LogError(string message)
    {
        // Implement your logging mechanism here
        Console.WriteLine(message);
    }
}

public class CacheManager
{
    private readonly Dictionary<string, string> _cache = new Dictionary<string, string>(DEFAULT_CACHE_SIZE);

    public void Set(string key, string value, int duration)
    {
        lock (_cache)
        {
            if (_cache.Count >= DEFAULT_CACHE_SIZE)
                _cache.Remove(_cache.First().Key); // implement eviction policy

            _cache.Add(key, value);
        }
    }

    public bool ContainsKey(string key)
    {
        lock (_cache)
        {
            return _cache.ContainsKey(key);
        }
    }

    public string Get(string key)
    {
        lock (_cache)
        {
            return _cache[key];
        }
    }
}
