    public ResponseEntity<PokemonResponse> getPokemonDetails(int pokemonId) {
        PokemonResponse response = new PokemonResponse();
        response.setPokemonName(getPokemonName(pokemonId));
        response.setType(getPokemonType(pokemonId));
        List<Weakness> weaknesses = getWeaknesses(pokemonId);
        response.setWeaknesses(weaknesses);
        Evolution evolution = getEvolutionDetails(pokemonId);
        response.setEvolution(evolution);
        response.setHabitat(getHabitatDescription(pokemonId));

        return new ResponseEntity<>(response, HttpStatus.OK);
    }

    private String getPokemonName(int pokemonId) {
        // API call to retrieve Pokemon name
        // Return the response in JSON format
        return "{\"name\":\"Pikachu\"}";
    }

    private String getPokemonType(int pokemonId) {
        // API call to retrieve Pokemon type
        // Return the response in JSON format
        return "{\"type\":\"Electric/Fire\"}";
    }

    private List<Weakness> getWeaknesses(int pokemonId) {
        List<Weakness> weaknesses = new ArrayList<>();
        try {
            // API call to retrieve Weaknesses
            HttpClient client = HttpClients.createDefault();
            HttpGet get = new HttpGet("https://weakness-api.com/weaknesses/" + pokemonId);
            HttpResponse response = client.execute(get);
            int status = response.getStatusLine().getStatusCode();

            if (status == 200) {
                String responseString = EntityUtils.toString(response.getEntity());
                JSONObject jsonObject = new JSONObject(responseString);
                JSONArray weaknessesArray = jsonObject.getJSONArray("weaknesses");
                for (int i = 0; i < weaknessesArray.length(); i++) {
                    Weakness weakness = new Weakness(weaknessesArray.getJSONObject(i).getString("name"));
                    weaknesses.add(weakness);
                }
            } else if (status == 404) {
                // Handle not found
                return null;
            } else {
                // Handle other status codes
                return null;
            }
        } catch (IOException | ParserConfigurationException e) {
            // Handle exceptions
            return null;
        }
    }

    private Evolution getEvolutionDetails(int pokemonId) {
        Evolution evolution = new Evolution();
        try {
            // API call to retrieve Evolution details
            HttpClient client = HttpClients.createDefault();
            HttpGet get = new HttpGet("https://evolution-api.com/evolutions/" + pokemonId);
            HttpResponse response = client.execute(get);
            int status = response.getStatusLine().getStatusCode();

            if (status == 200) {
                String responseString = EntityUtils.toString(response.getEntity());
                JSONObject jsonObject = new JSONObject(responseString);
                evolution.setName(jsonObject.getString("name"));
                evolution.setLevel(jsonObject.getInt("level"));
            } else if (status == 404) {
                // Handle not found
                return null;
            } else {
                // Handle other status codes
                return null;
            }
        } catch (IOException | ParserConfigurationException e) {
            // Handle exceptions
            return null;
        }

        return evolution;
    }

    private String getHabitatDescription(int pokemonId) {
        // API call to retrieve Habitat description
        // Return the response in JSON format
        return "{\"habitat\":\"Grassland\"}";
    }
}

