    public async Task VerifyFileAsync(string filePath)
    {
        try
        {
            using var md5 = MD5.Create();
            using var fileStream = File.OpenRead(filePath);
            int chunkSize = 4096;
            byte[] hashBytes;

            do
            {
                byte[] buffer = new byte[chunkSize];
                int bytesRead = fileStream.Read(buffer, 0, chunkSize);

                if (bytesRead > 0)
                {
                    using var hashMemoryStream = new MemoryStream();
                    using var hashCryptoStream = new CryptoStream(hashMemoryStream, md5);
                    await hashCryptoStream.WriteAsync(buffer, 0, bytesRead);
                    await hashCryptoStream.FlushAsync();

                    hashBytes = hashMemoryStream.ToArray();

                    if (await VerifyHashAgainstApiAsync(hashBytes))
                    {
                        _verifiedHashes.Add(filePath, (hashBytes.Length, DateTime.Now));
                    }
                }
            } while (fileStream.Position < fileStream.Length);

            // Log any errors
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error: {ex.Message}");
        }
