function updateClinicStatus($clinic_id, $new_status, $last_modified_ip) {
    $redis = new Redis();
    $redis->connect('localhost', 6379);

    // Check rate limit for the IP address
    if ($redis->hget('rate_limit:'.$last_modified_ip, 'count') < 5 && time() - $redis->hget('rate_limit:'.$last_modified_ip, 'timestamp') < 60) {
        return 'Rate limit exceeded';
    }

    // Start distributed transaction
    $transaction = new DistributedTransaction();
    try {
        $transaction->start();

        // Prepare update query
        $query = "UPDATE clinics SET status = ?, last_modified_ip = ?, last_modified_date = ? WHERE id = ?";
        $stmt = $transaction->prepare($query);
        $stmt->execute([$new_status, $last_modified_ip, date('Y-m-d H:i:s'), $clinic_id]);

        // Commit transaction
        $transaction->commit();
    } catch (Exception $e) {
        // Log error to ELK Stack service
        $logClient = new LogClient();
        $logClient->error('Failed to update clinic status', $e);

        // Roll back transaction and return error message
        try {
            $transaction->rollBack();
        } catch (Exception $rollbackError) {
            // Log rollback error as well
            $logClient->error('Failed to roll back transaction', $rollbackError);
        }
        return 'Update failed: '.$e->getMessage();
    } finally {
        // Release distributed transaction
        $transaction->release();

        // Update rate limit for the IP address in Redis cache
        $redis->hmset('rate_limit:'.$last_modified_ip, ['count' => 1, 'timestamp' => time()]);
    }

    return 'Update successful';
}
