class ThemeCache {
    private val bitmapCache = ConcurrentHashMap<String, Bitmap>()
    private val lock = ReentrantLock()
    private val networkQueue = LinkedBlockingDeque<BitmapDownloadTask>()

    fun getAndMaybeDownloadTheme(themeName: String): Bitmap? {
        return lock.withLock {
            val cachedBitmap = bitmapCache[themeName]
            if (cachedBitmap != null) {
                // If the bitmap is already in cache, return it
                return cachedBitmap
            }

            // Download the theme bitmap from the remote server
            val downloadTask = BitmapDownloadTask(themeName)
            networkQueue.add(downloadTask)

            try {
                // Wait for the download task to complete
                downloadTask.get()
            } catch (e: InterruptedException) {
                // Handle interrupted thread
                return null
            }

            // Update the cache with the downloaded bitmap
            val downloadedBitmap = downloadTask.bitmap
            bitmapCache[themeName] = downloadedBitmap

            // Save the theme path to the local configuration file
            updateThemePathInConfig(themeName)

            return downloadedBitmap
        }
    }

    fun clearUnusedThemes() {
        lock.withLock {
            bitmapCache.clear()
        }
    }

    private inner class BitmapDownloadTask internal constructor(val themeName: String) :
        AsyncTask<Void, Void, Bitmap>() {

        var bitmap: Bitmap? = null

        override fun doInBackground(vararg params: Void): Bitmap {
            // Download the theme bitmap from the remote server
            val response = downloadBitmapFromServer(themeName)

            if (response.code() == 200) {
                val bitmapArray = response.body() as ByteArray
                bitmap = BitmapFactory.decodeByteArray(bitmapArray, 0, bitmapArray.size)
            } else {
                bitmap = null
            }

            return bitmap
        }
    }

    private fun downloadBitmapFromServer(themeName: String): Response<ByteArray> {
        // Implement your network request here
