import java.io.ByteArrayInputStream;
import java.io.ObjectInputStream;
import java.io.StreamCorruptedException;

public class ObjectDeserializer {
    public static <T> T deserialize(byte[] data, Class<T> clazz) throws RuntimeException {
        try (ByteArrayInputStream bis = new ByteArrayInputStream(data);
             ObjectInputStream ois = new ObjectInputStream(bis)) {
            T object = (T) ois.readObject();
            return object;
        } catch (StreamCorruptedException e) {
            throw new RuntimeException("Failed to deserialize: " + e.getMessage());
        } catch (ClassNotFoundException e) {
            // Fallback mechanism for older class versions
            String message = "Unsupported version of the serialized object";
            if (e.getMessage() != null && e.getMessage().startsWith("Class not found")) {
                message += ". Check your classpath and ensure that the required classes are available.";
            }
            throw new RuntimeException(message);
        } catch (Exception e) {
            // Fallback mechanism for older class versions
            String message = "Failed to deserialize: " + e.getMessage();
            if (e instanceof ClassNotFoundException) {
                message += ". Check your classpath and ensure that the required classes are available.";
            }
            throw new RuntimeException(message);
        }
    }
}
