#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/err.h>
#include <openssl/aes.h>
#include <openssl/chacha.h>
#include <openssl/sha.h>

typedef enum {
    AES_256,
    CHACHA20
} encryption_algorithm_t;

typedef enum {
    SHA_256,
    SHA_384,
    SHA_512
} hashing_algorithm_t;

struct secure_messaging_library {
    // Map of enabled algorithms
    const char *enabled_algorithms[4];

    // OpenSSL context
    EVP_CTX *ctx;
};

secure_messaging_library_t *init_secure_messaging_library(const char *config_str) {
    secure_messaging_library_t *library = malloc(sizeof(secure_messaging_library_t));

    if (!library) {
        return NULL;  // Out of memory
    }

    library->enabled_algorithms[0] = NULL;
    library->enabled_algorithms[1] = NULL;
    library->ctx = EVP_CTX_new();

    if (!library->ctx) {
        free(library);
        return NULL;  // Initialization error
    }

    int i = 0;
    const char *token = strtok(config_str, ",");

    while (token && i < 2) {
        if (strcmp(token, "AES-256") == 0) {
            library->enabled_algorithms[0] = token;
            AES_set_table(AES_ENCRYPT);
        } else if (strcmp(token, "CHACHA20") == 0) {
            library->enabled_algorithms[1] = token;
            CHACHA_set_table(CHACHA_ENCRYPT);
        }

        token = strtok(NULL, ",");
        i++;
    }

    int j = 0;
    token = strtok(config_str, ",");

    while (token && j < 3) {
        if (strcmp(token, "SHA-256") == 0) {
            library->enabled_algorithms[2] = token;
            SHA224_Init();
        } else if (strcmp(token, "SHA-384") == 0) {
            library->enabled_algorithms[3] = token;
            SHA384_Init();
        } else if (strcmp(token, "SHA-512") == 0) {
            library->enabled_algorithms[4] = token;
            SHA512_Init();
        }

        token = strtok(NULL, ",");
        j++;
    }

    // Handle initialization errors
    if (!library->enabled_algorithms[0] && !library->enabled_algorithms[1]) {
        ERR_error_string(ERR_get_error(), NULL);
        free(library);
        return NULL;
    }

    return library;
}
