import hashlib
import pickle
import socket
from threading import Lock, Thread
from collections import defaultdict

class DistributedCache:
    def __init__(self, node_id, host, port, max_size=1024*1024*10, timeout=60):
        self.node_id = node_id
        self.host = host
        self.port = port
        self.max_size = max_size
        self.timeout = timeout
        self.cache = defaultdict(dict)
        self.lock = Lock()
        self.stats = {"hits": 0, "misses": 0}
        self.serializer = pickle.dumps

    def _get_node_address(self):
        return f"{self.host}:{self.port}"

    def _hash_key(self, key):
        return hashlib.md5(key.encode()).hexdigest()

    def get(self, key):
        hash_value = self._hash_key(key)
        node = int(hash_value, 16) % 256
        with self.lock:
            if self.cache[node].get(hash_value):
                self.stats["hits"] += 1
                return self.cache[node][hash_value]
        self.stats["misses"] += 1

    def set(self, key, value, timeout=None):
        hash_value = self._hash_key(key)
        node = int(hash_value, 16) % 256
        with self.lock:
            if not self.cache[node].get(hash_value):
                self.cache[node][hash_value] = (value, min(timeout or self.timeout, self.timeout))
                self.stats["hits"] += 1

    def update(self, key, value):
        hash_value = self._hash_key(key)
        node = int(hash_value, 16) % 256
        with self.lock:
            if self.cache[node].get(hash_value):
                self.cache[node][hash_value] = (value, min(self.timeout, self.timeout))

    def serialize(self):
        return pickle.dumps((self.stats, self.cache))

    def deserialize(self, data):
        stats, cache = pickle.loads(data)
        with self.lock:
            self.stats = stats
            self.cache = cache

    def run(self):
        while True:
            try:
                sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                sock.bind((self.host, self.port))
                sock.listen(5)
                print(f"Node {self.node_id} is listening on {self._get_node_address()}")
                while True:
                    conn, addr = sock.accept()
                    if conn:
                        try:
                            data = conn.recv(1024).decode()
                            if data.startswith("GET"):
                                key = data[3:]
                                value = self.get(key)
                                conn.sendall(f"VALUE {value}".encode())
                            elif data.startswith("SET"):
                                key, value = data[3:].split(",")
                                self.set(key.strip(), value.strip())
                                conn.sendall(f"OK".encode())
                        except:
                            pass
                    else:
                        break
            except:
                print(f"Node {self.node_id} has failed. Shutting down...")
                sock.close()
                return
