```
function findElements(root, selector, testFunc = () => true, maxDepth = Infinity) {
  const result = [];
  (function traverse(node, depth) {
    if (!node || depth > maxDepth) return;
    if (node.matches(selector)) {
      if (!testFunc(node)) return;
      result.push(node);
    }
    for (let child of node.childNodes) {
      traverse(child, depth + 1);
    }
  })(root, 0);
  return result;
}
