#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <mysql/mysql.h>
#include <pthread.h>

// Define the record structure
typedef struct {
    long offset;
    int key;
    double timestamp;
} Record;

// Function to manage database connections and populate a list of records
void* db_manager(void* arg) {
    // Initialize variables
    MYSQL *conn = (MYSQL*)arg;
    Record **records = (Record**)malloc(1 * sizeof(Record*));
    int num_records = 0;
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Query the database and populate the records array
    while (mysql_query(conn, "SELECT * FROM table")) {
        // Handle errors
        printf("Error: %s\n", mysql_error(conn));
        break;
    }

    // Process the results
    result = mysql_use_result(conn);
    while ((row = mysql_fetch_row(result))) {
        Record* record = (Record*)malloc(sizeof(Record));
        record->offset = atoi(row[0]);
        record->key = atoi(row[1]);
        record->timestamp = atof(row[2]);
        pthread_mutex_lock(&lock);
        records = realloc(records, ++num_records * sizeof(Record*));
        records[num_records - 1] = record;
        pthread_mutex_unlock(&lock);
    }

    // Free resources
    mysql_free_result(result);
    mysql_close(conn);

    return NULL;
}

// Main function
int main() {
    // Initialize the database connections
    MYSQL *conns[3];
    for (int i = 0; i < 3; i++) {
        conns[i] = mysql_init(NULL);
        mysql_options(conns[i], MYSQL_SET_CHARSET_NAME, "utf8");
    }

    // Start threads to query each server
    pthread_t threads[3];
    for (int i = 0; i < 3; i++) {
        pthread_create(&threads[i], NULL, db_manager, conns[i]);
    }

    // Wait for threads to finish
    for (int i = 0; i < 3; i++) {
        pthread_join(threads[i], NULL);
    }

    // Print the records
    for (int i = 0; i < num_records; i++) {
        printf("Offset: %ld, Key: %d, Timestamp: %.2f\n", records[i]->offset, records[i]->key, records[i]->timestamp);
    }

    return 0;
}
