import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

import javax.ws.rs.GET;
import javax.ws.rs.Path;
import javax.ws.rs.PathParam;
import javax.ws.rs.Produces;
import javax.ws.rs.core.MediaType;
import java.io.IOException;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;

@Path("/pokemon/{id}/weaknesses")
public class PokemonWeaknessService {

    private static final String API_URL = "https://pokeapi.co/api/v2/pokemon/%s";

    @GET
    @Produces(MediaType.APPLICATION_JSON)
    public Response getPokemonWeaknesses(@PathParam("id") int id) throws IOException, InterruptedException {
        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(String.format(API_URL, id)))
                .get()
                .build();

        HttpResponse<String> response = HttpClient.newHttpClient().send(request, HttpResponse.BodyHandlers.ofString());

        ObjectMapper mapper = new ObjectMapper();
        JsonNode node = mapper.readTree(response.body());
        JsonNode weaknesses = node.get("weaknesses");

        return Response.ok(weaknesses).build();
    }
}
