package dfs;

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.locks.ReentrantLock;

public class DistributedFileStorage {
    private List<Node> nodes = new ArrayList<>();
    private int totalCapacity;
    private int usedCapacity;
    private ReentrantLock lock = new ReentrantLock();

    public void addNode(Node node) {
        nodes.add(node);
        totalCapacity += node.getCapacity();
        usedCapacity = 0;
        rebalance();
    }

    public void removeNode(Node node) {
        nodes.remove(node);
        totalCapacity -= node.getCapacity();
        rebalance();
    }

    public void uploadFile(String filename, byte[] data) throws IOException {
        lock.lock();
        try {
            Node targetNode = getTargetNode(filename.length());
            if (targetNode == null) {
                throw new IOException("No available node");
            }
            targetNode.writeFile(filename, data);
            usedCapacity += data.length;
            rebalance();
        } finally {
            lock.unlock();
        }
    }

    public void downloadFile(String filename, byte[] buffer) throws IOException {
        lock.lock();
        try {
            Node node = getNode(filename);
            if (node == null) {
                throw new IOException("File not found");
            }
            node.readFile(filename, buffer);
        } finally {
            lock.unlock();
        }
    }

    public void deleteFile(String filename) {
        lock.lock();
        try {
            Node node = getNode(filename);
            if (node != null) {
                node.deleteFile(filename);
                usedCapacity -= 1;
            }
        } finally {
            lock.unlock();
        }
    }

    private Node getNode(String filename) {
        for (Node node : nodes) {
            if (node.containsFile(filename)) {
                return node;
            }
        }
        return null;
    }

    private Node getTargetNode(int fileSize) {
        double maxLoad = 0.5; // dynamic partitioning policy
        Node targetNode = null;
        for (Node node : nodes) {
            if (node.getUsedCapacity() / node.getCapacity() < maxLoad) {
                if (targetNode == null || node.getUsedCapacity() + fileSize > targetNode.getUsedCapacity()) {
                    targetNode = node;
                }
            }
        }
        return targetNode;
    }

    private void rebalance() {
        double threshold = 0.7; // dynamic partitioning policy
        for (Node node : nodes) {
            if (node.getUsedCapacity() / node.getCapacity() > threshold) {
                int excess = (int) ((node.getUsedCapacity() - node.getCapacity()) * 0.5);
                if (excess > 0) {
                    String filename = getLargeFile(node, excess);
                    if (filename != null) {
                        uploadFile(filename, node.readLargeFile(filename));
                    }
                } else {
                    downloadFilesFromNode(node);
                }
            }
        }
    }

    private String getLargeFile(Node node, int excess) {
        for (String file : node.getFileList()) {
            if (node.readFile(file).length > excess) {
                return file;
            }
        }
        return null;
    }

    private void downloadFilesFromNode(Node node) {
        List<String> files = new ArrayList<>();
        for (String file : node.getFileList()) {
            byte[] data = node.readfile(file);
            int fileSize = data.length;
            if (fileSize > 0 && usedCapacity - fileSize >= 0) {
                files.add(file);
                usedCapacity -= fileSize;
            }
        }
        for (String file : files) {
            downloadFile(file, new byte[0]);
        }
    }

    public class Node {
        private int capacity;
        private List<String> fileList = new ArrayList<>();
        private ReentrantLock lock = new ReentrantLock();

        public int getCapacity() {
            return capacity;
        }

        public void setCapacity(int capacity) {
            this.capacity = capacity;
        }

        public void writeFile(String filename, byte[] data) throws IOException {
            lock.lock();
            try {
                if (!fileList.contains(filename)) {
                    fileList.add(filename);
                }
                // implement file writing logic
            } finally {
                lock.unlock();
            }
        }

        public byte[] readFile(String filename) throws IOException {
            lock.lock();
            try {
                if (fileList.contains(filename)) {
                    // implement file reading logic
                } else {
                    throw new IOException("File not found");
                }
            } finally {
                lock.unlock();
            }
        }

        public void deleteFile(String filename) {
            lock.lock();
            try {
                fileList.remove(filename);
                // implement file deletion logic
            } finally {
                lock.unlock();
            }
        }

        public boolean containsFile(String filename) {
            return fileList.contains(filename);
        }

        public List<String> getFileList() {
            return fileList;
        }

        public int getUsedCapacity() {
            // calculate used capacity based on files and node size
        }
    }
}
