```cpp
#include <iostream>
#include <memory>

class OctreeNode {
public:
    OctreeNode(int level, double featureSize)
        : level(level), featureSize(featureSize) {}

    virtual ~OctreeNode() {}

    int level;
    double featureSize;

    // Virtual to allow for different node types (e.g., leaf nodes vs. internal nodes)
};

class LeafNode : public OctreeNode {
public:
    LeafNode(int level, double featureSize)
        : OctreeNode(level, featureSize) {}

    // Store objects in this node
    std::vector<Object*> objects;
};

class InternalNode : public OctreeNode {
public:
    InternalNode(int level, double featureSize)
        : OctreeNode(level, featureSize) {}

    // Pointer to child nodes
    std::unique_ptr<OctreeNode[]> children;

    void addChild(OctreeNode* node) {
        if (children.empty()) {
            children = std::make_unique<OctreeNode[]>(8);
        }
        children[getChildIndex(node)] = node;
    }

    int getChildIndex(OctreeNode* node) const {
        return (int)((node - &children[0]) / sizeof(OctreeNode));
    }
};

class Octree {
public:
    Octree(int initialLevel, double featureSize, size_t maxCapacity)
        : root(new InternalNode(initialLevel, featureSize)), capacity(maxCapacity), level(initialLevel) {}

    ~Octree() {
        // Recursively delete nodes
        destroy(root.get());
    }

    void insert(Object* object);

private:
    void destroy(OctreeNode* node) {
        if (node == nullptr) return;
        if (dynamic_cast<LeafNode*>(node)) {
            for (Object* obj : ((LeafNode*)node)->objects) delete obj;
            delete node;
        } else {
            InternalNode* internal = dynamic_cast<InternalNode*>(node);
            for (OctreeNode* child : *internal->children) destroy(child.get());
            delete node;
        }
    }

    std::unique_ptr<InternalNode> root;
    size_t capacity;
    int level;
};

