```java
import io.jsonwebtoken.JwtBuilder;
import io.jsonwebtoken.Jwts;
import java.security.KeyStore;
import java.util.Date;

public class JwtGenerator {
    public String generateJwt(String username, String password) throws Exception {
        // Retrieve private key from KMS
        KeyStore keyStore = KeyStore.getInstance("JKS");
        // keyStore.load(new FileInputStream("path/to/keystore"), "password".toCharArray());

        // Create JWT Builder
        JwtBuilder builder = Jwts.builder()
                .setSubject(username)
                .setExpiration(new Date(System.currentTimeMillis() + 3600000)) // expires in 1 hour
                .claim("role", "admin") // add user role claim

        // Sign JWT with private key
        String jwtToken = builder.signWith(keyStore.getKey("privateKeyAlias", "password".toCharArray())).compact();

        return jwtToken;
    }
}
