```java
import com.fasterxml.jackson.databind.ObjectMapper;
import org.apache.kafka.clients.producer.KafkaProducer;
import org.apache.kafka.clients.producer.ProducerConfig;

public class SensorDataProcessor {
    public void processSensorData(String jsonData) throws Exception {
        // Validate incoming JSON format against schema
        ObjectMapper mapper = new ObjectMapper();
        JsonNode jsonNode = mapper.readTree(jsonData);

        if (!jsonNode.isObject() || !jsonNode.has("temperature") && !jsonNode.has("humidity")) {
            throw new Exception("Invalid JSON format");
        }

        // Store data into Apache Kafka
        Properties props = new Properties();
        props.put(ProducerConfig.BOOTSTRAP_SERVERS, "localhost:9092");
        KafkaProducer<String, String> producer = new KafkaProducer<>(props);
        producer.send("sensor_data_topic", jsonData);

        // Process concurrent data requests efficiently
        producer.initTransactions();
        producer.beginTransaction();
        try {
            while (producer.hasNext()) {
                RecordMetadata metadata = producer.next();
                if (!metadata.offset == 0) break;
            }
        } finally {
            producer.endTransaction(true);
        }

        // Handle disk I/O operations to minimize latency
        KafkaStreams streams = new KafkaStreams(streamsBuilder, props);
        streams.start();
    }
}
