import java.io.*;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.zip.ZipInputStream;

public class FileUploadService {

    public static void uploadFileToCloudStorage(String filePath, String bucketName, String directoryPath) {
        // Validate file metadata
        File file = new File(filePath);
        if (!file.exists()) {
            System.out.println("Error: File not found.");
            return;
        }

        try (BufferedInputStream in = new BufferedInputStream(new FileInputStream(file))) {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            byte[] buffer = new byte[1024];
            int len;
            while ((len = in.read(buffer)) > 0) {
                md.update(buffer, 0, len);
            }
            String fileHash = bytesToHex(md.digest());

            // Check if file already exists
            boolean isFileAlreadyExist = checkIfFileAlreadyExist(bucketName, directoryPath, fileHash);

            if (isFileAlreadyExist) {
                System.out.println("Warning: File already uploaded.");
                return;
            }

            // Upload the file to cloud storage
            uploadFileToCloudStorageAPI(filePath, bucketName, directoryPath);
        } catch (Exception e) {
            System.out.println("Error: " + e.getMessage());
        }
    }

    private static String bytesToHex(byte[] b) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < b.length; i++) {
            sb.append(Integer.toHexString((b[i] & 0xFF) | 0x100).substring(1));
        }
        return sb.toString();
    }

    private static boolean checkIfFileAlreadyExist(String bucketName, String directoryPath, String fileHash) {
        // API call to check if the file already exists
