import requests
from typing import List, Dict, Any
import logging
import time
import concurrent.futures

def update_profile(profile_data: Dict[str, str], services: List[Dict[str, Any]]) -> None:
    def validate_data(data: Dict[str, str]) -> None:
        # implement schema validation here
        pass

    def handle_api_error(response: requests.Response) -> None:
        if response.status_code == 429:
            logging.error("Rate limit exceeded. Retrying after a short delay.")
            time.sleep(1)
        elif response.status_code >= 500:
            logging.error(f"API error {response.status_code}. Retrying in 5 minutes.")
            time.sleep(300)
        else:
            logging.error(f"Unexpected API error {response.status_code}. Aborting update.")

    def retry_update(update_func: Any, max_retries: int = 3) -> None:
        for i in range(max_retries):
            try:
                update_func()
                return
            except requests.exceptions.RequestException as e:
                if i < max_retries - 1:
                    logging.error(f"Failed to update. Retrying after a short delay.")
                    time.sleep(2 ** (i + 1))
                else:
                    logging.error("Max retries exceeded. Aborting update.")

    def parallel_update(profile_data: Dict[str, str], service_config: Dict[str, Any]) -> None:
        with concurrent.futures.ThreadPoolExecutor(max_workers=5) as executor:
            futures = []
            for _ in range(5):
                futures.append(executor.submit(update_service, profile_data, service_config))
            for future in futures:
                future.result()

    def update_service(profile_data: Dict[str, str], service_config: Dict[str, Any]) -> None:
        headers = {"Authorization": f"Bearer {service_config['access_token']}"}
        try:
            response = requests.put(f"{service_config['api_url']}/profile", json=profile_data, headers=headers)
            if response.status_code == 200:
                logging.info("Profile updated successfully.")
            else:
                handle_api_error(response)
        except requests.exceptions.RequestException as e:
            retry_update(lambda: update_service(profile_data, service_config))

    def main() -> None:
        validate_data(profile_data)
        for service in services:
            parallel_update(profile_data, service)

if __name__ == "__main__":
    # example usage
    profile_data = {"email": "new_email@example.com", "phone_number": "123-456-7890"}
    services = [
        {"api_url": "https://api-service1.com", "access_token": "access-token-1"},
        {"api_url": "https://api-service2.com", "access_token": "access-token-2"},
        # add more services as needed
    ]
    update_profile(profile_data, services)
