import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class TextFileAnalyzer {

    private static final int BUFFER_SIZE = 1024 * 1024; // 1MB buffer

    public void analyzeFiles(String directoryPath, String[] keywords, String outputFormat) {
        List<File> files = new ArrayList<>();
        File directory = new File(directoryPath);

        if (directory.isDirectory()) {
            for (File file : directory.listFiles()) {
                if (file.isFile() && file.getName().endsWith(".txt")) {
                    files.add(file);
                }
            }

            analyzeFiles(files, keywords, outputFormat);
        } else {
            System.out.println("Directory not found");
        }
    }

    private void analyzeFiles(List<File> files, String[] keywords, String outputFormat) {
        for (File file : files) {
            try (FileReader reader = new FileReader(file)) {
                int bytesRead;
                char[] buffer = new char[BUFFER_SIZE];
                StringBuilder content = new StringBuilder();

                while ((bytesRead = reader.read(buffer)) != -1) {
                    content.append(buffer, 0, bytesRead);
                }

                String fileContent = content.toString();

                for (String keyword : keywords) {
                    Pattern pattern = Pattern.compile(keyword, Pattern.CASE_INSENSITIVE);
                    Matcher matcher = pattern.matcher(fileContent);

                    while (matcher.find()) {
                        System.out.println("Found keyword '" + keyword + "' in file " + file.getName());
                    }
                }

                generateSummaryReport(file.getName(), content.toString(), outputFormat);
            } catch (IOException e) {
                System.out.println("Error reading file: " + file.getName() + ". Error message: " + e.getMessage());
            }
        }
    }

    private void generateSummaryReport(String fileName, String fileContent, String outputFormat) {
        // Call external reporting API to generate report
        // Assume the API method is reportGenerator
        try {
            reportGenerator(fileContent, fileName, outputFormat);

            System.out.println("Summary report generated successfully for " + fileName);
        } catch (Exception e) {
            System.out.println("Error generating summary report: " + e.getMessage());
        }
    }

    // Call the external reporting API to generate the report
    private void reportGenerator(String fileContent, String fileName, String outputFormat) {
        // Implement the logic for calling the external API
    }
}

