```java
import java.io.IOException;
import java.lang.reflect.Constructor;
import java.util.*;

public class ObjectDeserializer {

    private static final int MAX_CACHE_ENTRIES = 1000;

    private static Map<String, Constructor<?>> cache = new LruCache(MAX_CACHE_ENTRIES);
    private static ExecutorService executorService = Executors.newCachedThreadPool();

    public static Object deserialize(byte[] data, String className) {
        try {
            Constructor<?> constructor = getConstructor(className);
            return constructor.newInstance(data);
        } catch (InstantiationException | IllegalAccessException e) {
            logError("Instantiation or Access Exception", e);
            throw new RuntimeDeserializationException(e.getMessage());
        }
    }

    private static Constructor<?> getConstructor(String className) throws ClassNotFoundException {
        if (!cache.containsKey(className)) {
            Constructor<?> constructor = Class.forName(className).getDeclaredConstructor();
            cache.put(className, constructor);
        }
        return cache.get(className);
    }

    private static void logError(String message, Exception e) {
        // Implement logging mechanism here
    }
}

class LruCache<K, V> extends LinkedHashMap<K, V> {

    private final int maxEntries;

    public LruCache(int maxEntries) {
        this.maxEntries = maxEntries;
    }

    @Override
    protected boolean removeEldestEntry(Map.Entry<K, V> eldest) {
        return size() > maxEntries;
    }
}

class RuntimeDeserializationException extends RuntimeException {

    public RuntimeDeserializationException(String message) {
        super(message);
    }
}
