import os
import exifread
from PIL import Image
from concurrent.futures.thread import ThreadPoolExecutor
from datetime import datetime
import boto3
import requests
import json

class ImageAnalyzer:
    def __init__(self):
        self.s3 = boto3.client('s3')
        self.slack_client = None

    def analyze_images(self, directory, filters=None):
        images = []
        for filename in os.listdir(directory):
            if not filename.lower().endswith(('.jpg', '.jpeg', '.png', '.gif')):
                continue
            filepath = os.path.join(directory, filename)
            try:
                image = Image.open(filepath)
                exif_data = exifread.process_file(open(filepath, 'rb'))
                images.append({
                    'filename': filename,
                    'size': (image.width, image.height),
                    'date_taken': datetime.strptime(exif_data.get('EXIF DateTimeOriginal', '').strip(), '%Y:%m:%d %H:%M:%S'),
                    'metadata': dict(exif_data)
                })
            except Exception as e:
                print(f"Error processing {filename}: {str(e)}")
        return images

    def filter_images(self, images, filters):
        result = []
        for image in images:
            if all(getattr(image, key) >= value or getattr(image, key) <= value for key, value in filters.get('date_range', {}).items()):
                if all(size[0] >= value[0] and size[1] >= value[1] for size, value in filters.get('size_range', {}).items()):
                    if all(getattr(image, key) == value for key, value in filters.get('metadata_filters', {})):
                        result.append(image)
        return result

    def generate_report(self, images):
        report = {}
        for image in images:
            report[image['filename']] = {
                'size': image['size'],
                'date_taken': str(image['date_taken']),
                'metadata': dict((key, value) for key, value in image['metadata'].items() if value)
            }
        return json.dumps(report)

    def upload_report_to_s3(self, report):
        s3.put_object(Body=report.encode('utf-8'), Bucket='your-bucket', Key='image-report.json')

    def send_notification_to_slack(self, message):
        if self.slack_client:
            self.slack_client.chat_postMessage(channel='#images', text=message)

    def start_analyzer(self, directory, filters=None):
        images = self.analyze_images(directory, filters)
        filtered_images = self.filter_images(images, filters)
        report = self.generate_report(filtered_images)
        self.upload_report_to_s3(report)
        self.send_notification_to_slack(f"Image analysis report ready: {report}")

    def set_slack_client(self, client):
        self.slack_client = client
