        payment_processor = os.environ.get('PAYMENT_PROCESSOR')
        user_authenticator = os.environ.get('USER_AUTHENTICATOR')

        if not (email_service and payment_processor and user_authenticator):
            raise Exception("One or more third-party services are missing.")

    def setup_logging(self) -> None:
        logging.basicConfig(
            level=logging.INFO,
            format='%(asctime)s - %(name)s - %(levelname)s - %(message)s'
        )
        self.logger = logging.getLogger(__name__)

    @wraps(setup_logging)
    def setup_retry_policy(self, func: Callable[[], None], attempts: int = 3) -> None:
        def wrapped_func() -> None:
            for _ in range(attempts):
                try:
                    return func()
                except Exception as e:
                    self.logger.error(f"Error initializing {func.__name__}. Retrying...")
                    if _ == attempts - 1:
                        raise
        wrapped_func()

    @wraps(setup_retry_policy)
    def setup_exponential_backoff(self, func: Callable[[], None], attempts: int = 3) -> None:
        backoff_time = timedelta(seconds=2 ** (_ for _ in range(attempts)))

        def wrapped_func() -> None:
            for _ in range(attempts):
                try:
                    return func()
                except Exception as e:
                    self.logger.error(f"Error initializing {func.__name__}. Retrying...")
                    time.sleep(backoff_time.total_seconds())
                    if _ == attempts - 1:
                        raise

        wrapped_func()

# Example usage
config_script = ConfigInitialization('development')
