        public DistributionType type;
        public DistributionParams params;
    }

    private Dictionary<string, DistributionConfiguration> configurations = new Dictionary<string, DistributionConfiguration>();
    private Cache<RandomValueGenerator> randomValueGenerators = new Cache<RandomValueGenerator>();

    public void ConfigureDistribution(string distributionName, float min, float max)
    {
        if (configurations.ContainsKey(distributionName))
            return;

        switch ((int)GetDistributionTypeFromName(distributionName))
        {
            case 0: // Uniform
                configurations.Add(distributionName, new DistributionConfiguration { name = distributionName, type = DistributionType.Uniform, params = new DistributionParams { min, max } });
                break;
            case 1: // Gaussian
                if (min > max)
                    throw new ArgumentException("Invalid range for Gaussian distribution");
                configurations.Add(distributionName, new DistributionConfiguration { name = distributionName, type = DistributionType.Gaussian, params = new DistributionParams { min, max } });
                break;
            case 2: // Exponential
                if (min <= 0)
                    throw new ArgumentException("Invalid minimum value for exponential distribution");
                configurations.Add(distributionName, new DistributionConfiguration { name = distributionName, type = DistributionType.Exponential, params = new DistributionParams { min, max } });
                break;
            default:
                throw new ArgumentException("Unsupported distribution type");
        }
    }

    public float GetRandomFloatValueInRange(float min, float max)
    {
        if (configurations.Count == 0)
            return UnityEngine.Random.Range(min, max);

        string currentDistribution = configurations["current"];
        DistributionConfiguration config = configurations[currentDistribution];
        RandomValueGenerator generator;
        lock (randomValueGenerators)
        {
            if (!randomValueGenerators.ContainsKey(currentDistribution))
                randomValueGenerators.Add(currentDistribution, GetRandomValueGenerator(config));
            generator = randomValueGenerators[currentDistribution];
        }

        return generator.GetRandomFloatValueInRange(min, max);
    }

    public int GetRandomIntValueInRange(int min, int max)
    {
        if (configurations.Count == 0)
            return UnityEngine.Random.Range(min, max + 1);

        string currentDistribution = configurations["current"];
        DistributionConfiguration config = configurations[currentDistribution];
        RandomValueGenerator generator;
        lock (randomValueGenerators)
        {
            if (!randomValueGenerators.ContainsKey(currentDistribution))
                randomValueGenerators.Add(currentDistribution, GetRandomValueGenerator(config));
            generator = randomValueGenerators[currentDistribution];
        }

        return generator.GetRandomIntValueInRange(min, max);
    }

    public override string ToString()
    {
        if (configurations.Count == 0)
            return "No distributions configured";

        return $"Current distribution: {configurations["current"]}. Range: [{configurations["current"].params.min} ,{configurations["current"].params.max}]";
    }

    private DistributionType GetDistributionTypeFromName(string name)
    {
        // TO DO: Implement the logic to determine the distribution type from its name
    }

    private RandomValueGenerator GetRandomValueGenerator(DistributionConfiguration config)
    {
        // TO DO: Create instances of RandomValueGenerators for different distributions
    }
}

public class Cache<T>
{
    private Dictionary<string, T> cache = new Dictionary<string, T>();
    private object lockObject = new object();

    public void Add(string key, T value)
    {
        lock (lockObject)
        {
            if (!cache.ContainsKey(key))
                cache.Add(key, value);
        }
    }

    public T Get(string key)
    {
        lock (lockObject)
        {
            return cache.ContainsKey(key) ? cache[key] : default(T);
        }
    }
}

