import json
import time
from typing import Dict, Any

class UserAuthenticationAPI:
    def __init__(self):
        self.services = {}
        self.retry_timeouts = {}

    def add_service(self, service_name: str, api_url: str, required_fields: Dict[str, bool], 
                    optional_fields: Dict[str, str] = None) -> None:
        self.services[service_name] = {'api_url': api_url, 'required_fields': required_fields}
        if not optional_fields:
            optional_fields = {}
        self.services[service_name]['optional_fields'] = optional_fields
        self.retry_timeouts[service_name] = 1.0

    def validate_response(self, service_name: str, response_json: Dict[str, Any]) -> Dict[str, Any]:
        if not isinstance(response_json, dict):
            raise ValueError(f"Invalid JSON response from {service_name}")

        try:
            access_token = response_json['access_token']
            user_id = response_json['user_id']
        except KeyError as e:
            raise ValueError(f"Missing required field '{e.args[0]}' in response from {service_name}")

        validated_response = {'access_token': access_token, 'user_id': user_id}

        for field, required in self.services[service_name]['required_fields'].items():
            if required and field not in response_json:
                raise ValueError(f"Missing required field '{field}' in response from {service_name}")
            elif required and field in response_json:
                validated_response[field] = response_json[field]

        if 'refresh_token' in response_json:
            validated_response['refresh_token'] = response_json['refresh_token']

        if 'roles' in response_json:
            validated_response['roles'] = response_json['roles']

        if 'status' in response_json:
            validated_response['status'] = response_json['status']

        return validated_response

    def process_api_call(self, service_name: str) -> None:
        while True:
            try:
                response_json = requests.get(self.services[service_name]['api_url']).json()
                break
            except requests.exceptions.RequestException as e:
                if self.retry_timeouts[service_name] <= 0:
                    raise e
                time.sleep(self.retry_timeouts[service_name])
                self.retry_timeouts[service_name] *= 2

    def validate_concurrently(self, services: Dict[str, str]) -> Dict[str, Any]:
        threads = []
        for service_name in services:
            thread = threading.Thread(target=self.process_api_call, args=(service_name,))
            thread.start()
            threads.append(thread)

        validated_responses = {}
        for thread in threads:
            thread.join()
            validated_response = self.validate_response(service_name, response_json)
            validated_responses[service_name] = validated_response

        return validated_responses
