#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>
#include <time.h>

int runCommandBackground(const char* command, int timeout, int retries) {
    pid_t child_pid;
    int status;
    struct timespec start_time, end_time;

    // Set the timestamp for the current time
    clock_gettime(CLOCK_REALTIME, &start_time);

    // Fork a new process
    if ((child_pid = fork()) == -1) {
        perror("fork");
        return 0;
    }

    // Child process: Run the command and exit
    else if (child_pid == 0) {
        // Execute the command
        execlp(command, command, NULL);

        // If the command is not found or there's an error, print an error message
        perror("execlp");
        return 1;
    }

    // Parent process: Wait for the child to finish and set a timeout
    else {
        // Set the timestamp for the current time
        clock_gettime(CLOCK_REALTIME, &end_time);

        // If the command takes longer than the specified time, kill it
        while (clock_gettime(CLOCK_REALTIME, &end_time) - start_time.tv_nsec >= timeout * 1e9) {
            if ((status = waitpid(child_pid, NULL, WNOHANG)) == -1) {
                perror("waitpid");
                break;
            }
            else if (status > 0) {
                break;
            }

            // If the command is still running after the timeout and retries are available
            if (retries > 0) {
                sleep(1);
                retries--;
            }
            else {
                // Kill the process if it takes too long to start or runs indefinitely
                kill(child_pid, SIGKILL);
                break;
            }
        }

        // If the command is still running after all retries are used up
        if (status == 0) {
            return 0;
        }
    }

    return 1;
}

