#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>

int batchConvertJpegToPdf(const char *inputDir, const char *outputDir, size_t maxPagesPerPdf) {
    DIR *dir;
    struct dirent *ent;
    int error = 0;
    int filesConverted = 0;
    int totalFiles = 0;

    dir = opendir(inputDir);
    if (dir == NULL) {
        // Handle ENOTDIR or ENOENT errors
        return -1;
    }

    while ((ent = readdir(dir)) != NULL) {
        char filePath[256];
        if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0) {
            continue;
        }
        totalFiles++;
        sprintf(filePath, "%s/%s", inputDir, ent->d_name);
        // Validate the file extension to ensure it's a JPEG
        if (strcmp(ent->d_type, "REG") && strstr(ent->d_name, ".jpg")) {
            int pdfPageCount = 0;
            FILE *fp = fopen(filePath, "rb");
            if (fp == NULL) {
                error = -2; // Handle EACCES or ENOENT errors
                break;
            }
            // Read the JPEG file contents...
            // ...

            fclose(fp);

            fp = fopen(outputDir, "ab+");
            if (fp == NULL) {
                error = -3; // Handle EACCES or ENOENT errors
                break;
            }

            for (; pdfPageCount < maxPagesPerPdf && totalFiles > 0; pdfPageCount++) {
                filesConverted++;
                // Write the JPEG file contents to the PDF...
                // ...

                if (filesConverted % 10 == 0) {
                    printf("\rConverting... (%d/%d) - %.2f%%", filesConverted, totalFiles, (double)filesConverted / totalFiles * 100);
                }
            }

            fclose(fp);

            if (pdfPageCount < maxPagesPerPdf) {
                break;
            }
        } else {
            // Handle non-JPEG file types...
        }
    }

    closedir(dir);

    printf("\nConversion complete! - %d files converted.\n", filesConverted);
    return error ? error : 0;
}

