    public static string CalculateFileMd5(string filePath, int chunkSize = 1024 * 8)
    {
        using (var md5 = MD5.Create())
        {
            using (var stream = File.OpenRead(filePath))
            {
                var hash = new StringBuilder();

                while (true)
                {
                    var buffer = new byte[chunkSize];
                    var bytesRead = stream.Read(buffer, 0, chunkSize);

                    if (bytesRead == 0)
                        break;

                    md5.TransformBlock(buffer, 0, bytesRead);
                }

                var result = md5.Hash;
                hash.Append(result.ToString("X"));
            }
        }

        return hash.ToString();
    }

    public static string CalculateFileMd5FromUrl(string url, int chunkSize = 1024 * 8)
    {
        using (var md5 = MD5.Create())
        {
            using (var stream = new MemoryStream())
            {
                var request = WebRequest.CreateHttp(url);
                request.Method = "GET";

                try
                {
                    var response = (HttpWebResponse)request.GetResponse();
                    using (var responseStream = response.GetResponseStream())
                    {
                        var bytesRead = 0;

                        while ((bytesRead = responseStream.Read(new byte[chunkSize], 0, chunkSize)) > 0)
                        {
                            md5.TransformBlock(new byte[bytesRead], 0, bytesRead);
                        }

                        var result = md5.Hash;
                    }
                }
                catch (WebException ex)
                {
                    Logger.LogError($"Error downloading file: {ex.Message}", 500);
                    return null;
                }

                var hash = new StringBuilder();
                hash.Append(result.ToString("X"));
            }
        }

        return hash.ToString();
    }
}
