// iot-sensor-module.js
import WebSocket from 'ws';
import { createClient } from '@cassandra/client';
import axios from 'axios';

const wsServer = new WebSocket.Server({ port: 8080 });
const cassandraClient = createClient({
  contactPoints: ['127.0.0.1'],
  localDataCenter: 'datacenter1',
});

wsServer.on('connection', (ws) => {
  const deviceID = ws.upgradeReq.url.match(/device_(\d+)/)[1];
  ws.on('message', (message) => {
    try {
      const { sensor, value } = JSON.parse(message);
      cassandraClient.use('iot_data').insert({
        device_id: deviceID,
        sensor,
        value,
      });
    } catch (error) {
      console.error(`Error processing message from device ${deviceID}:`, error);
    }
  });

  ws.on('close', () => {
    // Handle device disconnection
  });

  ws.on('error', (error) => {
    console.error(`Error with WebSocket connection to device ${deviceID}:`, error);
  });
});

wsServer.on('listening', () => {
  console.log('WebSocket server listening on port 8080');
});

// RESTful API for data retrieval and analytics
const apiRouter = express.Router();

apiRouter.get('/data', (req, res) => {
  const { start, end } = req.query;
  cassandraClient.use('iot_data').select({
    device_id: deviceID,
    sensor: req.query.sensor,
    time: { $between: [start, end] },
  })
    .then((result) => {
      // Process and return the data
      res.json(result);
    })
    .catch((error) => {
      console.error('Error retrieving data:', error);
      res.status(500).send({ message: 'Internal Server Error' });
    });
});

apiRouter.get('/summary', (req, res) => {
  // Return summary statistics for the specified sensor and time range
  const { sensor, start, end } = req.query;
  cassandraClient.use('iot_data').select({
    device_id: deviceID,
    sensor,
    time: { $between: [start, end] },
  })
    .then((result) => {
      // Process and return the summary statistics
      res.json(result);
    })
    .catch((error) => {
      console.error('Error retrieving summary statistics:', error);
      res.status(500).send({ message: 'Internal Server Error' });
    });
});

app.use('/api', apiRouter);

// Start the WebSocket server and RESTful API
wsServer.listen(() => {
  console.log('WebSocket server started');
});

app.listen(3000, () => {
  console.log('RESTful API started on port 3000');
});
