        public DynamicUpdateMiddleware(RequestDelegate next, ILogger<DynamicUpdateMiddleware> logger, IConfigurationRoot config)
        {
            _next = next;
            _logger = logger;
            _config = config;
        }

        public async Task InvokeAsync(HttpContext context)
        {
            if (context.Request.Method == "POST")
            {
                string elementId = context.Request.Form["elementId"];
                string content = context.Request.Form["content"];

                // Check if the element ID exists
                if (!string.IsNullOrEmpty(elementId))
                {
                    try
                    {
                        // Determine which CMS provider to use based on configuration
                        string providerName = _config["ProviderName"];

                        // Implement provider-specific logic here...
                        // For example, for WordPress:
                        // using WordPressAPI;
                        // var wordpressClient = new WordPressClient(_config["WordPressApiUrl"], _config["WordPressApiKey"]);
                        // var contentResponse = await wordpressClient.GetContentAsync(elementId);

                        // Apply the updated content to the webpage
                        // ...

                    }
                    catch (Exception ex)
                    {
                        _logger.LogError(ex, "Error updating element {ElementId}", elementId);
                        context.Response.StatusCode = 500;
                        await context.Response.WriteAsync("Internal Server Error");
                    }
                }
                else
                {
                    context.Response.StatusCode = 400;
                    await context.Response.WriteAsync("Invalid request");
                }
            }

            await _next.InvokeAsync(context);
        }
    }

    public static class DynamicUpdateMiddlewareExtensions
    {
        public static IApplicationBuilder UseDynamicUpdate(this IApplicationBuilder builder, ILogger<DynamicUpdateMiddleware> logger, IConfigurationRoot config)
        {
            return builder.UseMiddleware<DynamicUpdateMiddleware>(logger, config);
        }
    }
