```csharp
using UnityEngine;
using System.Collections.Generic;

public class DynamicValueGenerator : MonoBehaviour
{
    private Dictionary<string, Distribution> distributions = new Dictionary<string, Distribution>();
    private Distribution currentDistribution;

    public enum DistributionType { Gaussian, Uniform, Exponential, Triangular }

    public void InitializeDistributions(Configuration config)
    {
        foreach (var distribution in config.Distributions)
        {
            switch (distribution.Type)
            {
                case DistributionType.Gaussian:
                    distributions.Add(distribution.Name, new GaussianDistribution(distribution.Min, distribution.Max, distribution.StandardDeviation));
                    break;
                case DistributionType.Uniform:
                    distributions.Add(distribution.Name, new UniformDistribution(distribution.Min, distribution.Max));
                    break;
                case DistributionType.Exponential:
                    distributions.Add(distribution.Name, new ExponentialDistribution(distribution.Min, distribution.Max));
                    break;
                case DistributionType.Triangular:
                    distributions.Add(distribution.Name, new TriangularDistribution(distribution.Min, distribution.Mode, distribution.Max));
                    break;
            }
        }

        currentDistribution = config.DefaultDistribution;
    }

    public float GetRandomFloatValue(float min, float max)
    {
        return currentDistribution.Generate(min, max);
    }

    public int GetRandomIntValue(int min, int max)
    {
        return (int)GetRandomFloatValue(min, max + 1f - min);
    }

    public override string ToString()
    {
        return $"Range: [{currentDistribution.Min}, {currentDistribution.Max})\n" +
               $"Type: {currentDistribution.GetType().Name}\n" +
               $"Parameters: {string.Join(", ", currentDistribution.Parameters)}";
    }
}

public abstract class Distribution
{
    public float Min { get; set; }
    public float Max { get; set; }

    protected Distribution(float min, float max)
    {
        Min = min;
        Max = max;
    }

    public abstract float Generate(float min, float max);
}

public class GaussianDistribution : Distribution
{
    public float StandardDeviation { get; set; }

    public GaussianDistribution(float min, float max, float standardDeviation) 
        : base(min, max)
    {
        StandardDeviation = standardDeviation;
    }

    public override float Generate(float min, float max)
    {
        // Gaussian distribution implementation
        return UnityEngine.Random.Range(Min + StandardDeviation * UnityEngine.Random.Gaussian(), Max - StandardDeviation * UnityEngine.Random.Gaussian());
    }
}

public class UniformDistribution : Distribution
{
    public UniformDistribution(float min, float max) 
        : base(min, max)
    {
    }

    public override float Generate(float min, float max)
    {
        // Uniform distribution implementation
        return UnityEngine.Random.Range(Min, Max);
    }
}

public class ExponentialDistribution : Distribution
{
    public ExponentialDistribution(float min, float max) 
        : base(min, max)
    {
    }

    public override float Generate(float min, float max)
    {
        // Exponential distribution implementation
        return -Mathf.Log(UnityEngine.Random.value) * (Max - Min) + Min;
    }
}

public class TriangularDistribution : Distribution
{
    public float Mode { get; set; }

    public TriangularDistribution(float min, float mode, float max) 
        : base(min, max)
    {
        Mode = mode;
    }

    public override float Generate(float min, float max)
    {
        // Triangular distribution implementation
        return UnityEngine.Random.Range(Min, Mathf.Min(Max, Mode)) + (Mode - Min) * UnityEngine.Random.value;
    }
}
