function generateSecurePassword($password, $saltLength = 16, $characterSet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789', $algorithm = PASSWORD_BCRYPT) {
    if (!is_string($password)) {
        return array('error' => 'Invalid password');
    }

    if (!isset($saltLength) || !is_int($saltLength) || $saltLength < 8 || $saltLength > 64) {
        return array('error' => 'Invalid salt length');
    }

    if (!is_string($characterSet)) {
        return array('error' => 'Invalid character set');
    }

    if ($algorithm !== PASSWORD_DEFAULT && $algorithm !== PASSWORD_BCRYPT) {
        return array('error' => 'Unsupported hashing algorithm');
    }

    try {
        // Generate a random salt
        $salt = substr(str_shuffle($characterSet), 0, $saltLength);

        // Hash the password using the given algorithm and salt
        if ($algorithm === PASSWORD_BCRYPT) {
            $hashedPassword = password_hash($password, $algorithm, array('cost' => 12));
        } elseif ($algorithm === PASSWORD_DEFAULT) {
            $hashedPassword = password_hash($password, $algorithm);
        }

        return array(
            'salt' => $salt,
            'hashedPassword' => $hashedPassword
        );
    } catch (Exception $e) {
        error_log("Error generating secure password: " . $e->getMessage());
        return array('error' => 'An unexpected error occurred');
    }
}

function checkPassword($password, $salt, $hashedPassword, $algorithm = PASSWORD_BCRYPT) {
    if (!is_string($password)) {
        return array('error' => 'Invalid password');
    }

    if (!isset($salt) || !is_string($salt) || empty($salt)) {
        return array('error' => 'Invalid salt');
    }

    if (!isset($hashedPassword) || !is_string($hashedPassword)) {
        return array('error' => 'Invalid hashed password');
    }

    try {
        // Check if the given password matches the hashed password
        if ($algorithm === PASSWORD_BCRYPT) {
            if (password_verify($password, $hashedPassword)) {
                return true;
            }
        } elseif ($algorithm === PASSWORD_DEFAULT) {
            if (password_verify($password, $hashedPassword)) {
                return true;
            }
        }

        return false;
    } catch (Exception $e) {
        error_log("Error checking password: " . $e->getMessage());
        return array('error' => 'An unexpected error occurred');
    }
}
