Here is the C function that parses a TIFF image file and extracts information about the image's bits per sample and sample per pixel, along with the database connection and caching configurations:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <enviro.h>

typedef struct {
    int bits_per_sample;
    int samples_per_pixel;
} ImageInfo;

ImageInfo parse_tiff_image(const char *filename) {
    TIFF *tiff = NULL;
    tdir_t dir;
    uint16_t bitsPerSample;
    uint32_t samplesPerPixel;

    if (TIFFOpen(filename, "r") != 0) {
        return (ImageInfo){-1, -1}; // Error opening the file
    }

    TIFFGetField(tiff, TIFF_FIELD_BITSPERSAMPLE, &bitsPerSample);
    TIFFGetField(tiff, TIFF_FIELD_SAMPLESPERPIXEL, &samplesPerPixel);

    if (bitsPerSample != 1 && bitsPerSample != 2 && bitsPerSample != 4 &&
        bitsPerSample != 8 && bitsPerSample != 16) {
        // unsupported bits per sample
        return (ImageInfo){-1, -1};
    }

    ImageInfo imageInfo = (ImageInfo){
        .bits_per_sample = bitsPerSample,
        .samples_per_pixel = samplesPerPixel,
    };

    TIFFClose(tiff);
    return imageInfo;
}
```

