#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <enviro.h>

// Function to read environment variables from .env file
void load_env() {
    FILE *fp = fopen(".env", "r");
    if (fp != NULL) {
        char line[1024];
        while (fgets(line, 1024, fp)) {
            size_t pos = strcspn(line, "=");
            char var_name[pos + 1];
            memcpy(var_name, line, pos);
            var_name[pos] = '\0';
            char value[1024];
            strcpy(value, line + pos + 1);

            env_set(var_name, value);
        }
        fclose(fp);
    }

    // Load .env.local file if it exists
    fp = fopen(".env.local", "r");
    if (fp != NULL) {
        while (fgets(line, 1024, fp)) {
            size_t pos = strcspn(line, "=");
            char var_name[pos + 1];
            memcpy(var_name, line, pos);
            var_name[pos] = '\0';
            char value[1024];
            strcpy(value, line + pos + 1);

            env_set(var_name, value);
        }
        fclose(fp);
    }
}
