import org.springframework.http.HttpMethod;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;

@SpringBootApplication
@RestController
public class IoTMicroserviceApplication {

    @Autowired
    private KafkaProducer<String, String> kafkaProducer;

    @PostMapping("/data")
    public ResponseEntity<String> ingestData(@RequestBody String sensorData) {
        // Validate JSON format against dynamic schema provided by external configuration service
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(SerializationFeature.INDENT_OUTPUT);

        try {
            // Deserialize JSON data into a custom POJO class (e.g., SensorReading)
            SensorReading reading = mapper.readValue(sensorData, SensorReading.class);

            // Validate sensor data against dynamic schema
            // ...

            // Store validated data into Apache Kafka topic
            ProducerRecord<String, String> record = new ProducerRecord<>("iot-sensor-data", "key", sensorData);
            kafkaProducer.send(record);

            return ResponseEntity.status(HttpStatus.CREATED).body("Data ingested successfully!");
        } catch (Exception e) {
            // Handle errors: data inconsistencies, network failures, API call timeouts
            return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body("Error ingesting data: " + e.getMessage());
        }
    }

    @Bean
    public KafkaProducer<String, String> kafkaProducer() {
        return new KafkaProducer<>(
                Properties(props -> {
                    props.put(ProducerConfig.BOOTSTRAP_SERVERS, "localhost:9092");
                    props.put(ProducerConfig.KEY_SERIALIZER_CLASS, StringSerializer.class);
                    props.put(ProducerConfig.VALUE_SERIALIZER_CLASS, StringSerializer.class);
                }));
    }

    public static void main(String[] args) {
        SpringApplication.run(IoTMicroserviceApplication.class, args);
    }
}
