```rust
use reqwest::blocking::{get, Client};
use reqwest::header;
use std::time::Duration;
use std::collections::HashMap;
use log::{info, error};

struct HttpClientConfig {
    disable_certificate_validation: bool,
    retries: usize,
    retry_interval: Duration,
    timeout: Duration,
    custom_headers: HashMap<String, String>,
}

fn create_http_client(config: HttpClientConfig) -> Result<Client, Box<dyn std::error::Error>> {
    let mut client = if config.disable_certificate_validation {
        reqwest::blocking::ClientBuilder::new()
            .dangerously_allow_unsafe_locations(true)
            .build()?
    } else {
        reqwest::blocking::ClientBuilder::new().build()?
    };

    for (key, value) in &config.custom_headers {
        client = client.header(key.to_string(), value.to_string());
    }

    let mut request_builder = |url: &str| -> Result<Client, Box<dyn std::error::Error>> {
        info!("Making request to {}", url);
        let mut retries = 0;
        loop {
            match get(&client, url) {
                Ok(response) => {
                    if response.status().is_success() {
                        return Ok(client);
                    } else if response.status().is_client_error() || response.status().is_server_error() {
                        error!("Server error: {}", response.text().await.unwrap());
                        return Err( Box::new(std::io::Error::new(std::io::ErrorKind::Other, "Server error")) );
                    } else if response.status().is_redirect() {
                        let location = response.header("Location").unwrap();
                        info!("Redirecting to {}", location);
                        let new_url = url::Url::parse(&location)?;
                        *url = &new_url.to_string();
                    }
                }
                Err(err) => {
                    if retries < config.retries {
                        error!("Failed request: {} (attempt {}/{}), retrying in {}ms", err, retries + 1, config.retries, config.retry_interval.as_millis());
                        tokio::time::sleep(config.retry_interval).await;
                        continue;
                    } else {
                        error!("Failed request after {} attempts: {}", config.retries, err);
                        return Err( Box::new(std::io::Error::new(std::io::ErrorKind::Other, "Failed request")) );
                    }
                }
            }
        }
    };

    Ok(request_builder)
}
