function runTests(moduleName, testCases, setUpFunction) {
  try {
    const module = require(moduleName);
    for (const testCase of testCases) {
      if (setUpFunction) setUpFunction();
      console.log(`Running test ${testCase.name} for module ${moduleName}`);
      try {
        const result = testCase(module);
        console.log(`Test ${testCase.name} passed`);
      } catch (error) {
        console.error(`Test ${testCase.name} failed: ${error}`);
      }
      blueslip.reset(); // Reset mocking library after each test
    }
  } catch (error) {
    console.error(`Error running tests for module ${moduleName}: ${error}`);
  }
}
