const express = require('express');
const app = express();
const { OpenWeatherMapAPI, ClimateAPIService } = require('./api-integrations');
const { SecureMessagingLibrary } = require('./secure-messaging-library');

app.use(express.json());

// Initialize secure messaging library
SecureMessagingLibrary.init();

// Set up rate limiting
const rateLimiter = require('express-rate-limit');
app.use(rateLimiter({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  delayAfter: 5,
}));

// Implement API endpoint for fetching weather data
app.get('/weather', async (req, res) => {
  try {
    const location = req.query.location;
    const currentWeatherData = await OpenWeatherMapAPI.getCurrentWeather(location);
    const forecastData = await ClimateAPIService.getForecast(location, '7days');
    const averageTemperatureStats = await ClimateAPIService.getAverageTemperatureStats(location, '1year');
    const historicalClimateEvents = await ClimateAPIService.getHistoricalClimateEvents(location);

    res.json({
      currentWeather: currentWeatherData,
      forecast: forecastData,
      averageTemperatureStats,
      historicalClimateEvents,
    });
  } catch (error) {
    console.error(error);
    res.status(500).send({ message: 'Error fetching weather data' });
  }
});

// Implement API endpoint for fetching climate data
app.get('/climate', async (req, res) => {
  try {
    const location = req.query.location;
    const climateData = await ClimateAPIService.getClimateData(location);

    res.json(climateData);
  } catch (error) {
    console.error(error);
    res.status(500).send({ message: 'Error fetching climate data' });
  }
});

// Start the server
const port = process.env.PORT || 3000;
app.listen(port, () => {
  console.log(`Server started on port ${port}`);
});
