import java.io.BufferedReader;
import java.io.File;
import java.io.FileReader;
import java.io.IOException;
import java.util.Arrays;

public class Main {
    private static final int BUFFER_SIZE = 1024;

    public static void logError(String format, Object... args) {
        StringBuilder message = new StringBuilder();
        char[] buffer = new char[BUFFER_SIZE];
        snprintf(buffer, BUFFER_SIZE, format, args);
        message.append(buffer);
        System.out.println(message.toString());
    }

    public static int snprintf(char[] buffer, int length, String format, Object... args) {
        return java.lang.String.format(format, args).getChars(0, Math.min(length, java.lang.String.format(format, args).length()), buffer, 0);
    }

    public static void main(String[] args) {
        try {
            File logFile = new File("error.log");
            if (logFile.exists()) {
                logFile.delete();
            }
            ProcessBuilder builder = new ProcessBuilder("command", "with", "arguments");
            builder.directory(new File("/path/to/directory"));
            Process process = builder.start();

            BufferedReader outputReader = new BufferedReader(new FileReader(process.getInputStream()));
            StringBuilder outputMessage = new StringBuilder();
            String line;
            while ((line = outputReader.readLine()) != null) {
                logError("Output: %s%n", line);
                outputMessage.append(line).append("\n");
            }
            outputReader.close();

            BufferedReader errorReader = new BufferedReader(new FileReader(process.getErrorStream()));
            StringBuilder errorMessage = new StringBuilder();
            while ((line = errorReader.readLine()) != null) {
                logError("Error: %s%n", line);
                errorMessage.append(line).append("\n");
            }
            errorReader.close();

            process.waitFor();
        } catch (IOException | InterruptedException e) {
            logError("An error occurred: %s%n", Arrays.toString(e.getStackTrace()));
        }
    }
}

