    private static Dictionary<string, Distribution> _cache = new Dictionary<string, Distribution>();
    private string _currentDistribution;

    public void SetCurrentDistribution(string distributionName)
    {
        if (!_cache.ContainsKey(distributionName))
        {
            throw new ArgumentException($"Invalid distribution '{distributionName}'");
        }
        _currentDistribution = distributionName;
    }

    public float GetRandomFloatValue(float min, float max)
    {
        return _GetRandomValue(min, max);
    }

    public int GetRandomIntValue(int min, int max)
    {
        return (int)_GetRandomValue(min, max);
    }

    private float _GetRandomValue(float min, float max)
    {
        if (_currentDistribution == "Uniform")
            return UnityEngine.Random.Range(min, max);
        else if (_currentDistribution == "Gaussian")
            return GaussianDistribution(min, max);
        else if (_currentDistribution == "Exponential")
            return ExponentialDistribution(min, max);
        throw new ArgumentException("Invalid distribution");
    }

    private float GaussianDistribution(float min, float max)
    {
        // Gaussian implementation
    }

    private float ExponentialDistribution(float min, float max)
    {
        // Exponential implementation
    }

    public override string ToString()
    {
        return $"Range: {min} to {max}, Current Distribution: {_currentDistribution}";
    }
}
