int createAndConfigureNetworkPduList(NetworkPDUConfig_T **pduList, size_t *listSize, int maxStructures) {
    if (!pduList || !listSize || maxStructures <= 0) {
        LOG_ERROR("Invalid input parameters");
        return -1;
    }

    *listSize = 0;
    for (int i = 0; i < maxStructures && i < 5000; i++) {
        NetworkPDUConfig_T* pdu = new NetworkPDUConfig_T();
        if (!pdu) {
            LOG_ERROR("Memory allocation failure");
            return -1;
        }

        // Generate unique packet ID
        pdu->packetID = (i + 1);

        // Set source IP address using custom IP class
        pdu->sourceIP = IPAddress("192.168.1.100");

        // Set destination IP address using custom IP class
        pdu->destinationIP = IPAddress("8.8.8.8");

        // Randomly generate packet payload length
        pdu->packetPayloadLength = rand() % 1500 + 128;

        if (*listSize < maxStructures) {
            (*pduList)[*listSize] = pdu;
            (*listSize)++;
        } else {
            LOG_WARNING("Maximum structure limit reached");
        }
    }

    // Sort the configurations based on packet payload length in ascending order
    std::sort(&((*pduList))[0], &((*pduList)[*listSize - 1]) + 1, [](const NetworkPDUConfig_T& lhs, const NetworkPDUConfig_T& rhs) {
        return lhs.packetPayloadLength < rhs.packetPayloadLength;
    });

    return 0;
}
