public async Task<IActionResult> UpdatePageElement(string pageSectionId, string elementId, int versionId, string htmlContent)
{
    if (string.IsNullOrEmpty(pageSectionId))
        return BadRequest("Page section ID is required.");

    if (string.IsNullOrEmpty(elementId))
        return BadRequest("Element ID is required.");

    // Validate user permissions
    if (!await HasUpdatePermissions(pageSectionId, elementId))
        return Forbid();

    try
    {
        await UpdateElementAsync(pageSectionId, elementId, versionId, htmlContent);
        return Ok("Page should be refreshed.");
    }
    catch (Exception ex)
    {
        _logger.LogError(ex, "Error updating page element");
        return StatusCode(500, "Internal Server Error");
    }
}

private async Task UpdateElementAsync(string pageSectionId, string elementId, int versionId, string htmlContent)
{
    // Ensure atomic updates
    using (var transaction = await _dbContext.Database.BeginTransactionAsync())
    {
        try
        {
            // Check for existing updates and handle conflicts
            var existingVersion = await GetExistingVersion(elementId);
            if (existingVersion > 0 && versionId != existingVersion)
            {
                // Resolve conflict by merging changes or notifying users
                await HandleConflict(pageSectionId, elementId, htmlContent, existingVersion);
            }

            // Update element HTML content using a service class
            await _pageService.UpdateElementHtml(pageSectionId, elementId, htmlContent);

            // Log update
            await _logger.LogInformationAsync("Updated page element {0} with version {1}", elementId, versionId);

            transaction.Commit();
        }
        catch (Exception ex)
        {
            transaction.Rollback();
            _logger.LogError(ex, "Error updating page element");
            throw;
        }
    }
}

