// Define a record structure
typedef struct {
    int id;
    long offset1, offset2;
    int key1, key2;
    double average;
} Record;

// Function to read data from text file and populate the list of records
void process_file(char *filename) {
    FILE *file = fopen(filename, "r");

    if (file == NULL) {
        printf("Error opening file!\n");
        return;
    }

    MYSQL *mysql = mysql_init(NULL);
    if (!mysql_real_connect(mysql, "localhost", "username", "password", "database", 3306)) {
        printf("Error connecting to database: %s\n", mysql_error(mysql));
        fclose(file);
        return;
    }

    Record *record;
    int record_count = 0;

    while (fscanf(file, "%d %ld %ld %d %d", &record->id, &record->offset1, &record->offset2, &record->key1, &record->key2) == 5) {
        // Calculate the average of the last two fields
        record->average = (double)(record->key1 + record->key2) / 2.0;

        // Insert the record into the database
        if (!mysql_query(mysql, "INSERT INTO table_name (id, offset1, offset2, key1, key2, average) VALUES (%d, %ld, %ld, %d, %d, %f)", record->id, record->offset1, record->offset2, record->key1, record->key2, record->average)) {
            printf("Error inserting record: %s\n", mysql_error(mysql));
        } else {
            printf("Record inserted successfully!\n");
        }

        // Free the record
        free(record);
        record = NULL;
        record_count++;
    }

    fclose(file);
    mysql_close(mysql);

    if (record) {
        free(record);
    }
}
