```javascript
class TransactionReducer {
  constructor(config) {
    this.config = config;
    this.workerPool = new WorkerPool(this.config.concurrency);
  }

  async reduce(transactionIds, timeoutSeconds = 60) {
    const financialApiService = new FinancialApiService();

    try {
      if (!Array.isArray(transactionIds)) throw new Error('Invalid input type: Array expected');
      if (transactionIds.length === 0) return 0;

      const chunkSize = Math.ceil(transactionIds.length / this.config.concurrency);
      const chunks = [];
      for (let i = 0; i < transactionIds.length; i += chunkSize) {
        chunks.push(transactionIds.slice(i, i + chunkSize));
      }

      let totalAmount = 0;
      for await (const chunk of chunks) {
        const promises = chunk.map((id) => this workerPool.schedule(() => financialApiService.fetchTransactionAmount(id)));
        const amounts = await Promise.allSettled(promises);
        const validAmounts = amounts.filter(({ status }) => status === 'fulfilled').map(({ result }) => result.amount);

        if (validAmounts.length > 0) {
          totalAmount += validAmounts.reduce((acc, current) => acc + current, 0);
        } else {
          throw new Error('Invalid or missing transaction IDs');
        }

        console.log(`Processed chunk ${chunk.map((id) => id.toString()).join(', ')}, remaining: ${chunks.length - 1}`);
      }

      return totalAmount;
    } catch (error) {
      console.error(error);
      process.exit(1);
    } finally {
      await financialApiService.close();
    }
  }
}

class FinancialApiService {
  async fetchTransactionAmount(id) {
    // Simulated API call
    const response = await new Promise((resolve, reject) => setTimeout(() => resolve({ id, amount: Math.floor(Math.random() * 10000) }), 500));
    if (!response.ok) throw new Error('Failed to fetch transaction amount');

    return response.json();
  }

  async close() {
    // Close API connection
  }
}

class WorkerPool {
  constructor(concurrency) {
    this.concurrency = concurrency;
    this.workers = [];
  }

  schedule(task) {
    return new Promise((resolve, reject) => {
      const worker = { id: Date.now(), task, resolve, reject };
      this.workers.push(worker);
      if (this.workers.length < this.concurrency) {
        setTimeout(() => {
          this.processWorker();
        }, 0);
      } else {
        this.processWorker();
      }
    });
  }

  processWorker() {
    const worker = this.workers.shift();
    if (!worker) return;
    this.workers.push(worker);
    setTimeout(() => {
      this.processWorker();
    }, 0);

    // Run the task in a new scope
    (async () => {
      try {
        await worker.task;
        worker.resolve();
      } catch (error) {
        worker.reject(error);
      }
    })();
  }
}

// Example usage
const config = { concurrency: 5 };
const reducer = new TransactionReducer(config);

(async () => {
  const transactionIds = [...Array(10000)].map(() => Math.floor(Math.random() * 1000));
  console.time('Transaction Reduction');
  const totalAmount = await reducer.reduce(transactionIds);
  console.timeEnd('Transaction Reduction');
  console.log(`Total amount: ${totalAmount}`);
})();
