using System.Threading.Tasks;

namespace CustomDataStructureLoader
{
    public class DataStructureLoader
    {
        private readonly HttpClient _httpClient;
        private readonly BinaryFormatter _binaryFormatter;

        public DataStructureLoader(HttpClient httpClient, BinaryFormatter binaryFormatter)
        {
            _httpClient = httpClient;
            _binaryFormatter = binaryFormatter;
        }

        public async Task LoadAndDeserializeDataAsync(string filePath, string schemaVersion)
        {
            try
            {
                using (var fileStream = File.OpenRead(filePath))
                {
                    var dataStructure = await DeserializeDataAsync(fileStream, schemaVersion);
                    if (dataStructure == null)
                    {
                        throw new Exception("Failed to load or deserialize data.");
                    }

                    // Validate data structure against the latest schema
                    var validationResult = await ValidateDataAsync(dataStructure, schemaVersion);

                    if (!validationResult.IsValid)
                    {
                        throw new Exception($"Validation failed: {validationResult.ErrorMessage}");
                    }

                    Console.WriteLine("Data loaded and validated successfully!");
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error loading or deserializing data: {ex.Message}");
            }
        }

        private async Task<DataStructure> DeserializeDataAsync(Stream fileStream, string schemaVersion)
        {
            try
            {
                using (var binaryReader = new BinaryReader(fileStream))
                {
                    // Use a retry mechanism with exponential backoff for transient errors
                    var attempts = 0;
                    while (attempts < 3)
                    {
                        try
                        {
                            return _binaryFormatter.Deserialize(binaryReader) as DataStructure;
                        }
                        catch (IOException ex)
                        {
                            if (ex.HResult == -2147024882) // Eaten by another process
                            {
                                Console.WriteLine("Error deserializing data. Retrying in 5 seconds.");
                                await Task.Delay(5000);
                            }
                            else
                            {
                                throw;
                            }
                        }

                        attempts++;
                    }

                    throw new Exception("Failed to deserialize data after multiple retries.");
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error deserializing data: {ex.Message}");
            }
        }

        private async Task<ValidationResult> ValidateDataAsync(DataStructure dataStructure, string schemaVersion)
        {
            try
            {
                // Make a GET request to the external API for the latest schema definition
                var response = await _httpClient.GetAsync($"schema/{schemaVersion}");
                if (!response.IsSuccessStatusCode)
                {
                    throw new Exception("Failed to retrieve schema definition from the external API.");
                }

                var jsonContent = await response.Content.ReadAsStringAsync();
                // Use the retrieved schema to validate the data structure

                return ValidationResult.Valid;
            }
            catch (HttpRequestException ex)
            {
                Console.WriteLine($"Error validating data: {ex.Message}");
                return new ValidationResult { IsValid = false, ErrorMessage = "Transient error occurred during validation." };
            }
        }

        public async Task SerializeDataAsync(DataStructure dataStructure, string filePath, string schemaVersion)
        {
            try
            {
                using (var fileStream = File.OpenWrite(filePath))
                {
                    var formatter = new BinaryFormatter();
                    formatter.Serialize(fileStream, dataStructure);
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error serializing data: {ex.Message}");
            }
        }

        public enum ValidationResult
        {
            Valid,
            Invalid,
        }
    }
}
