    {
        aes.Key = Convert.FromBase64String(key);
        aes.IV = Convert.FromBase64String(iv);

        ICryptoTransform encryptor = aes.CreateEncryptor(aes.Key, aes.IV);

        using (MemoryStream ms = new MemoryStream())
        {
            using (CryptoStream cs = new CryptoStream(ms, encryptor, CryptoStreamMode.Write))
            {
                cs.Write(ciphertext, 0, ciphertext.Length);
            }

            byte[] plaintext = ms.ToArray();

            return Decrypt(plaintext, padding);
        }
    }
}

byte[] Decrypt(byte[] data, PaddingScheme padding)
{
    switch (padding)
    {
        case PaddingScheme.PKCS7:
            return DecryptPKCS7(data);
        case PaddingScheme.ANSIX923:
            return DecryptANSIX923(data);
        default:
            return DecryptNoPadding(data);
    }
}

byte[] DecryptPKCS7(byte[] data)
{
    // PKCS#7 padding implementation
}

byte[] DecryptANSIX923(byte[] data)
{
    // ANSI X9.23 padding implementation
}

byte[] DecryptNoPadding(byte[] data)
{
    // No padding scheme implementation
}

public enum PaddingScheme { PKCS7, ANSIX923, NoPadding }
