import java.io.File;
import java.io.FileReader;
import java.io.BufferedReader;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class FileProcessor {

    private static final String REGEX_ERROR = "error";
    private static final String REGEX_WARNING = "warning";

    public void processFiles(String directoryPath) throws IOException {
        File directory = new File(directoryPath);
        if (!directory.isDirectory()) {
            throw new IOException("Not a directory: " + directoryPath);
        }

        List<File> files = new ArrayList<>();
        for (File file : directory.listFiles()) {
            if (file.isFile() && file.getName().endsWith(".txt")) {
                files.add(file);
            }
        }

        ExecutorService executor = Executors.newFixedThreadPool(5);

        for (File file : files) {
            executor.submit(() -> processFile(file));
        }

        executor.shutdown();

        waitUntilFinished(executor);

        SummaryReport report = generateSummaryReport();
        sendNotification(report);
    }

    private void processFile(File file) throws IOException {
        Pattern patternError = Pattern.compile(REGEX_ERROR, Pattern.CASE_INSENSITIVE);
        Pattern patternWarning = Pattern.compile(REGEX_WARNING, Pattern.CASE_INSENSITIVE);

        try (BufferedReader br = new BufferedReader(new FileReader(file))) {
            String line;
            int errorCount = 0;
            int warningCount = 0;

            while ((line = br.readLine()) != null) {
                Matcher matcherError = patternError.matcher(line);
                Matcher matcherWarning = patternWarning.matcher(line);

                if (matcherError.find() || matcherWarning.find()) {
                    if (matcherError.find()) errorCount++;
                    else warningCount++;

                    // execute shell command via child process
                    Process process = Runtime.getRuntime().exec("your_shell_command");
                    BufferedReader stdInput = new BufferedReader(new InputStreamReader(process.getInputStream()));
                    String s;
                    while ((s = stdInput.readLine()) != null) {
                        System.out.println(s);
                    }
                }
            }

            if (errorCount > 0) {
                // output error summary
                System.out.println("Error count: " + errorCount);
            }

            if (warningCount > 0) {
                // output warning summary
                System.out.println("Warning count: " + warningCount);
            }
        }
    }

    private SummaryReport generateSummaryReport() {
        // implement logic to generate summary report
    }

    private void sendNotification(SummaryReport report) {
        // implement logic to send notification
    }

    private void waitUntilFinished(ExecutorService executor) throws InterruptedException {
        while (!executor.isTerminated()) {
            Thread.sleep(100);
        }
    }
}
