EVP_CIPHER_CTX* choose_cipher(const char* mode) {
    EVP_CIPHER_CTX* ctx = NULL;
    int i;

    // Define the supported cipher modes
    const char* supported_modes[] = {"ECB", "EDE", "EDE3", "CFB", NULL};
    EVP_CIPHER* ciphers[] = {EVP_des_ecb(), EVP_des_ede(), EVP_des_ede3(), EVP_des_cfb64(), NULL};

    // Validate the user input
    for (i = 0; supported_modes[i] != NULL; i++) {
        if (strcmp(mode, supported_modes[i]) == 0) {
            break;
        }
    }

    // Check if the mode is valid
    if (supported_modes[i] == NULL || ciphers[i] == NULL) {
        ERR_error_fp(stderr, "Invalid cipher mode");
        return ctx; // Return NULL to indicate an error
    }

    // Create a new EVP_CIPHER_CTX for the chosen cipher
    ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        ERR_error_fp(stderr, "Failed to create EVP_CIPHER_CTX");
        return NULL;
    }

    // Set the cipher context
    if (EVP_CipherInit_ex(ctx, ciphers[i], NULL, NULL, 0, 1) != 1) {
        ERR_error_fp(stderr, "Failed to initialize cipher context");
        EVP_CIPHER_CTX_free(ctx);
        ctx = NULL;
        return ctx; // Return NULL to indicate an error
    }

    return ctx;
}
