import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import com.google.common.cache.CacheBuilder;
import com.google.common.cache.LoadingCache;
import org.apache.commons.lang3.exception.ContextedException;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.lang.reflect.Constructor;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.TimeUnit;

public class DynamicNestedDeserializer {

    private final LoadingCache<String, ClassDefinition> cache = CacheBuilder
            .ofSize(1000) // cache size
            .expireAfterAccess(1, TimeUnit.MINUTES) // expire after 1 minute
            .build(new CacheLoader<>());

    public <T> List<T> deserialize(byte[] data, Class<T> rootClass) {
        List<T> result = new ArrayList<>();
        ByteArrayInputStream stream = new ByteArrayInputStream(data);
        ObjectMapper mapper = new ObjectMapper();

        try (ObjectMapper.Context context = mapper.getContext()) {
            T rootObject = mapper.readValue(stream, rootClass);
            Object currentObject = rootObject;

            while (currentObject != null) {
                ClassDefinition classDef = cache.getUnchecked(currentObject.getClass().getName());
                Constructor<?> constructor = classDef.getConstructor();
                Object[] args = getDeserializationArguments(currentObject, classDef);

                T nestedObject;
                try {
                    nestedObject = (T) constructor.newInstance(args);
                } catch (Exception e) {
                    throw new ContextedException("Failed to deserialize nested object: " + e.getMessage(), e);
                }

                result.add(nestedObject);
                currentObject = nestedObject;
            }
        } catch (IOException | ClassNotFoundException e) {
            throw new ContextedException("Error deserializing data: " + e.getMessage(), e);
        }

        return result;
    }

    private Object[] getDeserializationArguments(Object object, ClassDefinition classDef) {
        // TO DO: implement custom deserialization logic
        return null;
    }
}

class CacheLoader<K, V> implements com.google.common.cache.LoadingCache.LoadsResultLoader<K, V> {

