Record* records = NULL;
int record_count = 0;

void* load_configuration_file() {
    // Load configuration file and initialize random values
    FILE* file = fopen("config.txt", "r");
    if (file == NULL) {
        return NULL;
    }

    fseek(file, SEEK_END, SEEK_SET);
    long size = ftell(file);
    fseek(file, 0, SEEK_SET);
    char* buffer = malloc(size + 1);
    fread(buffer, 1, size, file);
    fclose(file);

    // Initialize records with unique values within the specified range
    for (int i = 0; i < RECORDS; i++) {
        Record record;
        record.key = rand() % OFFSET_RANGE;
        record.offset = rand() % OFFSET_RANGE;
        if (record.records == NULL) {
            record_count++;
        }
        // Add error handling for memory allocation
    }

    free(buffer);
    return &records;
}

void initialize_memory_allocation() {
    // Allocate memory for the records array
    records = mmap(NULL, RECORDS * sizeof(Record), PROT_READ | PROT_WRITE,
                     MAP_SHARED | MAP_ANONYMOUS, -1, 0);
    if (records == MAP_FAILED) {
        return;
    }

    // Initialize the record count
    record_count = 0;

    return;
}

void finalize_memory_allocation() {
    // Release memory for the records array
    munmap(records, RECORDS * sizeof(Record));

    return;
}

int get_record(int key) {
    // Search for a specific record based on its integer key
    for (int i = 0; i < record_count; i++) {
        if (records[i].key == key) {
            return i;
        }
    }

