import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.google.common.cache.CacheBuilder;
import com.google.common.cache.CacheLoader;
import com.google.common.cache.LoadingCache;

import java.io.IOException;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.RejectedExecutionHandler;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;

public class PokemonService {
    private static final int MAX_CONCURRENT_REQUESTS = 1000;
    private static final int CACHE_SIZE = 10000;
    private static final long CACHE_EXPIRATION = 60 * 1000; // 1 minute

    private final LoadingCache<String, PokemonData> pokemonCache = CacheBuilder.newBuilder()
            .maximumSize(CACHE_SIZE)
            .expireAfterWrite(CACHE_EXPIRATION, TimeUnit.MILLISECONDS)
            .build(new CacheLoader<String, PokemonData>() {
                public PokemonData load(String pokemonId) throws Exception {
                    // Call external REST API to fetch Pokemon data
                    String response = HttpClient.get("https://api.example.com/pokemon/" + pokemonId);
                    ObjectMapper mapper = new ObjectMapper();
                    JsonNode node = mapper.readTree(response);

                    // Extract relevant information from the JSON response
                    String name = node.get("name").asText();
                    JsonNode typesNode = node.get("types");
                    List<String> types = Arrays.asList(typesNode.asText().split(","));
                    JsonNode weaknessesNode = node.get("weaknesses");
                    List<String> weaknesses = Arrays.asList(weaknessesNode.asText().split(","));
                    JsonNode evolutionNode = node.get("evolution");

                    // Extract next evolution stage details
                    String nextEvolutionName = null;
                    int nextEvolutionLevel = 0;
                    if (evolutionNode.isArray()) {
                        for (JsonNode evolution : evolutionNode) {
                            if (evolution.has("name") && evolution.has("level")) {
                                nextEvolutionName = evolution.get("name").asText();
                                nextEvolutionLevel = evolution.get("level").asInt();
                                break;
                            }
                        }
                    }

                    return new PokemonData(name, types, weaknesses, nextEvolutionName, nextEvolutionLevel);
                }
            });

    private final ExecutorService executor = Executors.newFixedThreadPool(MAX_CONCURRENT_REQUESTS);

    public PokemonService() {
        // Initialize thread pool with a queue
        ThreadPoolExecutor threadPool = (ThreadPoolExecutor) executor;
        threadPool.setCorePoolSize(MAX_CONCURRENT_REQUESTS);
        threadPool.setMaxPoolSize(MAX_CONCURRENT_REQUESTS);
        threadPool.setQueueCapacity(1000); // 1000 requests in the queue
        threadPool.setRejectedExecutionHandler(new RejectedExecutionHandler() {
            public void rejectedExecution(Runnable r, ThreadPoolExecutor executor) {
                try {
                    Thread.sleep(1000); // 1 second
                    executor.getQueue().put(r);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        });
    }

    public PokemonData getPokemonData(String pokemonId) throws ExecutionException, InterruptedException {
        return pokemonCache.get(pokemonId);
    }

