        incident_data = {
            'error_message': log_content,
            'severity': severity
        }
        response = incidents_client.post(INCIDENT_MANAGEMENT_SYSTEM_URL, json=incident_data)
        if response.status_code == 201:
            nlp_logger.info(f'Incident created: {response.json()["id"]}')
        else:
            nlp_logger.error(f'Failed to create incident: {response.text}')
    except Exception as e:
