# Alert mechanism
def send_alert(severity):
    if severity >= ALERT_SEVERITY_THRESHOLDS[0]:
        for channel in ALERT_CHANNELS[:1]:  # prioritize email
            send_channel(channel)
    elif severity >= ALERT_SEVERITY_THRESHOLDS[1]:
        for channel in ALERT_CHANNELS[1:]:
