```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define a structure for a single resource item in the bundle
typedef struct {
    int id;
    char* name;
} ResourceItem;

// Define a function to load a resource bundle from a file and return the number of items
int loadResourceBundle(const char* filePath) {
    FILE* file = fopen(filePath, "rb");
    if (file == NULL) {
        printf("Error opening file: %s\n", filePath);
        return -1; // Return error code to indicate failure
    }

    int itemCount = 0;
    ResourceItem* bundle = NULL;

    // Allocate memory for the resource bundle using dynamic memory allocation
    size_t bundleSize = sizeof(ResourceItem) * 100; // Initial capacity
    bundle = (ResourceItem*)malloc(bundleSize);

    if (bundle == NULL) {
        printf("Error allocating memory: %s\n", "failed to allocate");
        fclose(file);
        return -1; // Return error code to indicate failure
    }

    while (fscanf(file, "%d %s\n", &bundle[itemCount].id, bundle[itemCount].name) == 2) {
        itemCount++;

        // Check if the file has reached its end and we need to reallocate memory
        if (itemCount * sizeof(ResourceItem) >= bundleSize) {
            bundleSize *= 2; // Double the capacity
            void* temp = realloc(bundle, bundleSize);
            if (temp == NULL) {
                printf("Error allocating memory: %s\n", "failed to allocate");
                fclose(file);
                free(bundle);
                return -1; // Return error code to indicate failure
            }
            bundle = temp;
        }
    }

    fclose(file);

    // Free the remaining resources and clear the bundle
    for (int i = 0; i < itemCount; i++) {
        free(bundle[i].name);
    }
    free(bundle);

    return itemCount;
}

// Unit tests to validate the functionality and performance of your solution under different conditions.
#include "unit_test.h"

void testLoadResourceBundle() {
    const char* filePath = "resource_bundle.txt";
    int expectedItemCount = 10;

    int actualItemCount = loadResourceBundle(filePath);
    assert(actualItemCount == expectedItemCount);

    // Test for file access issues
    actualItemCount = loadResourceBundle("non_existent_file.txt");
    assert(actualItemCount == -1);

    // Test for corrupted data
    actualItemCount = loadResourceBundle("corrupted_data.txt");
    assert(actualItemCount == -1);
}

int main() {
    testLoadResourceBundle();
    return 0;
}
