# Assuming you have a User model defined elsewhere in your codebase
users = []

def update_user_profile():
    user_id = request.json.get('user_id')
    updated_data = request.json

    if not isinstance(user_id, int):
        return jsonify({'error': 'Invalid user ID'}), 400

    for user in users:
        if user['id'] == user_id:
            existing_data = user.copy()
            break
    else:
        return jsonify({'error': 'User not found'}), 404

    # Merging updated data with the existing profile data efficiently
    updated_user = {**existing_data, **updated_data}

    return jsonify(updated_user)

def soft_delete_user_profile():
    user_id = request.json.get('user_id')

    if not isinstance(user_id, int):
        return jsonify({'error': 'Invalid user ID'}), 400

    for i, user in enumerate(users):
        if user['id'] == user_id:
            users.pop(i)
            break
    else:
        return jsonify({'error': 'User not found'}), 404

    # Return a list of all active profiles in the system after deletion
    return jsonify([user for user in users])

@app.route('/users', methods=['PUT'])
def update_user():
    return update_user_profile()

@app.route('/users', methods=['PATCH'])
def soft_delete_user():
    return soft_delete_user_profile()
