import java.util.HashMap;
import java.util.Map;
import java.io.IOException;
import javax.net.ssl.SSLContext;
import io.netty.bootstrap.Bootstrap;
import io.netty.channel.Channel;
import io.netty.channel.EventLoopGroup;
import io.netty.channel.nio.NioEventLoopGroup;
import io.netty.handler.codec.http.DefaultHttpContent;
import io.netty.handler.codec.http.HttpHeaders;
import io.netty.handler.codec.http.HttpObjectMessage;
import io.netty.handler.codec.http.LastHttpContent;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.context.annotation.Bean;
import org.springframework.data.jpa.repository.config.EnableJpaRepositories;

@SpringBootApplication
@EnableJpaRepositories
public class ChatApplication {

    @Bean
    public EventLoopGroup bossGroup() {
        return new NioEventLoopGroup();
    }

    @Bean
    public EventLoopGroup workerGroup() {
        return new NioEventLoopGroup();
    }

    @Bean
    public SSLContext sslContext() throws Exception {
        SSLContext context = SSLContext.getInstance("TLS");
        context.init(null, null, null);
        return context;
    }

    @Bean
    public Bootstrap bootstrap(Bootstrap bootstrap) {
        bootstrap.group(bossGroup());
        bootstrap.channel(Channel.class);
        return bootstrap;
    }

    @Bean
    public Map<String, Object> config() {
        Map<String, Object> config = new HashMap<>();
        config.put("messaging.service.sms", "com.example.SMSAdapter");
        config.put("messaging.service.email", "com.example.EmailAdapter");
        config.put("messaging.service.social.media", "com.example.SocialMediaAdapter");
        return config;
    }

    @Bean
    public DefaultHttpContent defaultHttpContent() {
        return new DefaultHttpContent();
    }

    @Bean
    public LastHttpContent lastHttpContent() {
        return new LastHttpContent();
    }

    @Bean
    public HttpHeaders httpHeaders() {
        return new HttpHeaders();
    }

    public static void main(String[] args) throws IOException {
        SpringApplication.run(ChatApplication.class, args);
    }
}
