import io.vertx.core.Vertx;
import io.vertx.core.http.HttpServerRequest;
import io.vertx.ext.web.WebClient;
import io.vertx.ext.web.client.WebClientOptions;
import org.apache.commons.lang3.StringUtils;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.io.IOException;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.atomic.AtomicInteger;

public class EvolutionService {
    private static final Logger LOGGER = LoggerFactory.getLogger(EvolutionService.class);
    private static final Gson GSON = new GsonBuilder().setPrettyPrinting().create();
    private static final Map<String, ClassDefinition> CLASS_CACHE = new HashMap<>();
    private static final AtomicInteger REQUEST_COUNT = new AtomicInteger(0);

    public EvolutionService(Vertx vertx) {
        WebClient webClient = WebClient.create(vertx);
        webClient.setWebClientOptions(new WebClientOptions()
                .setConnectTimeout(10000)
                .setRequestTimeout(20000));
    }

    public void handleRequest(HttpServerRequest request) {
        String pokemonId = request.getParam("pokemonId");
        if (StringUtils.isEmpty(pokemonId)) {
            sendError(request, 400, "Invalid Pokemon ID");
            return;
        }
        ClassDefinition classDefinition = getClassDefinitionFromCache(pokemonId);
        if (classDefinition == null) {
            // Fetch data from multiple APIs and merge
            try {
                Map<String, Object> responseMap = fetchPokemonData(pokemonId);
                classDefinition = new ClassDefinition(responseMap);
                cacheClassDefinition(classDefinition);
            } catch (Exception e) {
                sendError(request, 500, "Failed to retrieve Pokemon data: " + e.getMessage());
                return;
            }
        }
        // Send response
        request.response().putHeader("Content-Type", "application/json").end(GSON.toJson(classDefinition));
    }

    private ClassDefinition getClassDefinitionFromCache(String pokemonId) {
        if (CLASS_CACHE.containsKey(pokemonId)) {
            REQUEST_COUNT.incrementAndGet();
            return CLASS_CACHE.get(pokemonId);
        }
        return null;
    }

    private void cacheClassDefinition(ClassDefinition classDefinition) {
        CLASS_CACHE.put(classDefinition.getPokemonId(), classDefinition);
    }

    private Map<String, Object> fetchPokemonData(String pokemonId) {
        // Implement logic to fetch data from multiple APIs and merge
        // For demonstration purposes, assume a simple API response
        return new HashMap<>() {{
            put("name", "Pikachu");
            put("type", "Electric");
            put("weaknesses", Arrays.asList("Rock", "Steel"));
            put("currentEvolution", "Raichu");
            put("nextEvolution", null);
        }};
    }

    private void sendError(HttpServerRequest request, int status, String message) {
        request.response().setStatusCode(status).putHeader("Content-Type", "text/plain").end(message);
    }
}
