            {
                _logger.LogError("Invalid directory path or user ID");
                return;
            }

            // Create a cache for storing validated user IDs and API responses
            var cache = new Dictionary<string, object>();

            // Define a function to update a single user's profile
            async Task UpdateUserProfileAsync(int userId, Dictionary<string, string> profileDetails)
            {
                // Validate the user ID and profile details
                if (!ValidateUserIdAndProfileDetails(userId, profileDetails))
                {
                    _logger.LogError("Invalid user ID or profile details");
                    return;
                }

                // Prioritize critical updates (email and phone number) before less critical ones
                var priority = GetPriority(profileDetails);

                // Implement a mechanism to prioritize critical updates based on predefined rules
                if (priority >= 2)
                {
                    await UpdateEmailAndPhoneNumberAsync(userId, profileDetails);
