import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.FileReader;
import java.io.FileWriter;
import java.io.IOException;
import java.text.SimpleDateFormat;
import java.util.Date;

public class Main {
    private static final int MAX_RETRIES = 3;
    private static final int INITIAL_BACKOFF = 1000; // in milliseconds

    public static void main(String[] args) {
        if (checkAndDeleteConfigFile()) {
            for (String command : getCommandsToExecute()) {
                executeCommand(command);
            }
        } else {
            System.out.println("Error: Configuration file exists. Aborting.");
        }
    }

    private static boolean checkAndDeleteConfigFile() {
        File configFile = new File("config.txt");
        if (configFile.exists()) {
            configFile.delete();
            return true;
        }
        return false;
    }

    private static String[] getCommandsToExecute() {
        // return your commands here
        return new String[]{"command1", "command2", "command3"};
    }

    private static void executeCommand(String command) {
        for (int i = 0; i <= MAX_RETRIES; i++) {
            try {
                Process process = Runtime.getRuntime().exec(command);
                BufferedReader stdoutReader = new BufferedReader(new InputStreamReader(process.getInputStream()));
                BufferedReader stderrReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));

                String line;
                while ((line = stdoutReader.readLine()) != null) {
                    logMessage(line, "stdout");
                }
                while ((line = stderrReader.readLine()) != null) {
                    logMessage(line, "stderr");
                }

                int exitCode = process.waitFor();
                if (exitCode == 0) {
                    break;
                } else {
                    logMessage("Command failed: " + command, "error");
                    long backoffTime = (long) Math.pow(2, i) * INITIAL_BACKOFF;
                    try {
                        Thread.sleep(backoffTime);
                    } catch (InterruptedException e) {
                        // handle interrupt
                    }
                }
            } catch (IOException | InterruptedException e) {
                logMessage("Error executing command: " + command, "error");
                break;
            }
        }
    }

    private static void logMessage(String message, String type) {
        SimpleDateFormat dateFormat = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
        Date date = new Date();
        String formattedDate = dateFormat.format(date);
        char[] buffer = new char[256];
        snprintf(buffer, "Error: [" + formattedDate + "] [" + type + "] " + message, 0);

        System.out.println(new String(buffer));
    }
}
