function updateClinicStatus($clinic_id, $new_status, $last_modified_ip) {
    // Initialize rate limiter with a bucket size of 5 requests per minute
    $bucket = new TokenBucket(5, 60);

    // Verify clinic details through an external API call before performing the update
    $api_response = json_decode(file_get_contents('https://patient-management-system.com/api/clinics/' . $clinic_id), true);

    if ($api_response['status'] !== 'active') {
        return 'Invalid clinic details';
    }

    // Check if rate limit is exceeded for the current IP address
    if (!$bucket->try_acquire()) {
        return 'Rate limit exceeded. Please try again later.';
    }

    $query = "UPDATE clinics SET status = ?, last_modified_ip = ?, last_modified_date = NOW() WHERE id = ?";
    $stmt = db_connect()->prepare($query);
    $stmt->execute(array($new_status, $last_modified_ip, $clinic_id));

    if ($stmt->rowCount()) {
        return 'Clinic status updated successfully';
    } else {
        return 'Failed to update clinic status. Please try again later.';
    }
}
