#include <pthread.h>
#include <semaphore.h>

typedef struct {
    int transaction_id;
    double amount;
    time_t timestamp;
    char* category;
} Transaction;

typedef struct {
    int category_id; // Unique identifier for each category
    double total_amount;
    double max_weighted_sum;
} Metrics;

Metrics filter_transactions(Transaction* transactions, size_t num_transactions, time_t base_timestamp) {
    // Initialize metrics
    Metrics* category_metrics = ...; // Assume this is pre-allocated and initialized elsewhere

    // Initialize semaphore for synchronization
    sem_t lock_sem;
    if (sem_init(&lock_sem, 0, 1) != 0) {
        // Error handling
    }

    // Process transactions
    time_t current_time = time(NULL);
    size_t processed_transactions = 0;
    Transaction* curr_transaction = &transactions[0];
    while (num_transactions-- > 0) {
        if (curr_transaction->timestamp < current_time - 5 * 60) { // 5 minutes ago
            if (processed_transactions++ >= 100) {
                sem_wait(&lock_sem);
                sleep(1); // Wait for 1 second to avoid over-processing
                sem_post(&lock_sem);
            }
            double weight = 1.0 / (curr_transaction->timestamp - base_timestamp);
            weight = fmin(weight, 1.0 / 600.0); // Ensure weight does not exceed 1/6th of a minute

            int category_id = ...; // Assume this is pre-allocated and initialized elsewhere
            Metrics* curr_category_metrics = &category_metrics[category_id];
            curr_category_metrics->total_amount += curr_transaction->amount * weight;
            if (curr_category_metrics->max_weighted_sum < curr_category_metrics->total_amount) {
                curr_category_metrics->max_weighted_sum = curr_category_metrics->total_amount;
            }

            // Update metrics
            sem_wait(&lock_sem);
            pthread_mutex_lock();
            // ...
            pthread_mutex_unlock();
            sem_post(&lock_sem);
        }
        curr_transaction++;
    }

    // Find category with maximum weighted sum
    int max_weighted_sum_category_id = ...; // Assume this is pre-allocated and initialized elsewhere
    double max_weighted_sum = 0.0;
    Transaction* max_weighted_sum_transaction = NULL;

    for (int i = 0; i < ...; i++) { // Assume the number of categories is pre-defined
        Metrics* curr_category_metrics = &category_metrics[i];
        if (curr_category_metrics->max_weighted_sum > max_weighted_sum) {
            max_weighted_sum = curr_category_metrics->max_weighted_sum;
            max_weighted_sum_category_id = i;
            max_weighted_sum_transaction = ...; // Assume this is pre-allocated and initialized elsewhere
        }
    }

    // Return the category with maximum weighted sum
    Metrics result;
    result.category_id = max_weighted_sum_category_id;
    result.max_weighted_sum_transaction_id = max_weighted_sum_transaction->transaction_id;
    result.timestamp = max_weighted_sum_transaction->timestamp;

    return result;
}
