import asyncio
import logging
from aiohttp import ClientSession
import requests

logging.basicConfig(filename='payment_errors.log', level=logging.ERROR)

async def process_order_payment(order_id: int, payment_amount: float, customer_ip: str, shipping_address: dict):
    session = ClientSession()

    async with session.get('https://order-management-system.com/api/orders/{}'.format(order_id)) as response:
        order_data = await response.json()

    if not order_data or order_data['status'] != 'pending':
        return {'error': 'Invalid or cancelled order'}

    payment_gateway_url = 'https://payment-gateway.com/api/payments'
    async with session.post(payment_gateway_url, json={'amount': payment_amount}) as payment_response:
        payment_result = await payment_response.json()

    if payment_result['status'] == 'failed':
        logging.error('Payment failed: {}'.format(payment_result['error']))

        # Implement retry mechanism
        for i in range(1, 4):
            if i > 1:
                await asyncio.sleep(2 ** i)

            async with session.post(payment_gateway_url, json={'amount': payment_amount}) as payment_response:
                payment_result = await payment_response.json()

            if payment_result['status'] == 'success':
                break

        else:
            return {'error': 'Payment failed after retries'}

    shipping_api_url = 'https://shipping-api.com/api/update_status'
    data = {'order_id': order_id, 'status': 'shipped', 'address': shipping_address}
    async with session.post(shipping_api_url, json=data) as response:
        if response.status == 200:
            return {'message': 'Order payment processed successfully'}

        else:
            logging.error('Failed to update order status: {}'.format(response.text))
            return {'error': 'Failed to update order status'}

    await session.close()
