#include <openssl/aes.h>
#include <openssl/err.h>
#include <openssl/pbkdf2.h>

// Function to initialize AES-256-GCM cipher with password and salt
int init_cipher(const char* password, const unsigned char* salt, int salt_len,
                unsigned char** key, unsigned char** iv, EVP_CIPHER_CTX** ctx) {
    // Set the PBKDF2 iteration count for key stretching
    int iterations = 100000;

    // Create a new EVP_CIPHER_CTX object
    *ctx = EVP_CIPHER_CTX_new();
    if (*ctx == NULL) {
        return 0; // Error creating cipher context
    }

    // Initialize AES-256-GCM with GCM mode and 96-bit IV length
    if (!EVP_CipherInit_ex(*ctx, EVP_aes_256_gcm(), NULL, NULL, NULL)) {
        ERR_error_proc(NULL, NULL); // Log error and cleanup
        return 0; // Error initializing cipher context
    }

    // Set the IV length to 96 bits (12 bytes)
    unsigned char iv_len = 12;

    if (!EVP_CipherInit_ex(*ctx, NULL, NULL, NULL, &iv_len)) {
        ERR_error_proc(NULL, NULL); // Log error and cleanup
        return 0; // Error initializing cipher context
    }

    // Derive the encryption key using PBKDF2 with SHA-256
    unsigned char* derived_key = malloc(AES_BLOCK_SIZE);
    if (derived_key == NULL) {
        ERR_error_proc(NULL, NULL); // Log error and cleanup
        return 0; // Error allocating memory for derived key
    }

    int deriv_len = PBKDF2_hmac_sha256(*ctx, password, salt_len, salt, iterations,
                                        AES_BLOCK_SIZE, derived_key);

    if (deriv_len < AES_BLOCK_SIZE) {
        ERR_error_proc(NULL, NULL); // Log error and cleanup
        free(derived_key);
        return 0; // Error deriving key using PBKDF2
    }

    // Set the encryption key in the cipher context
    if (!EVP_CipherInit_ex(*ctx, NULL, NULL, derived_key, NULL)) {
        ERR_error_proc(NULL, NULL); // Log error and cleanup
        free(derived_key);
        return 0; // Error setting encryption key in cipher context
    }

    // Set the IV in the cipher context
    if (!EVP_CipherInit_ex(*ctx, NULL, NULL, NULL, iv)) {
        ERR_error_proc(NULL, NULL); // Log error and cleanup
        free(derived_key);
        return 0; // Error setting IV in cipher context
    }

    *key = derived_key;

    return 1; // Cipher initialization successful
}

// Function to clean up and disable the cipher when it is no longer needed
int clean_up_cipher(EVP_CIPHER_CTX* ctx) {
    if (!EVP_CipherFinal_ex(ctx)) {
        ERR_error_proc(NULL, NULL); // Log error and cleanup
        return 0; // Error finalizing cipher context
    }

    EVP_CIPHER_CTX_free(ctx);

    return 1; // Cipher cleaning up successfully
}

// Example usage:
int main() {
    const char* password = "my_secret_password";
    unsigned char* salt = (unsigned char*) "my_salt_value";
    int salt_len = strlen((char*)salt);

    unsigned char* key = NULL;
    unsigned char* iv = NULL;
    EVP_CIPHER_CTX* ctx = NULL;

    if (init_cipher(password, salt, salt_len, &key, &iv, &ctx)) {
        // Use the cipher for encryption/decryption
    }

    clean_up_cipher(ctx);

    return 0;
}
