        this.quantity = quantity;
    }
}

// Define the OrderFulfillment class
public class OrderFulfillment {
    private Cassandra client;

    public OrderFulfillment(Cassandra client) {
        this.client = client;
    }

    // Method to fulfill orders
    public void fulfillOrder(Order order) {
        lock.lock();
        try {
            // Get the available stock for the product in the warehouse
            Product product = client.get("inventory", "products", order.getWarehouseId(), order.getProductId());

            if (product.getQuantity() >= order.getQuantity()) {
                // Update the inventory levels and fulfill the order
                client.update("inventory", "products", order.getWarehouseId(), order.getProductId(), "quantity", product.getQuantity() - order.getQuantity());
                System.out.println("Order fulfilled successfully!");
            } else {
                System.out.println("Insufficient stock to fulfill the order.");
            }
        } finally {
            lock.unlock();
        }
    }
}

