table_name = 'resources'

def update_resource(resource_id, body):
    try:
        resource = table_name.get_item(Key={'id': resource_id})['Item']
        for key, value in body.items():
            if key in resource:
                resource[key] = value
        table_name.update_item(Key={'id': resource_id}, UpdateExpression='set #fields = :vals', 
                                ExpressionAttributeNames={'#fields': 'fields'}, 
                                ExpressionAttributeValues={":vals": {k: v for k, v in body.items()}})
        return {'message': f'Resource {resource_id} updated successfully'}
    except KeyError as e:
        return {'error': f'Invalid resource id: {e}'}
    except Exception as e:
        return {'error': str(e)}

def delete_resource(resource_id):
    try:
        table_name.delete_item(Key={'id': resource_id})
        # Cascade deletion of related resources
        related_resources = dynamodb.Table('related_resources').scan(Filters=[
            {'AttributeNames': ['resource_id'], 'AttributeValueList': [resource_id]}
        ])
        for resource in related_resources['Items']:
            dynamodb.Table('related_resources').delete_item(Key={'id': resource['id']})
        return {'message': f'Resource {resource_id} deleted successfully'}
    except KeyError as e:
        return {'error': f'Invalid resource id: {e}'}
    except Exception as e:
        # Return a new resource with default values
        return {'resource': {'fields': []}, 'message': 'Deletion failed, but default resource created'}

