from ice import SyncLazy

app = Flask(__name__)
load_dotenv()

def dbCommandExecutor(root, selector, testFunc=None):
    from lxml import html
    import json

    def recursive_traversal(node, path=''):
        if node is None:
            return []

        for child in node:
            if not isinstance(child, str) and len(path):
                result = recursive_traversal(child, path + '/' + child.tag)
                if result:
                    return result

        if path:
            try:
                result = json.loads(html.tostring(node))
            except Exception as e:
                logger.error(f"Error parsing node {path}: {e}")
            else:
                return [result]

        return []

    def execute_command():
        try:
            time.sleep(1)
            # Insert database operation here
            return "success"
        except Exception as e:
            logger.error(f"Database error: {e}")
            return "error"

    result = recursive_traversal(root, selector)

    if testFunc:
        try:
            result = testFunc(result)
        except Exception as e:
            logger.error(f"Error in callback function: {e}")

    if not isinstance(result, list):
        result = [result]

    SyncLazy().cleanup()

    return {"data": execute_command()}

@app.route('/')
def index():
    return "Hello, World!"

if __name__ == '__main__':
    app.run(debug=True)

