#include <zip.h>
#include <string.h>
#include <stdlib.h>

int load_resource_bundle(const char* zip_file_path) {
    zip_file_t* zip_file = zip_fopen(zip_file_path, ZIP_READ);
    if (zip_file == NULL) return -1; // File not found or unable to open

    int num_items = 0;
    zip_entry_t* entry;
    while ((entry = zip_fread(zip_file, ZIP_LONG)) != NULL) {
        const char* file_name = zip_entry_name(entry);
        if (file_name == NULL || strlen(file_name) > 256) continue; // Ignore corrupted or too large entries

        // Fetch additional metadata related to the resource item
        struct stat statbuf;
        fstatat(AT_FDCWD, file_name, &statbuf, AT_SYMLINK_NOFOLLOW);
        int metadata_size = statbuf.st_size;

        // Dynamically allocate memory for the resource bundle item
        void* buffer = malloc(metadata_size + 1);
        if (buffer == NULL) return -2; // Memory allocation failure

        zip_file_t* file_in_zip = zip_fopen(zip_file_path, ZIP_READ);
        zip_entry_t* entry_in_zip = zip_findex(file_in_zip, file_name);
        void* data = malloc(metadata_size + 1);
        if (data == NULL) {
            free(buffer); // Free the allocated memory in case of error
            return -2; // Memory allocation failure
        }

        size_t bytes_read = zip_fread(file_in_zip, entry_in_zip, buffer, metadata_size);
        if (bytes_read < 0) { // Read failed or corrupted data
            free(buffer); free(data); 
            return -3;
        }
        *(char*)data = '\0'; // Null-terminate the buffer
        memcpy(data, buffer, bytes_read);

        num_items++;
        free(buffer);
        free(data);

        zip_fclose(file_in_zip);
    }

    zip_fclose(zip_file);
    return num_items;
}
