import asyncio
from aiohttp import ClientSession, request
import json
import logging
import sqlite3

class WebScraper:
    def __init__(self):
        self.log = logging.getLogger(__name__)
        self.session = ClientSession()
        self.db_file = 'data.db'
        self.schemas = {}

    async def fetch(self, url):
        try:
            response = await request('GET', url)
            return await response.text()
        except asyncio.CancelledError:
            raise
        except Exception as e:
            self.log.error(f'Failed to fetch {url}: {e}')
            return None

    async def scrape(self, url):
        data = await self.fetch(url)
        if not data:
            return None

        try:
            parsed_data = json.loads(data)
        except ValueError as e:
            self.log.warning(f'Failed to parse JSON from {url}: {e}')
            return None

        return parsed_data

    async def save_to_db(self, data):
        conn = sqlite3.connect(self.db_file)
        cursor = conn.cursor()

        try:
            if not self.schemas.get(data['source']):
                await self.create_schema(cursor, data)

            query = f"INSERT INTO {data['table']} ({', '.join(data['fields'])}) VALUES ({', '.join(['?'] * len(data['fields']))})"
            cursor.execute(query, list(data.values())[1:])
            conn.commit()
        except Exception as e:
            self.log.error(f'Failed to save data to database: {e}')
        finally:
            cursor.close()
            conn.close()

    async def create_schema(self, cursor, data):
        query = f"CREATE TABLE IF NOT EXISTS {data['table']} ({', '.join([f'{column} TEXT' for column in data['fields']])})"
        try:
            cursor.execute(query)
        except Exception as e:
            self.log.error(f'Failed to create table: {e}')
        finally:
            await cursor.close()

    async def run(self):
        while True:
            tasks = []
            for source, urls in self.config.items():
                for url in urls:
                    task = asyncio.create_task(self.scrape_and_save(url))
                    tasks.append(task)

            results = await asyncio.gather(*tasks)
            if any(result is None for result in results):
                self.log.warning('Some data sources failed to scrape. Retrying...')
            else:
                self.log.info('Data collection complete.')

    async def scrape_and_save(self, url):
        try:
            response = await request('GET', url)
            return await response.text()
        except asyncio.CancelledError:
            raise
        except Exception as e:
            self.log.error(f'Failed to fetch {url}: {e}')
            return None

async def main():
    scraper = WebScraper()
    await scraper.run()

if __name__ == '__main__':
    asyncio.run(main())
