import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.module.jsonSchema.JsonSchemaModule;
import io.github.resilience4j.circuitbreaker.CircuitBreaker;
import io.github.resilience4j.timelimiter.TimeLimiter;
import org.apache.http.HttpResponse;
import org.apache.http.client.HttpClient;
import org.apache.http.client.methods.HttpGet;
import org.apache.http.impl.client.HttpClients;
import org.apache.http.util.EntityUtils;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.cache.annotation.EnableCaching;
import org.springframework.context.annotation.Bean;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RestController;

@SpringBootApplication
@EnableCaching
public class PokemonServiceApplication {

    @Bean
    public ObjectMapper objectMapper() {
        return new ObjectMapper().registerModule(new JsonSchemaModule());
    }

    @Bean
    public CircuitBreaker circuitBreaker() {
        return CircuitBreaker.ofDefaults("pokemon-service");
    }

    @Bean
    public TimeLimiter timeLimiter() {
        return TimeLimiter.ofDefaults("pokemon-service");
    }

    @RestController
    public class PokemonController {

        private final HttpClient httpClient;
        private final PokemonService pokemonService;

        @Autowired
        public PokemonController(HttpClient httpClient, PokemonService pokemonService) {
            this.httpClient = httpClient;
            this.pokemonService = pokemonService;
        }

        @GetMapping("/pokemon/{id}")
        public ResponseEntity<String> getPokemonDetails(@PathVariable Long id) {
            String jsonResponse = pokemonService.getPokemonDetails(id);
            return new ResponseEntity<>(jsonResponse, HttpStatus.OK);
        }
    }

    public class PokemonService {

        private final ObjectMapper objectMapper;
        private final CircuitBreaker circuitBreaker;
        private final TimeLimiter timeLimiter;

        @Autowired
        public PokemonService(ObjectMapper objectMapper, CircuitBreaker circuitBreaker, TimeLimiter timeLimiter) {
            this.objectMapper = objectMapper;
            this.circuitBreaker = circuitBreaker;
            this.timeLimiter = timeLimiter;
        }

        public String getPokemonDetails(Long id) {
            // Call external REST API to fetch Pokémon data
            HttpResponse response = callApi(id);
            if (response.getStatusLine().getStatusCode() == 200) {
                // Parse JSON response and extract relevant details
                Pokemon pokemon = parseResponse(response.getEntity().getContent());
                return objectMapper.writeValueAsString(pokemon);
            } else {
                // Handle error responses or API rate limits
                return "Error: " + response.getStatusLine().getReasonPhrase();
            }
        }

        private HttpResponse callApi(Long id) {
            // Call external REST API to fetch Pokémon data
            HttpGet httpGet = new HttpGet("https://api.pokemon.com/v2/pokemon/" + id);
            HttpClient client = HttpClients.createDefault();
            return client.execute(httpGet);
        }

        private Pokemon parseResponse(InputStream inputStream) {
            // Parse JSON response and extract relevant details
            String json = EntityUtils.toString(inputStream);
            Pokemon pokemon = objectMapper.readValue(json, Pokemon.class);
            return pokemon;
        }
    }
}
