```javascript
const { Buffer } = require('buffer');
const { Transform } = require('stream');

class ChunkCopier extends Transform {
  constructor(options = {}) {
    super(options);
    this.chunkSize = options.chunkSize || 1024 * 1024; // default chunk size: 1MB
    this.bufferChunks = [];
    this.errorHandlingEnabled = options.errorHandling !== false;
  }

  _transform(chunk, encoding, callback) {
    if (!Buffer.isBuffer(chunk)) {
      return callback(new Error('Invalid data type'));
    }

    const length = chunk.length;
    if (length === 0) {
      return callback();
    }

    for (let i = 0; i < length; i += this.chunkSize) {
      const end = Math.min(length, i + this.chunkSize);
      const chunkBuffer = Buffer.alloc(end - i);
      chunk.copy(chunkBuffer, 0, i, end);

      if (!this.bufferChunks.includes(chunkBuffer)) {
        this.push(chunkBuffer);
      }
    }

    callback();
  }

  _final(callback) {
    if (this.errorHandlingEnabled && this.bufferChunks.length > 0) {
      const buffer = Buffer.concat(this.bufferChunks);
      this.push(buffer);
    }

    callback();
  }

  _error(error, callback) {
    if (this.errorHandlingEnabled) {
      this.push(null); // indicate end of stream
      this.push(error); // push error message
    }

    callback();
  }
}

module.exports = ChunkCopier;
