```python
import json
import logging
from concurrent.futures import ThreadPoolExecutor, as_completed
import sqlite3

class IoTLogProcessor:
    def __init__(self, log_files):
        self.log_files = log_files
        self.db_conn = sqlite3.connect('iot_data.db')
        self.db_cursor = self.db_conn.cursor()

    def process_log_file(self, file_path):
        try:
            with open(file_path, 'r') as file:
                log_data = json.load(file)
                for sensor_reading in log_data:
                    # Filter out anomalies
                    if abs(sensor_reading['value']) > 10:
                        continue
                    self.db_cursor.execute('INSERT INTO sensor_readings VALUES (?, ?, ?)', 
                                            (sensor_reading['device_id'], sensor_reading['timestamp'], 
                                             sensor_reading['value']))
        except Exception as e:
            logging.error(f"Error processing file {file_path}: {str(e)}")

    def process_logs_concurrently(self):
        with ThreadPoolExecutor(max_workers=4) as executor:
            futures = {executor.submit(self.process_log_file, file): file for file in self.log_files}
            for future in as_completed(futures):
                file_path = futures[future]
                try:
                    future.result()
                except Exception as e:
                    logging.error(f"Error processing file {file_path}: {str(e)}")

    def close_db(self):
        self.db_conn.commit()
        self.db_conn.close()

if __name__ == '__main__':
    log_files = ['log_file1.json', 'log_file2.json', ...]
    processor = IoTLogProcessor(log_files)
    processor.process_logs_concurrently()
    processor.close_db()
