using System;
using System.Collections.Generic;
using System.Linq;
using UnityEngine;

public class DynamicValueGenerator
{
    private readonly Dictionary<string, Func<float[], float>> _distributions = new();
    private string _currentDistribution;
    private float[] _distributionParams;
    private int _cacheSize = 1000;
    private LRU Cache = new(_cacheSize);

    public void ConfigureDistribution(string distributionName, float[] parameters)
    {
        if (!_distributions.ContainsKey(distributionName))
        {
            throw new ArgumentException("Unsupported distribution: " + distributionName);
        }
        _currentDistribution = distributionName;
        _distributionParams = parameters;
    }

    public float GenerateFloatValue(float min, float max, bool inclusive = true)
    {
        if (_currentDistribution == null)
        {
            throw new InvalidOperationException("No distribution configured");
        }
        var distributionFunc = _distributions[_currentDistribution];
        return distributionFunc(_distributionParams).Clamp(min, max);
    }

    public int GenerateIntValue(int min, int max, bool inclusive = true)
    {
        if (_currentDistribution == null)
        {
            throw new InvalidOperationException("No distribution configured");
        }
        var value = GenerateFloatValue((float)min, (float)max, inclusive);
        return (int)Mathf.Round(value);
    }

    public override string ToString()
    {
        return $"Range: [{_distributionParams[0]}, {_distributionParams[1]}], Distribution: {_currentDistribution}";
    }
}

public class LRU
{
    private readonly int _size;
    private readonly Dictionary<int, Node> _cache = new();

    public LRU(int size)
    {
        _size = size;
    }

    public void Add(int key, object value)
    {
        if (_cache.ContainsKey(key))
        {
            Remove(key);
        }
        _cache.Add(key, new Node(key, value));
        if (_cache.Count > _size)
        {
            Remove(_cache.Keys.First());
        }
    }

    public object Get(int key)
    {
        if (!_cache.ContainsKey(key))
        {
            return null;
        }
        var node = _cache[key];
        Remove(node.Key);
        Add(key, node.Value);
        return node.Value;
    }

    private void Remove(int key)
    {
        _cache.Remove(key);
    }

    public class Node
    {
        public int Key { get; }
        public object Value { get; }

        public Node(int key, object value)
        {
            Key = key;
            Value = value;
        }
    }
}
