import hashlib
import requests
from flask import Flask, request, jsonify
from flask_cors import CORS
from werkzeug.utils import secure_filename
from threading import Lock
from queue import Queue

app = Flask(__name__)
CORS(app)

FILE_QUEUE = Queue()
FILE_LOCK = Lock()

@app.route('/hash', methods=['POST'])
def hash_file():
    data = request.get_json()

    if 'file_path' in data:
        file_path = secure_filename(data['file_path'])
        return get_local_file_hash(file_path)
    elif 'url' in data:
        url = data['url']
        return get_remote_file_hash(url)
    else:
        return jsonify({'error': 'Invalid request'}), 400

def get_local_file_hash(file_path):
    try:
        file_size = os.path.getsize(file_path)

        if file_size == 0:
            return jsonify({'hash': '', 'file_size': file_size}), 200

        with open(file_path, 'rb') as f:
            chunk_size = 1024 * 1024
            chunk_count = -(-file_size // chunk_size)

            for _ in range(chunk_count):
                chunk = f.read(chunk_size)
                hash_object = hashlib.sha256()
                hash_object.update(chunk)

            file_hash = hash_object.hexdigest()
        return jsonify({'hash': file_hash, 'file_size': file_size}), 200
    except Exception as e:
        return jsonify({'error': str(e)}), 500

def get_remote_file_hash(url):
    try:
        response = requests.get(url, stream=True)

        if response.status_code != 200:
            return jsonify({'error': 'Failed to retrieve file'}), 404

        file_size = response.headers['Content-Length']

        if file_size == '0':
            return jsonify({'hash': '', 'file_size': file_size}), 200

        with FILE_LOCK:
            while True:
                chunk = response.raw.read(1024 * 1024)

                if not chunk:
                    break

                hash_object = hashlib.sha256()
                hash_object.update(chunk)

            file_hash = hash_object.hexdigest()

        return jsonify({'hash': file_hash, 'file_size': int(file_size)}), 200
    except Exception as e:
        return jsonify({'error': str(e)}), 500

if __name__ == '__main__':
    app.run(debug=True)
