#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    char timestamp[20];
    char client_ip[20];
    char request_method[10];
    char url[50];
    char http_version[10];
    int response_status;
    int response_size;
} log_entry;

void parse_log_file(char *filename, FILE *output_file) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) return;

    char line[1024];
    log_entry entry;

    while (fgets(line, sizeof(line), file)) {
        // Split the line into fields
        char *fields = strtok(line, "[ ]+");

        // Process each field
        for (int i = 0; i < 7; i++) {
            switch(i) {
                case 0: strcpy(entry.timestamp, fields); break;
                case 1: strcpy(entry.client_ip, fields); break;
                case 2: strcpy(entry.request_method, fields); break;
                case 3: strcpy(entry.url, fields); break;
                case 4: strcpy(entry.http_version, fields); break;
                case 5: entry.response_status = atoi(fields); break;
                case 6: entry.response_size = atoi(fields); break;
            }
        }

        // Write the processed entry to the output file
        fprintf(output_file, "%s %d %d\n", entry.timestamp, entry.response_status, entry.response_size);

        // Free dynamically allocated memory for this entry
        free(entry.client_ip);
    }

    fclose(file);
}
