import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;
import org.apache.commons.compress.archivers.ArchiveException;
import org.apache.commons.compress.archivers.ZipArchive;
import org.apache.commons.compress.utils.ZipOutputStream;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class TextFileProcessor {

    private static final Logger logger = LoggerFactory.getLogger(TextFileProcessor.class);

    private File directory;
    private String keywordRegex;
    private String reportFormat;
    private int maxLinesPerFile;
    private String compressionAlgorithm;
    private int maxRetryAttempts;
    private long apiUploadTimeout;

    public TextFileProcessor(File directory, String keywordRegex, String reportFormat) {
        this.directory = directory;
        this.keywordRegex = Pattern.compile(keywordRegex);
        this.reportFormat = reportFormat;
    }

    public void processFiles() throws IOException, ArchiveException {

        List<FileSummary> summaries = new ArrayList<>();

        for (File file : directory.listFiles()) {

            if (!file.isFile()) {
                continue;
            }

            try (AutoCloseableBufferedReader reader = Files.newBufferedReader(Paths.get(file.getAbsolutePath()))) {

                FileSummary summary = new FileSummary(file.getName());

                String line;

                while ((line = reader.readLine()) != null) {

                    if (keywordRegex.matcher(line).find()) {

                        summary.addLine(line);

                        if (summary.getLineCount() >= maxLinesPerFile) {
                            break;
                        }
                    }
                }

                summaries.add(summary);
            }
        }

        generateSummaryReport(summaries);
    }

    private void generateSummaryReport(List<FileSummary> summaries) throws IOException, ArchiveException {

        ZipArchive report = new ZipArchive();

        for (FileSummary summary : summaries) {

            byte[] bytes = summary.toString().getBytes();
            ZipOutputStream zip = new ZipOutputStream(Files.newOutputStream(Paths.get("summary-" + summary.getName() + ".zip")));

            try {
                zip.putNextEntry(new ZipEntry("summary.txt"));
                zip.write(bytes);
                zip.closeEntry();
            } catch (IOException | ArchiveException e) {
                logger.error("Error compressing report", e);
                return;
            }

            report.addArchiveEntry(zip);
        }

        report.setCompressionAlgorithm(compressionAlgorithm);

        try {

            // Upload the report to the API and notify upon successful upload
            apiUpload(report);
            logger.info("Report uploaded successfully");
        } catch (Exception e) {
            logger.error("Error uploading report", e);

            // Retry failed uploads with a configurable threshold for retries
            if (!retryFailedUploads(e, maxRetryAttempts)) {
                logger.error("Maximum number of retries exceeded");
            }
        }
    }

    private void apiUpload(ZipArchive report) throws IOException {

        // Implement the external reporting API integration here

        // Simulate a network operation for demonstration purposes
        Thread.sleep(apiUploadTimeout);
    }

    private boolean retryFailedUploads(Exception e, int maxAttempts) {
        if (maxAttempts <= 0) {
            return false;
        }
        // Implement the retry mechanism and API upload logic here

        // Simulate a retry attempt for demonstration purposes
        logger.info("Retrying failed report upload");
        Thread.sleep(500);

        return true;
    }

    public static class FileSummary {

        private String name;
        private List<String> lines = new ArrayList<>();

        public FileSummary(String name) {
            this.name = name;
        }

        public void addLine(String line) {
            lines.add(line);
        }

        public int getLineCount() {
            return lines.size();
        }

        @Override
        public String toString() {
            StringBuilder builder = new StringBuilder();

            for (String line : lines) {
                builder.append(line).append("\n");
            }

            return builder.toString();
        }
    }
}
