import java.io.*;
import java.util.*;

public class DeserializeByteArray {
    public static Object deserializeByteArray(byte[] byteArray) throws IOException {
        Properties properties = new Properties();
        try (FileInputStream fis = new FileInputStream("configuration.properties")) {
            properties.load(fis);
        } catch (IOException e) {
            throw new RuntimeException("Failed to load configuration file", e);
        }

        String className = properties.getProperty("deserialization.class");
        if (className == null || className.isEmpty()) {
            throw new RuntimeException("Configuration file missing or malformed. Class name not found.");
        }

        try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(byteArray))) {
            return ois.readObject();
        } catch (ClassNotFoundException e) {
            throw new RuntimeException("Failed to deserialize object: " + e.getMessage());
        } catch (StreamCorruptedException | InvalidClassException e) {
            throw new RuntimeException("Invalid or corrupted stream. Failed to deserialize object: " + e.getMessage());
        }
    }
}
