class SecureMessagingLibrary {
public:
    SecureMessagingLibrary(const std::string& config, const std::string& logFile);
    ~SecureMessagingLibrary();

    void setKeyRotationInterval(int seconds);

private:
    class AlgorithmPlugin {
    public:
        virtual void init() = 0;
        virtual void destroy() = 0;
    };

    class AESPlugin : public AlgorithmPlugin {
    public:
        void init() override { ECDH_init(); }
        void destroy() override { ECDH_free(); }
    };

    class ChaCha20Plugin : public AlgorithmPlugin {
    public:
        void init() override { ChaCha20_init(); }
        void destroy() override { ChaCha20_free(); }
    };

    std::vector<std::unique_ptr<AlgorithmPlugin>> algorithms;
    std::ofstream logFile;

    void loadAlgorithms(const std::string& config);
    void rotateKeys();
};

SecureMessagingLibrary::SecureMessagingLibrary(const std::string& config, const std::string& logFile)
    : logFile(logFile) {
    loadAlgorithms(config);
}

SecureMessagingLibrary::~SecureMessagingLibrary() {
    for (const auto& algorithm : algorithms) {
        algorithm->destroy();
    }
}

void SecureMessagingLibrary::setKeyRotationInterval(int seconds) {
    // implement key rotation interval logic
}

void SecureMessagingLibrary::loadAlgorithms(const std::string& config) {
    // parse configuration string and dynamically load enabled algorithms
    // example: "AES-256,ChaCha20"
    size_t start = 0;
    while (start < config.size()) {
        size_t end = config.find(',', start);
        if (end == std::string::npos) {
            end = config.size();
        }
        std::string algorithmName = config.substr(start, end - start);
        // check if the algorithm is supported by OpenSSL
        if (algorithmName == "AES-256") {
            algorithms.emplace_back(std::make_unique<AESPlugin>());
        } else if (algorithmName == "ChaCha20") {
            algorithms.emplace_back(std::make_unique<ChaCha20Plugin>());
        }
        start = end + 1;
    }
}

void SecureMessagingLibrary::rotateKeys() {
    // implement key rotation logic using the KMS integration
}
