void uploadAndMonitorFile(const std::string& filePath, const std::string& bucketName, const std::vector<std::pair<std::string, std::string>>& metadata, CloudStorageConfig config) {
    if (!std::ifstream(filePath).good()) {
        std::cerr << "Error: File not found or inaccessible." << std::endl;
        return;
    }

    std::string sha256Hash = calculateFileSha256(filePath);

    try {
        // Upload file to cloud storage
        // Implement the upload logic here using the provided configuration

        std::cout << "Upload successful!" << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Error uploading file: " << e.what() << std::endl;
    }
}

std::string calculateFileSha256(const std::string& filePath) {
    std::ifstream file(filePath, std::ios::binary);
    if (!file.is_open()) {
        return ""; // File not found or inaccessible
    }

    const size_t chunkSize = 1024 * 1024; // Adjust the chunk size as needed

    std::hash<std::uint8_t> sha256;
    std::stringstream ss;

    file.seekg(0, std::ios::end);
    size_t fileSize = file.tellg();
    file.seekg(0, std::ios::beg);

    while (fileSize > 0) {
        char buffer[chunkSize];
        file.read(buffer, chunkSize);
        fileSize -= chunkSize;

        for (size_t i = 0; i < chunkSize && i < fileSize; ++i) {
            ss << static_cast<char>(buffer[i]);
        }
    }

    return ss.str();
}
