#include <json-c/json.h>
#include <stdio.h>

int validate_oauth_token_response(char *json_string) {
    json_object *jobj = json_decode(json_string, 0);

    if (json_object_object_get(jobj, "access_token") == NULL || 
        json_object_object_get(jobj, "expires_in") == NULL || 
        json_object_object_get(jobj, "token_type") == NULL || 
        !json_object_is_type(jobj, "expires_in", json_type_int) || 
        json_object_object_get(jobj, "scope") == NULL) {
        printf("Invalid JSON object\n");
        return 0;
    }

    if (!json_string_is_string(json_object_get_string(jobj, "access_token"))) {
        printf("Access token is not a string\n");
        return 0;
    }

    if (json_object_get_int(jobj, "expires_in") <= 0 || 
        json_object_get_int(jobj, "expires_in") > 3600) {
        printf("Expires in must be a positive integer less than or equal to 3600\n");
        return 0;
    }

    if (!json_string_is_string(json_object_get_string(jobj, "token_type"))) {
        printf("Token type is not a string\n");
        return 0;
    }

    if (strcmp(json_object_get_string(jobj, "token_type"), "Bearer") != 0) {
        printf("Token type must be 'Bearer'\n");
        return 0;
    }

    if (json_object_object_get(jobj, "refresh_token") != NULL) {
        // validate against existing token store
        if (!validate_refresh_token(json_object_get_string(jobj, "refresh_token"))) {
            printf("Invalid or expired refresh token\n");
            return 0;
        }
    }

    char *scope = json_object_get_string(jobj, "scope");
    if (strcmp(scope, "predefined_scope1") != 0 && 
        strcmp(scope, "predefined_scope2") != 0) {
        printf("Invalid scope: %s\n", scope);
        return 0;
    }

    // validate refresh token and scope successfully
    json_object_put(jobj);
    return 1;
}

int main() {
    char *json_string = "{\"access_token\": \"some_access_token\", ...}";
    int valid = validate_oauth_token_response(json_string);
    printf("Token is %svalid\n", valid ? "" : "not ");

    return 0;
}
