import com.google.common.cache.CacheBuilder;
import com.google.common.cache.CacheLoader;
import com.google.common.cache.LoadingWriter;
import com.google.common.util.concurrent.LoopingExecutorService;
import retrofit2.Call;
import retrofit2.Response;

import java.io.IOException;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;

public class WeatherFetcher {

    private static final ExecutorService executor = new LoopingExecutorService();
    private static final LoadingWriter<String, WeatherData> cacheLoader = CacheBuilder
            .newLoadingWriter(() -> "unknown")
            .setCacheLoader(new CacheLoader<String, WeatherData>() {
                @Override
                public WeatherData load(String key) throws Exception {
                    // Fetch weather data from external API using Retrofit
                    WeatherApi api = RetrofitInstance.getRetrofit().create(WeatherApi.class);
                    Call<WeatherResponse> call = api.getWeather(key);
                    Response<WeatherResponse> response = call.execute();
                    if (response.code() >= 200 && response.code() < 300) {
                        return new WeatherData(response.body());
                    } else {
                        // Fallback mechanism in case of network failure
                        return null;
                    }
                }
            })
            .maximumSize(10000)
            .build();

    public static void main(String[] args) throws IOException, InterruptedException {
        Random random = new Random();
        String location = "New York";
        AtomicInteger requestCount = new AtomicInteger(0);
        AtomicInteger cacheHitCount = new AtomicInteger(0);
        AtomicInteger cacheMissCount = new AtomicInteger(0);

        for (int i = 0; i < 10; i++) {
            WeatherData weatherData = cacheLoader.getUnchecked(location);
            if (weatherData != null) {
                System.out.println("Weather in " + location + ": " + weatherData.getDescription());
                cacheHitCount.incrementAndGet();
            } else {
                // Fetch data from API if not cached
                Call<WeatherResponse> call = RetrofitInstance.getRetrofit().create(WeatherApi.class).getWeather(location);
                Response<WeatherResponse> response = call.execute();
                requestCount.incrementAndGet();
                if (response.code() >= 200 && response.code() < 300) {
                    weatherData = new WeatherData(response.body());
                    cacheLoader.putIfAbsent(location, weatherData);
                    cacheMissCount.incrementAndGet();
                    System.out.println("Weather in " + location + ": " + weatherData.getDescription());
                } else {
                    // Fallback mechanism in case of network failure
                    System.out.println("Failed to fetch weather data for " + location);
                }
            }
        }

        System.out.println("API requests: " + requestCount.get());
        System.out.println("Cache hits: " + cacheHitCount.get());
        System.out.println("Cache misses: " + cacheMissCount.get());

    }
}

class WeatherData {
    private String description;

    public WeatherData(WeatherResponse response) {
        this.description = response.getDescription();
    }

    public String getDescription() {
        return description;
    }
}

class RetrofitInstance {

    static Retrofit getRetrofit() {
        return new Retrofit.Builder()
                .baseUrl("https://api.example.com/")
                .addConverterFactory(GsonConverterFactory.create())
                .build();
    }
}

interface WeatherApi {
    Call<WeatherResponse> getWeather(String location);
}

class WeatherResponse {
    private String description;

    public WeatherResponse(String description) {
        this.description = description;
    }

    public String getDescription() {
        return description;
    }
}
