const { Kafka } = require('kafkajs');
const { createCipheriv, createDecipheriv } = require('crypto');

class StreamingDataCollector {
  constructor({
    kafkaTopic,
    databaseStream,
    encryptionSettings = {},
  }) {
    this.kafkaTopic = kafkaTopic;
    this.databaseStream = databaseStream;
    this.encryptionSettings = encryptionSettings;

    this.keyPair = {
      publicKey: '',
      privateKey: '',
    };

    this.cipher = null;
  }

  async start() {
    await this.generateKeyPair();
    await this.connectToDataSources();

    console.log('Streaming data collector started');

    process.on('SIGINT', () => {
      this.pause().then(() => {
        process.exit();
      });
    });

    setImmediate(this.ingestData.bind(this));
  }

  async generateKeyPair() {
    const crypto = require('crypto');
    const keySize = 256;
    const ivSize = 128;

    this.keyPair.publicKey = crypto.randomBytes(keySize / 8).toString('hex');
    this.keyPair.privateKey = crypto.randomBytes(keySize / 8).toString('hex');

    this.cipher = createCipheriv('aes-256-cbc', this.keyPair.privateKey, '0000000000000000');
  }

  async connectToDataSources() {
    if (this.kafkaTopic) {
      const client = new Kafka.Client({
        clientId: 'streaming-data-collector',
      });

      this.kafkaConsumer = client.consumer({ topics: [this.kafkaTopic] });

      await this.kafkaConsumer.connect();
    }

    if (this.databaseStream) {
      // implement database connection logic here
    }
  }

  async ingestData() {
    let dataPacket;
    try {
      if (this.kafkaTopic) {
        const message = await this.kafkaConsumer.consume({ timeout: 100 });
        dataPacket = message.value.toString();
      } else if (this.databaseStream) {
        // implement database stream logic here
      }

      if (dataPacket) {
        const encryptedData = this.encrypt(dataPacket);

        console.log(`Ingested and encrypted data packet: ${encryptedData}`);
      }
    } catch (error) {
      console.error('Error ingesting data:', error);
    }

    setTimeout(this.ingestData.bind(this), 10);
  }

  encrypt(data) {
    const cipher = this.cipher;
    let encryptedData;

    try {
      encryptedData = Buffer.concat([cipher.update(Buffer.from(data)), cipher.final()]).toString('hex');
    } catch (error) {
      console.error('Error encrypting data:', error);
    }

    return encryptedData;
  }

  async pause() {
    if (this.kafkaTopic) {
      await this.kafkaConsumer.pause();
    }
    // implement database stream pause logic here

    console.log('Streaming data collector paused');
  }

  async resume() {
    if (this.kafkaTopic) {
      await this.kafkaConsumer.resume();
    }
    // implement database stream resume logic here

    console.log('Streaming data collector resumed');
  }
}

module.exports = StreamingDataCollector;
