using Microsoft.AspNetCore.Mvc;
using System.IO;
using System.Text.RegularExpressions;
using System.Threading.Tasks;

namespace WebApp.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    public class LogController : ControllerBase
    {
        private readonly ILogService _logService;
        private readonly ICacheService _cacheService;
        private readonly ILogger _logger;

        public LogController(ILogService logService, ICacheService cacheService, ILogger logger)
        {
            _logService = logService;
            _cacheService = cacheService;
            _logger = logger;
        }

        [HttpPost]
        public async Task<IActionResult> HandleLogRequest([FromBody]LogRequest request)
        {
            if (!await ValidateRequest(request))
                return BadRequest("Invalid request");

            try
            {
                var filteredLines = await FilterAndAggregateLogLines(request.PageSectionId, request.ElementId, request.HtmlContent);
                await UpdateElementHtml(request.ElementId, filteredLines);

                // Upload summary report to external logging API
                _logger.LogInformation(filteredLines);

                // Cache the result for future requests
                await _cacheService.SetCacheItemAsync(request.PageSectionId, filteredLines);

                return new ResponseEntity { Message = "Page should be refreshed" };
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error handling log request");
                return StatusCode(500, "Internal Server Error");
            }
        }

        private async Task<bool> ValidateRequest(LogRequest request)
        {
            // Check user permissions and validate input IDs
            if (!await _logService.HasPermission(request.PageSectionId))
                return false;

            return true;
        }

        private async Task<string[]> FilterAndAggregateLogLines(string pageSectionId, string elementId, string htmlContent)
        {
            // Read log file from specified directory
            var lines = await _logService.ReadLogFileAsync(pageSectionId);

            // Filter lines based on regex pattern
            var filteredLines = Regex.Split(lines, "[^" + htmlContent + "]");

            // Aggregate filtered lines into a summary report
            return filteredLines;
        }

        private async Task UpdateElementHtml(string elementId, string[] filteredLines)
        {
            // Use service class to update element's HTML content atomically
            await _logService.UpdateElementHtmlAsync(elementId, filteredLines);
        }
    }

    public class LogRequest
    {
        public string PageSectionId { get; set; }
        public string ElementId { get; set; }
        public string HtmlContent { get; set; }
    }

    public class ResponseEntity
    {
        public string Message { get; set; }
    }
}
