#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int *states;
    int num_states;
    void (*next)(int);
} FSA;

void update_fsa(FSA* fsa, int last_state) {
    if (fsa == NULL || fsa->states == NULL) {
        // Handle error: invalid input parameter
        return;
    }

    int new_state = last_state + 1; // Assuming next state always exists
    int* new_states = malloc(sizeof(int));
    for (int i = 0; i < fsa->num_states; i++) {
        if (i < last_state) {
            new_states[i] = fsa->states[i];
        } else {
            new_states[i] = -1; // Mark as end of list
        }
    }

    new_states[last_state] = new_state;
    for (int i = 0; i < fsa->num_states; i++) {
        if (fsa->states[i] == last_state) {
            fsa->next = malloc(sizeof(void *));
            *fsa->next = &update_fsa;
            break;
        }
    }

    free(fsa->states);
    fsa->states = new_states;
}
