#include <openssl/ssl.h>
#include <openssl/err.h>

EVP_CIPHER_CTX* choose_cipher(const char* mode) {
    EVP_CIPHER_CTX* ctx;
    const EVP_CIPHER* cipher;

    if (strcasecmp(mode, "ECB") == 0) {
        cipher = EVP_des_ecb();
    } else if (strncasecmp(mode, "EDE", 3) == 0) {
        cipher = EVP_des_ede();
    } else if (strncasecmp(mode, "EDE3", 4) == 0) {
        cipher = EVP_des_ede3();
    } else if (strcasecmp(mode, "CFB") == 0) {
        cipher = EVP_des_cfb();
    } else if (strncasecmp(mode, "NULL", 4) == 0) {
        cipher = EVP_null();
    } else {
        ERR_error_wrap_ui(1, "Invalid cipher mode: %s");
        return NULL;
    }

    ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL);
    return ctx;
}
