#!/usr/bin/env php
<?php

use Symfony\Component\Yaml\Yaml;

require __DIR__ . '/vendor/autoload.php';

class DeploymentScript {
    private $config;
    private $env;

    public function __construct($options = array()) {
        $this->config = Yaml::parse(file_get_contents('config.yml'));
        $this->env = $this->loadEnvironmentVariables();
    }

    private function loadEnvironmentVariables() {
        $environmentVariables = [];
        foreach ($this->config['environments'] as $env => $values) {
            if (!isset($options[$env])) continue;
            $environmentVariables[$env] = array_filter(array_merge($values, $options[$env]));
        }
        return $environmentVariables;
    }

    public function deploy($options = array()) {
        $kubectl = new Kubectl(__DIR__ . '/.kube/config');
        foreach ($this->config['nodes'] as $node) {
            if (!isset($options[$node])) continue;
            $deploymentOptions = array_merge($this->env, $options[$node]);
            try {
                $kubectl.applyDeployment($node, $deploymentOptions);
            } catch (Exception $e) {
                echo "Failed to deploy to node {$node}: " . $e->getMessage() . PHP_EOL;
            }
        }
    }

    public function getHelp() {
        return implode(PHP_EOL, array_map(function ($option) {
            return "$option: [required|optional] - description";
        }, array_keys($this->config['options'])));
    }
}

class Kubectl {
    private $configFile;

    public function __construct($configFile) {
        $this->configFile = $configFile;
    }

    public function applyDeployment($node, $options) {
        // Implement kubectl API call to deploy the application
        // Handle potential API rate limits and authentication issues
        // Optimize for performance when dealing with large numbers of nodes
    }
}

$script = new DeploymentScript();

if (count($argv) > 1 && $argv[1] === '--help') {
    echo "Usage: deploy.php [options]\n" . $script->getHelp() . PHP_EOL;
    exit;
}

$options = array();
foreach ($argv as $arg) {
    if (strpos($arg, '=') !== false) {
        list($key, $value) = explode('=', $arg);
        $options[$key] = $value;
    }
}

$script->deploy($options);

```

