                .flatMap(orderData -> checkInventoryAndCredits(orderData))
                .doOnNext(orderData -> updateInventoryAndFinancialRecords(orderService, orderData))
                .retryWhen(Retry.maxAttempts(3).delay(Duration.ofMillis(100)).backoff(Duration.ofSeconds(2)))
                .onErrorResume(error -> {
                    log.error("Order processing failed:", error);
                    return Mono.just(OrderStatus.FAILED);
                })
                .doOnNext(orderData -> notifyUser(orderService, orderData))
                .andThen(getCreditLimit(orderService, apiToken));
    }

