namespace HashUtility
{
    public class HashUtility
    {
        private static int _maxConcurrentHashOperations = 10;
        private static readonly object _lockObject = new object();

        public string GetMD5Hash(string input)
        {
            using (var md5 = MD5.Create())
            {
                var bytes = System.Text.Encoding.UTF8.GetBytes(input);
                return BitConverter.ToString(md5.ComputeHash(bytes)).Replace("-", "").ToLower();
            }
        }

        public bool ValidateHashAgainstSalt(string input, string saltedHash, string salt)
        {
            if (string.IsNullOrEmpty(input) || string.IsNullOrEmpty(saltedHash) || string.IsNullOrEmpty(salt))
            {
                throw new ArgumentException("Input or salted hash or salt cannot be null or empty.");
            }

            try
            {
                var expectedHash = GetMD5Hash($"{input}{salt}");
                return expectedHash == saltedHash;
            }
            catch (Exception ex)
            {
                throw new Exception("Error validating hash: " + ex.Message);
            }
        }
    }
}
