use std::fs::File;
use std::io::{self, BufReader};
use std::path::Path;

use rusqlite::{Connection, NoResult, Row};
use serde_json::Value;
use early_error::early_error;

struct ConnectionPool {
    connections: Vec<Connection>,
}

impl ConnectionPool {
    fn new() -> Self {
        ConnectionPool { connections: vec![] }
    }

    fn get_connection(&mut self) -> io::Result<&mut Connection> {
        if self.connections.is_empty() {
            let conn = Connection::open_in_memory()?;
            self.connections.push(conn);
        }
        Ok(self.connections.last_mut().unwrap())
    }

    fn return_connection(&mut self, conn: &mut Connection) {
        self.connections.push(conn.clone());
    }
}

fn process_file(path: &Path) -> Result<Vec<Value>, early_error::EarlyError> {
    let mut connection_pool = ConnectionPool::new();
    let file = File::open(path)?;
    let reader = BufReader::new(file);

    let mut results = Vec::new();

    for line in reader.lines() {
        let line = line?;
        let bytes = line.as_bytes().to_vec();
        // Process the byte array according to your schema
        let values = process_schema(&bytes);
        let formatted_string = format!("SELECT * FROM table1 JOIN table2 ON ... WHERE ... AND {}", values[1], values[2]);
        let mut conn = connection_pool.get_connection()?;
        match conn.execute(&formatted_string) {
            Ok(_) => {
                results.push(serde_json::to_value(Row::new)?);
                conn.close()?
            }
            Err(e) => {
                early_error!("Error executing query: {}", e)?;
                log::error!("Failed to execute query");
            }
        };
    }

    connection_pool.return_connection(&mut conn);

    Ok(results)
}

fn process_schema(bytes: &[u8]) -> Vec<f64> {
