// Global variables
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
FILE *error_log_file = NULL;
FILE *debug_log_file = NULL;

// Function to log messages
void log_message(char *log_type, const char *format, ...) {
    va_list args;
    va_start(args, format);

    // Error logs have priority, so write them first
    if (strcmp(log_type, "error") == 0) {
        pthread_mutex_lock(&lock);
        fprintf(error_log_file, "[ERROR] ");
        vfprintf(error_log_file, format, args);
        fprintf(error_log_file, "\n");
        pthread_mutex_unlock(&lock);
    } else { // Debug logs are timestamped
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);

        pthread_mutex_lock(&lock);
        fprintf(debug_log_file, "[%04d-%02d-%02d %02d:%02d:%02d] [DEBUG] ", 
                tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday, tm->tm_hour, tm->tm_min, tm->tm_sec);
        vfprintf(debug_log_file, format, args);
        fprintf(debug_log_file, "\n");
        pthread_mutex_unlock(&lock);
    }

    va_end(args);
}

int main() {
    // Initialize logging files
    error_log_file = fopen("error.log", "a+");
    debug_log_file = fopen("debug.log", "a+");

    // Load and execute JavaScript files
    const char *js_files[] = {"file1.js", "file2.js"};
