        integers.push_back(n);
    }
    return integers;
}

int findLargestInteger(const std::vector<int>& integers) {
    return *std::max_element(integers.begin(), integers.end());
}

void sendGetRequests(std::vector<int> integers, SandeshClient& client, InterfaceTable& interfaceTable) {
    for (const auto& integer : integers) {
        boost::asio::io_service io;
        boost::asio::deadline_timer timer(io);
        timer.expires_from_now(boost::posix_time::seconds(1));
        timer.async_wait([&](boost::system::error_code ec, long long ms) {
            if (!ec) {
                try {
                    SandeshResponse response = client.sendGetRequest(std::to_string(integer));
                    if (response.isSuccess()) {
                        std::cout << "Fetched metadata for integer: " << integer << std::endl;
                    } else {
                        std::cout << "Failed to fetch metadata for integer: " << integer << std::endl;
                    }
                } catch (boost::exception& e) {
                    std::cerr << "Error: " << boost::diagnostic_information(e) << std::endl;
                }
            }
        });
    }
}

int main() {
    std::vector<int> integers = readIntegers();
    int largestInteger = findLargestInteger(integers);

    SandeshClient client("https://example.com/api");
    InterfaceTable interfaceTable;

    sendGetRequests(integers, client, interfaceTable);

    return 0;
}
