    public class FileDeserializer
    {
        private const int BufferSize = 1024 * 1024; // 1MB buffer for better performance

        public void DeserializeFromFile(string filePath)
        {
            using (FileStream fileStream = new FileStream(filePath, FileMode.Open))
            {
                using (BinaryFormatter formatter = new BinaryFormatter())
                {
                    byte[] buffer = new byte[BufferSize];
                    int bytesRead;
                    object deserializedObject;

                    while ((bytesRead = fileStream.Read(buffer, 0, BufferSize)) > 0)
                    {
                        try
                        {
                            // Check for corrupted files by validating the file size and contents
                            if (fileStream.Length != bytesRead || !IsValidData(buffer))
                            {
                                throw new InvalidOperationException("Corrupted or invalid data in file.");
                            }

                            // Deserialize the object
                            using (MemoryStream ms = new MemoryStream())
                            {
                                ms.Write(buffer, 0, bytesRead);
                                ms.Position = 0;
                                deserializedObject = formatter.Deserialize(ms);
                            }
                        }
                        catch (Exception ex)
                        {
                            // Handle errors during deserialization
                            Console.WriteLine($"Error deserializing data: {ex.Message}");
                            return;
                        }
                    }

                    // Validate the file size and contents again after successful deserialization
                    if (fileStream.Length != bytesRead || !IsValidData(buffer))
                    {
                        throw new InvalidOperationException("Corrupted or invalid data in file.");
                    }

                    Console.WriteLine($"Deserialized object: {deserializedObject}");
                }
            }
        }

        private bool IsValidData(byte[] buffer)
        {
            // Implement your custom validation logic for the data
            return true; // Replace with actual validation code
        }
    }

    class Program
    {
        static void Main(string[] args)
        {
