import hashlib
import os
from typing import Callable, Any

class StorageBackend:
    def store(self, file_path: str, md5_hash: str) -> None:
        pass  # Implement storage logic in the subclass


def calculate_file_md5(file_path: str, chunk_size: int = 8192, progress_callback: Callable[[int], None] = lambda x: None, storage_backend: StorageBackend = None) -> str:
    try:
        md5_hash = hashlib.md5()

        if not os.path.exists(file_path):
            return "File not found"

        with open(file_path, 'rb') as file:
            chunk = file.read(chunk_size)

            while chunk:
                md5_hash.update(chunk)

                if progress_callback is not None:
                    progress_callback(int((os.path.getsize(file_path) - len(chunk)) * 100 / os.path.getsize(file_path)))

                chunk = file.read(chunk_size)

        return md5_hash.hexdigest()

    except IOError as e:
        print(f"Error reading file: {e}")
        return None

    finally:
        if storage_backend is not None and "store" in dir(storage_backend):
            storage_backend.store(file_path, calculate_file_md5.__wrapped__(file_path, chunk_size, progress_callback, storage_backend))
