typedef struct {
    int bandwidth_limit;
    int priority_level;
    void (*callback)(struct config_settings*);
} config_settings_t, *config_settings_ptr;

int process_devices(device_t** devices, size_t num_devices) {
    if (!devices || !num_devices) {
        LOG_ERROR("Invalid device list");
        return -1;
    }

    for (size_t i = 0; i < num_devices; i++) {
        device_t* device = devices[i];
        if (!device) {
            LOG_ERROR("Device is NULL");
            return -1;
        }

        if (!validate_ip_address(device->ip_address)) {
            LOG_ERROR("Invalid IP address for device %s", device->name);
            return -1;
        }

        if (device->port_number < 0 || device->port_number > 65535) {
            LOG_ERROR("Port number out of range for device %s", device->name);
            return -1;
        }

        config_settings_ptr settings = device->settings;
        if (!settings) {
            LOG_ERROR("Configuration settings are NULL for device %s", device->name);
            return -1;
        }

        if (settings->bandwidth_limit < 0 || settings->priority_level < 0) {
            LOG_ERROR("Invalid configuration settings for device %s", device->name);
            return -1;
        }

        if (!settings->callback) {
            LOG_ERROR("Callback function is NULL for device %s", device->name);
            return -1;
        }

        (void)settings->callback(settings);
    }

    return 0;
}

