import requests
import threading
import time
import json
import os
import re
from typing import List, Dict, Any


class NetworkResourceOptimizer:
    def __init__(self, urls: List[str]):
        self.urls = urls
        self.resource_status = {}
        self.api_metadata = {}
        self.config = self.load_config()
        self.lock = threading.Lock()

    def add_url(self, url: str):
        if url not in self.urls:
            self.urls.append(url)
            self.resource_status[url] = "Unknown"
            self.api_metadata[url] = {"response_time": 0, "latency": 0}

    def check_availability(self, url: str) -> Dict[str, Any]:
        start_time = time.time()
        try:
            response = requests.get(url)
            end_time = time.time()
            latency = end_time - start_time
            self.resource_status[url] = "Available"
            self.api_metadata[url]["response_time"] += end_time - start_time
            self.api_metadata[url]["latency"] += latency
            return {"status": "Available", "time_taken": end_time - start_time, "latency": latency}
        except requests.exceptions.RequestException as e:
            self.resource_status[url] = "Unavailable"
            self.api_metadata[url]["response_time"] += time.time() - start_time
            self.api_metadata[url]["latency"] += time.time() - start_time
            return {"status": "Unavailable", "time_taken": time.time() - start_time, "error": str(e)}

    def fetch_api_metadata(self, url: str) -> Dict[str, Any]:
        try:
            response = requests.get(f"{url}/metadata")
            metadata = json.loads(response.text)
            self.api_metadata[url] = {"response_time": metadata["response_time"], "latency": metadata["latency"]}
            return metadata
        except requests.exceptions.RequestException as e:
            print(f"Error fetching metadata for {url}: {str(e)}")

    def optimize_availability_check(self, url: str) -> None:
        # Implement caching mechanisms and batch operations for checking resource availability
        pass

    def report_availability_and_metadata(self) -> Dict[str, Any]:
        availability_report = {"available": 0, "unavailable": 0}
        metadata_report = {}
        for url in self.urls:
            if self.resource_status[url] == "Available":
                availability_report["available"] += 1
                metadata_report[url] = self.api_metadata[url]
            else:
                availability_report["unavailable"] += 1
        return {"availability": availability_report, "metadata": metadata_report}

    def load_config(self) -> Dict[str, Any]:
        config_file_path = os.path.join(os.getcwd(), "config.json")
        if not os.path.exists(config_file_path):
            return {}
        with open(config_file_path, "r") as f:
            config = json.load(f)
            self.config["retry_interval"] = float(config.get("retry_interval", 1.0))
            self.config["max_retries"] = int(config.get("max_retries", 3))
            self.config["num_threads"] = int(config.get("num_threads", 5))
        return self.config


if __name__ == "__main__":
