// Inventory Service
public class InventoryService {
    private final InventoryRepository repository;
    private final CachingLayer cachingLayer;

    public InventoryService(InventoryRepository repository, CachingLayer cachingLayer) {
        this.repository = repository;
        this.cachingLayer = cachingLayer;
    }

    public void updateProductStock(String productId, int quantity) {
        // Update product stock in the database
        repository.updateProductStock(productId, quantity);

        // Update cache to reflect the change
        cachingLayer.updateCache(productId, quantity);
    }
}

// Payment Gateway Service
public class PaymentGatewayService {
    private final StripeAPI stripeAPI;

    public PaymentGatewayService(StripeAPI stripeAPI) {
        this.stripeAPI = stripeAPI;
    }

    public void processPayment(PaymentRequest paymentRequest) {
        // Process payment using the Stripe API
        stripeAPI.chargeCard(paymentRequest);
    }
}

// Caching Layer
public class CachingLayer {
    private final Map<String, Integer> cache;

    public CachingLayer() {
        this.cache = new HashMap<>();
    }

    public void updateCache(String productId, int quantity) {
        // Update the cache to reflect the change in product stock level
        cache.put(productId, quantity);
    }
}

// Distributed Database (Cassandra)
public class CassandraDatabase {
    private final Cluster cluster;

    public CassandraDatabase(Cluster cluster) {
        this.cluster = cluster;
    }

    public void updateProductStock(String productId, int quantity) {
        // Update product stock in the Cassandra database
        cluster.execute("UPDATE products SET stock_level = ? WHERE id = ?", quantity, productId);
    }
}

