using System;
using System.Xml;
using System.IO;
using System.Linq;
using System.Collections.Generic;

public class ConfigurationManager
{
    private Dictionary<string, string> _settings = new Dictionary<string, string>();
    private List<XmlDocument> _xmlFiles = new List<XmlDocument>();
    private ILogger _logger;
    private IConfigValidator _validator;
    private IDatabaseService _databaseService;

    public ConfigurationManager(ILogger logger, IConfigValidator validator, IDatabaseService databaseService)
    {
        _logger = logger;
        _validator = validator;
        _databaseService = databaseService;
    }

    public void LoadXmlFiles(string[] xmlFileNames)
    {
        foreach (string fileName in xmlFileNames)
        {
            XmlDocument xmlDocument = new XmlDocument();
            xmlDocument.Load(fileName);

            _xmlFiles.Add(xmlDocument);

            // Load settings from each XML file
            foreach (XmlNode node in xmlDocument.SelectNodes("/Config"))
            {
                foreach (XmlNode settingNode in node.ChildNodes)
                {
                    if (settingNode.NodeType == XmlNodeType.Element && settingNode.Name == "Setting")
                    {
                        string key = settingNode.GetAttribute("Key");
                        string value = settingNode.InnerText;

                        // Validate and apply the settings
                        if (_validator.ValidateSetting(key, value))
                        {
                            _settings[key] = value;
                        }
                        else
                        {
                            _logger.LogError($"Invalid configuration setting: {key}={value}");
                        }
                    }
                }
            }
        }

        // Load fallback settings from database (if available)
        Dictionary<string, string> fallbackSettings = _databaseService.GetFallbackSettings();
        foreach (var setting in fallbackSettings)
        {
            if (!_settings.ContainsKey(setting.Key))
            {
                _settings[setting.Key] = setting.Value;
            }
        }
    }

    public void UpdateSetting(string key, string value)
    {
        // Check if the setting exists
        if (_settings.ContainsKey(key))
        {
            // Validate the new value
            if (_validator.ValidateSetting(key, value))
            {
                _settings[key] = value;
                _logger.LogInformation($"Updated configuration setting: {key}={value}");
            }
            else
            {
                _logger.LogError($"Invalid configuration setting: {key}={value}");
            }
        }
        else
        {
            _logger.LogError($"Unknown configuration setting: {key}");
        }
    }

    public string GetSetting(string key)
    {
        return _settings.ContainsKey(key) ? _settings[key] : null;
    }

    // Serialization and deserialization methods for database storage
    public void SerializeSettings()
    {
        // TO DO: implement serialization logic
    }

    public void DeserializeSettings()
    {
        // TO DO: implement deserialization logic
    }
}

public interface ILogger
{
    void LogError(string message);
    void LogInformation(string message);
}

public interface IConfigValidator
{
    bool ValidateSetting(string key, string value);
}

public interface IDatabaseService
{
    Dictionary<string, string> GetFallbackSettings();
}
