import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.util.HashMap;
import java.util.Map;

public class ObjectDeserializer {
    private Map<String, Class<?>> cachedClassNames;
    private Map<String, String> configMap;

    public Object deserialize(byte[] serializedObject) throws Exception {
        if (serializedObject == null || serializedObject.length == 0) {
            throw new RuntimeException("Invalid byte array");
        }

        try (ByteArrayInputStream bais = new ByteArrayInputStream(serializedObject);
             ObjectInputStream ois = new ObjectInputStream(bais)) {
            String className = getConfig().getOrDefault("className", null);
            if (className == null) {
                throw new RuntimeException("Configuration file missing or malformed");
            }

            Class<?> clazz = cachedClassNames.get(className);
            if (clazz == null) {
                try {
                    clazz = Class.forName(className);
                    cachedClassNames.put(className, clazz);
                } catch (ClassNotFoundException e) {
                    throw new RuntimeException("Class not found: " + className);
                }
            }

            return ois.readObject();
        } catch (IOException e) {
            throw new RuntimeException("Deserialization failed: " + e.getMessage());
        }
    }

    private Map<String, String> getConfig() throws IOException {
        // Implement configuration retrieval mechanism from external database or file
        // For demonstration purposes, use a hardcoded configuration map
        return new HashMap<>() {{
            put("className", "com.example.MyClass");
        }};
    }
}
