#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    char timestamp[30];
    char clientIP[20];
    char requestMethod[10];
    char URL[50];
    char httpVersion[10];
    int responseStatus;
    int responseSize;
} LogEntry;

void processLogFiles() {
    FILE *fp = fopen("log.txt", "r");
    if (fp == NULL) {
        perror("Error opening file");
        return;
    }

    LogEntry *currentEntry = (LogEntry *)malloc(sizeof(LogEntry));
    LogEntry *previousEntry = (LogEntry *)malloc(sizeof(LogEntry));

    int lastTwoResponseSizes[2] = {0, 0};
    int count = 0;

    while (fscanf(fp, "[%29s] [%19s] [%9s] [%49s] [%9s] %d %d",
                  currentEntry->timestamp,
                  currentEntry->clientIP,
                  currentEntry->requestMethod,
                  currentEntry->URL,
                  currentEntry->httpVersion,
                  &currentEntry->responseStatus,
                  &currentEntry->responseSize) == 7) {
        if (count >= 2) {
            double avgResponseSize = (lastTwoResponseSizes[0] + lastTwoResponseSizes[1]) / 2.0;
            printf("Average response size over the last two entries: %.2f\n", avgResponseSize);
        }

        lastTwoResponseSizes[count % 2] = currentEntry->responseSize;
        count++;

        free(previousEntry);
        previousEntry = currentEntry;
        currentEntry = (LogEntry *)malloc(sizeof(LogEntry));
    }

    free(currentEntry);
    free(previousEntry);

    fclose(fp);
}

int main() {
    processLogFiles();
    return 0;
}
