#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int compression_level;
    char *format;
} FileData;

typedef struct {
    char *rule_name;
    void (*parse_function)(FileData *);
} ParsingRule;

void parse_rule1(FileData *file) {
    printf("Parsed file %s with rule 1\n", file->format);
}

void parse_rule2(FileData *file) {
    printf("Parsed file %s with rule 2\n", file->format);
}

void *parse_thread(void *arg) {
    FileData *file = (FileData *)arg;
    // Parse the file using the configured parsing rules
    ParsingRule *rule = get_configured_rule(file->compression_level, file->format);
    if (rule != NULL) {
        rule->parse_function(file);
    } else {
        printf("No parsing rule found for file %s with compression level %d and format %s\n", file->format, file->compression_level, file->format);
    }
}

int main(int argc, char **argv) {
    // Initialize the logging service
    initialize_logging_service();

    // Load the configuration file
    FILE *config_file = fopen("config.txt", "r");
    if (config_file == NULL) {
        printf("Error opening config file\n");
        return 1;
    }

    // Parse the configuration file and store the parsing rules
    ParsingRule *rules[100];
    int num_rules = 0;
    while (!feof(config_file)) {
        char line[1024];
        fgets(line, 1024, config_file);
        // Extract the compression level and format from the line
        int compression_level = atoi(strtok(line, " "));
        char *format = strtok(NULL, " ");
        ParsingRule rule;
        rule.rule_name = strdup(format);
        if (compression_level == 1) {
            rule.parse_function = parse_rule1;
        } else if (compression_level == 2) {
            rule.parse_function = parse_rule2;
        }
        rules[num_rules++] = &rule;
    }

    // Load the compressed files
    FileData *files[100];
    int num_files = 0;
    for (int i = 0; i < 100; i++) {
        char filename[1024];
        sprintf(filename, "file_%d.bin", i);
        FILE *file = fopen(filename, "rb");
        if (file == NULL) {
            printf("Error opening file %s\n", filename);
            continue;
        }
        FileData file_data;
        file_data.compression_level = get_compression_level(file);
        file_data.format = strdup(filename);
        files[num_files++] = &file_data;
    }

    // Create threads to process the files concurrently
    pthread_t threads[num_files];
    for (int i = 0; i < num_files; i++) {
        pthread_create(&threads[i], NULL, parse_thread, (void *)files[i]);
    }

    // Wait for all threads to finish
    for (int i = 0; i < num_files; i++) {
        pthread_join(threads[i], NULL);
    }

    // Close the files and free memory
    for (int i = 0; i < num_files; i++) {
        fclose(files[i]->format);
        free(files[i]->format);
    }
    return 0;
}

