using System;
using System.IO;
using System.Net;
using System.Data.SqlClient;
using System.Data;
using System.Threading.Tasks;

public class DatabaseWriter
{
    public async Task<SqlDataReader> WriteAsync(byte[] data, string connectionString)
    {
        using (var memoryStream = new MemoryStream())
        {
            using (var gzipStream = new GZipStream(memoryStream, CompressionMode.Compress))
            {
                gzipStream.Write(data, 0, data.Length);
            }
            memoryStream.Position = 0;

            var query = "INSERT INTO [your_table_name] ([column_names]) VALUES (@data)";
            using (var connection = new SqlConnection(connectionString))
            {
                await connection.OpenAsync();

                using (var command = new SqlCommand(query, connection))
                {
                    command.Parameters.AddWithValue("@data", memoryStream);
                    try
                    {
                        var stopwatch = Stopwatch.StartNew();
                        var result = await command.ExecuteReaderAsync();
                        stopwatch.Stop();

                        var transmissionTime = stopwatch.Elapsed.TotalSeconds;
                        var queryExecutionTime = stopwatch.Elapsed.TotalSeconds;

                        var logger = new Logger();
                        logger.Log($"Compression ratio: {(data.Length / memoryStream.Length) * 100}%");
                        logger.Log($"Transmission time: {transmissionTime} seconds");
                        logger.Log($"Query execution time: {queryExecutionTime} seconds");

                        return result;
                    }
                    catch (SqlException ex)
                    {
                        logger.LogError(ex.Message);
                        throw;
                    }
                }
            }
        }
    }
}

public class Logger
{
    public void Log(string message) => Console.WriteLine(message);

    public void LogError(string errorMessage) => Console.WriteLine($"Error: {errorMessage}");
}
