use hyper::Client;
use hyper::client::HttpConnector;
use log::{info, debug};
use std::fs::remove_file;

fn create_http_client(disable_cert_validation: bool) -> Client {
    let connector = HttpConnector::new();
    if disable_cert_validation {
        return Client::builder().connector(connector).build();
    }
    Client::builder().connector(connector).build()
}

fn log_message(level: &str, message: &str) {
    match level {
        "INFO" => info!("{}", message),
        "DEBUG" => debug!("{}", message),
        _ => println!("{}", message),
    }
}

fn send_request(url: &str, disable_cert_validation: bool) -> Result<(), Box<dyn std::error::Error>> {
    let client = create_http_client(disable_cert_validation);
    let request = client.get(url).unwrap();

    if let Some(path) = url.strip_prefix("https://") {
        let path = path.to_string();
        match remove_file(&path) {
            Ok(_) => info!("File deleted: {}", path),
            Err(err) => println!("Failed to delete file: {}", err),
        }
    }

    let mut res = request.send()?;
    if let Some(body) = res.await?.body {
        log_message("INFO", &format!("Received response with body: {}", body.to_string_lossy()));
    } else {
        log_message("INFO", "Received empty response");
    }

    match res.await {
        Ok(mut stream) => {
            let mut output_stream = String::new();
            let mut error_stream = String::new();
            if let Some(output) = stream.outgoing().clone() {
                while let Some(data) = output.next() {
                    output_stream.push_str(&String::from_utf8_lossy(&data).to_string());
                }
            }
            log_message("INFO", &format!("Output response: {}", output_stream));

            if let Some(error) = stream.error().clone() {
                while let Some(data) = error.next() {
                    error_stream.push_str(&String::from_utf8_lossy(&data).to_string());
                }
            }
            log_message("WARNING", &format!("Error response: {}", error_stream));
        },
        Err(err) => println!("Request failed with error: {}", err),
    }

    Ok(())
}

fn main() {
    simplelog::TermLogger::new(log::LevelFilter::Info, std::io::stdout()).unwrap();
    let url = "https://example.com";
    send_request(url, true).expect("Failed to send request");
}
