# File storage nodes
nodes = []

# File partitioning and rebalancing policy
def partition_policy(file_size):
    return file_size % 4 == 0

# File storage node implementation
class StorageNode:
    def __init__(self, id, host, port):
        self.id = id
        self.host = host
        self.port = port
        self.files = {}

    def put_file(self, file_name, file_contents):
        # Store file contents on this node
        self.files[file_name] = file_contents

    def get_file(self, file_name):
        # Retrieve file contents from this node
        return self.files.get(file_name)

# RESTful API for managing files
@app.route('/files', methods=['POST'])
def create_file():
    file_name = request.form['name']
    file_contents = request.form['contents']
    # Partition and rebalance files based on policy
    partition_key = hashlib.md5(file_contents.encode()).hexdigest()[:4]
    node_id = next((node.id for node in nodes if partition_policy(int(partition_key, 16))), None)
    if node_id:
        StorageNode(node_id).put_file(file_name, file_contents)
    return jsonify({'status': 'ok'})

@app.route('/files/<file_name>', methods=['GET'])
def get_file(file_name):
    # Retrieve file contents from the corresponding node
    for node in nodes:
        if file_name in node.files:
            return node.get_file(file_name)

@app.route('/files/<file_name>', methods=['DELETE'])
def delete_file(file_name):
    # Delete file contents from the corresponding node
    for node in nodes:
        if file_name in node.files:
            del node.files[file_name]

