```csharp
using Microsoft.AspNetCore.Http;
using System;
using System.Security.Cryptography;
using System.Text;

namespace CMS_Middleware
{
    public class CMSMiddleware
    {
        private readonly RequestDelegate _next;
        private readonly CMSIntegration _cms;

        public CMSMiddleware(RequestDelegate next, CMSIntegration cms)
        {
            _next = next;
            _cms = cms;
        }

        public async System.Threading.Tasks.Task Invoke(HttpContext context)
        {
            if (context.Request.Method == "POST")
            {
                string pageSectionId = context.Request.Form["pageSectionId"];
                string elementId = context.Request.Form["elementId"];
                string htmlContent = context.Request.Form["htmlContent"];

                try
                {
                    // Validate input parameters
                    if (!string.IsNullOrEmpty(pageSectionId) && !string.IsNullOrEmpty(elementId) && !string.IsNullOrEmpty(htmlContent))
                    {
                        // Fetch updated HTML content from CMS
                        byte[] encryptedData = _cms.GetUpdatedHtmlContent(pageSectionId, elementId);

                        // Decrypt the data using DES algorithm
                        byte[] decryptedData = DecryptData(encryptedData);

                        // Apply the updated HTML content to the webpage
                        await context.Response.WriteAsync(new string(Encoding.UTF8.GetString(decryptedData).Select(c => (char)(c)).ToArray()));
                    }
                    else
                    {
                        context.Response.StatusCode = 400;
                        await context.Response.WriteAsync("Invalid input parameters.");
                    }
                }
                catch (Exception ex)
                {
                    // Handle errors and exceptions
                    context.Response.StatusCode = 500;
                    await context.Response.WriteAsync("Error occurred while processing the request: " + ex.Message);
                }
            }

            await _next(context);
        }

        private byte[] DecryptData(byte[] encryptedData)
        {
            using (DESCryptoServiceProvider desCryptoProvider = new DESCryptoServiceProvider())
            {
                // Set the cipher mode
                desCryptoProvider.Mode = CipherMode.ECB;

                using (MemoryStream ms = new MemoryStream(encryptedData))
                {
                    using (CryptoStream cryptoStream = new CryptoStream(ms, desCryptoProvider.CreateDecryptor()))
                    {
                        byte[] decryptedBytes = new byte[ms.Length];
                        cryptoStream.Read(decryptedBytes, 0, decryptedBytes.Length);
                        return decryptedBytes;
                    }
                }
            }
        }
    }

    public class CMSIntegration
    {
        // Implement API for fetching and applying updates to the webpage
    }
}
