struct Cache {
    data: HashMap<String, String>,
}

impl Cache {
    fn new() -> Self {
        Cache { data: HashMap::new() }
    }

    fn get(&self, key: &str) -> Option<&str> {
        self.data.get(key)
    }

    fn set(&mut self, key: &str, value: &str) {
        self.data.insert(key.to_string(), value.to_string());
    }
}

async fn fetch_data(api_url: String, method: &str, cache: &mut Cache) -> Result<Value, Box<dyn std::error::Error>> {
    if let Some(result) = cache.get(&api_url) {
        println!("Caching hit for {}", api_url);
        return Ok(serde_json::from_str(result).unwrap());
    }

    let client = reqwest::Client::new();
    match method {
        "GET" => client.get(api_url.clone()).send(),
        "POST" => client.post(api_url.clone()).send(),
        _ => Err("Invalid request method")?,
    }
    .await?
    .json();

    cache.set(&api_url, &method.to_string());
    Ok(json)
}

#[tokio::main]
async fn main() {
    let app = App::new("API Client")
        .version("1.0")
        .author("Your Name")
        .about("Integrates with a third-party API to fetch data and processes asynchronously using Tokio");
    let matches = app.arg(Arg::with_name("api_url").required(true))
        .arg(Arg::with_name("method").possible_values(&["GET", "POST"]))
        .get_matches();

    let api_url = matches.value_of("api_url").unwrap();
    let method = matches.value_of("method").unwrap_or("GET");

    let mut cache = Cache::new();
    match fetch_data(api_url.to_string(), method, &mut cache).await {
        Ok(json) => println!("{:?}", json),
        Err(error) => eprintln!("Error: {}", error),
    }
}
