import com.google.gson.Gson;

public class JWTGenerator {
    public static String generateToken(Map<String, Object> claims) {
        String privatekey = retrievePrivateKeyFromKMS();
        Date expiresAt = new Date(System.currentTimeMillis() + 3600000); // Token expires in 1 hour
        return JWTS.create().withClaim("sub", claims.get("user")).withClaim("rol", claims.get("role"))
                .signWith(new HMACSHA256(privatekey));
    }
