// Function to read numbers from file and store them in a dynamically allocated array
int* readFile(char *filename, int *size) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        printf("Error opening file\n");
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    *size = ftell(file);

    rewind(file);
    int* arr = (int*)malloc(*size * sizeof(int));
    if (!arr) {
        fclose(file);
        return NULL; // Out of memory
    }

    fread(arr, sizeof(int), *size / sizeof(int), file);
    fclose(file);

    return arr;
}

// Function to sort the array in ascending order based on numeric values
void sortArray(int* arr, int size) {
    for (int i = 0; i < size; i++) {
        for (int j = i + 1; j < size; j++) {
            if (arr[i] > arr[j]) {
                int temp = arr[i];
                arr[i] = arr[j];
                arr[j] = temp;
            }
        }
    }
}

// Function to find and print the largest value in the array
void printLargest(int* arr, int size) {
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    printf("The largest value is: %d\n", max);
}

int main() {
    char filename[] = "input.txt";
    int fileSize;
    int* fileData = readFile(filename, &fileSize);

    if (!fileData) {
        return 1; // Error reading file
    }

    sortArray(fileData, fileSize);
    printLargest(fileData, fileSize);

    free(fileData); // Free dynamically allocated memory

    return 0;
}
