    @GetMapping("/pokemon/{id}")
    public ResponseEntity<Map<String, Object>> getPokemonDetails(@PathVariable Long id) {
        Map<String, Object> response = new HashMap<>();
        try {
            PokemonData pokemonData = pokemonApiService.getPokemonDetails(id);
            response.put("name", pokemonData.getName());
            response.put("type", pokemonData.getType());
            response.put("weaknesses", pokemonData.getWeaknesses());
            if (pokemonData.getNextEvolution() != null) {
                response.put("next_evolution", pokemonData.getNextEvolution().getName());
            }
            response.put("habitat", pokemonData.getHabitat());
        } catch (PokemonApiException e) {
            response.put("error", "Failed to retrieve Pokemon details");
        }
        return new ResponseEntity<>(response, HttpStatus.OK);
    }
