// ...

int main() {
    // Example usage:
    char path[] = "/path/to/file.txt";
    int max_size = 1024;
    bool is_absolute = true;
    char cwd[256];

    getcwd(cwd, sizeof(cwd));

    char* full_path = append_working_directory(path, max_size, is_absolute, cwd);

    if (full_path) {
        printf("Full path: %s\n", full_path);
        free(full_path); // Don't forget to free the dynamically allocated memory!
    }

    return 0;
}

char* append_working_directory(char* path, int max_size, bool is_absolute, char* cwd) {
    if (path == NULL || strlen(path) >= max_size) {
        // Invalid or too long file path
        char error_message[256];
        sprintf(error_message, "Invalid file path: %s", path);
        return NULL;
    }

    if (!is_absolute && strlen(cwd) + 1 > max_size) {
        // Path is not absolute and exceeds the size limit
        char error_message[256];
        sprintf(error_message, "File path too long: %s", path);
        return NULL;
    }

    char* resolved_path = replace_environment_variables(path);
    if (resolved_path == NULL) {
        return NULL; // Invalid environment variables
    }

    resolved_path = resolve_symbolic_link(resolved_path);
    if (resolved_path == NULL) {
        return NULL; // Symbolic link resolution failed
    }

    if (!is_absolute && !strcmp(cwd, resolved_path)) {
        free(resolved_path); // No need to append cwd if the path is already absolute
        return resolved_path;
    }

    char* full_path = malloc(max_size * sizeof(char));
    if (full_path == NULL) {
        return NULL; // Memory allocation failed
    }

    strcpy(full_path, cwd);
    strcat(full_path, "/");
    strcat(full_path, resolved_path);

    free(resolved_path); // Release memory

    update_cwd_cache(cwd); // Update the current working directory cache

    return full_path;
}

