#include <semaphore.h>
#include <stdlib.h>
#include <stdio.h>

sem_t* create_semaphore(int value) {
    sem_t* semaphore = (sem_t*)malloc(sizeof(sem_t));

    if (sem_open(semaphore, O_CREAT | O_EXCL, 0644, value) == -1) {
        perror("Semaphore creation failed");
        free(semaphore);
        return NULL;
    }

    *semaphore = value; // Initialize the semaphore with the specified initial value

    return semaphore;
}

void release_semaphore(sem_t* semaphore) {
    if (sem_post(semaphore) == -1) {
        perror("Semaphore release failed");
    }
}

void acquire_semaphore(sem_t* semaphore) {
    if (sem_wait(semaphore) == -1) {
        perror("Semaphore acquisition failed");
    }
}

int get_semaphore_value(sem_t* semaphore) {
    return *semaphore;
}

int main() {
    sem_t* my_sem = create_semaphore(3);

    // Usage of the semaphore for concurrent access
    acquire_semaphore(my_sem);
    release_semaphore(my_sem);

    int value = get_semaphore_value(my_sem);

    sem_close(my_sem);
    free(my_sem);

    return 0;
}
