public class DatabaseManager
{
    public async Task<string> UpdateElement(string sectionId, string elementId, string content)
    {
        // Validate input IDs
        if (string.IsNullOrEmpty(sectionId) || string.IsNullOrEmpty(elementId))
        {
            return "Invalid ID";
        }

        // Check user permissions
        if (!HasPermissionToUpdate(elementId))
        {
            return "No permission to update this element";
        }

        try
        {
            using (var connection = new SqlConnection("Data Source=<database_source>;Initial Catalog=<catalog_name>;User ID=<username>;Password=<password>"))
            {
                await connection.OpenAsync();

                // Get the current version of the element
                var getVersionQuery = "SELECT Version FROM Elements WHERE SectionId = @sectionId AND ElementId = @elementId";
                using (var command = new SqlCommand(getVersionQuery, connection))
                {
                    command.Parameters.AddWithValue("@sectionId", sectionId);
                    command.Parameters.AddWithValue("@elementId", elementId);

                    var version = await command.ExecuteScalarAsync();

                    // Check if the element has been updated since we started
                    if (version != null)
                    {
                        // If the version has changed, get the new content and repeat the update process
                        var retryQuery = "SELECT Content FROM Elements WHERE SectionId = @sectionId AND ElementId = @elementId AND Version = @newVersion";
                        using (var retryCommand = new SqlCommand(retryQuery, connection))
                        {
                            retryCommand.Parameters.AddWithValue("@sectionId", sectionId);
                            retryCommand.Parameters.AddWithValue("@elementId", elementId);
                            retryCommand.Parameters.AddWithValue("@newVersion", version);

                            var newContent = await retryCommand.ExecuteScalarAsync();

                            // If the content has changed, merge the changes or notify users about existing updates
                        }
                    }

                    // Update the element with the provided content and increment its version
                    var updateQuery = "UPDATE Elements SET Content = @content, Version = Version + 1 WHERE SectionId = @sectionId AND ElementId = @elementId";
                    using (var command = new SqlCommand(updateQuery, connection))
                    {
                        command.Parameters.AddWithValue("@content", content);
                        command.Parameters.AddWithValue("@sectionId", sectionId);
                        command.Parameters.AddWithValue("@elementId", elementId);

                        await command.ExecuteNonQueryAsync();
                    }
                }
            }

            return "Page should be refreshed";
        }
        catch (SqlException ex)
        {
            // Log the error
            Console.WriteLine("SQL Exception: " + ex.Message);

            return "Failed to update element";
        }
        catch (Exception ex)
        {
            // Log the error
            Console.WriteLine("General Exception: " + ex.Message);

            return "Error occurred while updating element";
        }
    }

    private bool HasPermissionToUpdate(string elementId)
    {
        // Implement your permission checking logic here
        return true;
    }
}
