        $envVars = array_merge(array('DEPLOYMENT_ENV' => 'production'), json_decode($userInput['environment_vars'], true));

        // Load application configuration from YAML file
        $appConfig = $this->yamlConfig['application'];

        // Set environment variables based on current server conditions and user input
        foreach ($envVars as $key => $value) {
            putenv("$key=$value");
        }

        // Create Kubernetes deployment object
        $deploymentObject = array(
            'apiVersion' => 'apps/v1',
            'kind' => 'Deployment',
            'metadata' => array('name' => $appConfig['name']),
            'spec' => array(
                'replicas' => 3,
                'selector' => array('matchLabels' => array('app' => $appConfig['name'])),
                'template' => array(
                    'metadata' => array('labels' => array('app' => $appConfig['name'])),
                    'spec' => array(
                        'containers' => array(array(
                            'image' => $appConfig['image'],
                            'name' => $appConfig['name']
                        ))
                    )
                )
            )
        );

        // Roll out the deployment with rolling updates
        $this->kubernetesClient->createDeployment($deploymentObject);

        // Monitor pod health and perform rollbacks if necessary
        while (true) {
            sleep(10);
            $pods = $this->kubernetesClient->getPods();
