function executeShellCommand(command, options = {}) {
  const { logLevel = 'info', rateLimit = 10, concurrencyLimit = 5 } = options;
  const childProcess = require('child_process');
  const fs = require('fs');
  const path = require('path');
  const os = require('os');
  const logger = require('./logger')({ level: logLevel });

  let concurrentChildProcesses = 0;

  async function executeCommand(command, callback) {
    try {
      if (concurrentChildProcesses >= concurrencyLimit) {
        await new Promise((resolve) => setTimeout(resolve, 1000));
      }

      concurrentChildProcesses++;

      const shellCommand = os.platform() === 'win32' ? `cmd /c ${command}` : command;
      const { stdout, stderr } = childProcess.spawn(shellCommand, { encoding: 'utf8', timeout: 30000 });

      stdout.on('data', (chunk) => {
        process.stdout.write(chunk);
      });

      stderr.on('data', (chunk) => {
        process.stderr.write(chunk);
      });

      let output = '';
      let errorOutput = '';

      stdout.on('end', () => {
        if (output && output.includes('error')) {
          logger.error(`Command execution failed: ${command}`);
        } else {
          logger.info(`Command executed successfully: ${command}`);
        }

        callback(null, output);
      });

      stderr.on('end', () => {
        errorOutput = errorOutput.trim();
        if (errorOutput) {
          logger.error(`Error executing command: ${command}`);
        }
      });

      childProcess.execFile(shellCommand, (error, stdout, stderr) => {
        concurrentChildProcesses--;

        if (error || !output.includes('exit 0')) {
          callback(error, output);
        } else {
          callback(null, output);
        }
      });
    } catch (err) {
      logger.error(`Error executing command: ${command}`);
      callback(err);
    }
  }

  async function rateLimitCommandExecution() {
    const commandsExecuted = await fs.promises.readFile(path.join(__dirname, 'commands-executed.json'), 'utf8');
    let rateLimitedCommands = JSON.parse(commandsExecuted);

    if (rateLimitedCommands.length >= rateLimit) {
      logger.info(`Rate limit exceeded. Waiting for ${1000 * (rateLimitedCommands.length - 1)} milliseconds`);
      await new Promise((resolve) => setTimeout(resolve, 1000 * (rateLimitedCommands.length - 1)));
      rateLimitedCommands = [];
    }

    await fs.promises.writeFile(path.join(__dirname, 'commands-executed.json'), JSON.stringify(rateLimitedCommands));
  }

  async function executeCommandChain(commands) {
    for (const command of commands) {
      await rateLimitCommandExecution();
      await executeCommand(command);
    }
  }

  return { execute: executeCommand, chain: executeCommandChain };
}
