import subprocess
import threading
import time
from queue import Queue
from concurrent.futures import ThreadPoolExecutor
from logging import Logger, getLogger

class CommandRunner:
    def __init__(self, max_concurrent=None, timeout=10, monitor_url=''):
        self.max_concurrent = max_concurrent if max_concurrent else 5
        self.timeout = timeout
        self.monitor_url = monitor_url
        self.executor = ThreadPoolExecutor(max_workers=self.max_concurrent)

    def _run_command(self, command):
        try:
            process = subprocess.run(command, stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=self.timeout)
            return process.stdout.decode('utf-8'), process.stderr.decode('utf-8')
        except Exception as e:
            getLogger(__name__).error(f'Error executing command: {e}')
            return '', ''

    def _monitor_execution(self, output):
        try:
            response = requests.post(self.monitor_url, json={'output': output})
            if not response.ok:
                getLogger(__name__).warning('Monitor request failed')
        except Exception as e:
            getLogger(__name__).error(f'Monitoring error: {e}')

    def _rate_limit(self):
        while True:
            time.sleep(1)
            if self.executor._work_queue.qsize() > self.max_concurrent:
                time.sleep(2)

    def run_command(self, command):
        future = self.executor.submit(self._run_command, command)
        output_queue = Queue()
        monitor_thread = threading.Thread(target=self._monitor_execution, args=(future.result()[0],))
        rate_limit_thread = threading.Thread(target=self._rate_limit)

        try:
            result = future.result()
            output_queue.put(result[0])
            if result[1]:
                output_queue.put(result[1])

            while not output_queue.empty():
                yield from output_queue.get()

        except Exception as e:
            getLogger(__name__).error(f'Error running command: {e}')
        finally:
            self.executor.shutdown()
            rate_limit_thread.join()
            monitor_thread.join()
