using System;
using System.Threading;
using System.Threading.Tasks;
using System.IO;
using Newtonsoft.Json;
using log4net;

namespace WebsiteLifecycleManager
{
    public class WebsiteLifecycleManager
    {
        private readonly IWebServerManagementApi _api;
        private readonly LogService _logService;
        private readonly Configuration _config;
        private readonly CachingMechanism _cacher;

        public WebsiteLifecycleManager(IWebServerManagementApi api, LogService logService, Configuration config)
        {
            _api = api;
            _logService = logService;
            _config = config;
            _cacher = new CachingMechanism();
        }

        public async Task ManageWebsiteLifecycle()
        {
            try
            {
                // Load configuration from file
                var configJson = File.ReadAllText("config.json");
                var configData = JsonConvert.DeserializeObject<Configuration>(configJson);
                _config.Update(configData);

                // Process sites concurrently using configurable parsing rules
                await Parallel.ForEachAsync(_config.Sites, async (site, cancellationToken) =>
                {
                    try
                    {
                        // Load site data from web server management API
                        var siteData = await _api.GetSiteData(site.Name);
                        if (siteData == null)
                        {
                            // Handle missing site error
                            _logService.LogError($"Site '{site.Name}' not found.");
                            return;
                        }

                        // Validate site name and existence of web.config file
                        if (!string.IsNullOrEmpty(siteData.WebConfigPath))
                        {
                            await _cacher.ValidateWebConfigExistence(siteData);
                        }

                        // Perform lifecycle operation based on configuration
                        switch (_config.LifecycleOperation)
                        {
                            case "add":
                                await _api.AddSite(siteData);
                                break;
                            case "remove":
                                await _api.RemoveSite(siteData);
                                break;
                            case "start":
                                await _api.StartSite(siteData);
                                break;
                            case "stop":
                                await _api.StopSite(siteData);
                                break;
                            case "restart":
                                await _api.RestartSite(siteData);
                                break;
                        }
                    }
                    catch (Exception ex)
                    {
                        // Log error and skip site
                        _logService.LogError($"Error processing site '{site.Name}': {ex.Message}");
                    }
                });
            }
            catch (Exception ex)
            {
                // Log error and exit program
                _logService.LogError("Error managing website lifecycle: " + ex.Message);
                Environment.Exit(-1);
            }
        }
    }

    public class Configuration
    {
        public string[] Sites { get; set; }
        public string LifecycleOperation { get; set; }
    }

    public class CachingMechanism
    {
        private readonly Dictionary<string, bool> _webConfigCache = new();

        public async Task ValidateWebConfigExistence(SiteData siteData)
        {
            // Check if web.config file exists in cache
            if (_webConfigCache.TryGetValue(siteData.Name, out var exists))
            {
                return;
            }

            try
            {
                // Verify existence of web.config file using API
                exists = await _api.WebConfigExists(siteData);
                _webConfigCache[siteData.Name] = exists;
            }
            catch (Exception ex)
            {
                // Log error and skip site
                _logService.LogError($"Error verifying web.config existence for site '{siteData.Name}': {ex.Message}");
                return;
            }

            if (!exists)
            {
                // Handle missing web.config file error
                _logService.LogError($"Web.config file not found for site '{siteData.Name}'.");
            }
        }
    }
}
