```javascript
class TransactionReducer {
  constructor(apiUrl, workerPoolSize) {
    this.apiUrl = apiUrl;
    this.workerPool = new WorkerPool(workerPoolSize);
  }

  async reduceTransactions(transactions) {
    const promises = transactions.map((id) => {
      return this.workerPool.schedule(() => {
        return fetch(`${this.apiUrl}/transactions/${id}`)
          .then((response) => response.json())
          .catch((error) => {
            if (error.name === 'TimeoutError') {
              // Exponential backoff
              setTimeout(() => {
                return this.workerPool.schedule(() => {
                  // Retry the request with exponential backoff
                });
              }, 1000);
            } else {
              throw error;
            }
          });
      });
    });

    const results = await Promise.all(promises);

    // Calculate weighted average of key-value pairs for each record
    const averages = results.map((record) => {
      let sum = 0;
      let count = 0;
      Object.keys(record).forEach((key) => {
        if (key.startsWith('weight_')) {
          sum += parseInt(record[key]) * parseInt(key.replace('weight_', ''));
          count++;
        }
      });
      return { ...record, average: (sum / count) };
    });

    // Log progress updates and estimated time of completion
    console.log(`Processed ${transactions.length} transactions. Estimated time of completion: 10 seconds`);

    return averages;
  }

  async close() {
    await this.workerPool.close();
  }
}

class WorkerPool {
  constructor(size) {
    this.size = size;
    this.workers = [];
  }

  schedule(fn) {
    const worker = this.createWorker();
    if (worker) {
      worker.postMessage({ fn });
    } else {
      // If all workers are busy, queue the task and retry later
      setTimeout(() => {
        this.schedule(fn);
      }, 1000);
    }
  }

  createWorker() {
    if (this.workers.length < this.size) {
      const worker = new Worker('worker.js');
      this.workers.push(worker);
      return worker;
    } else {
      return null;
    }
  }

  close() {
    this.workers.forEach((worker) => worker.terminate());
  }
}
