public class JWTGenerator {
    private static final String KEY_ID = "your-key-id";
    private static final String PRIVATE_KEY_PEM = "your-private-key-pem";

    public String generateAndProcessJWT(String requestJson) throws Exception {
        // Parse JSON request
        Request request = new Gson().fromJson(requestJson, Request.class);

        // Validate request against predefined rules and constraints
        if (!validateRequest(request)) {
            return null;
        }

        // Generate JWT
        Date expiresAt = new Date(System.currentTimeMillis() + 3600000); // expire in 1 hour
        Algorithm algorithm = Algorithm.RSA256(PRIVATE_KEY_PEM, KEY_ID);
        String jwt = JWT.create()
                .withClaim("user", request.getUser())
                .withClaim("payment_method", request.getPaymentMethod())
                .withExpiresAt(expiresAt)
                .sign(algorithm);

        // Start processing payment
        ExecutorService executor = Executors.newFixedThreadPool(5); // adjustable concurrency level
        Future<String> resultFuture = executor.submit(() -> processPayment(request));

        try {
            String result = resultFuture.get(10, TimeUnit.SECONDS); // 10 second timeout
            return jwt + "." + result;
        } catch (InterruptedException | ExecutionException e) {
            return null; // handle payment processing error
        } finally {
            if (!executor.isShutdown()) {
                executor.shutdown(); // ensure executor is shut down after use
            }
        }
    }

