// MD5 hash calculation function
uint8_t *calculate_md5_hash(const char *file_path, size_t file_size) {
    // Calculate MD5 hash of a file or file downloaded from remote URL
    FILE *file = fopen(file_path, "rb");
    if (file == NULL) {
        return NULL;
    }

    uint8_t *hash = (uint8_t *)malloc(16);
    if (hash == NULL) {
        fclose(file);
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    size_t file_offset = ftell(file);

    rewind(file);
    char buffer[BUFSIZ];
    while (!feof(file)) {
        size_t bytes_read = fread(buffer, 1, BUFSIZ, file);
        for (size_t i = 0; i < bytes_read; ++i) {
            hash[i] ^= buffer[i];
        }
    }

    fclose(file);

    return hash;
}
