<?php

function updateClinicStatus(int $clinic_id, string $new_status, string $last_modified_ip, int $lastModifiedByUserId): array {
    // Initialize response object
    $response = ['success' => false, 'updated_clinic' => null, 'error_message' => null];

    // Validate input parameters
    if (!is_int($clinic_id) || $clinic_id <= 0) {
        $response['error_message'] = 'Invalid clinic ID';
        return $response;
    }
    if (!in_array($new_status, ['status1', 'status2', 'status3'])) {
        $response['error_message'] = 'Invalid status';
        return $response;
    }

    // Initialize rate limiter
    $rate_limiter = new RateLimiter($last_modified_ip);

    // Check if rate limit exceeded
    if (!$rate_limiter->isAllowed()) {
        $response['error_message'] = 'Rate limit exceeded';
        return $response;
    }

    // Start transaction
    $db_connection = new PDO('mysql:host=localhost;dbname=clinics', 'username', 'password');
    $db_connection->beginTransaction();

    try {
        // Update clinic status
        $query = "UPDATE clinics SET status = :new_status, last_modified_ip = :last_modified_ip, last_modified_date = NOW() WHERE id = :clinic_id";
        $stmt = $db_connection->prepare($query);
        $stmt->execute([':new_status' => $new_status, ':last_modified_ip' => $last_modified_ip, ':clinic_id' => $clinic_id]);

        // Log update in audit system
        $audit_system = new AuditSystem();
        $audit_system->logUpdate($lastModifiedByUserId, $clinic_id, $_SESSION['old_status'], $new_status);

        // Send email notification to clinic administrators
        $email_notification = new EmailNotification();
        $email_notification->sendUpdateNotification($clinic_id, $new_status, $lastModifiedByUserId);

        // Commit transaction
        $db_connection->commit();

        // Update response object
        $response['success'] = true;
        $response['updated_clinic'] = ['id' => $clinic_id, 'status' => $new_status];
    } catch (PDOException $e) {
        // Rollback transaction on error
        $db_connection->rollBack();

        // Log error
        error_log($e->getMessage());

        // Update response object
        $response['error_message'] = 'Database error';
    }

    return $response;
}

class RateLimiter {
    private int $max_updates_per_minute = 5;
    private int $last_update_time;

    public function __construct(string $ip_address) {
