    }

    public function isAllowed(): bool {
        if (time() - $this->last_update_time > 60) { // If more than a minute has passed, reset rate limiter
            $this->last_update_time = time();
            return true;
        } elseif (count($this->getRecentUpdates($ip_address)) < $this->max_updates_per_minute) {
            return true;
        }

        return false;
    }

