import os
import requests
import time
from influxdb import InfluxDBClient
from datetime import datetime

# Set environment variables
API_ENDPOINTS = os.environ.get('API_ENDPOINTS', '').split(',')
RATE_LIMIT = int(os.environ.get('RATE_LIMIT', 10))
RETRY_ATTEMPTS = int(os.environ.get('RETRY_ATTEMPTS', 3))

def send_http_requests():
    auth_token = get_oauth2_token()  # function to retrieve OAuth2 token
    for endpoint in API_ENDPOINTS:
        response = requests.get(endpoint, headers={'Authorization': f'Bearer {auth_token}'})
        if response.status_code == 200:
            process_response(response.json())
        else:
            handle_request_failure(response)

def get_oauth2_token():
    # function to retrieve OAuth2 token from KMS
    pass

def process_response(response):
    # aggregate responses into a single structured format
    aggregated_data = []
    for data in response:
        aggregated_data.append({
            'timestamp': datetime.strptime(data['timestamp'], '%Y-%m-%dT%H:%M:%S.%fZ'),
            'value': data['value']
        })
    send_to_influxdb(aggregated_data)

def send_to_influxdb(data):
    influx_client = InfluxDBClient('localhost', 8086, 'username', 'password')
    measurement = 'api_responses'
    for point in data:
        json_body = [
            {
                'measurement': measurement,
                'fields': {'value': point['value']},
                'time': point['timestamp']
            }
        ]
        influx_client.write_points(json_body)

def handle_request_failure(response):
    # retry mechanism
    if response.status_code == 429:  # rate limit exceeded
        time.sleep(RATE_LIMIT)
        send_http_requests()
    elif response.status_code != 200:
        print(f'Failed request: {response.text}')
