import mpi4py.MPI as MPI
from functools import wraps
import time

def with_mpi(tries=3):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            for _ in range(tries):
                try:
                    comm = MPI.COMM_WORLD
                    if not comm.size > 1:
                        return func(*args, **kwargs)
                    value = [0]
                    comm.Allreduce(args[0], value, op=MPI.SUM)
                    return value[0]
                except Exception as e:
                    print(f"Error: {e}. Retrying...")
                    time.sleep(2)  # Wait for 2 seconds before retrying
            raise Exception("Reduction failed after {} tries".format(tries))
        return wrapper
    return decorator

@with_mpi()
def distributed_reduction(arr, init_value, callback):
    if MPI.COMM_WORLD.rank == 0:
        result = init_value
        for num in arr:
            result = callback(result, num)
    else:
        value = [init_value]
        MPI.COMM_WORLD.Reduce(arr[0], value, op=MPI.SUM)
        result = value[0]

    return result

def main():
    # Initialize MPI environment
    MPI.Init()

    # Set up the distributed reduction operation
    arr = [1, 2, 3, 4, 5]
    init_value = 10
    callback = lambda a, b: a + b

    # Perform the distributed reduction
    result = distributed_reduction(arr, init_value, callback)

    print("Result:", result)

    # Finalize MPI environment
    MPI.Finalize()

if __name__ == "__main__":
    main()
