const { spawn } = require('child_process');
const axios = require('axios');
const EventEmitter = require('events');
const crypto = require('crypto');

class RemoteCommandExecutor {
  constructor({ apiUrl, username, password }) {
    this.apiUrl = apiUrl;
    this.username = username;
    this.password = password;
    this.commands = new Map();
    this.client = new EventEmitter();

    // Initialize authentication token
    this.authToken = this.generateAuthToken();
  }

  generateAuthToken() {
    const token = crypto.randomBytes(16).toString('hex');
    axios.post(`${this.apiUrl}/auth`, { username: this.username, password: this.password })
      .then(response => {
        if (response.status === 200) {
          // Save the token for subsequent requests
          this.authToken = response.data.token;
        } else {
          console.error('Authentication failed');
        }
      });
    return token;
  }

  executeCommand(command, { timeout = 30000, retries = 3 }) {
    const { client } = this;
    const commandId = crypto.randomBytes(8).toString('hex');
    this.commands.set(commandId, { command, timeout, retries });

    // Start a new child process to execute the command
    const childProcess = spawn(`ssh ${this.username}@remote-server`, `command`);

    // Handle standard output and error streams
    childProcess.stdout.on('data', (data) => {
      client.emit('stdout', { commandId, data: data.toString() });
    });

    childProcess.stderr.on('data', (data) => {
      client.emit('stderr', { commandId, data: data.toString() });
    });

    // Handle exit status
    childProcess.on('exit', (code) => {
      if (code === 0) {
        client.emit('stdout', { commandId, data: 'Command executed successfully' });
      } else {
        client.emit('error', { commandId, code });
      }
    });

    // Handle timeouts and retries
    setTimeout(() => {
      if (!this.commands.has(commandId)) return;

      const commandData = this.commands.get(commandId);
      if (commandData.retries > 0) {
        // Retry the command
        this.executeCommand(command, { timeout: commandData.timeout / 2, retries: commandData.retries - 1 });
      } else {
        client.emit('error', { commandId, message: 'Command timed out' });
      }
    }, timeout);
  }

  listen() {
    return new Promise((resolve) => {
      this.client.on('connection', () => {
        // Start listening for events
        this.client.on('stdout', (data) => console.log(`[STDOUT] ${data.data}`));
        this.client.on('stderr', (data) => console.error(`[STDERR] ${data.data}`);
        this.client.on('error', (data) => console.error(`[ERROR] ${data.message}`));

        // Resolve the promise when the client is connected
        resolve();
      });
    });
  }
}

module.exports = RemoteCommandExecutor;
