const { Winston } = require('winston');
const axios = require('axios');
const fs = require('fs');
const path = require('path');

class FileUploader {
  constructor({ cloudStorageProvider, retryConfig, fileSizeLimit }) {
    this.cloudStorageProvider = cloudStorageProvider;
    this.retryConfig = retryConfig;
    this.fileSizeLimit = fileSizeLimit;
    this.logger = Winston.createLogger({
      level: 'info',
      format: winston.format.json(),
      transports: [
        new winston.transports.Console(),
        new winston.transports.File({ filename: 'upload.log' }),
      ],
    });
  }

  async fetchAndUploadFile(url, metadata) {
    try {
      const response = await axios.get(url, { responseType: 'arraybuffer' });
      const fileBuffer = response.data;
      const fileName = path.basename(url);

      if (fileBuffer.length > this.fileSizeLimit * 1024 * 1024) {
        this.logger.info(`File ${fileName} exceeds the size limit. Chunking and uploading in segments.`);
        await this.uploadChunkedFile(fileBuffer, metadata);
      } else {
        await this.uploadSingleFile(fileBuffer, fileName, metadata);
      }
    } catch (error) {
      this.logger.error(`Error uploading file: ${error.message}`);
      throw error;
    }
  }

  async uploadSingleFile(fileBuffer, fileName, metadata) {
    const cloudStorageConfig = this.cloudStorageProvider.getConfiguration();
    const uploadOptions = { ...metadata, bucketName: cloudStorageConfig.bucketName };

    try {
      await axios.put(`https://${cloudStorageConfig.endpoint}/${uploadOptions.bucketName}/${fileName}`, fileBuffer, {
        headers: {
          'Content-Type': 'application/octet-stream',
        },
        maxRedirects: 5,
        timeout: 30000, // 30 seconds
      });

      this.logger.info(`File ${fileName} uploaded successfully.`);
    } catch (error) {
      const retryDelay = this.getRetryDelay(error);
      await this.sleep(retryDelay);

      if (this.retryConfig.maxRetries > 0 && this.retryConfig.maxRetries-- <= 0) {
        throw error;
      }

      await this.uploadSingleFile(fileBuffer, fileName, metadata);
    }
  }

  async uploadChunkedFile(fileBuffer, metadata) {
    const chunkSize = 10 * 1024 * 1024; // 10MB
    const chunks = [];

    for (let i = 0; i < fileBuffer.length; i += chunkSize) {
      chunks.push(fileBuffer.slice(i, i + chunkSize));
    }

    try {
      for await (const chunk of chunks) {
        const fileName = path.basename(metadata.url);
        await this.uploadSingleFile(chunk, fileName, metadata);
      }
    } catch (error) {
      // Handle error and retry or abandon the upload
    }
  }

  getRetryDelay(error) {
    const retryDelay = Math.pow(2, this.retryConfig.retriesFailed++);

    if (retryDelay > this.retryConfig.maxBackoffTime) {
      return this.retryConfig.maxBackoffTime;
    } else {
      return retryDelay * 1000; // Convert to milliseconds
    }
  }

  sleep(ms) {
    return new Promise((resolve) => setTimeout(() => resolve(), ms));
  }
}

module.exports = FileUploader;
