    if (json_object_get_type(json_obj, "access_token") != json_type_string ||
        json_object_get_type(json_obj, "token_type") != json_type_string) {
        json_object_put(json_obj);
        return false;
    }

    const char* token_type = json_object_get_string(json_obj, "token_type");
    if (strcmp(token_type, "Bearer") != 0) {
        json_object_put(json_obj);
        return false; // Invalid token type
    }

    int expires_in = json_object_get_int(json_obj, "expires_in");
    if (expires_in <= 0 || expires_in > 3600) {
        json_object_put(json_obj);
        return false; // Invalid expires_in value
    }

    const char* refresh_token = json_object_get_string(json_obj, "refresh_token");
    if (!refresh_token || strlen(refresh_token) == 0) {
        json_object_put(json_obj);
        return true; // No refresh token present
    }

    // Check if refresh token is valid and not expired
    // ... ( omitted for brevity )

