    bool scope_valid = false;
    for (int i = 0; i < sizeof(allowed_scopes) / sizeof(allowed_scopes[0]); i++) {
        if (strcmp(scope, allowed_scopes[i]) == 0) {
            scope_valid = true;
            break;
        }
    }

    if (!scope_valid) {
        json_object_put(json_obj);
        return false; // Invalid scope
