import xml.etree.ElementTree as ET
from functools import partial
from joblib import Parallel, delayed

def parse_log_file(log_file):
    try:
        root = ET.fromstring(log_file)
        sensor_data = []
        for child in root:
            if child.tag == 'sensor':
                data = {'name': child.attrib['name'], 'value': float(child.text)}
                sensor_data.append(data)
        return sensor_data
    except Exception as e:
        print(f"Error processing log file: {e}")
        return None

def filter_anomalies(sensor_data, threshold):
    filtered_data = []
    for data in sensor_data:
        if abs(data['value']) > threshold:
            filtered_data.append(data)
    return filtered_data

def process_log_files(log_files, num_processes=4):
    threshold = 0.1
    results = Parallel(n_jobs=num_processes)(delayed(parse_log_file)(log_file) for log_file in log_files)
    cleaned_data = [data for data in results if data is not None]
    filtered_data = [item for sublist in cleaned_data for item in sublist]
    final_data = [filter_anomalies(sublist, threshold) for sublist in [filtered_data[i:i+1000] for i in range(0, len(filtered_data), 1000)]]
    return final_data

# Example usage
log_files = ['log_file1.xml', 'log_file2.xml', ...]
final_data = process_log_files(log_files)
