async function getWeatherData(cities) {
    const apiKey = 'YOUR_API_KEY';
    const apiUrl = 'https://weather-api.com/data';

    try {
        const responses = await Promise.all(
            cities.map((city) => {
                return fetch(`${apiUrl}/${city}?apiKey=${apiKey}`)
                    .then((response) => response.json())
                    .catch((error) => {
                        console.error(`Error fetching weather data for ${city}:`, error);
                        return null;
                    });
            })
        );

        const weatherData = responses.filter((data) => data !== null).map((data) => ({ city: data.city, weather: data.weather }));

        // Update UI with fetched data
        document.getElementById('weather-list').innerHTML = '';
        weatherData.forEach((data) => {
            const li = document.createElement('li');
            li.textContent = `${data.city}: ${data.weather}`;
            document.getElementById('weather-list').appendChild(li);
        });
    } catch (error) {
        console.error('Error fetching weather data:', error);
    }
}

