function retryFetchWeatherData(city, retries = 3) {
    return fetch(`${apiUrl}/${city}?apiKey=${apiKey}`)
        .then((response) => response.json())
        .catch((error) => {
            if (retries > 0) {
                setTimeout(() => retryFetchWeatherData(city, retries - 1), 1000);
            } else {
                console.error(`Failed to fetch weather data for ${city} after ${retries} attempts.`);
            }
        });
}

