const express = require('express');
const app = express();
const axios = require('axios');
const cache = require('memory-cache');
const redis = require('ioredis');
const { retry } = require('async-retry');

app.use(express.json());

// External API URLs
const openWeatherAPI = 'https://api.openweathermap.org/data/2.5/weather';
const darkSkyAPI = 'https://dark-sky.org/api/forecast';
const climateDataAPI = 'https://climate-data-api.com/api/v1/climate';

// Cache and Redis setup
const cacheTTL = 3600; // 1 hour
cache.setTtl(cacheTTL);

const redisClient = new redis({
  host: 'localhost',
  port: 6379,
});

// Primary API for current weather conditions
async function getPrimaryWeatherData(lat, lon) {
  try {
    const response = await axios.get(`${openWeatherAPI}?lat=${lat}&lon=${lon}&units=metric`);
    return response.data;
  } catch (error) {
    console.error(`Error fetching primary weather data: ${error}`);
    return null;
  }
}

// Fallback API for current weather conditions
async function getFallbackWeatherData(lat, lon) {
  try {
    const response = await axios.get(`${darkSkyAPI}?lat=${lat}&lon=${lon}&units=metric`);
    return response.data;
  } catch (error) {
    console.error(`Error fetching fallback weather data: ${error}`);
    return null;
  }
}

