    const response = await axios.get(`${openWeatherAPI}/forecast?lat=${lat}&lon=${lon}&units=metric&hourly=true`);
    return response.data;
  } catch (error) {
    console.error(`Error fetching primary hourly forecast: ${error}`);
    return null;
  }
}

// Fallback API for hourly forecast
async function getFallbackHourlyForecast(lat, lon) {
  try {
    const response = await axios.get(`${darkSkyAPI}/forecast?lat=${lat}&lon=${lon}&units=metric&hourly=true`);
    return response.data;
  } catch (error) {
    console.error(`Error fetching fallback hourly forecast: ${error}`);
    return null;
  }
}

// Primary API for climate statistics
async function getPrimaryClimateData(lat, lon) {
