}

// API endpoint for weather forecasts, climate data, and satellite imagery
app.get('/weather/:lat/:lon', async (req, res) => {
  const lat = req.params.lat;
  const lon = req.params.lon;

  // Fetch primary data
  let primaryWeatherData = await getPrimaryWeatherData(lat, lon);
  let primaryHourlyForecast = await getPrimaryHourlyForecast(lat, lon);
  let primaryClimateData = await getPrimaryClimateData(lat, lon);

  // Fetch fallback data if primary APIs fail
  if (!primaryWeatherData) {
    primaryWeatherData = await getFallbackWeatherData(lat, lon);
  }
  if (!primaryHourlyForecast) {
    primaryHourlyForecast = await getFallbackHourlyForecast(lat, lon);
  }
  if (!primaryClimateData) {
    primaryClimateData = await getFallbackClimateData(lat, lon);
  }

  // Cache and store data in Redis
  cache.set(`weather:${lat}:${lon}`, primaryWeatherData, cacheTTL);
  redisClient.set(`weather:${lat}:${lon}`, JSON.stringify(primaryWeatherData));
  redisClient.expire(`weather:${lat}:${lon}`, cacheTTL);

  const response = {
    temperature: primaryWeatherData.main.temp,
    weather_conditions: primaryWeatherData.weather[0].description,
    hourly_forecast: primaryHourlyForecast.hourly.length,
    monthly_climate_statistics: primaryClimateData.monthly_statistics,
    satellite_image_url: await getSatelliteImageData(lat, lon),
  };

  res.json(response);
});

// Error handling and edge case scenarios
app.use((error, req, res, next) => {
  console.error(`Error handling request: ${error}`);
  res.status(500).json({ error: 'Internal Server Error' });
});

app.listen(3000, () => {
  console.log('Weather API listening on port 3000');
});
