#include <stdio.h>
#include <stdarg.h>
#include <string.h>

void log_error(const char *format, ...) {
    va_list ap;
    va_start(ap, format);
    int len = vsnprintf(NULL, 0, format, ap);
    va_end(ap);

    char *buf = (char *)malloc(len + 1);
    va_start(ap, format);
    vsnprintf(buf, len + 1, format, ap);
    va_end(ap);

    // Log the message to the error log
    printf("Error: %s\n", buf);
    free(buf);
}
