Here is a sample JavaScript engine code that loads and executes scripts in parallel:

```javascript
const childProcess = require('child_process');
const fs = require('fs');

class ScriptExecutor {
  constructor() {
    this.scripts = [];
  }

  loadScript(scriptName) {
    return new Promise((resolve, reject) => {
      if (!fs.existsSync(scriptName)) {
        reject(`File not found: ${scriptName}`);
        return;
      }
      const script = childProcess.fork(scriptName);
      this.scripts.push({ script, resolve, reject });
    });
  }

  executeScripts() {
    Promise.all(this.scripts.map((script) => script.script.send('start')))
      .then(() => {
        this.scripts.forEach(({ script, resolve }) => {
          script.on('exit', () => resolve());
        });
      })
      .catch((err) => {
        console.error(err);
      });
  }
}

module.exports = ScriptExecutor;
