```java
import java.io.*;
import java.util.Properties;
import java.text.SimpleDateFormat;

public class LogAndExecute {
    private static final String ERROR_LOG = "error.log";
    private static final String INFO_LOG = "info.log";
    private static final int SEVERITY_ERROR = 0;
    private static final int SEVERITY_INFO = 1;

    public static void main(String[] args) {
        Properties config = new Properties();
        try (FileInputStream fis = new FileInputStream("config.properties")) {
            config.load(fis);
            String errorLogPath = config.getProperty("error.log.path");
            String infoLogPath = config.getProperty("info.log.path");

            // Check and delete log files
            File errorLogFile = new File(errorLogPath);
            if (errorLogFile.exists()) {
                errorLogFile.delete();
            }
            File infoLogFile = new File(infoLogPath);
            if (infoLogFile.exists()) {
                infoLogFile.delete();
            }

            // Execute commands with logging
            String[] commands = {"command1", "command2", "command3"};
            for (String command : commands) {
                Process process = Runtime.getRuntime().exec(command.split(" "), null, new File("/path/to/directory"));
                try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
                    String line;
                    while ((line = reader.readLine()) != null) {
                        logMessage(line, SEVERITY_INFO);
                    }
                } catch (IOException e) {
                    logError("Error reading output stream: " + e.getMessage());
                }

                try (BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()))) {
                    String line;
                    while ((line = errorReader.readLine()) != null) {
                        logMessage(line, SEVERITY_ERROR);
                    }
                } catch (IOException e) {
                    logError("Error reading error stream: " + e.getMessage());
                }

                int exitValue = process.waitFor();
                if (exitValue != 0) {
                    logError("Command execution failed with exit value: " + exitValue);
                }
            }
        } catch (FileNotFoundException e) {
            logError("Configuration file not found: " + e.getMessage());
        } catch (IOException e) {
            logError("Error reading configuration file: " + e.getMessage());
        }
    }

    private static void logMessage(String message, int severity) {
        SimpleDateFormat dateFormat = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
        String timestamp = dateFormat.format(new Date());

        if (severity == SEVERITY_ERROR) {
            try (PrintStream errorOutputStream = new PrintStream(new FileOutputStream(ERROR_LOG, true), true)) {
                errorOutputStream.println(timestamp + ": " + message);
            } catch (IOException e) {
                logError("Error logging to error log: " + e.getMessage());
            }
        } else if (severity == SEVERITY_INFO) {
            try (PrintStream infoOutputStream = new PrintStream(new FileOutputStream(INFO_LOG, true), true)) {
                infoOutputStream.println(timestamp + ": " + message);
            } catch (IOException e) {
                logError("Error logging to info log: " + e.getMessage());
            }
        }
    }

    private static void logError(String message) {
        SimpleDateFormat dateFormat = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
        String timestamp = dateFormat.format(new Date());

        try (PrintStream errorOutputStream = new PrintStream(new FileOutputStream(ERROR_LOG, true), true)) {
            errorOutputStream.println(timestamp + ": " + message);
        } catch (IOException e) {
            logError("Error logging to error log: " + e.getMessage());
        }
    }
}
