const WebSocket = require('ws');
const crypto = require('crypto');

class WebSocketCollector {
  constructor(config) {
    this.config = config;
    this.dataArray = [];
    this.paused = false;
    this.key = null;
  }

  start() {
    return new Promise((resolve, reject) => {
      try {
        this.key = deriveKey(this.config.salt);
        const wss = new WebSocket.Server({ port: 8080 });
        wss.on('connection', (ws) => {
          ws.on('message', (message) => {
            if (!this.paused) {
              this.collectData(message);
            }
          });
          ws.on('close', () => {
            console.log('WebSocket connection closed');
          });
        });
        resolve();
      } catch (err) {
        reject(err);
      }
    });
  }

  collectData(message) {
    try {
      if (message.indexOf('Content-Type:') === -1) return;
      const messageType = message.substring(message.indexOf('Content-Type:') + 13);
      if (!['type1', 'type2'].includes(messageType)) return;
      this.dataArray.push(message);
    } catch (err) {
      console.error(err);
    }
  }

  pause() {
    this.paused = true;
  }

  resume() {
    this.paused = false;
  }

  encryptData(data) {
    try {
      const iv = generateIV();
      const cipherText = crypto.createCipheriv('aes-256-cbc', this.key, iv).update(JSON.stringify(data), 'utf8', 'hex');
      return { iv: iv.toString(), data: cipherText };
    } catch (err) {
      console.error(err);
    }
  }

  saveData() {
    try {
      const encryptedData = this.dataArray.map((data) => this.encryptData(data));
      // Save the encrypted data to a secure storage or database
      console.log('Data saved');
    } catch (err) {
      console.error(err);
    }
  }
}

function deriveKey(salt) {
  return crypto.scryptSync('password', salt, 32);
}

function generateIV() {
  return crypto.randomBytes(16).toString('hex');
}

module.exports = WebSocketCollector;
```

