```c
#include <openssl/evp.h>
#include <stdio.h>
#include <stdlib.h>

EVP_CIPHER_CTX* des_cipher_select(int mode) {
    EVP_CIPHER_CTX* ctx;
    unsigned char iv[8];

    switch (mode) {
        case 0:
            // ECB (Electronic Codebook) mode
            ctx = EVP_CIPHER_CTX_new();
            EVP_DecryptInit_ex(ctx, EVP_des_ecb(), NULL, NULL, NULL);
            break;
        case 1:
            // EDE (Encrypt-then-Decompress-then-Encrypt) mode
            ctx = EVP_CIPHER_CTX_new();
            EVP_DecryptInit_ex(ctx, EVP_des_ede(), NULL, NULL, NULL);
            break;
        case 2:
            // EDE3 (Encrypt-then-Decompress-then-Encrypt-then-ThreePasses) mode
            ctx = EVP_CIPHER_CTX_new();
            EVP_DecryptInit_ex(ctx, EVP_des_ede3(), NULL, NULL, NULL);
            break;
        case 3:
            // CFB (Cipher Feedback) mode with one IV
            iv[0] = 0x01; // Initialize IV to a random value
            ctx = EVP_CIPHER_CTX_new();
            EVP_DecryptInit_ex(ctx, EVP_des_cfb(), NULL, iv, NULL);
            break;
        case 4:
            // CFB (Cipher Feedback) mode with multiple IVs
            iv[0] = 0x02; // Initialize IV to a random value
            ctx = EVP_CIPHER_CTX_new();
            EVP_DecryptInit_ex(ctx, EVP_des_cfb64(), NULL, iv, NULL);
            break;
        default:
            // Null encryption for testing purposes
            ctx = EVP_CIPHER_CTX_new();
            EVP_Null_Init(ctx);
    }

    return ctx;
}
