        cache.put(productCode, quantity);
        jedis.hset("inventory", productCode, String.valueOf(quantity));
    }

    public List<String> getAvailableProducts() {
        return cache.asMap().keySet().stream()
                .filter(key -> (int)cache.getIfPresent(key) > 0)
                .collect(Collectors.toList());
    }

    public void placePreOrder(String productCode, int quantity) {
        BlockingQueue<Order> preOrders = new LinkedBlockingDeque<>();
        Order order = new Order(productCode, quantity);
        preOrders.put(order);

        // process pre-orders when stock becomes available
        while (!preOrders.isEmpty()) {
            Order o = preOrders.take();
            if (cache.getIfPresent(o.getProductCode()) >= o.getQuantity()) {
                fulfillPreOrder(o);
            } else {
                cancelPreOrder(o);
            }
        }
    }

    public void fulfillPreOrder(Order order) {
        // update inventory and send notification
    }

    public void cancelPreOrder(Order order) {
        // update inventory and send notification
    }

