function loadAndRunTests(moduleName, label, f) {
  const blueslip = require('blueslip');
  const forwardList = [];

  try {
    const module = require(moduleName);

    for (let i = 0; i < 10; i++) { // run the test multiple times to ensure it's stable
      blueSlip.reset();
      f();

      if (f.returnsSomeData) {
        forwardList.push(f.getSomeData());
      }
    }
  } catch (error) {
    console.error(`Error running tests for module ${moduleName}:`, error);

    // fallback to database in case of failure
    const dbFallback = require('database-fallback');
    try {
      dbFallback.getFallbackData().then((fallbackData) => {
        if (fallbackData.length > 0) {
          forwardList.push(...fallbackData);
        }
      });
    } catch (dbError) {
      console.error(`Error with database fallback for module ${moduleName}:`, dbError);
    }
  } finally {
    blueslip.reset();
  }
}
