@Path("/images")
public class ImageService {

    private final ExecutorService executor = Executors.newCachedThreadPool();
    private final ImageProcessor processor = new ImageProcessor();

    @POST
    @Path("/compress")
    @Consumes(MediaType.APPLICATION_OCTET_STREAM)
    public Response compressImage(final File file) {
        BufferedImage image = null;
        try {
            image = ImageIO.read(file);
        } catch (IOException e) {
            return Response.status(400).entity("Error reading the image").build();
        }
        byte[] compressedImage = processor.compress(image);
        //Save to cloud storage
        URI uri = new URI("cloud-storage://" + file.getName());
        try {
            //Upload the compressed image
            File uploadFile = new File(uri);
            ImageIO.write(compressedImage, "jpg", uploadFile);
        } catch (IOException e) {
            return Response.status(500).entity("Error uploading the compressed image").build();
        }
        return Response.ok().build();
    }

    @GET
    @Path("/retrieve/{imageName}")
    public Response retrieveCompressedImage(@PathParam("imageName") String imageName) {
        URI uri = new URI("cloud-storage://" + imageName);
        File file = new File(uri);
        try {
            byte[] compressedImage = ImageIO.read(file);
            //Return the compressed image
            return Response.ok(compressedImage).build();
        } catch (IOException e) {
            return Response.status(404).entity("Error retrieving the compressed image").build();
        }
    }

