using json = nlohmann::json;

std::unordered_map<std::string, std::variant<int, double, std::string, bool>> readConfigurations(const std::string& filePath) {
    // Create a cache to store the parsed JSON file
    static std::unordered_map<std::string, json> configurationCache;
    static std::mutex cacheMutex;

    // Check if the file exists in the cache and return the cached result if it does
    if (auto iter = configurationCache.find(filePath); iter != configurationCache.end()) {
        return parseConfigurations(iter->second);
    }

    // Load the JSON file and check for errors
    try {
        json config;
        std::ifstream ifs(filePath);
        ifs >> config;

        // Check if the file is malformed or empty
        if (config.is_discarded() || config.empty()) {
            throw std::runtime_error("Invalid or empty configuration file");
        }
    } catch (const std::exception& e) {
        // Log the error and return an empty map with default values
        logError(e.what());
        return readDefaultConfigurations();
    }

    // Parse the JSON configuration into a map of settings
    auto configurations = parseConfigurations(config);

    // Store the parsed configuration in the cache for future use
    {
        std::lock_guard<std::mutex> lock(cacheMutex);
        configurationCache[filePath] = config;
    }

    return configurations;
}

