public class Main {

    public static void main(String[] args) throws IOException, CsvException {
        List<User> users = readUsersFromCSV("users.csv");
        User oldestUser = findOldestUser(users);
        System.out.println("The oldest user is: " + oldestUser.getName());
        String email = oldestUser.getEmail();
        fetchUserDetails(email);
    }

    private static List<User> readUsersFromCSV(String filename) throws IOException, CsvException {
        CSVReader reader = new CSVReader(new FileReader(filename));
        List<User> users = new ArrayList<>();
        String[] nextLine;
        while ((nextLine = reader.readNext()) != null) {
            User user = new User(nextLine[0], nextLine[1], Integer.parseInt(nextLine[2]));
            users.add(user);
        }
        return users;
    }

    private static User findOldestUser(List<User> users) {
        User oldestUser = users.get(0);
        for (User user : users) {
            if (user.getAge() > oldestUser.getAge()) {
                oldestUser = user;
            }
        }
        return oldestUser;
    }

