        ApiClient apiClient = new ApiClient();
        try {
            User user = apiClient.fetchUserDetails(email);
            System.out.println("User details: " + user.getAddress() + ", Phone number: " + user.getPhoneNumber());
        } catch (Exception e) {
            Logger.getLogger(Main.class.getName()).log(Level.SEVERE, null, e);
        }
    }
}

