import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.lang.reflect.Constructor;
import java.lang.reflect.InvocationTargetException;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.util.*;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class DynamicNestedDeserializer {
    private final Map<String, Class<?>> cache = new HashMap<>();
    private final Map<String, Constructor<?>> constructorCache = new HashMap<>();
    private final Lock lock = new ReentrantLock();

    public <T> T deserialize(byte[] data, String className) throws ClassNotFoundException, InstantiationException, IllegalAccessException, IOException {
        if (!cache.containsKey(className)) {
            try {
                deserializationFromClassInfo(data, className);
            } catch (IOException e) {
                throw new CustomClassNotFoundException("Failed to retrieve class definition for " + className, e);
            }
        }

        try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(data))) {
            return (T) ois.readObject();
        }
    }

    private void deserializationFromClassInfo(byte[] data, String className) throws IOException, ClassNotFoundException {
        lock.lock();
        try {
            if (!cache.containsKey(className)) {
                byte[] classDefinitionBytes;
                try {
                    HttpRequest request = HttpRequest.newBuilder().uri(URI.create("https://api.example.com/classes/" + className)).build();
                    HttpResponse<byte[]> response = HttpClient.newHttpClient().send(request, HttpResponse.BodyHandlers.ofByteArray());
                    classDefinitionBytes = response.body();

                    Class<?> clazz = new CustomClassLoader().loadClass(className);
                    Constructor<?> constructor = clazz.getConstructor(byte[].class);

                    cache.put(className, clazz);
                    constructorCache.put(className, constructor);

                    String jsonString = new String(classDefinitionBytes, "UTF-8");
                    Object jsonObject = new JSONObject(jsonString).getJSONObject("constructors").getJSONObject(0);
                    Class<?>[] parameterTypes = className.equals(jsonObject.getString("type")) ? null : (Class<?>[]) clazz.getConstructor().getParameterTypes();
                    constructor.newInstance(data);

                } catch (IOException | ClassNotFoundException e) {
                    throw new CustomClassNotFoundException("Failed to retrieve class definition for " + className, e);
                }
            }
        } finally {
            lock.unlock();
        }
    }

    public static class CustomClassNotFoundException extends Exception {
        public CustomClassNotFoundException(String message, Throwable cause) {
            super(message, cause);
        }
    }
}
