// Function to append a slash to a given string only if its length is less than or equal to a specified size limit.
char* add_slash_if_necessary(const char* str, int max_length) {
    if (strlen(str) <= max_length) {
        char* modified_str = malloc(strlen(str) + 2);
        strcpy(modified_str, str);
        strcat(modified_str, "/");
        return modified_str;
    }
    return NULL;
}
