```python
import os
import re
import heapq
from concurrent.futures import ThreadPoolExecutor

# Regular expression pattern to extract sequence number from the last line of each file.
sequence_pattern = r'\d+'

def process_file(file_path):
    try:
        with open(file_path, 'r') as file:
            lines = file.readlines()
            sorted_lines = sorted(lines)
            last_line = sorted_lines[-1]
            match = re.search(sequence_pattern, last_line)
            if match:
                return int(match.group())
    except Exception as e:
        print(f"Error processing {file_path}: {str(e)}")
        return None

def main(config_file):
    try:
        with open(config_file, 'r') as config:
            file_paths = [line.strip() for line in config.readlines()]

        # Use ThreadPoolExecutor to concurrently process files and optimize performance.
        executor = ThreadPoolExecutor()
        results = list(executor.map(process_file, file_paths))
        executor.shutdown()

        if all(result is not None for result in results):
            with open('output.txt', 'w') as output:
                output.write('\n'.join(map(str, results)))
        else:
            print("Not all files processed successfully.")

    except Exception as e:
        print(f"Error processing config file: {str(e)}")

if __name__ == '__main__':
    main('config.txt')
