#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <zip.h>
#include <tar.h>
#include <rar.h>
#include <zlib.h>
#include <bz2.h>

typedef struct {
    int id;
    char* name;
    void* data;
} Resource;

Resource* loadBundle(const char* path) {
    zip_file_t *zf = zip_fopen(path, "r");
    if (!zf) {
        return NULL;
    }

    Resource* resources = NULL;
    int count = 0;

    zip_dir_t *dir = zip_fopen_name(zf, "", ZIP_FL_NOCREATE);
    if (dir) {
        zip_entry_t *entry;
        while ((entry = zip_fread(dir))) {
            char buffer[256];
            sprintf(buffer, "%s", entry->name);

            Resource* resource = malloc(sizeof(Resource));
            resource->id = count++;
            resource->name = strdup(buffer);
            resource->data = malloc(entry-> uncompressed_size);
            fread(resource->data, 1, entry->uncompressed_size, zip_fopen_file(zf, entry->name, ZIP_FL_NOCREATE));

            if (resources) {
                resources = realloc(resources, sizeof(Resource) * (count));
            } else {
                resources = malloc(sizeof(Resource) * count);
            }

            resources[count - 1] = resource;
        }
    }

    zip_fclose(dir);
    zip_fclose(zf);

    return resources;
}

void unloadBundle(Resource* resources, int count) {
    for (int i = 0; i < count; i++) {
        free(resources[i]->name);
        free(resources[i]->data);
        free(resources[i]);
    }
    free(resources);
}

int main() {
    Resource* resources = loadBundle("bundle.zip");
    int count = sizeof(resources) / sizeof(Resource);

    // Use the loaded bundle...

    unloadBundle(resources, count);

    return 0;
}
