import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.ThreadPoolExecutor;

public class AsyncTaskManager {

    public <T> Future<T> executeAsyncTaskWithRetry(Callable<T> task, List<BackendService> backendServices, RetryStrategy retryStrategy, int maxRetries, long timeout) {
        if (task == null || backendServices.isEmpty() || retryStrategy == null) {
            throw new RuntimeException("Invalid input: task is null or backend services list is empty");
        }

        ExecutorService executor = Executors.newCachedThreadPool();

        for (int i = 0; i <= maxRetries; i++) {
            Future<T> future = executor.submit(task);

            try {
                return future.get(timeout, TimeUnit.MILLISECONDS);
            } catch (TimeoutException e) {
                if (i < maxRetries - 1) {
                    // Implement exponential backoff
                    try { Thread.sleep((long) Math.pow(2, i) * 100); } catch (InterruptedException ie) {}
                    continue;
                }
                throw new ExecutionException("Task execution timed out", future);
            } catch (ExecutionException e) {
                if (!retryStrategy.shouldRetry(future.getException())) {
                    // Task failed and should not be retried
                    executor.shutdown();
                    return null;
                }

                // Implement exponential backoff
                try { Thread.sleep((long) Math.pow(2, i) * 100); } catch (InterruptedException ie) {}
            }
        }

        executor.shutdown();
        return null;
    }
}
