using System;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Threading;

public class WebSiteManager
{
    private readonly ConfigurationManagementSystem _configMgr;
    private readonly string _logFilePath;

    public WebSiteManager(ConfigurationManagementSystem configMgr, string logFilePath)
    {
        _configMgr = configMgr;
        _logFilePath = logFilePath;
    }

    public void AddAndStartWebsite(string directoryPath, string siteName)
    {
        if (string.IsNullOrEmpty(directoryPath) || !Directory.Exists(directoryPath))
        {
            LogError($"Invalid directory path: {directoryPath}");
            return;
        }

        var webConfigExist = Directory.GetFiles(directoryPath, "web.config").Any();
        if (!webConfigExist)
        {
            LogInfo("Missing web.config file. Cannot start the website.");
            return;
        }

        // Check if site is already running
        if (IsSiteAlreadyRunning(directoryPath))
        {
            LogInfo($"The {siteName} website is already running at {directoryPath}.");
            return;
        }

        try
        {
            StartWebsite(directoryPath, siteName);
        }
