```
import hashlib
import requests
from tqdm import tqdm

def calculate_sha256_hash(file_path_or_url, checksum=None):
    if 'http' in file_path_or_url:
        response = requests.get(file_path_or_url, stream=True)
        if response.status_code != 200:
            return f"Failed to download {file_path_or_url}: {response.reason}"

    if not checksum or isinstance(checksum, str) and len(checksum) == 64:
        file_size = 0
        if 'http' in file_path_or_url:
            file_size = int(response.headers.get('content-length', 0))
        else:
            try:
                file_size = os.path.getsize(file_path_or_url)
            except OSError as e:
                return f"Failed to access {file_path_or_url}: {e}"

        with open('/dev/shm/tempfile', 'wb') as tempfile:
            for chunk in tqdm(response.iter_content(chunk_size=1024), total=file_size, unit='KB'):
                tempfile.write(chunk)

        with open('/dev/shm/tempfile', 'rb') as file:
            file_hash = hashlib.sha256()
            for chunk in iter(lambda: file.read(4096), b''):
                file_hash.update(chunk)
            file_hash.hexdigest()

        if checksum and str(file_hash) != checksum:
            return f"Checksum mismatch for {file_path_or_url}: Expected {checksum}, got {str(file_hash)}"

        return "File has been successfully hashed and verified."
    else:
        return "Invalid checksum value."

