<?php

use Composer\Autoload\ClassLoader;

class Configurator {
    private $env;
    private $cache;
    private $logger;

    public function __construct() {
        $this->env = getenv('APP_ENV') ?? 'development';
        $this->cache = [];
        $this->logger = new Logger();
    }

    public function run($argv = []) {
        $this->detectEnvironment($argv);
        $configFile = $this->loadConfigFile();
        if (!$configFile) return;

        $this->setEnvironmentVariables($configFile);
    }

    private function detectEnvironment($argv) {
        if (isset($argv[1])) {
            $this->env = strtolower($argv[1]);
        }
    }

    private function loadConfigFile() {
        $file = 'config/' . $this->env . '.json';
        if (!file_exists($file)) {
            $this->logger->error('Configuration file not found: ' . $file);
            return null;
        }

        $data = json_decode(file_get_contents($file), true);
        if (json_last_error() !== JSON_ERROR_NONE) {
            $this->logger->error('Malformed configuration file: ' . $file);
            return null;
        }

        $this->cache[$file] = $data;

        return $data;
    }

    private function setEnvironmentVariables($configFile) {
        foreach ($configFile as $key => $value) {
            putenv(strtoupper($key) . '=' . $value);
        }
    }
}

class Logger {
    public function error($message) {
        echo $message . "\n";
    }
}
