import os
import hashlib
from PIL import Image
from concurrent.futures import ThreadPoolExecutor
from loguru import logger

class ImageProcessorService:
    def __init__(self):
        self.cache = {}
        self.max_retries = 3
        self.services = {
            'cloudinary': {'api_key': '', 'api_secret': '', 'cloud_name': ''},
            'imgur': {'client_id': '', 'client_secret': ''},
            'flickr': {'api_key': '', 'api_secret': ''}
        }

    def process_image(self, file_path, transformations, service):
        try:
            image = Image.open(file_path)
            md5_hash = hashlib.md5(image.tobytes()).hexdigest()
            if self.cache.get(md5_hash):
                logger.info(f"Image {file_path} already processed, skipping upload")
                return

            for _ in range(self.max_retries):
                try:
                    transformed_image = self.apply_transformations(image, transformations)
                    self.upload_to_service(transformed_image, service)
                    break
                except Exception as e:
                    if self.max_retries > 1:
                        logger.warning(f"Error processing image {file_path}: {str(e)}")
                        continue
                    else:
                        raise

            self.cache[md5_hash] = file_path
        except Exception as e:
            logger.error(f"Error processing image {file_path}: {str(e)}")

    def apply_transformations(self, image, transformations):
        transformed_image = image.copy()
        for transformation in transformations:
            if 'resize' in transformation:
                width, height = map(int, transformation['resize'].split('x'))
                transformed_image.thumbnail((width, height))
            elif 'format' in transformation:
                format = transformation['format']
                if format == 'jpg':
                    transformed_image.save(f"{os.path.splitext(file_path)[0]}.jpg", 'JPEG')
                # Add more formats as needed
        return transformed_image

    def upload_to_service(self, image, service):
        try:
            if service == 'cloudinary':
                from cloudinary import Cloudinary
                cloudinary = Cloudinary(api_key=self.services[service]['api_key'], api_secret=self.services[service]['api_secret'], cloud_name=self.services[service]['cloud_name'])
                uploaded_image = cloudinary.uploader.upload(image, public_id=os.path.basename(file_path), overwrite=True)
            elif service == 'imgur':
                from imgurpython import Imgur
                imgur = Imgur(client_id=self.services[service]['client_id'], client_secret=self.services[service]['client_secret'])
                uploaded_image = imgur.upload_image(image, title=os.path.splitext(os.path.basename(file_path))[0])
            elif service == 'flickr':
                from flickrapi import FlickrAPI
                flickr = FlickrAPI(api_key=self.services[service]['api_key'], api_secret=self.services[service]['api_secret'])
                uploaded_image = flickr.upload_image(image, title=os.path.splitext(os.path.basename(file_path))[0])
            logger.info(f"Image {file_path} successfully uploaded to {service}")
        except Exception as e:
            logger.error(f"Error uploading image {file_path} to {service}: {str(e)}")

if __name__ == '__main__':
    service = 'cloudinary'  # or 'imgur', or 'flickr'
    file_path = '/path/to/image.jpg'
    transformations = [{'resize': '500x300'}, {'format': 'jpg'}]
    image_processor_service = ImageProcessorService()
    with ThreadPoolExecutor() as executor:
        executor.submit(image_processor_service.process_image, file_path, transformations, service)
