#include <openssl/err.h>
#include <openssl/aes.h>
#include <openssl/camellia.h>
#include <openssl/md5.h>
#include <openssl/sha.h>
#include <openssl/rsa.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int load_crypto_primitives(const char* config_file) {
    FILE* file = fopen(config_file, "r");
    if (!file) {
        OpenSSL_add_all_algorithms();
        return 1;
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        // Parse configuration options
        char* token = strtok(line, ",");
        while (token) {
            if (strcmp(token, "AES") == 0) {
                // Load AES library and initialize AES context
                EVP_add_cipher(EVP_enc_null);
                AES_set_encrypt_key("your_key_here", 16, NULL);
                printf("Loaded AES\n");
            } else if (strcmp(token, "Camellia") == 0) {
                // Load Camellia library and initialize Camellia context
                EVP_add_cipher(EVP_dec_null);
                Camellia_set_decrypt_key("your_key_here", 16, NULL);
                printf("Loaded Camellia\n");
            } else if (strcmp(token, "MD5") == 0) {
                // Load MD5 library and initialize MD5 context
                EVP_add_digest(EVP_MD_NULL);
                MD5_init();
                printf("Loaded MD5\n");
            } else if (strcmp(token, "SHA") == 0) {
                // Load SHA library and initialize SHA context
                EVP_add_digest(EVP_sha256());
                SHA_init();
                printf("Loaded SHA\n");
            } else if (strcmp(token, "RSA_with_SHA1") == 0) {
                // Load RSA and SHA1 libraries and initialize RSA context with SHA1
                EVP_add_cipher(EVP_enc_null);
                RSA_generate_key_ex(NULL, 2048, 65537, NULL, NULL);
                printf("Loaded RSA with SHA1\n");
            }
            token = strtok(NULL, ",");
        }
    }

    fclose(file);

    // Initialize OpenSSL error queue
    ERR_free_strings();
    ERR_clear_error();

    return 0;
}

int main() {
    load_crypto_primitives("config.txt");
    return 0;
}
