    public class SensorDataProcessor
    {
        private readonly IMongoDatabase _database;
        private readonly XPathNavigator _xpathNavigator;

        public SensorDataProcessor(string mongoConnectionString)
        {
            _database = new MongoClient(mongoConnectionString).GetDatabase("IoTDatabase");
            _xpathNavigator = XDocument.NewValidatingReader();
        }

        public void ProcessSensorData(string xmlFilePath)
        {
            try
            {
                // Load XML document
                var xmlDocument = XDocument.Load(xmlFilePath);

                // Iterate through each sensor device in the XML document
                foreach (var deviceNode in xmlDocument.Descendants("Device"))
                {
                    // Extract the most recent sensor reading for each device using XPath
                    var latestReading = _xpathNavigator.Compile("/" + deviceNode.Name + "/Readings[last()]/Value").Evaluate(xmlDocument.CreateReader());
                    var deviceMetadata = GetDeviceMetadata(deviceNode);

                    // Store the results in a NoSQL database
                    var collection = _database.GetCollection<BsonDocument>("SensorReadings");
                    collection.InsertOne(new BsonDocument
                    {
                        {"deviceId", deviceNode.Attribute("id").Value},
                        {"reading", latestReading},
                        {"metadata", deviceMetadata}
                    });
                }
            }
            catch (Exception ex)
            {
                // Handle errors and exceptions
                Console.WriteLine($"Error processing sensor data: {ex.Message}");
            }
        }

        private BsonDocument GetDeviceMetadata(XNode deviceNode)
        {
            // Implement logic to retrieve device metadata from the enterprise system or external API
