    if response.status_code == 200:
        data = response.json()
        name = data["name"]
        type_ = [t["type"]["name"] for t in data["types"]]

        weaknesses_url = f"https://pokeapi.co/api/v2/pokemon/{pokemon_id}/weaknesses/"
        weaknesses_response = requests.get(weaknesses_url)
        if weaknesses_response.status_code == 200:
            weaknesses_data = weaknesses_response.json()
            weaknesses = [w["type"]["name"] for w in weaknesses_data]

            weather_effects_url = f"https://pokeapi.co/api/v2/pokemon/{pokemon_id}/weather/"
            weather_effects_response = requests.get(weather_effects_url)
            if weather_effects_response.status_code == 200:
                weather_effects_data = weather_effects_response.json()
                weather_effects = [we["condition"]["name"] for we in weather_effects_data]

                terrain_effects_url = f"https://pokeapi.co/api/v2/pokemon/{pokemon_id}/terrain/"
