        int truncatedLen = destSize - 1;
        memcpy(dest, src, truncatedLen);
        dest[truncatedLen] = '\0'; // Append null terminator
        logging_system_log_error("String truncated due to buffer size constraints.");
        return truncatedLen; 
    } else if (srcLen > destSize) {
        // Log error and truncate the string as above
        int truncatedLen = destSize - 1;
        memcpy(dest, src, truncatedLen);
        dest[truncatedLen] = '\0'; 
        logging_system_log_error("String too long for buffer size. Truncated.");
        return truncatedLen; 
    } else {
        // Copy the source string safely
        int copyLen = strlen(src);
        strcpy(dest, src);
        logging_system_log_info("String copied successfully.");
        return copyLen + 1;
    }
}

