    temperature: Float!
    humidity: Float!
  }

  type ClimateData {
    averageTemperature: Float!
    historicalEvents: [String!]!
  }

  type Query {
    weather(location: String!): WeatherData
    climate(location: String!): ClimateData
  }
`;

const resolvers = {
