      // Fetch current weather conditions from OpenWeatherMap API
      const weatherAPI = 'https://api.openweathermap.org/data/2.5/weather';
      return fetch(`${weatherAPI}?q=${location}&units=metric`)
        .then(response => response.json())
        .then(data => ({ temperature: data.main.temp, humidity: data.main.humidity }));
    },
    climate: (parent, { location }) => {
      // Fetch forecasted weather for the next 7 days from Climate API
      const climateAPI = 'https://api.climate-api.com/v1/forecast';
      return fetch(`${climateAPI}?location=${location}&units=metric`)
        .then(response => response.json())
        .then(data => ({ averageTemperature: data.average_temp, historicalEvents: data.historical_events }));
    },
  },
};

