const fs = require('fs');
const path = require('path');

function readDirContent(dirPath) {
    return new Promise((resolve, reject) => {
        const files = [];
        fs.readdir(dirPath, (err, items) => {
            if (err) {
                reject(err);
            } else {
                items.forEach(item => {
                    const filePath = path.join(dirPath, item);
                    fs.stat(filePath, (statErr, stats) => {
                        if (statErr) {
                            reject(statErr);
                        } else {
                            if (!stats.isDirectory() && !/^\./.test(item)) { // filter out hidden files
                                if (stats.size > 1048576) { // skip large files
                                    console.log(`Skipping file ${item} as it is larger than 1MB`);
                                } else {
                                    fs.readFile(filePath, 'utf8', (readErr, content) => {
                                        if (readErr) {
                                            console.warn(`Error reading file ${item}: ${readErr}`);
                                        } else {
                                            files.push({ filename: item, content });
                                        }
                                    });
                                }
                            }
                        }
                    });
                });
            }
        });
        resolve(files);
    });
}

