public class ClinicStatusMiddleware
{
    private readonly RequestDelegate _next;
    private readonly ILogger _logger;

    public ClinicStatusMiddleware(RequestDelegate next, ILogger<ClinicStatusMiddleware> logger)
    {
        _next = next;
        _logger = logger;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        if (context.Request.Method != "POST")
        {
            return;
        }

        var clinicId = int.Parse(context.Request.Form["ClinicId"]);
        var newStatus = context.Request.Form["NewStatus"];
        var lastModifiedIp = context.Request.Form["LastModifiedIp"];
        var lastModifiedByUserId = int.Parse(context.Request.Form["LastModifiedByUserId"]);

        try
        {
            using (var scope = _logger.BeginScope())
            {
                await UpdateClinicStatus(clinicId, newStatus, lastModifiedIp, lastModifiedByUserId);
            }
        }
        catch (Exception ex)
        {
            if (_logger.IsEnabled(LogLevel.Error))
            {
                _logger.LogError(ex, "Error updating clinic status");
            }

            var response = new { Success = false, Message = "Failed to update clinic status" };
            await context.Response.WriteAsync(JsonConvert.SerializeObject(response));
        }
    }

    private async Task UpdateClinicStatus(int clinicId, string newStatus, string lastModifiedIp, int lastModifiedByUserId)
    {
        // Fetch updated clinic status from CMS
        var cmsResponse = await GetUpdatedClinicStatusFromCms(clinicId, newStatus);

        if (cmsResponse == null || !cmsResponse.Success)
        {
            throw new Exception("Failed to fetch updated clinic status from CMS");
        }

        // Apply updated clinic status
        using (var scope = _logger.BeginScope())
        {
            await UpdateDatabaseAndNotifyAdministrators(clinicId, newStatus, lastModifiedIp, lastModifiedByUserId);
        }
    }

    private async Task<ClinicStatusResponse> GetUpdatedClinicStatusFromCms(int clinicId, string newStatus)
    {
        // Integrate with CMS to fetch updated clinic status
        // ...
    }

    private async Task UpdateDatabaseAndNotifyAdministrators(int clinicId, string newStatus, string lastModifiedIp, int lastModifiedByUserId)
    {
        using (var scope = _logger.BeginScope())
        {
            // Update database with new clinic status and log changes
            await UpdateDatabase(clinicId, newStatus);

            // Notify administrators of the updated clinic status
            await SendNotificationEmail(clinicId, newStatus);
        }
    }

    private async Task UpdateDatabase(int clinicId, string newStatus)
    {
        // Use transactions to maintain data integrity
        using (var dbContext = new ClinicDbContext())
        {
            using (var transaction = dbContext.Database.BeginTransaction())
            {
                try
                {
                    // Update database with new clinic status
                    await dbContext.Clinics.UpdateAsync(c => c.Status = newStatus, clinicId);

                    transaction.Commit();
                }
                catch
