public class CompressionMiddleware
{
    private readonly RequestDelegate _next;
    private readonly ILogger<CompressionMiddleware> _logger;
    private readonly Dictionary<string, Func<Stream, Stream>> _algorithms = new()
    {
        {"GZIP", GZipAlgorithm},
        {"DEFLATE", DeflateAlgorithm},
        {"LZ4", Lz4Algorithm}
    };
    private readonly SemaphoreSlim _semaphore;

    public CompressionMiddleware(RequestDelegate next, ILogger<CompressionMiddleware> logger)
    {
        _next = next;
        _logger = logger;
        _semaphore = new SemaphoreSlim(3); // Initialize with 3 available slots for CMS providers
    }

    public async Task InvokeAsync(HttpContext context)
    {
        if (!context.Request.Method.Equals("POST", StringComparison.OrdinalIgnoreCase))
            return;

        var compressionAlgorithm = GetCompressionAlgorithm(context);
        var compressedData = CompressData(context);

        await SendCompressedDataToRemoteServer(compressionAlgorithm, compressedData);

        // Handle network failures and authentication issues
        try
        {
            await _next(context);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error processing request");
        }
    }

    private string GetCompressionAlgorithm(HttpContext context)
    {
        // Dynamic algorithm selection based on content and network conditions
        return // Algorithm logic goes here;
    }

    private byte[] CompressData(HttpContext context)
    {
        using var ms = new MemoryStream();
        using var compressor = _algorithms[GetCompressionAlgorithm(context)];
        using var stream = compressor(ms);

        // Compress data using the chosen algorithm
        return ms.ToArray();
    }

    private async Task SendCompressedDataToRemoteServer(string compressionAlgorithm, byte[] compressedData)
    {
        // Asynchronous network communication using HttpClient
        using var client = new HttpClient { BaseAddress = new Uri("https://remote.server.com/") };
        client.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", "your_access_token");

        try
        {
            await client.PostAsync("api/endpoint", new ByteArrayContent(compressedData));
        }
        catch (HttpRequestException ex)
        {
            // Handle network failures and authentication issues
            _logger.LogError(ex, "Error sending compressed data");
        }
    }

    private Stream GZipAlgorithm(Stream input) => new GZipStream(input, CompressionMode.Compress);

    private Stream DeflateAlgorithm(Stream input) => new DeflateStream(input, CompressionLevel.Fastest);

