import requests
from bs4 import BeautifulSoup
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
from queue import Queue
import time
import logging
from threading import Thread
from datetime import datetime, timedelta

class DataCollector:
    def __init__(self):
        self.driver = webdriver.Chrome()
        self.cache = {}
        self.config = {"frequency": "daily", "depth": 1, "region": "us"}

    def collect_data(self, url, config):
        if not self.is_website_valid(url, config):
            return None
        data = self.scrape_static_content(url)
        dynamic_data = self.scrape_dynamic_content(url, config["depth"])
        return {**data, **dynamic_data}

    def is_website_valid(self, url, config):
        try:
            response = requests.head(url)
            if response.status_code != 200:
                logging.error(f"Invalid website: {url}, status code {response.status_code}")
                return False
        except requests.exceptions.RequestException as e:
            logging.error(f"Error fetching {url}: {e}")
            return False
        return True

    def scrape_static_content(self, url):
        response = requests.get(url)
        soup = BeautifulSoup(response.text, "html.parser")
        data = {}
        for script in soup.find_all("script"):
            if script.has_attr("type") and script["type"] == "application/ld+json":
                data = json.loads(script.string)
        return data

    def scrape_dynamic_content(self, url, depth):
        self.driver.get(url)
        content = []
        for _ in range(depth):
            try:
                element = WebDriverWait(self.driver, 10).until(
                    EC.presence_of_element_located((By.XPATH, "//div[@id='dynamic-content']"))
                )
                content.append(element.text)
            except Exception as e:
                logging.error(f"Error scraping dynamic content: {e}")
        return {"dynamic": content}

    def run(self):
        while True:
            if self.config["frequency"] == "daily":
                start = datetime.now()
                for url in self.urls:
                    data = self.collect_data(url, self.config)
                    self.store_data(data)
                    end = datetime.now()
                    logging.info(f"Data collection took {end-start} seconds")
            elif self.config["frequency"] == "hourly":
                # implement hourly frequency logic here
                pass
            time.sleep(60)  # wait for the next run

    def store_data(self, data):
        if not self.cache.get(data["url"], None):
            self.cache[data["url"]] = []
        self.cache[data["url"]].append(data)

    def load_data(self):
        return {k: v for k, v in self.cache.items()}

class DataCollectorThread(Thread):
    def __init__(self, data_collector):
        Thread.__init__(self)
        self.data_collector = data_collector

    def run(self):
        self.data_collector.run()

# example usage
data_collector = DataCollector()
urls = ["http://example.com/page1", "http://example.com/page2"]
data_collector.urls = urls
data_collector.config["frequency"] = "daily"
data_collector.config["depth"] = 3

thread = DataCollectorThread(data_collector)
thread.start()

# unit tests
import unittest

class TestDataCollector(unittest.TestCase):
    def test_collect_data(self):
        data_collector = DataCollector()
        url = "http://example.com/page1"
        config = {"frequency": "daily", "depth": 1, "region": "us"}
        self.assertIsNotNone(data_collector.collect_data(url, config))

    def test_is_website_valid(self):
        data_collector = DataCollector()
        url = "http://example.com/invalid"
        self.assertFalse(data_collector.is_website_valid(url, {"frequency": "daily", "depth": 1, "region": "us"}))

if __name__ == "__main__":
    unittest.main()

