import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.stream.Collectors;

@Configuration
public class MqttAnomalyDetectionConfig {

    @Bean
    public MqttClient mqttClient() {
        return new MqttClient();
    }

    @Bean
    public ApplicationContext context() {
        return new ApplicationContext();
    }

    @Bean
    public ExecutorService executorService() {
        return Executors.newCachedThreadPool();
    }

    @Bean
    public ThreadPoolExecutor threadPoolExecutor() {
        return (ThreadPoolExecutor) executorService();
    }
}

@RestController
class MqttAnomalyDetectionController {

    private final Map<String, AnomalyDetector> detectors = new ConcurrentHashMap<>();
    private final ExecutorService executor;

    @Autowired
    public MqttAnomalyDetectionController(ExecutionContext context) {
        this.executor = context.getExecutor();
    }

    @PostMapping("/anomaly-detectors")
    public ResponseEntity<String> createDetector(@RequestBody DetectorConfig config) {
        AnomalyDetector detector = new AnomalyDetector(config);
        detectors.put(config.getDeviceType(), detector);
        executor.submit(() -> {
            try {
                MqttClient mqttClient = context.getBean(MqttClient.class);
                mqttClient.connect();
                mqttClient.subscribe(config.getTopic());
            } catch (MqttException e) {
                // handle error
            }
        });
        return ResponseEntity.status(HttpStatus.CREATED).body("Anomaly detector created");
    }

    @GetMapping("/anomalies")
    public ResponseEntity<List<Anomaly>> getAnomalies() {
        List<Anomaly> anomalies = detectors.values().stream()
                .map(detector -> detector.getAnomalies())
                .flatMap(List::stream)
                .collect(Collectors.toList());
        return ResponseEntity.ok(anomalies);
    }
}

class AnomalyDetector {

    private final MqttClient mqttClient;
    private final MachineLearningModel model;

    public AnomalyDetector(DetectorConfig config) {
        mqttClient = new MqttClient();
        model = createModel(config.getDeviceType());
    }

    public List<Anomaly> getAnomalies() {
        // process sensor data from MQTT and detect anomalies using machine learning model
        // ...
    }
}

