        return 1; // Key retrieved successfully
    }
    return -1; // Error retrieving the key
}

// Main DES library API
void des_encrypt(uint8_t *plaintext, uint32_t plaintext_len, uint8_t *key,
                 uint8_t mode) {
    if (mode >= sizeof(des_modes) / sizeof(des_modes[0])) {
        printf("Invalid encryption mode!\n");
        return;
    }

    // Retrieve the key from the external service or use a hardcoded key
    int key_len = 0;
    if (!get_key_from_service(NULL, NULL, &key_len)) {
        // Handle key not retrieved error condition
        printf("Failed to retrieve the key. Fallback to null encryption.\n");
        return;
    }

    des_algorithm *current_mode = &des_modes[mode];
    (*current_mode->encrypt)(plaintext, plaintext_len, key);
}

void des_decrypt(uint8_t *ciphertext, uint32_t ciphertext_len, uint8_t *key,
                 uint8_t mode) {
    if (mode >= sizeof(des_modes) / sizeof(des_modes[0])) {
        printf("Invalid encryption mode!\n");
        return;
    }

    // Retrieve the key from the external service or use a hardcoded key
    int key_len = 0;
    if (!get_key_from_service(NULL, NULL, &key_len)) {
        // Handle key not retrieved error condition
        printf("Failed to retrieve the key. Fallback to null encryption.\n");
        return;
    }

    des_algorithm *current_mode = &des_modes[mode];
    (*current_mode->decrypt)(ciphertext, ciphertext_len, key);
}

int main() {
    // Example usage: Encrypt a message using ECB mode
    uint8_t plaintext[] = "Hello World!";
    uint32_t plaintext_len = strlen((char *)plaintext);
    uint8_t key[] = "my_secret_key";
    des_encrypt(plaintext, plaintext_len, key, 0);

    return 0;
}
