import os
import threading
import hashlib
from queue import Queue
from concurrent.futures import ThreadPoolExecutor

def calculate_sha256(file_path, expected_hash=None):
    chunk_size = 65536

    def update_hash(file_path):
        try:
            with open(file_path, 'rb') as file:
                hash_object = hashlib.sha256()

                while True:
                    chunk = file.read(chunk_size)
                    if not chunk:
                        break
                    hash_object.update(chunk)

                return hash_object.hexdigest()
        except Exception as e:
            print(f"Error processing {file_path}: {e}")

    def verify_hash(file_path, expected_hash):
        try:
            actual_hash = update_hash(file_path)
            if actual_hash != expected_hash:
                print(f"Hash mismatch for {file_path}. Expected: {expected_hash}, Actual: {actual_hash}")
            else:
                print(f"SHA-256 hash of {file_path} matches the expected value")
        except Exception as e:
            print(f"Error verifying hash for {file_path}: {e}")

    with ThreadPoolExecutor() as executor:
        futures = []

        for file_path in [file_path]:
            if expected_hash is not None:
                future = executor.submit(verify_hash, file_path, expected_hash)
            else:
                future = executor.submit(update_hash, file_path)

            futures.append(future)

        for future in futures:
            result = future.result()
            print(f"SHA-256 hash of {file_path}: {result}")

    print(f"Time taken to calculate SHA-256 hash: {os.times()[4] - os.times()[3]}")
