    // Initialize config
    Config config;
    config.input_file = fopen(argv[1], "rb");
    config.output_file = fopen(argv[2], "wb");
    config.num_threads = atoi(argv[3]);
    config.log_level = atoi(argv[4]);
    config.log_service_url = argv[5];

    // Load parsing rules
    Rule *rules;
    int num_rules = load_rules(config.config, &rules);

    // Create threads for parallel processing
    pthread_t threads[config.num_threads];
    for (int i = 0; i < config.num_threads; i++) {
        pthread_create(&threads[i], NULL, process_data, (void *)/rules);
    }

    // Wait for all threads to finish
    for (int i = 0; i < config.num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    // Free memory allocated for rules
