            providers = currentProvider;
        } else {
            securityProvider* temp = providers;
            while (temp->next != NULL) {
                temp = temp->next;
            }
            temp->next = currentProvider;
        }
    }

    for (int i = 0; i < sizeof(blockCiphers) / sizeof(blockCiphers[0]); i++) {
        currentProvider = malloc(sizeof(securityProvider));
        if (!currentProvider) {
