import json
from abc import ABC, abstractmethod
from collections import defaultdict

class JSONParser(ABC):
    def __init__(self):
        self._registry = defaultdict(dict)
        self._schema_registry = {}
        self._instances = {}

    @abstractmethod
    def from_json(self, data):
        pass

    def to_json(self):
        pass

    def validate(self, data, schema_id):
        pass

    def add_factory_function(self, factory_id, factory_func):
        if factory_id in self._registry:
            raise ValueError(f"Factory function {factory_id} already exists")
        self._registry[factory_id] = factory_func
        return self

    def remove_factory_function(self, factory_id):
        if factory_id not in self._registry:
            raise ValueError(f"No such factory function {factory_id}")
        del self._registry[factory_id]
        return self

    def create_instance(self, json_data, factory_id):
        if factory_id not in self._registry:
            raise ValueError(f"No such factory function {factory_id}")
        try:
            instance = self._registry[factory_id](json_data)
            self._instances[factory_id] = instance
            return instance
        except Exception as e:
            raise ValueError(f"Failed to create instance for factory {factory_id}: {str(e)}")
