```csharp
using System;
using System.Collections.Concurrent;
using System.Security.Cryptography;
using System.Text;

public class SecureMessageProcessor
{
    private readonly ConcurrentDictionary<string, string> _decryptedCache = new ConcurrentDictionary<string, string>();
    private readonly ILogger _logger;

    public SecureMessageProcessor(ILogger logger)
    {
        _logger = logger;
    }

    public string DecryptMessage(string encodedMessage, byte[] key, byte[] iv)
    {
        if (string.IsNullOrEmpty(encodedMessage))
            throw new ArgumentException("Invalid message", nameof(encodedMessage));

        try
        {
            using (var tripleDES = TripleDes.Create())
            {
                tripleDES.Key = key;
                tripleDES.IV = iv;

                using (var memoryStream = new MemoryStream(Encoding.UTF8.GetBytes(encodedMessage)))
                {
                    using (var cryptoStream = new CryptoStream(memoryStream, tripleDES))
                    {
                        var buffer = new byte[1024];
                        int bytesRead;
                        string decryptedMessage = "";
                        while ((readBytes = cryptoStream.Read(buffer, 0, buffer.Length)) > 0)
                            decryptedMessage += Encoding.UTF8.GetString(buffer, 0, readBytes);
                        return decryptedMessage;
                    }
                }
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex);
            throw;
        }
    }

    public byte[] EncryptMessage(string message, byte[] key, byte[] iv)
    {
        if (string.IsNullOrEmpty(message))
            throw new ArgumentException("Invalid message", nameof(message));

        try
        {
            using (var tripleDES = TripleDes.Create())
            {
                tripleDES.Key = key;
                tripleDES.IV = iv;

                using (var memoryStream = new MemoryStream())
                {
                    using (var cryptoStream = new CryptoStream(memoryStream, tripleDES))
                    {
                        var writer = new StreamWriter(cryptoStream);
                        writer.Write(message);
                    }
                    return memoryStream.ToArray();
                }
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex);
            throw;
        }
    }

    private static TripleDes Create()
    {
        var tripleDES = new TripleDesCryptoServiceProvider
        {
            Mode = CipherMode.ECB,
            Key = new byte[16],
            IV = new byte[8]
        };
        return tripleDES;
    }
}
