using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using System.Threading.Tasks;
using System.Net.Http;
using System.Text;
using Newtonsoft.Json;
using Serilog;

public class ClinicStatusMiddleware
{
    private readonly RequestDelegate _next;
    private readonly ILogger _logger;
    private readonly HttpClient _httpClient;
    private readonly IRateLimiter _rateLimiter;

    public ClinicStatusMiddleware(RequestDelegate next, ILogger logger, HttpClient httpClient, IRateLimiter rateLimiter)
    {
        _next = next;
        _logger = logger;
        _httpClient = httpClient;
        _rateLimiter = rateLimiter;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        if (!await HandleUpdate(context))
        {
            await NextAsync(context);
        }
    }

    private async Task<bool> HandleUpdate(HttpContext context)
    {
        if (!TryGetUpdateParamsFromRequest(context, out var clinicId, out var newStatus, out var lastModifiedIp, out var lastModifiedByUserId))
        {
            return false;
        }

        if (!await ValidateUpdateParams(clinicId, newStatus, lastModifiedIp, lastModifiedByUserId))
        {
            return false;
        }

        try
        {
            await UpdateClinicStatus(context.Request.HttpContext.Connection.RemoteIpAddress, clinicId, newStatus, lastModifiedIp, lastModifiedByUserId);
        }
        catch (Exception ex)
        {
            _logger.Error(ex, "Error updating clinic status");
            await ReturnErrorAsync(context);
            return false;
        }

        return true;
    }

    private async Task UpdateClinicStatus(IPAddress ipAddress, int clinicId, string newStatus, IPAddress lastModifiedIp, int lastModifiedByUserId)
    {
        using (var dbContext = new ClinicContext())
        {
            await dbContext.Database.BeginTransactionAsync();
            try
            {
                var updatedClinic = await dbContext.Clinics.UpdateAsync(clinicId, newStatus);
                dbContext.SaveChanges();
                await dbContext.Database.CommitTransactionAsync();

                // Send email notification to clinic administrators
                await SendEmailNotificationAsync(updatedClinic);

                // Log update details in external audit system
                await LogUpdateDetailsInAuditSystemAsync(updatedClinic);
            }
            catch (Exception ex)
            {
                _logger.Error(ex, "Error updating clinic status");
                await dbContext.Database.RollbackTransactionAsync();
                throw;
            }
        }

        // Check rate limiter for IP address
        if (!_rateLimiter.Allow(ipAddress))
        {
            _logger.Warning("Rate limit exceeded for {ip}", ipAddress);
            return;
        }

        // Integrate with multiple external content management systems (CMS)
        foreach (var cms in GetCmsInstances())
        {
            await UpdateClinicStatusInCmsAsync(cms, clinicId, newStatus);
        }
    }

