import java.util.*;
import java.io.*;

public class EvolutionDataFetcher {

    private static Map<String, ClassDefinition> cache = new HashMap<>();
    private static final int MAX_CACHE_SIZE = 10000;
    private static final int CACHE_REFRESH_INTERVAL_MILLISECONDS = 30000; // 30 seconds

    public EvolutionDataFetcher() {
        ScheduledExecutorService executor = Executors.newSingleThreadScheduledExecutor();
        executor.scheduleWithFixedDelay(() -> refreshCache(), 0, CACHE_REFRESH_INTERVAL_MILLISECONDS / 1000, TimeUnit.MILLISECONDS);
    }

    private void refreshCache() {
        List<ClassProvider> providers = ClassProviders.getAvailableProviders();
        for (ClassProvider provider : providers) {
            try {
                Map<String, ClassDefinition> newClasses = provider.getClassDefinitions();
                cache.putAll(newClasses);
            } catch (Exception e) {
                // log error
            }
        }
    }

    public EvolutionDataResult fetchEvolutionData(String pokemonId, boolean isCurrentStage) throws Exception {
        EvolutionDataResult result = new EvolutionDataResult();

        List<ClassProvider> providers = ClassProviders.getAvailableProviders();
        for (ClassProvider provider : providers) {
            try {
                Map<String, ClassDefinition> classes = provider.getClassDefinitions();
                if (classes.containsKey(pokemonId)) {
                    ClassDefinition classDef = classes.get(pokemonId);
                    EvolutionData evolutionData = mergeEvolutionData(classDef.getEvolutionData(), isCurrentStage);

                    // handle concurrent requests safely
                    result.mergeEvolutionData(evolutionData);
                }
            } catch (Exception e) {
                if (!isCurrentStage && isNextStageAvailable(pokemonId, classDef)) {
                    continue; // try next stage
                } else {
                    throw new Exception("Error fetching evolution data for " + pokemonId);
                }
            }
        }

        return result;
    }

    private boolean isNextStageAvailable(String pokemonId, ClassDefinition classDef) throws Exception {
        List<ClassProvider> providers = ClassProviders.getAvailableProviders();
        for (ClassProvider provider : providers) {
            try {
                Map<String, ClassDefinition> classes = provider.getClassDefinitions();
                if (classes.containsKey(pokemonId)) {
                    ClassDefinition nextClass = classes.get(pokemonId);
                    return nextClass != null && nextClass.getEvolutionData() != null;
                }
            } catch (Exception e) {
                // log error
            }
        }
        return false;
    }

    private EvolutionData mergeEvolutionData(List<ClassDefinition> evolutionData, boolean isCurrentStage) throws Exception {
        EvolutionData mergedData = new EvolutionData();
        for (ClassDefinition classDef : evolutionData) {
            mergedData.merge(classDef.getEvolutionData());
        }
        if (!isCurrentStage) {
            List<ClassDefinition> nextStages = getNonCurrentEvolutionData(pokemonId);
            mergedData.merge(nextStages);
        }
        return mergedData;
    }

    private List<ClassDefinition> getNonCurrentEvolutionData(String pokemonId) throws Exception {
        // implement logic to fetch non-current evolution stages
    }

    public static void main(String[] args) throws Exception {
        EvolutionDataFetcher fetcher = new EvolutionDataFetcher();
        EvolutionDataResult result = fetcher.fetchEvolutionData("pikachu", true);
        System.out.println(result.toString());
    }
}
