#include <tiffio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

int parseTIFF(const char *file_path) {
    TIFF *tiff = TIFFOpen(file_path, "r");
    if (tiff == NULL) {
        return -1;
    }

    uint16_t bits_per_sample = 0;
    int sample_per_pixel = 0;

    // Get the bits per sample
    TIFFGetField(tiff, TIFF_FIELD_IMAGE_BITSPERPIXEL, &bits_per_sample);

    if (bits_per_sample != 1 && bits_per_sample != 2 && bits_per_sample != 4 && bits_per_sample != 8 && bits_per_sample != 16) {
        printf("Unsupported bits per sample: %d\n", bits_per_sample);
        TIFFClose(tiff);
        return -1;
    }

    // Get the sample per pixel
    TIFFGetField(tiff, TIFF_FIELD_IMAGE_SAMPLESPP, &sample_per_pixel);

    // Close the TIFF file
    TIFFClose(tiff);

    printf("Bits per sample: %d\n", bits_per_sample);
    printf("Sample per pixel: %d\n", sample_per_pixel);

    return 0;
}
