        lib->init(config.version, config.cipher_suites);
    } catch (const std::exception& e) {
        // Log error and print detailed message
        logger::logError("Failed to initialize TLS library", e.what());
    }

    // Handle initialization failure if any
    if (!lib || !lib->isInitialized()) {
        // Release memory and log error
        delete lib;
        logger::logError("TLS library initialization failed");
    } else {
        // Initialize certificate management API
        cert_manager_t* certMgr = new cert_manager_t();
        lib->setCertificateManager(certMgr);

        // Securely store and manage session keys
        session_key_mgr_t* keyMgr = new session_key_mgr_t(lib);
        lib->setSessionKeyManager(keyMgr);

        // Optimize function for inlinability
        inline void initHandshake(tls_library_t* lib) {
            // Initialize handshake process with optimized cipher suites
            lib->initHandshake(config.cipher_suites);
        }

        // Perform handshake
        initHandshake(lib);

        // Release memory and resources
        delete certMgr;
        delete keyMgr;
        delete lib;
    }
}
