// Union-Find data structure optimized for batch operations
class UnionFind {
public:
    vector<int> parent;
    int size;

    UnionFind(int n) : size(n), parent(size, -1) {}

    void makeSet(int x) { parent[x] = x; }

    int find(int x) {
        if (parent[x] != x)
            parent[x] = find(parent[x]);
        return parent[x];
    }

    bool connected(int x, int y) { return find(x) == find(y); }

    void unionSets(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX != rootY)
            parent[rootX] = rootY;
    }
};

