            .WaitAndRetry(3, (e) => TimeSpan.FromSeconds(1));

        public SensorDataProcessor(ILogger logger, DocumentClient documentDbClient)
        {
            _logger = logger;
            _documentDbClient = documentDbClient;
        }

        public async Task ProcessSensorData(string xmlData)
        {
            try
            {
                using var xmlDoc = XmlDocument.Parse(xmlData);
                foreach (XmlNode deviceNode in xmlDoc.SelectNodes("//device"))
                {
                    string deviceId = deviceNode["id"].InnerText;
                    XPathNavigator navigator = _deviceNavigators.GetOrAdd(deviceId, () => GetXPathNavigator(xmlDoc, deviceNode));
                    string latestSensorReading = navigator.SelectSingleNode("latest_reading").InnerText;
                    await ProcessLatestSensorReading(deviceId, latestSensorReading);
                }
            }
            catch (XmlException ex)
            {
                _logger.LogError(ex, "Failed to parse XML");
            }
            catch (DocumentClientException ex)
            {
                _retryPolicy.Execute(() => 
                {
                    try
                    {
                        await ProcessLatestSensorReading(deviceId, latestSensorReading);
                    }
                    catch (DocumentClientException innerEx)
                    {
                        _logger.LogError(innerEx, "Failed to store sensor data in DocumentDB");
                    }
                });
            }
        }

