#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int id;
    double offset;
    char key[20];
} Record;

Record* allocate_record(size_t size) {
    return (Record*)malloc(sizeof(Record) * size);
}

void process_file(const char* filename, Record** records, size_t* record_count) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        exit(EXIT_FAILURE);
    }

    Record* current_records = NULL;
    size_t record_size = 0;

    while (1) {
        char line[1024];
        if (!fgets(line, sizeof(line), file)) break;

        Record* new_record = allocate_record(1);
        sscanf(line, "%d %lf %19s", &new_record->id, &new_record->offset, new_record->key);

        if (record_size == 0) {
            current_records = new_record;
            record_size = 1;
        } else {
            *records = realloc(*records, sizeof(Record) * (*record_count + 1));
            current_records[(*record_count)++] = new_record;
        }
    }

    fclose(file);
}

double calculate_average(double* offsets, size_t count) {
    double sum = 0.0;
    for (size_t i = 0; i < count; ++i) {
        sum += offsets[i];
    }
    return sum / count;
}
