<?php

class RecordProcessor {
    private $records;
    private $recordCount;

    public function processFile($filename) {
        $this->records = array();
        $this->recordCount = 0;

        $file = fopen($filename, 'r');
        if (!$file) {
            throw new Exception('Error opening file');
        }

        while (1) {
            $line = trim(fgets($file));
            if (!strlen($line)) break;

            $record = array(
                'id' => (int)$line[0],
                'offset' => (double)substr($line, 2),
                'key' => substr($line, 30)
            );

            $this->records[] = $record;
        }

        fclose($file);

        $avgOffset = array_reduce(array_column($this->records, 'offset'), function ($carry, $item) {
            return $carry + $item;
        }, 0.0) / count($this->records);
        $avgKey = array_reduce(array_column($this->records, 'key'), function ($carry, $item) {
            return $carry . $item;
        }, '');

        foreach ($this->records as &$record) {
            $record['average_offset'] = $avgOffset;
            $record['average_key'] = $avgKey;
        }
    }

    public function getRecords() {
