#include <iostream>
#include <forward_list>
#include <string>

void insertAfterSearch(std::forward_list<std::string>& list, const std::string& search, const std::string& insertion, size_t maxInsertions) {
    if (list.empty()) {
        // Handle error: input list is empty
        return;
    }

    auto it = list.begin();
    size_t count = 0;

    while (it != list.end() && count <= maxInsertions) {
        if (*it == search) {
            // Insert after first occurrence of the search string or within maxInsertions limit
            list.insert_after(it, insertion);
            return;
        }
        ++it;
        ++count;
    }

    if (count > maxInsertions) {
        // Handle error: search string not found within specified range
        return;
    }

    // Insert at the end of the list
    list.insert_after(list.end(), insertion);

    for (auto& str : list) {
        size_t len = std::min(str.size(), 100);
        str.resize(len);
    }
}
