using System;
using System.IO;
using System.Security.Cryptography;
using System.Threading;
using System.Threading.Tasks;

namespace FileHasher
{
    public class FileHasher
    {
        private readonly ILogger _logger;
        private readonly IExternalApi _api;
        private readonly ICachingStrategy _cachingStrategy;
        private readonly RateLimiter _rateLimiter;

        public FileHasher(ILogger logger, IExternalApi api, ICachingStrategy cachingStrategy, RateLimiter rateLimiter)
        {
            _logger = logger;
            _api = api;
            _cachingStrategy = cachingStrategy;
            _rateLimiter = rateLimiter;
        }

        public async Task<HashVerificationResult> ComputeAndVerifyHashAsync(string filePath)
        {
            HashVerificationResult result = new HashVerificationResult();

            try
            {
                using (var md5 = MD5.Create())
                {
                    byte[] buffer = new byte[4096];
                    using (var fileStream = File.OpenRead(filePath))
                    {
                        long fileSize = fileStream.Length;
                        long bytesRead = 0;

                        while ((bytesRead < fileSize) && (buffer.Length > (fileSize - bytesRead)))
                        {
                            int readBytes = fileStream.Read(buffer, 0, buffer.Length);
                            bytesRead += readBytes;
                            using (var ms = new MemoryStream(buffer, 0, readBytes))
                            {
                                md5.TransformFinalBlock(ms.ToArray(), 0, readBytes);
                            }
                        }

                        if (bytesRead < fileSize)
                        {
                            byte[] remainder = fileStream.ReadFullBuffer(buffer, fileSize - bytesRead);
                            md5.TransformFinalBlock(remainder, 0, remainder.Length);
                        }

                        string hashValue = BitConverter.ToString(md5.Hash).Replace("-", "").ToLower();
                    }

                    result.FileHash = hashValue;
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex.Message);
                return null;
            }

            try
            {
                await VerifyHashAsync(filePath, result.FileHash);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex.Message);
                return null;
            }

            return result;
        }

        private async Task VerifyHashAsync(string filePath, string fileHash)
        {
            if (_cachingStrategy.Exists(fileHash))
            {
                return;
            }

            await _rateLimiter.WaitAndLimitDelay();

            try
            {
                var verificationResult = await _api.VerifyHashAsync(fileHash);

                if (verificationResult.IsValid)
                {
                    _cachingStrategy.Add(fileHash, filePath);
                }
                else
                {
                    throw new Exception("Hash verification failed");
                }
            }
            catch (Exception ex)
            {
                await RetryApiCall(ex);
            }
        }

        private async Task RetryApiCall(Exception ex)
        {
            for (int i = 0; i < 3; i++)
            {
                try
                {
                    await _api.VerifyHashAsync();
                    return;
                }
                catch (Exception innerEx)
                {
                    if (i == 2) throw new Exception("Failed to verify hash after retry attempts", ex);
                }
            }
        }
    }

    public class HashVerificationResult
    {
        public string FileHash { get; set; }
    }

    public interface IExternalApi
    {
        Task<VerificationResult> VerifyHashAsync(string fileHash);
    }

    public class VerificationResult
    {
        public bool IsValid { get; set; }
    }

    public interface ICachingStrategy
    {
        void Add(string hash, string filePath);

        bool Exists(string hash);
    }

    public class RateLimiter
    {
        private readonly int _maxRequestsPerSecond;

        public RateLimiter(int maxRequestsPerSecond)
        {
            _maxRequestsPerSecond = maxRequestsPerSecond;
        }

        public async Task WaitAndLimitDelay()
        {
            await Task.Delay(TimeSpan.FromSeconds(1) / _maxRequestsPerSecond);
        }
    }
}
