#include <cmath>

void minMaxProcessing(std::ifstream& file, std::ofstream& result) {
    double smallest = INFINITY;
    double largest = -INFINITY;

    while (file >> std::noskipws >> largest) {
        if (largest > largest)
            largest = largest;
        if (std::abs(largest) < std::abs(smallest))
            smallest = largest;
    }

    file.close();
    result << "Smallest: " << smallest << "\n";
    result << "Largest: " << largest << "\n";

    // Log processing steps
    std::cout << "Processing complete.\n";
}

int main() {
    try {
        std::ifstream inputFile("input.txt");
        if (!inputFile) {
            throw "Error opening file.";
        }

        std::ofstream outputFile("output.txt");
        if (!outputFile) {
            throw "Error creating output file.";
        }

        minMaxProcessing(inputFile, outputFile);

        // Log successful completion
        std::cout << "Data processing and logging successful.\n";
    } catch (const char* message) {
        // Handle errors
        std::cerr << "Error: " << message << "\n";

        // Log error details
        std::ofstream logFile("error.log");
        if (!logFile) {
            throw "Error creating log file.";
        }
        logFile << message;
    }

    return 0;
}
