public class GitCommitFetcher {

    private static final int MAX_RETRY_ATTEMPTS = 3;

    public static void main(String[] args) {
        if (args.length != 3) {
            System.out.println("Usage: java GitCommitFetcher <repository-path> <branch-name> <output-file-path>");
            return;
        }

        String repositoryPath = args[0];
        String branchName = args[1];
        String outputFilepath = args[2];

        File outputFile = new File(outputFilepath);
        if (outputFile.exists()) {
            try {
                Files.delete(outputFile.toPath());
            } catch (IOException e) {
                System.out.println("Error deleting output file: " + e.getMessage());
                return;
            }
        }

        ProcessBuilder builder = new ProcessBuilder(
                "git", "log", "-1", "--pretty=%B", "--no-merges", branchName);
        builder.directory(new File(repositoryPath));

        try {
            Process process = builder.start();
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
                String line;
                StringBuilder commitMessage = new StringBuilder();
                while ((line = reader.readLine()) != null) {
                    commitMessage.append(line).append("\n");
                }
                Files.write(outputFile.toPath(), commitMessage.toString().getBytes());
            } catch (IOException e) {
                System.out.println("Error reading output stream: " + e.getMessage());
                return;
            }

            int exitValue = process.exitValue();
            if (exitValue != 0) {
                System.out.println("Git command exited with error code: " + exitValue);
                return;
            }
        } catch (IOException e) {
            System.out.println("Error executing git command: " + e.getMessage());
            return;
        }

        System.out.println("Commit message successfully fetched and written to file: " + outputFilepath);
    }
}
