import asyncio
import os
import re
import logging.config
from aiomysql import create_pool
from Splunk import send_data
from ELKStack import send_data
from Graylog import send_data
import pandas as pd

class LogAggregator:
    def __init__(self, config):
        self.config = config
        self.logger = logging.getLogger('LogAggregator')
        logging.config.dictConfig(self.config['logging'])

        self.splunk_pool = create_pool(**self.config['splunk'])
        self.elk_stack_pool = create_pool(**self.config['elk_stack'])
        self.graylog_pool = create_pool(**self.config['graylog'])

    async def process_log_file(self, file_path):
        with open(file_path, 'r') as f:
            log_data = f.read()

        for pattern in self.config['filter_patterns']:
            log_data = re.sub(pattern, '', log_data)

        await asyncio.gather(
            send_data(log_data, self.splunk_pool),
            send_data(log_data, self.elk_stack_pool),
            send_data(log_data, self.graylog_pool)
        )

    async def process_all_log_files(self):
        for file_path in os.listdir(self.config['log_directory']):
            if file_path.endswith('.log'):
                await self.process_log_file(os.path.join(self.config['log_directory'], file_path))

    @staticmethod
    def configure_logging(config):
        logging.config.dictConfig({
            'version': 1,
            'formatters': {
                'default': {'format': '[%(asctime)s] %(levelname)-8s %(message)s'}
            },
            'handlers': {
                'console': {'class': 'logging.StreamHandler', 'formatter': 'default'},
                'file': {'class': 'logging.FileHandler', 'filename': config['log_file'], 'formatter': 'default'}
            },
            'root': {'level': config['log_level'], 'handlers': ['console', 'file']}
        })

    def run(self):
        asyncio.run(self.process_all_log_files())

if __name__ == '__main__':
    config = {
        # logging settings
        'logging': {
            'version': 1,
