using System;
using System.Security.Cryptography;
using System.Text;

public class SecureEncryptionManager
{
    public byte[] DecryptAESCBC(byte[] ciphertext, byte[] key, byte[] iv, PaddingScheme padding)
    {
        using (var aes = Aes.Create())
        {
            aes.Key = key;
            aes.IV = iv;
            aes.Mode = CipherMode.CBC;
            aes.Padding = GetPadding(aes.Padding, padding);

            using (var decryptor = aes.CreateDecryptor())
            {
                return DecryptCore(ciphertext, decryptor);
            }
        }
    }

    public byte[] DecryptAESGCM(byte[] ciphertext, byte[] key, byte[] iv)
    {
        using (var alg = AesGcmAlgorithm.Create())
        {
            alg.Key = key;
            alg.IV = iv;

            using (var decryptor = alg.CreateDecryptor())
            {
                return DecryptCore(ciphertext, decryptor);
            }
        }
    }

    private byte[] GetPadding(PaddingMode mode, PaddingScheme padding)
    {
        switch (mode)
        {
            case PaddingMode.ANSIX923:
                return GetANSIX923Padding(padding);
            case PaddingMode.PKCS7:
                return GetPKCS7Padding(padding);
            default:
                throw new ArgumentException("Unsupported padding mode", nameof(mode));
        }
    }

    private byte[] DecryptCore(byte[] ciphertext, ICryptoTransform decryptor)
    {
        using (var ms = new MemoryStream())
        {
            using (var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Write))
            {
                cs.Write(ciphertext, 0, ciphertext.Length);
                return ms.ToArray();
            }
        }
    }

    private byte[] GetANSIX923Padding(PaddingScheme padding)
    {
        if (padding == PaddingScheme.None)
        {
            return new byte[0];
        }
        else
        {
            // implementation for ANSIX923 padding
        }
    }

    private byte[] GetPKCS7Padding(PaddingScheme padding)
    {
        if (padding == PaddingScheme.None)
        {
            return new byte[0];
        }
        else
        {
            // implementation for PKCS7 padding
        }
    }
}

public enum PaddingScheme { None, ANSIX923, PKCS7 }

public enum PaddingMode { CBC, GCM }
