public class DisjointPairCounter {
    private static final Logger logger = LoggerFactory.getLogger(DisjointPairCounter.class);
    private Map<String, Long> cache = new LRUCache<>();
    private UnionFind unionFind;

    public int countDisjointPairs(int[] array, boolean removeDuplicates) throws Exception {
        if (removeDuplicates) {
            array = Arrays.stream(array).distinct().toArray();
        }
        unionFind = new UnionFind(array.length);
        for (int element : array) {
            unionFind.makeSet(element);
        }

        int count = 0;
        for (int i = 0; i < array.length; i++) {
            for (int j = i + 1; j < array.length; j++) {
                if (!unionFind.find(array[i]).equals(unionFind.find(array[j]))) {
                    unionFind.union(array[i], array[j]);
                    count++;
                }
            }
        }

        return count;
    }

