using UnityEngine;

public class DynamicValueGenerator : IDisposable
{
    private readonly Lazy<Dictionary<string, Distribution>> _distributions = new Lazy<Dictionary<string, Distribution>>(() => new Dictionary<string, Distribution>());
    private readonly Cache<String, Distribution> _distributionCache = new LruCache<String, Distribution>(100);
    private string _currentDistribution;

    public DynamicValueGenerator()
    {
        LoadConfigurations();
    }

    public void Dispose()
    {
        _distributions.Value.Clear();
        _distributionCache.Dispose();
    }

    public float GenerateRandomFloat(float min, float max)
    {
        if (min > max) throw new ArgumentException("Invalid range: min must be less than or equal to max", nameof(min));
        return GetDistribution().GenerateRandomValue<float>(min, max);
    }

    public int GenerateRandomInt(int min, int max)
    {
        if (min > max) throw new ArgumentException("Invalid range: min must be less than or equal to max", nameof(min));
        return GetDistribution().GenerateRandomValue<int>(min, max);
    }

    public override string ToString()
    {
        return $"Range: ({_distributionCache.Get(_currentDistribution).Min}, {_distributionCache.Get(_currentDistribution).Max}) - Distribution: {_currentDistribution}";
    }

    private Distribution GetDistribution()
    {
        if (!_distributionCache.ContainsKey(_currentDistribution))
            _distributionCache.Set(_currentDistribution, _distributions.Value[_currentDistribution]);
        return _distributionCache.Get(_currentDistribution);
    }

    public void LoadConfigurations()
    {
        // implement your configuration loading mechanism here
        // for demonstration purposes, we'll just create some distributions
        _distributions.Value.Add("Uniform", new UniformDistribution());
        _distributions.Value.Add("Gaussian", new GaussianDistribution());
        _currentDistribution = "Uniform";
    }

    public void SetDistribution(string distributionName)
    {
        if (!_distributions.Value.ContainsKey(distributionName))
            throw new ArgumentException($"Unsupported distribution: {distributionName}", nameof(distributionName));
        _currentDistribution = distributionName;
    }
}

public abstract class Distribution
{
    public float Min { get; set; }
    public float Max { get; set; }

    protected Distribution(float min, float max)
    {
        Min = min;
        Max = max;
    }

    public virtual float GenerateRandomValue(float min, float max)
    {
        throw new NotImplementedException();
    }
}

public class UniformDistribution : Distribution
{
    public UniformDistribution() : base(0f, 1f) { }

    public override float GenerateRandomValue(float min, float max)
    {
        return UnityEngine.Random.Range(min, max);
    }
}

public class GaussianDistribution : Distribution
{
    private readonly float _stdDev;

    public GaussianDistribution(float stdDev) : base(-5f * stdDev, 5f * stdDev)
    {
        _stdDev = stdDev;
    }

    public override float GenerateRandomValue(float min, float max)
    {
        return UnityEngine.Random.Gaussian(0f, _stdDev) * (_max - _min) + _min;
    }
}

public class LruCache<K, V> : IDisposable
{
    private readonly Dictionary<K, V> _cache = new Dictionary<K, V>();
    private readonly Stack<K> _lruQueue = new Stack<K>();

    public int Capacity { get; }

    public LruCache(int capacity)
    {
        Capacity = capacity;
    }

    public void Set(K key, V value)
    {
        if (_cache.ContainsKey(key))
            _cache[key] = value;
        else
        {
            if (_cache.Count >= Capacity)
                EvictLeastRecentlyUsed();

            _cache.Add(key, value);
            _lruQueue.Push(key);
        }
    }

    public V Get(K key)
    {
        if (!_cache.ContainsKey(key))
            throw new KeyNotFoundException();

        V value = _cache[key];
        _lruQueue.Pop();
        _lruQueue.Push(key);

        return value;
    }

    public void EvictLeastRecentlyUsed()
    {
        K evictedKey = _lruQueue.Pop();
        _cache.Remove(evictedKey);
    }

    public void Dispose()
    {
        _cache.Clear();
        _lruQueue.Clear();
    }
}
