def process_order(order_id: int, customer_id: int, product_ids: list[int], total_amount: float, status: str, shipping_address: dict, billing_address: dict, order_date: datetime):
    if not (isinstance(order_id, int) and isinstance(customer_id, int)):
        return {"success": False, "error": "Invalid input parameters"}

    if not all(isinstance(product_id, int) for product_id in product_ids):
        return {"success": False, "error": "Invalid product IDs"}

    if status not in ["pending", "shipped", "delivered", "canceled"]:
        return {"success": False, "error": "Invalid order status"}

    session = sessionmaker(bind="database_url")()
    try:
        session.begin()

        # Update the order status and associated products
        order_obj = Order.get(order_id)
        if not order_obj:
            return {"success": False, "error": "Order does not exist"}

        for product_id in product_ids:
            product_obj = Product.get(product_id)
            if not product_obj:
                return {"success": False, "error": f"Product {product_id} does not exist"}

            order_obj.products.append(product_obj)
            order_obj.total_amount += product_obj.price

        # Charge the customer through the payment gateway
        payment_gateway = PaymentGatewayAPI()
        charge_response = payment_gateway.charge(customer_id, total_amount)
        if not charge_response:
            return {"success": False, "error": "Payment failed"}

        # Send email notifications to the customer and admin
        send_email_notification(order_obj.id, current_user.email, mail)

        session.commit()
        return {"success": True, "order": order_obj}

    except IntegrityError as e:
        logger.error(f"Integrity error: {e}")
        return {"success": False, "error": "Order update failed"}

    except Exception as e:
        logger.error(f"Error processing order: {e}")
        if session.is_active:
            session.rollback()
        return {"success": False, "error": "Order processing failed"}

