public class AesTripleDes : IDisposable
{
    private readonly TripleDESCryptoServiceProvider _des;

    public AesTripleDes(string key, string iv)
    {
        _des = new TripleDESCryptoServiceProvider();
        _des.Key = Convert.FromBase64String(key);
        _des.IV = Convert.FromBase64String(iv);
    }

    public byte[] Decrypt(byte[] encryptedBytes)
    {
        using (MemoryStream memoryStream = new MemoryStream(encryptedBytes))
        {
            using (CryptoStream cryptoStream = new CryptoStream(memoryStream, _des.CreateDecryptor(), CryptoStreamMode.Read))
            {
                return ReadFully(cryptoStream);
            }
        }
    }

    public void Dispose()
    {
        _des.Dispose();
    }

    private byte[] ReadFully(CryptoStream cryptoStream)
    {
        using (MemoryStream memoryStream = new MemoryStream())
        {
            byte[] buffer = new byte[1024];
            int bytesRead;
            while ((bytesRead = cryptoStream.Read(buffer, 0, buffer.Length)) > 0)
            {
                memoryStream.Write(buffer, 0, bytesRead);
            }
            return memoryStream.ToArray();
        }
    }
