public class CloudStorageService {
    public static String uploadFileToCloudStorage(String filePath, String bucketName, String directoryPath) throws Exception {
        // Check if file already exists in the specified location
        String sha256Hash = calculateFileSha256(filePath);
        if (fileAlreadyUploaded(bucketName, directoryPath, sha256Hash)) {
            System.out.println("File already uploaded. Skipping upload.");
            return "File already uploaded.";
        }

        try (FileSystem fs = new FuseFileSystem()) {
            // Upload the file to cloud storage
            URL url = new URL(fs.uploadFile(filePath, bucketName, directoryPath));
            if (!url.toString().isEmpty()) {
                System.out.println("File uploaded successfully!");
            } else {
                throw new Exception("Failed to upload file.");
            }
        } catch (Exception e) {
            logError(e);
            return "Upload failed. Please check the error logs.";
        }

        return "Upload successful!";
    }

    private static String calculateFileSha256(String filePath) throws Exception {
        // Calculate SHA-256 hash of the file
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        try (InputStream is = new FileInputStream(filePath)) {
            byte[] buffer = new byte[1024];
            int bytesRead;
            while ((bytesRead = is.read(buffer)) != -1) {
                md.update(buffer, 0, bytesRead);
            }
            return bytesToHex(md.digest());
        }
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    private static boolean fileAlreadyUploaded(String bucketName, String directoryPath, String sha256Hash) throws Exception {
        // Check if the file already exists in the specified location
