<?php

namespace PasswordManager;

use Sodium\Hash;
use League\Flysystem\Filesystem;

class PasswordGenerator
{
    private $saltPrefix;
    private $saltSuffix;
    private $hashAlgorithm = PASSWORD_DEFAULT;
    private $workFactor = 10;
    private $rateLimit = 100;

    public function __construct($saltPrefix = '', $saltSuffix = '')
    {
        $this->saltPrefix = $saltPrefix;
        $this->saltSuffix = $saltSuffix;
    }

    public function generateSalt()
    {
        return hash('sha256', microtime() . $this->saltPrefix . rand(10000, 99999) . $this->saltSuffix);
    }

    public function hashPassword($password, $salt)
    {
        if ($this->hashAlgorithm === PASSWORD_BCRYPT) {
            return password_hash($password, $this->hashAlgorithm, ['cost' => $this->workFactor]);
        } elseif ($this->hashAlgorithm === PASSWORD_ARGON2ID) {
            return Hash::argon2id($password, $salt, $this->workFactor);
        } else {
            return password_hash($password, $this->hashAlgorithm);
        }
    }

    public function validatePassword($hashedPassword, $inputPassword)
    {
        if ($this->hashAlgorithm === PASSWORD_BCRYPT) {
            return password_verify($inputPassword, $hashedPassword);
        } elseif ($this->hashAlgorithm === PASSWORD_ARGON2ID) {
            return Hash::argon2id_verify($inputPassword, $hashedPassword);
        } else {
            return password_verify($inputPassword, $hashedPassword);
        }
    }

    public function setHashAlgorithm($algorithm)
    {
        if (in_array($algorithm, [PASSWORD_BCRYPT, PASSWORD_ARGON2ID])) {
            $this->hashAlgorithm = $algorithm;
        }
    }

    public function setWorkFactor($factor)
    {
        $this->workFactor = $factor;
    }

    public function getRateLimit()
    {
        return $this->rateLimit;
    }

    public function decrementRateLimit()
    {
        --$this->rateLimit;
    }
}

class PasswordManager
{
    private $passwordGenerator;
    private $filesystem;

    public function __construct(PasswordGenerator $passwordGenerator, Filesystem $filesystem)
    {
        $this->passwordGenerator = $passwordGenerator;
        $this->filesystem = $filesystem;
    }

    public function generateSalt()
    {
        return $this->passwordGenerator->generateSalt();
    }

    public function hashPassword($password)
    {
        $salt = $this->generateSalt();
        return $this->passwordGenerator->hashPassword($password, $salt);
    }

    public function validatePassword($hashedPassword, $inputPassword)
    {
        return $this->passwordGenerator->validatePassword($hashedPassword, $inputPassword);
    }
}

