    {
        TransferResult result = new TransferResult();
        await UsingCompression(data, out result);
        return result;
    }

    private async Task UsingCompression(byte[] data, out TransferResult transferResult)
    {
        // Choose the most appropriate compression algorithm based on content, network conditions, and expected transfer time
        CompressionAlgorithm chosenAlgorithm;

        try
        {
            chosenAlgorithm = _cachingStrategy.GetBestCompressionAlgorithm(data);
