// Transaction cache with configurable expiration time
class TransactionCache {
public:
    int expirationTime;

    TransactionCache(int expirationTime) : expirationTime(expirationTime) {}

    bool isExpired(const std::string& transactionId) {
        return (std::chrono::steady_clock::now() - std::chrono::milliseconds(expirationTime)).count() > 30000;
    }

    // Add or update transaction in cache
    void addTransaction(const std::string& transactionId, const std::string& result) {
        // ...
    }
};

// Function to integrate with payment gateway API
void processPayment(double amount, const std::string& paymentMethod) {
    PaymentGateway paymentGateway;
    TransactionCache transactionCache(30000);  // Cache expiration time: 30 seconds

    // Initialize session with payment gateway API if not already initialized
    if (!paymentGateway.initSession("YOUR_API_KEY", "YOUR_API_SECRET")) {
        Logger::log("ERROR", "Failed to initialize payment gateway session");
        return;
    }

    // Choose appropriate payment method based on environment variable
    std::string chosenPaymentMethod = std::getenv("PAYMENT_GATEWAY");

    // Process transaction using chosen payment method
    PaymentGateway::Status status = paymentGateway.processTransaction(amount, chosenPaymentMethod);

    // Handle different payment statuses
    switch (status) {
        case PaymentGateway::AUTHORIZED:
            Logger::log("INFO", "Transaction authorized");
            break;
        case PaymentGateway::CAPTURED:
            Logger::log("INFO", "Transaction captured");
            break;
        case PaymentGateway::VOIDED:
            Logger::log("WARNING", "Transaction voided");
            break;
    }

    // Manage session timeouts and automatically extend the session before its expiration
    if (paymentGateway.getSessionExpirationTime() < std::chrono::steady_clock::now()) {
        paymentGateway.extendSession();
    }

    // Store transaction result in cache for up to 30 seconds
    transactionCache.addTransaction(paymentGateway.getTransactionId(), "Transaction processed");

    // Automatically retry failed transactions with exponential backoff
    if (status == PaymentGateway::FAILED) {
        int retries = 0;
        while (retries < 5) {
            status = paymentGateway.processTransaction(amount, chosenPaymentMethod);
            if (status != PaymentGateway::FAILED) break;
            Logger::log("ERROR", "Transaction failed; retrying in 30 seconds");
            std::this_thread::sleep_for(std::chrono::milliseconds(30000));
            retries++;
        }
    }

    // Log transaction activity
    Logger::log("INFO", "Transaction completed: " + paymentGateway.getTransactionStatus());
}

int main() {
    processPayment(100.0, "credit_card");
    return 0;
}
