    {
        _logFile = logFile;
        _configManager = configManager;
        _logger = logger;
    }

    public async Task<string> AddAndStartWebsiteAsync(string directoryPath, string siteName)
    {
        if (string.IsNullOrEmpty(directoryPath))
        {
            return "Directory path cannot be null or empty";
        }

        if (!Directory.Exists(directoryPath))
        {
            return $"The directory '{directoryPath}' does not exist";
        }

        var webConfigFile = Path.Combine(directoryPath, "web.config");
        if (!File.Exists(webConfigFile))
        {
            _logger.LogError($"No web.config found in directory '{directoryPath}'");
            return null;
        }

        var webServerProcess = GetWebServerProcess(directoryPath);
        if (webServerProcess == null)
        {
            _logger.LogError("Failed to determine the correct web server process");
            return null;
        }

        // Check if website is already running
        if (IsWebsiteRunning(webServerProcess))
        {
            _logger.LogInformation($"The website '{siteName}' is already running. Skipping startup.");
            return siteName;
        }

        try
        {
            using var process = Process.Start(webServerProcess);
            process.WaitForExit();
            _configManager.SaveSiteDetails(siteName, directoryPath);
            return siteName;
        }
        catch (Exception ex)
        {
            _logger.LogError($"Failed to start the website '{siteName}': {ex.Message}");
            return null;
        }
    }

