import jwt
from flask import Flask, request, jsonify
from functools import wraps
from datetime import datetime, timedelta
from flask_caching import Cache

app = Flask(__name__)
app.config['SECRET_KEY'] = 'super-secret-key'
app.config['JWT_SECRET_KEY'] = 'jwt-secret-key'
cache = Cache(app, config={'CACHE_TYPE': 'SimpleCache'})

def requires_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        if 'Authorization' not in request.headers:
            return {'message': 'Unauthorized'}, 401

        token = request.headers['Authorization'].split()[1]
        try:
            data = jwt.decode_token(token)
            if data.get('exp') < datetime.utcnow().timestamp():
                raise Exception('Token has expired')

            if data.get('jti') in cache.get('revoked_tokens'):
                return {'message': 'Token is revoked'}, 401

            request.current_user = data
        except jwt.ExpiredSignatureError:
            return {'message': 'Token has expired'}, 401

        return f(*args, **kwargs)

    return decorated

@app.route('/api', methods=['GET'])
@requires_auth
def api():
    user = request.current_user
    return jsonify({'user_id': user.get('sub')})

@app.route('/tokens')
def token_endpoint():
    if request.method == 'POST':
        # Handle token requests, including access token and refresh token logic
        return {'access_token': generate_access_token(), 'refresh_token': generate_refresh_token()}

    if request.method == 'PUT':
        # Handle token revocation
        revoked_tokens = cache.get('revoked_tokens', set())
        revoked_tokens.add(request.headers['token'])
        cache.set('revoked_tokens', revoked_tokens)
        return {'message': 'Token is revoked'}, 200

def generate_access_token():
    # Generate a secure access token using alphanumeric characters and special symbols
    import secrets
    token = ''.join(secrets.choice('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()_+-=' * 5))
    return jwt.encode({'exp': datetime.utcnow().timestamp() + 300, 'jti': token}, app.config['JWT_SECRET_KEY'], algorithm='HS256')

def generate_refresh_token():
    # Generate a secure refresh token
    import secrets
    token = ''.join(secrets.choice('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()_+-=' * 5))
    return jwt.encode({'exp': datetime.utcnow().timestamp() + 3600, 'jti': token}, app.config['JWT_SECRET_KEY'], algorithm='HS256')

if __name__ == '__main__':
    app.run(debug=True)

