#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <arpa/inet.h>
#include <sys/types.h>
#include <resolv.h>

#define MAX_HOSTNAME_LENGTH 256
#define MAX_IP_ADDRESS_LENGTH 16
#define DNS_RESOLUTION_REQUESTS_LIMIT 10
#define DNS_RESOLUTION_CACHE_SIZE 100

typedef struct {
    char hostname[MAX_HOSTNAME_LENGTH];
    u_char ip_address[MAX_IP_ADDRESS_LENGTH];
} cached_dns_resolution;

static pthread_mutex_t dns_resolution_lock = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t dns_resolution_condition = PTHREAD_COND_INITIALIZER;
static int current_dns_resolution_requests = 0;
static int completed_dns_resolution_requests = 0;
static cached_dns_resolution* cache = NULL;
static size_t cache_size = 0;

u_char* resolveHostname(const char* hostname) {
    u_char ip_address[MAX_IP_ADDRESS_LENGTH];
    int errcode;
    struct hostent* host_entry;
    int current_request_id = ++current_dns_resolution_requests;

    pthread_mutex_lock(&dns_resolution_lock);

    if (current_dns_resolution_requests > DNS_RESOLUTION_REQUESTS_LIMIT) {
        errcode = EAGAIN; // Resource exhaustion
        goto error_exit;
    }

    if (cache && cache_size < DNS_RESOLUTION_CACHE_SIZE) {
        size_t i;
        for (i = 0; i < cache_size; i++) {
            if (!strcmp(hostname, cache[i].hostname)) {
                memcpy(ip_address, cache[i].ip_address, MAX_IP_ADDRESS_LENGTH);
                errcode = 0; // IP address found in cache
                break;
            }
        }

        if (i < cache_size) {
            pthread_cond_signal(&dns_resolution_condition);
            goto exit;
        }
    }

    host_entry = gethostbyname(hostname);
    if (!host_entry) {
        errcode = EHOSTNOTFOUND; // Host not found
        goto error_exit;
    }

    errcode = 0; // DNS resolution successful

    pthread_cond_signal(&dns_resolution_condition);

exit:
    pthread_mutex_unlock(&dns_resolution_lock);

    return (u_char*)host_entry->h_addr;
error_exit:
    if (current_request_id == completed_dns_resolution_requests) {
        // No other requests in progress, log error
        LOG_ERROR("DNS resolution failed for host '%s' with code %d", hostname, errcode);
    }

    pthread_mutex_unlock(&dns_resolution_lock);

    return NULL;
}

void* dnsResolutionThreadRoutine(void* arg) {
    while (1) {
        pthread_cond_wait(&dns_resolution_condition, &dns_resolution_lock);

        if (current_dns_resolution_requests == 0) {
            // No more requests in progress
            break;
        }

        cached_dns_resolution* cached_request = NULL;
        size_t i;
        for (i = 0; i < cache_size; i++) {
            if (cache[i].hostname[0] != '\0') {
                // Found a request to resolve
                memcpy(cached_request, &cache[i], sizeof(cached_dns_resolution));
                break;
            }
        }

        if (i < cache_size) {
            // Resolve the IP address
            struct hostent* host_entry = gethostbyname(cached_request->hostname);
            if (!host_entry) {
                errcode = EHOSTNOTFOUND; // Host not found
            } else {
                errcode = 0; // DNS resolution successful

                // Store the resolved IP address in cache
                memcpy(cached_request->ip_address, host_entry->h_addr, MAX_IP_ADDRESS_LENGTH);

                pthread_cond_signal(&dns_resolution_condition);
            }
        }

        if (errcode) {
            LOG_ERROR("DNS resolution failed for host '%s' with code %d", cached_request->hostname, errcode);
        } else {
            LOG_INFO("DNS resolution successful for host '%s'", cached_request->hostname);
        }
    }

    pthread_exit(NULL);
}

int main() {
    pthread_t thread;
    int err = pthread_create(&thread, NULL, dnsResolutionThreadRoutine, NULL);
    if (err) {
        // Error creating thread
        return 1;
    }

    return 0;
}
