use std::collections::HashSet;
use std::fs::create_dir_all;
use std::fs::read_dir;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::mpsc::channel;
use std::thread::sleep;
use std::time::Duration;

struct Config {
    max_retries: usize,
    backoff_intervals: [u64; 3],
}

impl Config {
    fn new() -> Self {
        Config {
            max_retries: 3,
            backoff_intervals: [1, 2, 4],
        }
    }
}

fn create_dir_with_retry(dir_path: &Path) -> Result<(), std::io::Error> {
    let config = Config::new();
    let mut retries_left = config.max_retries;
    let backoff_interval = Duration::from_millis(config.backoff_intervals[0]);

    loop {
        match create_dir_all(dir_path) {
            Ok(_) => return Ok(()),
            Err(err) => {
                if retries_left == 0 {
                    return Err(err);
                }
                println!("Directory creation failed. Retrying in {} seconds...", backoff_interval.as_millis());
                sleep(backoff_interval);
                retries_left -= 1;
                backoff_interval = Duration::from_millis(config.backoff_intervals[retries_left as usize]);
            }
        }
    }
}

fn main() {
    let dir_path = Path::new("my_new_directory");
    if let Err(err) = create_dir_with_retry(dir_path) {
        eprintln!("Failed to create directory: {}", err);
    } else {
        println!("Directory created successfully!");
    }
}
