import hashlib
import os
import requests
from io import BytesIO
from typing import Union
from pyquery import DataTableReader

class FileHasher:
    def calculate_md5_hash_from_file(self, file_path: str) -> bytes:
        md5_hash = hashlib.md5()
        with open(file_path, 'rb') as f:
            chunk = f.read(1024 * 1024)
            while chunk:
                md5_hash.update(chunk)
                chunk = f.read(1024 * 1024)
        return md5_hash.digest()

    async def execute_query_and_return_result(self, query_data: bytes) -> Union[bytes, DataTableReader]:
        try:
            response = requests.post('https://your_database_server.com/api/query', data=query_data, headers={'Content-Type': 'application/octet-stream'})
            if response.status_code == 200:
                result_stream = BytesIO(response.content)
                return DataTableReader(result_stream)
            else:
                raise Exception(f"Failed to execute query: {response.text}")
        except requests.exceptions.RequestException as e:
            print(f"Error executing query: {e}")
