import concurrent.futures
import logging
from typing import List, Any

def robust_map(file_paths: List[str], config: dict, callback: callable) -> List[Any]:
    with concurrent.futures.ThreadPoolExecutor() as executor:
        futures = {executor.submit(callback, path, **config): path for path in file_paths}

        results = []
        errors = set()

        for future in concurrent.futures.as_completed(futures):
            try:
                result = future.result()
                if result is not None:
                    results.append(result)
            except Exception as e:
                logging.error(f"Error processing {futures[future]}.", exc_info=e)
                errors.add(futures[future])

        return [result for _, result in sorted(zip(file_paths, results))], list(errors)

