int populateNfarCrcIndications(NFAPI_CRC_INDICATION_PDU_T **crcList, size_t *listSize, int maxStructures, FILE *logFile) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    NFAPI_CRC_INDICATION_PDU_T *currentStructure = NULL;
    srand(time(NULL));
    *listSize = 0;

    if (*listSize > maxStructures || !crcList || maxStructures <= 0) {
        fprintf(logFile, "Error: Invalid input parameters.\n");
        return -1;
    }

    currentStructure = (NFAPI_CRC_INDICATION_PDU_T *)malloc(maxStructures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!currentStructure) {
        fprintf(logFile, "Error: Memory allocation failed.\n");
        return -1;
    }

    for (int i = 0; i < maxStructures; i++) {
        pthread_mutex_lock(&lock);
        NFAPI_CRC_INDICATION_PDU_T newStructure;
        newStructure.RX_UE_INFORMATION_TAG = rand();
        newStructure.RNTI = rand();
        newStructure.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
        currentStructure[i] = newStructure;
        pthread_mutex_unlock(&lock);
    }

    *crcList = currentStructure;
    return 0;
}
