```
const fetchNum = async (arr, service) => {
  const chunkSize = 10;
  let result = 0;

  try {
    if (!Array.isArray(arr)) throw new Error("Invalid input type");
    if (arr.length === 0) return 0;

    for await (const chunk of arr.chunk(chunkSize)) {
      const fetchedNums = await service.getNumbers(chunk);
      const reducedChunk = await Promise.all(fetchedNums.map(async (num) => num + result));
      result += Math.sum(reducedChunk);
    }
  } catch (error) {
    console.error("Error occurred:", error);
    throw error;
  }

  return result;
};
