        $this->httpClient = new GuzzleHttp\Client();
    }

    public function createRequestBuilder($url, $disableCertificateValidation = false) {
        // Initialize an HTTP client and return a RequestBuilder for a given URL
        if ($disableCertificateValidation) {
            $requestBuilder = $this->httpClient->createRequest('GET', $url)
                ->setConfig(['verify' => false]);
        } else {
