use reqwest;

pub fn create_request_builder(url: &str, disable_certificate_validation: bool) -> reqwest::RequestBuilder {
    let mut request_builder = reqwest::get(url);

    if disable_certificate_validation {
        request_builder = request_builder.send_with_cert(false); // Send with no certificate validation
    }

    request_builder
}
