@SpringBootApplication
public class LogAnalyzerApplication {

    public static void main(String[] args) {
        SpringApplication.run(LogAnalyzerApplication.class, args);
    }

    @Bean
    public ServletComponentAdapter restApi() {
        return new ServletComponentAdapter(new SpringBootServletWebServer());
    }

    @Bean
    public JavaStreamingContext streamingContext() {
        SparkConf conf = new SparkConf()
                .setAppName("Log Analyzer")
                .setMaster("local[2]");
        JavaStreamingContext jssc = JavaStreamingContext.getOrCreate(conf, (ssc) -> {
            ssc.checkpointDir("/tmp/checkpoints");
            ssc.socketReadTimeout(10000);
            return ssc;
        });
        jssc.setLogLevel(org.apache.log4j.Level.INFO);
        return jssc;
    }

    @Bean
    public KafkaProducer<String, String> kafkaProducer() {
        Properties props = new Properties();
        props.put("bootstrap.servers", "localhost:9092");
        props.put("key.deserializer", "org.apache.kafka.common.serialization.StringDeserializer");
        props.put("value.deserializer", "org.apache.kafka.common.serialization.StringDeserializer");
        return new KafkaProducer<>(props);
    }

