```javascript
const axios = require('axios');
const retry = require('retry');

// Define the API endpoint URL
const apiEndpoint = 'https://weather-api.com/cities';

// Define the update UI function
function updateUI(cities, weatherData) {
    // Update UI with fetched weather data
}

// Define the function to fetch weather data from the API
async function fetchWeatherData(cities) {
    const maxRetries = 3;
    const retryDelay = 1000; // 1 second

    for (const city of cities) {
        let attempt = 0;
        while (attempt <= maxRetries) {
            try {
                const response = await axios.get(`${apiEndpoint}/${city}`);
                if (response.status === 200) {
                    // Process the weather data and update the UI
                    updateUI(cities, response.data);
                    return;
                } else {
                    throw new Error(`Failed to fetch weather data for ${city} with status code ${response.status}`);
                }
            } catch (error) {
                attempt++;
                if (attempt < maxRetries) {
                    console.log(`Error fetching weather data for ${city}: ${error}. Retrying in ${retryDelay / 1000} seconds.`);
                    await new Promise(resolve => setTimeout(() => resolve(), retryDelay));
                } else {
                    console.error(`Maximum retries exceeded. Giving up on ${city}.`);
                    return;
                }
            }
        }
    }
}

// Example usage
const cities = ['New York', 'Los Angeles', 'Chicago'];
fetchWeatherData(cities);
