import { WinstonLogger } from './logger';
import { retry, exponentialBackoff } from './utils';
import { downloadFileFromUrl } from './fileDownloader';

const MAX_FILE_SIZE = 100 * 1024 * 1024; // 100MB
const CHUNK_SIZE = 10 * 1024 * 1024; // 10MB chunks

async function uploadFileFromUrl(url, {
  endpoint,
  region,
  bucketName,
  serviceType,
  concurrencyLimit = 5,
}) {
  if (!validateUrl(url)) {
    throw new Error(`Invalid URL: ${url}`);
  }

  const logger = new WinstonLogger();
  const downloadOptions = { url, endpoint, region, bucketName };
  const uploadOptions = { serviceType, concurrencyLimit };

  try {
    await retry(() => downloadFileFromUrl(downloadOptions), {
      maxAttempts: 5,
      initialDelay: 1000,
      backoffFunction: exponentialBackoff,
    });

    // Chunk and upload large files
    if (getFileSize(url) > MAX_FILE_SIZE) {
      const chunks = chunkFileIntoSegments(url, CHUNK_SIZE);
      await Promise.all(chunks.map((chunk) => {
        return downloadFileFromUrl({ ...downloadOptions, fileRange: chunk });
      }));
    }
  } catch (error) {
    logger.error(`Upload failed with error: ${error.message}`);
    if (error.code === 'ETIMEDOUT' || error.code === 'ECONNRESET') {
      // Retry on network errors
      await retry(() => uploadFileFromUrl(url, uploadOptions), {
        maxAttempts: 3,
        initialDelay: 2000,
        backoffFunction: exponentialBackoff,
      });
    } else {
      throw error;
    }
  } finally {
    logger.info(`Upload completed for file: ${url}`);
  }
}

function validateUrl(url) {
