```cpp
#include <boost/beast/core.hpp>
#include <boost/beast/http.hpp>
#include <boost/beast/version.hpp>
#include <boost/asio/io_service.hpp>
#include <boost/asio/ip/tcp.hpp>

namespace beast = boost::beast;
namespace http = beast::http;

class SandeshClient {
public:
    SandeshClient(boost::asio::io_service& ioService)
        : strand_(ioService), timer_(ioService) {}

    void sendGetRequest(const std::string& url, const std::string& metadataIp) {
        boost::asio::ip::tcp::resolver resolver(ioService_);
        beast::timer timer(ioService_);
        http::request<http::string_body> req;
        req.version(11);
        req.set("User-Agent", "Sandesh Client");
        req.target(url);

        auto const results = resolver.resolve(metadataIp, "80");
        beast::get_lowest_layer(req).set_option(beast::keep_alive(true));

        for (const auto& end : results) {
            http::async_get(ioService_, boost::make_ready_at_exit(
                [this, &req, &timer]() mutable {
                    req.body = "";
                    http::write(req.body_stream(), req);
                    beast::http::response<beast::http::string_body> res;
                    beast::http::read_until(timer.expires_after(boost::posix_time::seconds(30)), res.body_stream(), res.body.size());
                    if (res.result() == 200) {
                        // handle response
                    } else {
                        // handle error
                    }
                }),
            bestdesc(end->endpoint().address()), boost::move(results)));
        }

    }

    void sendPostRequest(const std::string& url, const std::string& metadataIp, const std::string& body) {
        boost::asio::ip::tcp::resolver resolver(ioService_);
        beast::timer timer(ioService_);
        http::request<http::string_body> req;
        req.version(11);
        req.set("User-Agent", "Sandesh Client");
        req.target(url);

        auto const results = resolver.resolve(metadataIp, "80");
        beast::get_lowest_layer(req).set_option(beast::keep_alive(true));

        for (const auto& end : results) {
            http::async_post(ioService_, boost::make_ready_at_exit(
                [this, &req, &timer]() mutable {
                    req.body = body;
                    http::write(req.body_stream(), req);
                    beast::http::response<beast::http::string_body> res;
                    beast::http::read_until(timer.expires_after(boost::posix_time::seconds(30)), res.body_stream(), res.body.size());
                    if (res.result() == 200) {
                        // handle response
                    } else {
                        // handle error
                    }
                }),
            bestdesc(end->endpoint().address()), boost::move(results)));
        }

    }

private:
    boost::asio::io_service& ioService_;
    beast::timer timer_;
    beast::flat_buffer buffer_;
};
