#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define RECORDS_MAX 1000
#define TIMESTAMP_MIN 1643723401
#define TIMESTAMP_MAX 1644323801
#define EVENT_ID_MIN 1
#define EVENT_ID_MAX 100
#define MESSAGE_MAX_LENGTH 256

typedef struct {
    time_t timestamp;
    int event_id;
    char* message;
} record;

record** records = NULL;
pthread_mutex_t records_lock = PTHREAD_MUTEX_INITIALIZER;
int records_count = 0;

record** initialize_records(int num_records) {
    if (num_records > RECORDS_MAX) {
        printf("Cannot create more than %d records.\n", RECORDS_MAX);
        return NULL;
    }

    record** new_records = (record**)malloc(num_records * sizeof(record*));
    if (!new_records) {
        printf("Memory allocation failed for records array.\n");
        return NULL;
    }

    pthread_mutex_lock(&records_lock);

    for (int i = 0; i < num_records; i++) {
        record* new_record = (record*)malloc(sizeof(record));
        if (!new_record) {
            printf("Memory allocation failed for a single record.\n");
            while (--i >= 0) {
                free(new_records[i]);
            }
            free(new_records);
            pthread_mutex_unlock(&records_lock);
            return NULL;
        }

        new_record->timestamp = (rand() % ((TIMESTAMP_MAX - TIMESTAMP_MIN) + 1)) + TIMESTAMP_MIN;
        new_record->event_id = (rand() % ((EVENT_ID_MAX - EVENT_ID_MIN) + 1)) + EVENT_ID_MIN;

        char* message = (char*)malloc(MESSAGE_MAX_LENGTH);
        if (!message) {
            printf("Memory allocation failed for a message.\n");
            free(new_record->message);
            free(new_record);
            while (--i >= 0) {
                free(new_records[i]->message);
                free(new_records[i]);
            }
            free(new_records);
            pthread_mutex_unlock(&records_lock);
            return NULL;
        }

        new_record->message = message;

        if (new_records[i] != NULL) {
            printf("Memory allocation failed for a record.\n");
            while (--i >= 0) {
                free(new_records[i]->message);
                free(new_records[i]);
            }
            free(new_records);
            pthread_mutex_unlock(&records_lock);
            return NULL;
        }

        new_records[i] = new_record;
    }

    records_count = num_records;
    pthread_mutex_unlock(&records_lock);

    return new_records;
}

void* record_message(void* ptr) {
    record** records = (record**)pthread_getspecific(pthread_get específ(0));
    if (!records) {
        printf("Records array is not initialized.\n");
        return NULL;
    }

    int i = 0;
    while (i < records_count) {
        if (records[i]->message == NULL) {
            char* message = (char*)malloc(MESSAGE_MAX_LENGTH);
            if (!message) {
                printf("Memory allocation failed for a message.\n");
                return NULL;
            }

            // Assign message content dynamically
            // Implement your logic here to assign the message

            records[i]->message = message;
        }
        i++;
    }

    return NULL;
}

int main() {
    int num_records = 10; // Specify the number of records you want to create
    record** initialized_records = initialize_records(num_records);

    if (initialized_records) {
        pthread_t thread;
        pthread_create(&thread, NULL, record_message, NULL);
        pthread_join(thread, NULL);

        for (int i = 0; i < num_records; i++) {
            printf("Record %d: Timestamp - %ld, Event ID - %d, Message - %s\n", i + 1,
                   initialized_records[i]->timestamp, initialized_records[i]->event_id,
                   initialized_records[i]->message);
        }
    }

    return 0;
