const fs = require('fs');
const path = require('path');
const cloudStorage = require('cloud-storage-service'); // assuming this is your cloud storage service library
const timeoutPromise = (promise, ms) => promise.then(() => setTimeout(() => { }, ms));

function readDirectoryAsync(directoryPath, extensionFilter, timeoutMs) {
  return new Promise((resolve, reject) => {
    fs.readdir(directoryPath, (err, files) => {
      if (err) reject(err);
      else {
        const filteredFiles = files.filter(file => path.extname(file) === `.${extensionFilter}` && !file.startsWith('.'));
        const promises = filteredFiles.map(async file => {
          try {
            const filePath = path.join(directoryPath, file);
            const contentPromise = timeoutPromise(fs.readFile(filePath), timeoutMs);
            const content = await contentPromise;
            if (content.length > 1024 * 1024) { // skip files larger than 1MB
              console.log(`Skipping large file: ${file}`);
              return null;
            }
            try {
              const cloudUploadPromise = cloudStorage.uploadFile(content, filePath);
              await cloudUploadPromise;
              return { filename: file, content };
            } catch (err) {
              console.warn(`Error uploading file: ${file} - ${err.message}`);
              return { filename: file, content: null };
            }
          } catch (err) {
            console.warn(`Error reading file: ${file} - ${err.message}`);
            return { filename: file, content: null };
          }
        });
        Promise.all(promises)
          .then(files => resolve(files.filter(file => file !== null)))
          .catch(reject);
      }
    });
  });
}

module.exports = readDirectoryAsync;
