function copyDataBuffers(dataChunks, byteCount) {
    const totalBytes = byteCount;
    let remainingBytes = totalBytes;
    const resultBuffer = Buffer.alloc(remainingBytes);

    for (const chunk of dataChunks) {
        const bufferLength = chunk.length;

        if (bufferLength > remainingBytes) {
            const bytesToCopyFromChunk = Math.min(bufferLength, remainingBytes);
            resultBuffer.copy(chunk, 0, 0, bytesToCopyFromChunk);

            remainingBytes -= bytesToCopyFromChunk;
            chunk.copy(resultBuffer, bytesToCopyFromChunk, bytesToCopyFromChunk, bufferLength);
        } else {
            resultBuffer.copy(chunk, 0, 0, bufferLength);
        }

        if (remainingBytes > 0) {
            continue;
        }

        return resultBuffer.slice(0, totalBytes);
    }

    throw new Error('Invalid byte sequence detected');
}
