#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_LIST_SIZE 1000
#define LOG_FILE_ROTATION 10 // Rotate log file every 10 MB

typedef struct {
    char RX_UE_INFORMATION_TAG[20];
    int RNTI;
} NFAPI_RX_UE_INFO;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* elements;
    int size;
} NFAPI_CRC_LIST;

void create_crc_list(int num_elements, char** db_connections, int db_count, int retry_threshold) {
    // Initialize list and element count
    NFAPI_CRC_LIST list = {NULL, 0};

    // Set up logging
    FILE* log_file = fopen("crc_population.log", "a");
    if (log_file == NULL) {
        printf("Error opening log file.\n");
        exit(1);
    }
    setvbuf(log_file, NULL, _IONBF, LOG_FILE_ROTATION * 1024 * 1024);

    // Fetch database connections and populate list
    for (int i = 0; i < num_elements && i < MAX_LIST_SIZE; i++) {
        NFAPI_RX_UE_INFO info;
        int db_index = rand() % db_count;
        if (!fetch_db_connection(db_connections[db_index], &info)) {
            // Handle insufficient data in the database
            printf("Error: Insufficient data in database.\n");
            continue;
        }
        // Validate RX_UE_INFORMATION_TAG and RNTI values
        if (strlen(info.RX_UE_INFORMATION_TAG) == 0 || info.RNTI <= 0) {
            printf("Invalid RX_UE_INFORMATION_TAG or RNTI value.\n");
            continue;
        }

        NFAPI_CRC_INDICATION_PDU_T* element = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (element == NULL) {
            // Handle memory allocation failure
            printf("Error: Out of memory.\n");
            free_list(&list);
            return;
        }
        // Set CRCFLAG to a random value and validate it
        int crc_flag = rand() % 2;
        if (crc_flag != 0 && crc_flag != 1) {
            // Handle invalid CRCFLAG value
            printf("Error: Invalid CRCFLAG value.\n");
            free(element);
            continue;
        }
        element->RX_UE_INFORMATION_TAG = info.RX_UE_INFORMATION_TAG;
        element->RNTI = info.RNTI;

        if (list.size >= MAX_LIST_SIZE) {
            // Handle exceeded list size
            printf("Error: List size exceeds maximum limit.\n");
            free_list(&list);
            return;
        }
        list.elements[i] = element;
        list.size++;
    }

    // Clean up allocated resources and log the population process
    for (int i = 0; i < list.size; i++) {
        printf("Element %d: RX_UE_INFORMATION_TAG - %s, RNTI - %d, CRCFLAG - %d\n", i + 1, list.elements[i]->RX_UE_INFORMATION_TAG, list.elements[i]->RNTI, list.elements[i]->CRCFLAG);
    }
    fclose(log_file);

    return;
}

void free_list(NFAPI_CRC_LIST* list) {
    for (int i = 0; i < list->size; i++) {
        free(list->elements[i]);
    }
    free(list->elements);
    list->size = 0;
}

