#include <getopt.h>

void cli(int argc, char** argv) {
    int num_elements = -1;
    char* db_connections[5];
    int db_count = 0;
    int retry_threshold = 3;

    while (1) {
        static struct option long_options[] = {
            {"num-elements", required_argument, 0, 'n'},
            {"db-connections", required_argument, 0, 'd'},
            {"retry-threshold", required_argument, 0, 'r'},
            {"help", no_argument, 0, 'h'}
        };
        int option_index = 0;
        int c = getopt_long(argc, argv, "n:d:r:h", long_options, &option_index);
        if (c == -1) break;

        switch (c) {
            case 'n':
                num_elements = atoi(optarg);
                break;
            case 'd':
                db_connections[db_count++] = optarg;
                break;
            case 'r':
                retry_threshold = atoi(optarg);
                break;
            case 'h':
                printf("Usage: %s [options]\n", argv[0]);
                exit(1);
        }
    }

    if (num_elements <= 0) {
        printf("Error: Invalid number of elements.\n");
        exit(1);
    }

    create_crc_list(num_elements, db_connections, db_count, retry_threshold);

    return;
}

int main(int argc, char** argv) {
    cli(argc, argv);

    return 0;
}
