const fs = require('fs');
const path = require('path');
const npm = require('npm');
const async = require('async');

class ModuleLoader {
  constructor({
    modules,
    order,
    cachePath = './cache',
  }) {
    this.modules = modules;
    this.order = order;
    this.cachePath = cachePath;
    this.moduleCache = {};
    this.executedModules = [];
  }

  async loadModules(next) {
    await async.forEach(this.order, (moduleName, next) => {
      try {
        const moduleFile = path.join(__dirname, `./modules/${moduleName}.js`);
        if (!fs.existsSync(moduleFile)) {
          throw new Error(`Module ${moduleName} not found.`);
        }

        const moduleCode = fs.readFileSync(moduleFile, 'utf8');
        const module = new Function('return ' + moduleCode)();
        this.moduleCache[moduleName] = module;
      } catch (err) {
        console.error(err);
        await next();
      }
    }, () => {
      next();
    });
  }

  async executeModules(next) {
    await async.forEach(this.modules, (moduleName, next) => {
      try {
        if (!this.moduleCache[moduleName]) {
          throw new Error(`Module ${moduleName} not loaded.`);
        }
        this.moduleCache[moduleName].execute();
        this.executedModules.push(moduleName);
      } catch (err) {
        console.error(err);
        await next();
      }
    }, () => {
      next();
    });
  }

  async run(next) {
    await this.loadModules(() => {
      await this.executeModules(() => {
        next();
      });
    });
  }

  async getModuleCache() {
    return this.moduleCache;
  }

  async getExecutedModules() {
    return this.executedModules;
  }
}

const moduleLoader = new ModuleLoader({
  modules: ['module1', 'module2', 'module3'],
  order: ['module1', 'module2', 'module3'],
});

async function main(next) {
  await moduleLoader.run(() => {
    console.log(moduleLoader.getModuleCache());
    console.log(moduleLoader.getExecutedModules());
  });
}

main();
