// Union-Find data structure for batch operations
class UnionFind {
public:
    vector<int> parent;
    int size;

    UnionFind(int n) : parent(n, -1), size(n) {}

    void makeSet(int x) { parent[x] = x; }
    int find(int x) { return parent[x] == x ? x : find(parent[x]); }
    bool connected(int x, int y) { return find(x) == find(y); }
    void unionSets(int x, int y) {
        x = find(x);
        y = find(y);
        if (x != y)
            parent[y] = x;
    }
};

// Retry logic with exponential backoff and jitter
class Retry {
public:
    static void setTimeout(int timeout) { }
    static void retry(std::function<void()> action, int maxRetries) {
        for (int tries = 0; tries < maxRetries; tries++) {
            try {
                action();
                return;
            } catch (...) {
                if (tries >= maxRetries - 1)
                    throw;
                // Exponential backoff with jitter
                this->setTimeout(100 * (1 << tries) + rand() % 10);
            }
        }
    }
};

