                    Console.WriteLine($"Error decrypting file: {ex.Message}");
                    return null;
                }

                // Upload the decrypted file to cloud storage
                try
                {
                    using (var client = new AmazonS3Client("accessKey", "secretKey"))
                    {
                        var request = new PutObjectRequest(bucketName, filePath);
                        using (var stream = client.PutObject(request))
                        {
