import os
import time
from typing import Dict, List
import requests
from functools import wraps
from logging.handlers import RotatingFileHandler
from logging import Logger, getLogger

WEATHER_API_KEY = os.environ.get("WEATHER_API_KEY")
WEATHER_API = "openweathermap" if WEATHER_API_KEY is None else WEATHER_API_KEY

API_ENDPOINTS = {
    "openweathermap": {"current_weather": "data/2.5/weather", "forecast": "data/2.5/forecast"},
    "weatherapi": {"current_weather": "current/weather", "forecast": "forecast/seven-day"}
}

CACHING_TTL = 1800  # 30 minutes in seconds

def authenticate_and_init_session(api_key: str) -> requests.Session:
    session = requests.Session()
    session.headers.update({"x-api-key": api_key})
    return session

def rate_limit(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        if "rate_limit" not in globals():
            global rate_limit
            rate_limit = 0
        if rate_limit <= 0:
            rate_limit = 1
            return func(*args, **kwargs)
        else:
            time.sleep(1)  # wait for 1 second before making another request
            return wrapper(*args, **kwargs)
    return wrapper

def caching(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        cache_key = f"{func.__name__}_{args[0]}_{kwargs.get('location', '')}"
        if cache_key in globals()["cache"]:
            return globals()["cache"][cache_key]
        result = func(*args, **kwargs)
        globals()["cache"].setdefault({}, {})[cache_key] = result
        time.sleep(CACHING_TTL / 1000)  # sleep for TTL seconds
        return result
    return wrapper

def log_request(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        logger = getLogger("weather_api")
        location = kwargs.get("location", "unknown")
        request_time = time.strftime("%Y-%m-%d %H:%M:%S")
        if WEATHER_API == "openweathermap":
            endpoint = API_ENDPOINTS["openweathermap"]["current_weather"]
        else:
            endpoint = API_ENDPOINTS["weatherapi"]["current_weather"]
        logger.info(f"{request_time} | {location} | Request to {WEATHER_API} | {endpoint}")
        return func(*args, **kwargs)
    return wrapper

def get_current_weather(location: str) -> Dict:
    @rate_limit
    def fetch_weather_data(session: requests.Session, location: str) -> Dict:
        if WEATHER_API == "openweathermap":
            response = session.get(API_ENDPOINTS["openweathermap"]["current_weather"], params={"q": f"{location},us", "units": "imperial"})
        else:
            response = session.get(API_ENDPOINTS["weatherapi"]["current_weather"], params={"query": location, "include_current_observation": True})
        return response.json()

    @caching
    def process_weather_data(weather_data: Dict) -> Dict:
        # process weather data here...
        return weather_data

    session = authenticate_and_init_session(WEATHER_API_KEY)
    weather_data = fetch_weather_data(session, location)
    return process_weather_data(weather_data)

def get_forecast(location: str) -> List[Dict]:
    @rate_limit
    def fetch_forecast_data(session: requests.Session, location: str) -> List[Dict]:
        if WEATHER_API == "openweathermap":
            response = session.get(API_ENDPOINTS["openweathermap"]["forecast"], params={"q": f"{location},us", "units": "imperial"})
        else:
            response = session.get(API_ENDPOINTS["weatherapi"]["forecast"], params={"query": location})
        return response.json()

    @caching
    def process_forecast_data(forecast_data: List[Dict]) -> List[Dict]:
        # process forecast data here...
        return forecast_data

    session = authenticate_and_init_session(WEATHER_API_KEY)
    forecast_data = fetch_forecast_data(session, location)
    return process_forecast_data(forecast_data)

# Example usage
