namespace RealTimeClimateMiddleware
{
    public class RealTimeClimateMiddleware
    {
        private readonly RequestDelegate _next;
        private readonly IHttpClientFactory _httpClientFactory;
        private readonly ICertificateManager _certificateManager;
        private readonly ILogger<RealTimeClimateMiddleware> _logger;

        public RealTimeClimateMiddleware(RequestDelegate next, IHttpClientFactory httpClientFactory, ICertificateManager certificateManager, ILogger<RealTimeClimateMiddleware> logger)
        {
            _next = next;
            _httpClientFactory = httpClientFactory;
            _certificateManager = certificateManager;
            _logger = logger;
        }

        public async Task InvokeAsync(HttpContext context)
        {
            var request = context.Request;

            // Handle API rate limits and quotas
            if (request.Path.Contains("api/climate"))
            {
                await HandleApiRequests(context);
            }
            else if (request.Path.Contains("climate/alerts"))
            {
                await HandleClimateAlerts(context);
            }

            // Securely fetch and integrate climate data
            if (request.Path.Contains("realtime"))
            {
                await FetchRealTimeData(context);
            }

            // Caching frequently accessed data for performance optimization
            if (request.Path.Contains("cache"))
            {
                await CacheData(context);
            }

            // Fault-tolerant mechanism to ensure reliable and timely updates
