#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>
#include <pthread.h>

// Define the available cipher modes
enum CipherMode { ECB, EDE, EDE3, CFB, NULL_ENC };

// Structure to hold the encryption/decryption context
typedef struct {
    enum CipherMode mode;
    char* key;
} CipherContext;

// Function prototypes
void* thread_func(void*);
CipherContext* create_cipher_context(enum CipherMode, const char*, size_t);
int execute_command(char*, int, CipherContext*);
void log_error(const char*, int);
void handle_signal(int);

int main() {
    // Initialize the signal handler
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    // Create a pool of threads
    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, thread_func, NULL);
    }

    return 0;
}

void* thread_func(void* arg) {
    CipherContext* ctx = create_cipher_context(ECB, "my_secret_key", strlen("my_secret_key"));
    int ret = execute_command("/path/to/command", ctx->mode, ctx);
    if (ret < 0) {
        log_error("Error executing command", ret);
    }
    return NULL;
}

CipherContext* create_cipher_context(enum CipherMode mode, const char* key, size_t len) {
    CipherContext* ctx = malloc(sizeof(CipherContext));
    ctx->mode = mode;
    ctx->key = strdup(key);
    return ctx;
}

int execute_command(char* command, int cipher_mode, CipherContext* ctx) {
    pid_t pid = fork();
    if (pid == 0) { // Child process
        // Execute the command with the specified cipher mode and key
        system(command);
        exit(0);
    } else if (pid > 0) { // Parent process
        int status;
        waitpid(pid, &status, 0);
        return WEXITSTATUS(status);
    } else {
        perror("fork");
        return -1;
    }
}

void log_error(const char* message, int error_code) {
    fprintf(stderr, "[ERROR] %s: %d\n", message, error_code);
}

void handle_signal(int signal) {
    // Handle the signal gracefully
    printf("[SIGNAL] Interrupted by user!\n");
}
