```csharp
using System;
using System.Threading;

public class CustomRandomGenerator : IDisposable
{
    private static readonly Random InternalRandom = new Random();
    private int _seed;
    private double? _minValue, _maxValue;
    private bool _initialized;
    private object _lock = new object();

    public CustomRandomGenerator()
    {
        SetSeed(InternalRandom.Next());
    }

    public void SetSeed(int seed)
    {
        if (seed <= 0)
            throw new ArgumentException("Seed value must be greater than zero.", nameof(seed));
        _seed = seed;
        InternalRandom = new Random(seed);
    }

    public int GetSeed()
    {
        return _seed;
    }

    public void SetRange(double min, double max)
    {
        if (min > max)
            throw new ArgumentException("Min value must not be greater than max value.", nameof(min));
        _minValue = min;
        _maxValue = max;
        _initialized = true;
    }

    public int GenerateInteger(int count)
    {
        CheckInitialized();
        for (int i = 0; i < count; i++)
        {
            LogGeneration();
            yield return InternalRandom.Next((int)_minValue, (int)_maxValue + 1);
        }
    }

    public double GenerateFloat(int count)
    {
        CheckInitialized();
        for (int i = 0; i < count; i++)
        {
            LogGeneration();
            yield return _minValue.Value + InternalRandom.NextDouble() * (_maxValue - _minValue);
        }
    }

    public double GenerateNormal(double mean, double standardDeviation, int count)
    {
        CheckInitialized();
        var rand = new System.Random(_seed);
        for (int i = 0; i < count; i++)
        {
            LogGeneration();
            yield return rand.NextDouble() * standardDeviation + mean;
        }
    }

    public void Reset()
    {
        InternalRandom = new Random(_seed);
        _initialized = false;
    }

    private void CheckInitialized()
    {
        if (!_initialized)
            throw new InvalidOperationException("Generator has not been initialized.");
    }

    private void LogGeneration()
    {
        // implement logging mechanism here
    }

    public override string ToString()
    {
        return $"CustomRandomGenerator: Min={_minValue}, Max={_maxValue}, Seed={_seed}";
    }

    public void Dispose()
    {
        Reset();
    }
}
