function updateClinicStatus($clinicId) {
    $db = db_connect();

    try {
        // Fetch current status and IP address before updating
        $currentStatus = get_current_status($db, $clinicId);
        $currentIp = get_current_ip_address($db, $clinicId);

        if (!$currentStatus || !$currentIp) {
            throw new Exception("Invalid clinic ID or data not found.");
        }

        // Get new status and IP address from input
        $newStatus = $_POST['status'];
        $newIp = $_SERVER['REMOTE_ADDR'];

        // Validate IP address
        if (!filter_var($newIp, FILTER_VALIDATE_IP)) {
            throw new Exception("Invalid IP address.");
        }

        // Update clinic status and last modified timestamp
        db_query("UPDATE clinics SET status = ?, last_modified_timestamp = NOW(), last_modified_ip_address = ? WHERE id = ?", array($newStatus, $newIp, $clinicId));
    } catch (Exception $e) {
        log_error($e->getMessage());
        http_response_code(500);
    } finally {
        // Close database connection
        db_close();
    }
}

function get_current_status($db, $clinicId) {
    return db_query("SELECT status FROM clinics WHERE id = ?", array($clinicId))->fetchColumn();
}

function get_current_ip_address($db, $clinicId) {
    return db_query("SELECT last_modified_ip_address FROM clinics WHERE id = ?", array($clinicId))->fetchColumn();
}

function db_connect() {
    // Establish database connection
    $db = new mysqli("host", "user", "password", "database");

    if ($db->connect_error) {
        throw new Exception("Database connection failed: " . $db->connect_error);
    }

    return $db;
}

function db_query($query, array $params) {
    // Execute database query with prepared statements and bindings
    $stmt = $this->db->prepare($query);
    $stmt->bind_param(str_repeat("s", count($params)), ...$params);
    $stmt->execute();

    return $stmt;
}

function db_close() {
    // Close database connection
    $this->db->close();
}
