import asyncio
import aiohttp
import json

async def fetch_and_process_data(api_urls, data_processor=None, timeout=5, max_concurrent_requests=5):
    async with aiohttp.ClientSession() as session:
        tasks = []

        for url in api_urls:
            task = asyncio.create_task(fetch_api(session, url, data_processor, timeout))
            tasks.append(task)

        results = await asyncio.gather(*tasks, return_exceptions=True)

        processed_data = []
        for result in results:
            if isinstance(result, dict):
                if data_processor:
                    try:
                        processed_data.append(data_processor(**result))
                    except Exception as e:
                        print(f"Error processing API response: {e}")
                else:
                    processed_data.append(result)
            else:
                print(f"Failed to fetch or process API response: {result}")

        return processed_data

async def fetch_api(session, url, data_processor=None, timeout=5):
    try:
        async with session.get(url) as response:
            if response.status == 200:
                return await response.json()
            else:
                print(f"API call failed: {response.status}")
                return None
    except aiohttp.ClientError as e:
        print(f"Failed to connect to API: {e}")
        return None
    except asyncio.TimeoutError:
        print(f"Timeout while fetching API data")
        return None

