@app.route('/render-pokemon-script-tags', methods=['GET'])
def render_pokemon_script_tags():
    pokemon_id = request.args.get('pokemon_id')

    pokemon_data = requests.get(f'https://pokeapi.co/api/v2/pokemon/{pokemon_id}/').json()
    weather_effects = requests.get(f'https://weather-api.com/weather-effects/').json()['data']
    terrain_effects = requests.get(f'https://terrain-effects-api.com/effects/').json()['data']

    weaknesses = []
    for type in pokemon_data['types']:
        if type['type']['name'] == 'normal':
            continue
        weaknesses.append(type['type']['name'])

    scripts = []
    for weather_effect in weather_effects:
        script = {
            'src': f'https://weather-api.com/weather-effects/{weather_effect}/'
        }
        if not any(script['src'].startswith('http') for script in scripts):
            script['async'] = True
        scripts.append({'script': script})

    for terrain_effect in terrain_effects:
        script = {
            'src': f'https://terrain-effects-api.com/effects/{terrain_effect}/'
        }
        if not any(script['src'].startswith('http') for script in scripts):
            script['async'] = True
        scripts.append({'script': script})

    html_string = f'''
    <footer>
        <script type="text/javascript">
            {',\n'.join(f'document.write("<script src="{script['src']}"></" + "script>");' for script in scripts)}
        </script>
        <h2>{pokemon_data['name']['english']}</h2>
        <p>Type: {", ".join(type['type']['name'] for type in pokemon_data['types'])}</p>
        <ul>
            <li>Weaknesses: {', '.join(weaknesses)}</li>
        </ul>
    </footer>
    '''

    return jsonify({'html': html_string})

if __name__ == '__main__':
    app.run(debug=True)
