using System;
using System.Xml.XPath;
using System.IO;
using System.Threading.Tasks;
using System.Collections.Concurrent;

public class XmlParser
{
    private readonly string _apiEndpoint;
    private readonly int _maxCacheSize;
    private readonly ConcurrentDictionary<string, XPathDocument> _cache;

    public XmlParser(string apiEndpoint, int maxCacheSize = 1000)
    {
        _apiEndpoint = apiEndpoint;
        _maxCacheSize = maxCacheSize;
        _cache = new ConcurrentDictionary<string, XPathDocument>();
    }

    public async Task<XPathNavigator> GetElementAsync(string documentName, string elementName)
    {
        if (string.IsNullOrEmpty(documentName))
            throw new ArgumentException("Document name is required", nameof(documentName));
        if (string.IsNullOrEmpty(elementName))
            throw new ArgumentException("Element name is required", nameof(elementName));

        XPathNavigator result = null;

        // Check cache first
        if (_cache.TryGetValue(documentName, out XPathDocument document))
        {
            try
            {
                result = document.CreateNavigator().SelectSingleNode($"//{elementName}");
            }
            catch (XPathException)
            {
                // Element not found or multiple elements found with the given name
                throw new XmlParserException("Element not found or multiple elements found", elementName, documentName);
            }
        }
        else
        {
            // Fetch XML from API and cache it
            string xml = await GetXmlFromApiAsync(documentName);

            if (xml == null)
                throw new XmlParserException("Failed to fetch XML from API", documentName);

            document = new XPathDocument(new StringReader(xml));
            _cache.AddOrUpdate(documentName, document, (key, old) =>
            {
                // Limit cache size
                return old;
            });

            try
            {
                result = document.CreateNavigator().SelectSingleNode($"//{elementName}");
            }
            catch (XPathException)
            {
                throw new XmlParserException("Element not found or multiple elements found", elementName, documentName);
            }
        }

        return result;
    }

    private async Task<string> GetXmlFromApiAsync(string documentName)
    {
        // Implement API call logic to fetch XML
        await Task.Delay(100); // Simulate network delay

        if (/* API request failed */)
            return null;

        // Return fetched XML
        return /* Fetched XML */;
    }
}

public class XmlParserException : Exception
{
    public string ElementName { get; }
    public string DocumentName { get; }

    public XmlParserException(string message, string elementName, string documentName) 
        : base(message)
    {
        ElementName = elementName;
        DocumentName = documentName;
    }
}
