namespace DynamicCryptoGenerator
{
    public class CryptoGenerator
    {
        private string _configPath;
        private Dictionary<string, ICryptoAlgorithm> _algorithms;
        private Dictionary<string, IRandomDistribution> _distributions;
        private object _lock = new object();
        private readonly ILogger _logger;

        public CryptoGenerator(string configPath, ILogger logger)
        {
            _configPath = configPath;
            _logger = logger;
            _algorithms = new Dictionary<string, ICryptoAlgorithm>();
            _distributions = new Dictionary<string, IRandomDistribution>();
        }

        public string GenerateRandomValue(int min, int max, string distributionName)
        {
            var distribution = _distributions[distributionName];
            return distribution.Next(min, max);
        }

        public void SetAlgorithm(string algorithmName)
        {
            lock (_lock)
            {
                if (!_algorithms.ContainsKey(algorithmName))
                    LoadAlgorithm(algorithmName);

                // Switch to the selected algorithm
                _logger.LogInformation($"Switched to {algorithmName} algorithm");
            }
        }

        private void LoadAlgorithm(string algorithmName)
        {
            var alg = OpenSSL.LoadAlgorithm(_configPath, algorithmName);
            if (alg == null)
                throw new Exception($"Error loading {algorithmName} algorithm");

            _algorithms.Add(algorithmName, alg);
        }

        public void SetDistribution(string distributionName)
        {
            lock (_lock)
            {
                if (!_distributions.ContainsKey(distributionName))
                    LoadDistribution(distributionName);

                // Switch to the selected distribution
                _logger.LogInformation($"Switched to {distributionName} distribution");
            }
        }

        private void LoadDistribution(string distributionName)
        {
            var distr = UnityEngine.Random.CreateDistribution(_configPath, distributionName);
            if (distr == null)
                throw new Exception($"Error loading {distributionName} distribution");

            _distributions.Add(distributionName, distr);
        }

        public override string ToString()
        {
            return $"Range: [{minValue}, {maxValue}) - Distribution: {CurrentDistribution.Name} - Algorithm: {CurrentAlgorithm}";
        }
    }
}
