```javascript
const express = require('express');
const app = express();
const mongoose = require('mongoose');
const jwt = require('jsonwebtoken');
const { Message } = require('./models/Message');
const { User } = require('./models/User');
const { PushNotification } = require('./services/PushNotification');
const { MessageRouter } = require('./services/MessageRouter');
const { UserAuth } = require('./services/UserAuth');

// Connect to MongoDB
mongoose.connect('mongodb://localhost/chat-app', { useNewUrlParser: true, useUnifiedTopology: true });

// Define the authentication middleware
app.use((req, res, next) => {
  const token = req.header('Authorization');
  if (!token) return res.status(401).send({ status: 'failure', message: 'Unauthorized' });
  jwt.verify(token, process.env.SECRET_KEY, (err, decoded) => {
    if (err) return res.status(401).send({ status: 'failure', message: 'Invalid token' });
    req.user = decoded;
    next();
  });
});

// Define the message processing middleware
app.post('/messages', async (req, res) => {
  const { username, password, message, recipient } = req.body;
  try {
    // Validate user authentication
    const user = await UserAuth.validateUser(username, password);
    if (!user) return res.status(401).send({ status: 'failure', message: 'Invalid credentials' });

    // Store the message securely
    const newMessage = new Message({ text: message, sender: username, recipient });
    await newMessage.save();

    // Route the message to the appropriate recipient(s)
    await MessageRouter.routeMessage(newMessage);

    // Trigger push notifications if necessary
    PushNotification.sendPushNotifications([newMessage]);

    return res.send({ status: 'success', message: 'Message sent successfully' });
  } catch (err) {
    console.error(err);
    return res.status(500).send({ status: 'failure', message: 'Internal Server Error' });
  }
});

// Start the server
const port = process.env.PORT || 3000;
app.listen(port, () => {
  console.log(`Server started on port ${port}`);
});
