```javascript
class MessageRouterService {
  async routeMessage(message) {
    // Route the message to the appropriate recipient(s)
    if (message.recipient === 'all') {
      await this.broadcastMessage(message);
    } else {
      await this.sendMessageToUser(message);
    }
  }

  async broadcastMessage(message) {
    // Send the message to all users
    const users = await User.find();
    for (const user of users) {
      await PushNotification.sendToUser(user.username, 'New message from ' + message.sender);
    }
  }

  async sendMessageToUser(message) {
    // Send the message to a single user
    await PushNotification.sendToUser(message.recipient, 'New message from ' + message.sender);
  }
}

module.exports = new MessageRouterService();
