// PHP function for password strength check

function passwordStrengthCheck($password) {
    if (strlen($password) < 8) {
        return false;
    }
    if (!preg_match('/[A-Z]/', $password)) {
        return false;
    }
    if (!preg_match('/[0-9]/', $password)) {
        return false;
    }
    if (!preg_match('/[^a-zA-Z0-9]/', $password)) {
        return false;
    }
    return true;
}

// C function to initialize AES-256-GCM cipher
#include <openssl/aes.h>
#include <openssl/pbkdf2.h>

void initAESCipher(const char* password, const char* salt, unsigned char** key) {
    PBKDF2_CTX ctx;
    PBKDF2_key(ctx, (const void*)password, strlen(password), (const void*)salt, strlen(salt), 32768);
    AES_GCM_KEYSET *aesKey = malloc(AES_GCM_KEYSET_SIZE);
    aesKey->key = malloc(32);
    aesKey->iv = malloc(12);
    PBKDF2_derive_key(&ctx, (void**)aesKey->key, 32, 1);
    *key = aesKey;
}

