import java.util.*;
import java.io.*;

public class DistributedCache {
    private Map<String, CacheEntry> cache = new HashMap<>();
    private Set<CacheNode> nodes = new HashSet<>();
    private Lock lock = new ReentrantLock();

    public void put(String key, String value) {
        try (Connection conn = DriverManager.getConnection("jdbc:postgresql://localhost:5432/postgres", "postgres", "password")) {
            PreparedStatement ps = conn.prepareStatement("INSERT INTO cache (key, value) VALUES (?, ?)");
            ps.setString(1, key);
            ps.setString(2, value);
            ps.execute();
        } catch (SQLException e) {
            throw new RuntimeException(e);
        }
    }

    public String get(String key) {
        return cache.getOrDefault(key, CacheEntry.UNKNOWN).getValue();
    }

    public void nodeJoin(CacheNode node) {
        lock.lock();
        try {
            nodes.add(node);
        } finally {
            lock.unlock();
        }
    }

    public void nodeLeave(CacheNode node) {
        lock.lock();
        try {
            nodes.remove(node);
        } finally {
            lock.unlock();
        }
    }

    private class CacheEntry {
        String value;
        long timestamp;
        boolean isValid;

        public CacheEntry(String value, long timestamp, boolean isValid) {
            this.value = value;
            this.timestamp = timestamp;
            this.isValid = isValid;
        }

        public static CacheEntry UNKNOWN = new CacheEntry(null, 0L, false);
    }
}

