    if not isinstance(order_id, int) or order_id <= 0:
        raise ValueError("Invalid order ID")
    if status not in ORDER_STATUS:
        raise ValueError("Invalid status")
    for product_id in product_ids:
        if not isinstance(product_id, int) or product_id <= 0:
            raise ValueError("Invalid product ID")

    # Initialize logger
    logging.basicConfig(filename='order_processing.log', level=logging.INFO)

    # Rate limiter to allow no more than 100 order updates per hour from the same customer
    @limits(calls=100, period=60)  # 100 calls in 1 minute
    def rate_limited_function():
        try:
            # Update order status and charge customer
            # ...

            return {'success': True, 'order_details': ..., 'error_message': None}
        except Exception as e:
            logging.error(f"Error processing order {order_id}: {str(e)}")
            return {'success': False, 'order_details': ..., 'error_message': str(e)}

    try:
        # Send email notifications to customer and store admin
        # ...

        response = rate_limited_function()
        return response
    except Exception as e:
        logging.error(f"Error processing order {order_id}: {str(e)}")
        return {'success': False, 'order_details': ..., 'error_message': str(e)}

# Cleanup old logs older than 90 days
def cleanup_logs():
    cutoff_date = datetime.now() - timedelta(days=90)
    for file in os.listdir('logs'):
        if file.endswith('.log') and file.split('_')[0] <= cutoff_date.strftime('%Y%m%d'):
            os.remove(os.path.join('logs', file))
