#include <random>
#include <iostream>
#include <string>
#include <sqlite3.h>

namespace ClimateSimulation {

class WeatherRandomGenerator {
public:
    WeatherRandomGenerator(int seedValue) : mt_(std::mt19937(seedValue)), 
                                            temperature_(std::uniform_real_distribution<>(-100.0, 100.0)),
                                            precipitation_(std::uniform_real_distribution<>(0.0, 100.0)),
                                            windSpeed_(std::uniform_real_distribution<>(0.0, 50.0)) {}

    ~WeatherRandomGenerator() = default;

    int generateTemperature() {
        return static_cast<int>(temperature_(mt_));
    }

    int generatePrecipitation() {
        return static_cast<int>(precipitation_(mt_));
    }

    double generateWindSpeed() {
        return windSpeed_(mt_);
    }

private:
    std::mt19937 mt_;
    std::uniform_real_distribution<> temperature_;
    std::uniform_real_distribution<> precipitation_;
    std::uniform_real_distribution<> windSpeed_;
};

WeatherRandomGenerator* createRandomGenerator(sqlite3* db) {
    // Fetch seed value from database
    int seedValue = 0;
    sqlite3_stmt* stmt;
    char* errMsg;
    sqlite3_prepare_v2(db, "SELECT seed_value FROM weather_seeds", -1, &stmt, NULL);
    sqlite3_step(stmt);
    sqlite3_column_text(stmt, 0);
    seedValue = atoi((char*)sqlite3_column_text(stmt, 0));
    sqlite3_finalize(stmt);

    // Create and return the random generator
    WeatherRandomGenerator* randomGenerator = new WeatherRandomGenerator(seedValue);
    return randomGenerator;
}

void configureWeatherDistribution(sqlite3* db, WeatherRandomGenerator* randomGenerator) {
    // Fetch temperature range from database
    double minTemperature = 0.0, maxTemperature = 100.0;
    sqlite3_stmt* stmt;
    char* errMsg;
    sqlite3_prepare_v2(db, "SELECT min_temp, max_temp FROM weather_ranges WHERE attribute='temperature'", -1, &stmt, NULL);
    sqlite3_step(stmt);
    minTemperature = sqlite3_column_double(stmt, 0);
    maxTemperature = sqlite3_column_double(stmt, 1);
    sqlite3_finalize(stmt);

    // Configure temperature distribution
    randomGenerator->temperature_ = std::uniform_real_distribution<>(minTemperature, maxTemperature);

    // Fetch precipitation range from database
    double minPrecipitation = 0.0, maxPrecipitation = 100.0;
    sqlite3_prepare_v2(db, "SELECT min_precipitation, max_precipitation FROM weather_ranges WHERE attribute='precipitation'", -1, &stmt, NULL);
    sqlite3_step(stmt);
    minPrecipitation = sqlite3_column_double(stmt, 0);
    maxPrecipitation = sqlite3_column_double(stmt, 1);
    sqlite3_finalize(stmt);

    // Configure precipitation distribution
    randomGenerator->precipitation_ = std::uniform_real_distribution<>(minPrecipitation, maxPrecipitation);

    // Fetch wind speed range from database
    double minWindSpeed = 0.0, maxWindSpeed = 50.0;
    sqlite3_prepare_v2(db, "SELECT min_wind_speed, max_wind_speed FROM weather_ranges WHERE attribute='wind_speed'", -1, &stmt, NULL);
    sqlite3_step(stmt);
    minWindSpeed = sqlite3_column_double(stmt, 0);
    maxWindSpeed = sqlite3_column_double(stmt, 1);
    sqlite3_finalize(stmt);

    // Configure wind speed distribution
    randomGenerator->windSpeed_ = std::uniform_real_distribution<>(minWindSpeed, maxWindSpeed);
}

