use std::collections::HashMap;
use std::env;
use std::fs::create_dir_all;
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};
use serde::Deserialize;
use log::{info, error};

const MAX_RETRY_ATTEMPTS: u32 = 5;

struct Config {
    max_retry_attempts: u32,
    backoff_intervals: Vec<u64>,
}

impl Deserialize for Config {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: serde::Deserializer<'de>,
    {
        let config = HashMap::<String, String>::deserialize(deserializer)?;
        let max_retry_attempts = config.remove("max_retry_attempts").parse().unwrap_or(MAX_RETRY_ATTEMPTS);
        let backoff_intervals = config.remove("backoff_intervals").split(',').map(|s| s.parse().unwrap()).collect();
        Ok(Config { max_retry_attempts, backoff_intervals })
    }
}

fn create_directory(directory_name: &str) -> Result<(), std::io::Error> {
    // implement your directory creation logic here
    info!("Creating directory: {}", directory_name);
    // ...
}

async fn retry_operation<F>(f: F, retries: u32, intervals: Vec<u64>)
where
    F: Fn() -> Result<(), std::io::Error>,
{
    for i in 0..retries {
        if let Err(_) = f().await {
            info!("Operation failed. Retrying in {} seconds...", intervals[i]);
            tokio::time::sleep(std::time::Duration::from_millis(intervals[i])).await;
        } else {
            return Ok(());
        }
    }
    Err(std::io::Error::new(std::io::ErrorKind::Other, "Max retries exceeded"))
}

async fn create_directory_with_lock(directory_name: &str, config: &Config) -> Result<(), std::io::Error> {
    let lock = Arc::new(Mutex::new(false));
    if *lock.lock().await {
        return Err(std::io::Error::new(std::io::ErrorKind::Other, "Directory already exists"));
    }

    loop {
        match create_directory(directory_name) {
            Ok(()) => break,
            Err(e) => {
                info!("Failed to create directory: {}", e);
                if config.max_retry_attempts <= 1 {
                    error!("Max retries exceeded. Giving up.");
                    return Err(e);
                }
                let backoff_interval = &config.backoff_intervals[0];
                tokio::time::sleep(std::time::Duration::from_millis(*backoff_interval)).await;
            }
        }
    }

    *lock.lock().await = true;
    info!("Directory created successfully: {}", directory_name);
    Ok(())
}

fn main() {
    let config = Config::deserialize(include_yaml!("config.yaml")).unwrap();
    let directory_name = env::var("DIRECTORY_NAME").expect("EXPECTED DIRECTORY_NAME environment variable");
    if let Err(e) = create_directory_with_lock(&directory_name, &config) {
        error!("Failed to create directory: {}", e);
    } else {
        info!("Directory creation succeeded.");
    }
}
