using System.Threading.Tasks;

namespace CloudStorageEncryptionModule
{
    public class EncryptionModule
    {
        private readonly Aes _aes;
        private readonly byte[] _key;
        private readonly byte[] _iv;

        public EncryptionModule(Aes aes, byte[] key, byte[] iv)
        {
            _aes = aes;
            _key = key;
            _iv = iv;
        }

        public async Task<byte[]> DecryptFileAsync(byte[] fileBytes)
        {
            using (MemoryStream ms = new MemoryStream())
            {
                using (CryptoStream cs = new CryptoStream(ms, _aes.CreateDecryptor(_key, _iv), CryptoStreamMode.Write))
                {
                    cs.Write(fileBytes, 0, fileBytes.Length);
                    cs.FlushFinalBlock();
                }
                return ms.ToArray();
            }
        }

        public async Task<byte[]> EncryptFileAsync(byte[] fileBytes)
        {
            using (MemoryStream ms = new MemoryStream())
            {
                using (CryptoStream cs = new CryptoStream(ms, _aes.CreateEncryptor(_key, _iv), CryptoStreamMode.Write))
                {
                    cs.Write(fileBytes, 0, fileBytes.Length);
                    cs.FlushFinalBlock();
                }
                return ms.ToArray();
            }
        }

        public void Dispose()
        {
            _aes.Dispose();
        }
    }
}
