using System;
using System.Xml.XPath;

public class Program
{
    public static XPathNodeIterator FindElement(string xmlFile, string elementName)
    {
        try
        {
            XPathDocument doc = new XPathDocument(xmlFile);
            XPathNavigator nav = doc.CreateNavigator();
            XPathExpression expr = nav.Compile("/" + elementName);
            return nav.Select(expr);
        }
        catch (Exception ex)
        {
            throw new Exception("Failed to find the specified XML element", ex);
        }
    }

    public static string TruncateString(string s, int sizeLimit)
    {
        if (s.Length > sizeLimit)
            return s.Substring(0, sizeLimit) + "/";
        else
            return s;
    }
}

public class Program
{
    public static string CalculateFileMd5(string file_path, int chunk_size = 8192, Func<int> progress_callback = null, IStorageBackend storage_backend = null)
    {
        try
        {
            using (FileStream fs = File.OpenRead(file_path))
            {
                MD5CryptoServiceProvider md5 = new MD5CryptoServiceProvider();
                byte[] buffer = new byte[chunk_size];
                int totalBytes = 0;
                int bytesRead;

                Parallel.ForEach(Enumerable.Range(0, (int)Math.Ceiling((double)fs.Length / chunk_size)), i =>
                {
                    try
                    {
                        fs.Position = i * chunk_size;
                        bytesRead = fs.Read(buffer, 0, chunk_size);
                        totalBytes += bytesRead;
                        if (progress_callback != null)
                            progress_callback((int)(totalBytes * 100.0 / fs.Length));

                        md5.TransformBlock(buffer, 0, bytesRead);
                    }
                    catch (Exception ex)
                    {
                        // Handle the exception and prevent parallel loop from being terminated
                    }
                });

                fs.Close();

                byte[] result = md5.Hash;
                return BitConverter.ToString(result).Replace("-", string.Empty).ToLower();
            }
        }
        catch (FileNotFoundException e)
        {
            throw new FileNotFoundException("The file does not exist", e);
        }
        catch (UnauthorizedAccessException e)
        {
            throw new UnauthorizedAccessException("Access to the file is denied", e);
        }
        catch (IOException e)
        {
            throw new IOException("An I/O error occurred while reading the file", e);
        }
    }
}

public interface IStorageBackend
{
    void StoreHash(string hashValue);
}
