            self.session = await aiohttp.ClientSession().create()

        try:
            async with self.session.get(
                f"https://api.your-financial-api.com/v1/stock/{symbol}/realtime",
                headers={"Authorization": f"Bearer {self.api_key}"},
                timeout=10,
            ) as response:
                if response.status == 200:
                    return await response.json()
                else:
                    print(f"Failed to fetch data for {symbol}: {response.status}")
        except Exception as e:
            print(f"Error fetching data: {e}")

