    public static void filterCsv(String file_path, String filter_condition, String output_path) {
        try (BufferedReader reader = new BufferedReader(new FileReader(file_path))) {
            List<String[]> rows = reader.lines()
                    .map(line -> line.split(","))
                    .collect(Collectors.toList());

            boolean[] includedRows = rows.parallelStream()
                    .map(row -> evaluateFilterCondition(filter_condition, row))
                    .mapToBoolean(i -> i)
                    .toArray(boolean[]::new);

            try (BufferedWriter writer = Files.newBufferedWriter(Paths.get(output_path))) {
                for (int i = 0; i < rows.size(); i++) {
                    if (includedRows[i]) {
                        Arrays.stream(rows.get(i)).forEachOrdered(value -> writer.write(value + ","));
                        writer.newLine();
