from flask import Flask, request, jsonify
import os
import logging
import psycopg2
from psycopg2.extras import RealDictCursor
from envparse import env
from lib_payment_gateway import validate_key, make_request
from lib_pokemon import get_type, get_weaknesses

app = Flask(__name__)
logging.basicConfig(filename=os.environ['LOG_FILE_PATH'], level=logging.INFO)

def processPaymentTransaction(transaction_id, new_status, customer_id, payment_gateway_api_key):
    with psycopg2.connect(
        host='localhost',
        database='finance',
        user='finance_user',
        password=os.environ['DB_PASSWORD'],
        cursor_factory=RealDictCursor
    ) as conn:
        with conn.cursor() as cur:
            try:
                if not validate_key(payment_gateway_api_key):
                    logging.error('Invalid payment gateway API key')
                    return jsonify({'error': 'Invalid API key'}), 400

                query = """
                    UPDATE transactions 
                    SET status = %s 
                    WHERE id = %s AND customer_id = %s;
                """
                cur.execute(query, (new_status, transaction_id, customer_id))

                log_query = """
                    INSERT INTO logs 
                    VALUES (%s, %s, %s);
                """
                cur.execute(log_query, (transaction_id, new_status, 'Updated'))

            except psycopg2.Error as e:
                logging.error('Database error: {}'.format(e))
                return jsonify({'error': 'Database error'}), 500

    try:
        response = make_request(payment_gateway_api_key, request.method, request.get_json())
        if response.status_code == 200:
            logging.info('Payment gateway API call successful')
        else:
            logging.error('Payment gateway API call failed: {}'.format(response.text))
            return jsonify({'error': 'API call failed'}), 500
    except Exception as e:
        logging.error('Error processing payment transaction: {}'.format(e))
        return jsonify({'error': 'Internal error'}), 500

def getPokemonWeaknesses(pokemon):
    type = get_type(pokemon)
    weaknesses = {
        'fire': ['water', 'rock'],
        'grass': ['fire', 'bug'],
        # ... add more cases as needed
    }
    return ', '.join(weaknesses.get(type, ['None']))

@app.route('/process-payment', methods=['POST'])
def process_payment():
    transaction_id = request.json['transaction_id']
    new_status = request.json['new_status']
    customer_id = request.json['customer_id']
    payment_gateway_api_key = os.environ['PAYMENT_GATEWAY_API_KEY']

    return processPaymentTransaction(transaction_id, new_status, customer_id, payment_gateway_api_key)

@app.route('/pokemon-weaknesses', methods=['GET'])
def pokemon_weaknesses():
    pokemon_name = request.args.get('name')
    pokemon_type = get_type(Pokemon(pokemon_name))
    weaknesses = getPokemonWeaknesses(pokemon_type)
    return jsonify({'weaknesses': weaknesses})

if __name__ == '__main__':
