import java.io.IOException;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.Duration;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.CompletableFuture;

public class RemoteAPIFetcher {
    private final HttpClient client;
    private final Map<String, String> headers;
    private final Map<String, String> queryParameters;
    private final CacheManager cacheManager;
    private final RateLimiter rateLimiter;
    private final UIUpdater uiUpdater;

    public RemoteAPIFetcher(HttpClient client, Map<String, String> headers,
                             Map<String, String> queryParameters, CacheManager cacheManager,
                             RateLimiter rateLimiter, UIUpdater uiUpdater) {
        this.client = client;
        this.headers = headers;
        this.queryParameters = queryParameters;
        this.cacheManager = cacheManager;
        this.rateLimiter = rateLimiter;
        this.uiUpdater = uiUpdater;
    }

    public void fetchAndUpdateUI(String url) {
        CompletableFuture<HttpResponse<String>> responseFuture = sendRequest(url);
        responseFuture.thenAccept(this::handleResponse)
                .exceptionally(throwable -> handleException(throwable));
    }

    private CompletableFuture<HttpResponse<String>> sendRequest(String url) {
        HttpRequest request = HttpRequest.newBuilder()
                .uri(new URI(url))
                .headers(headers)
                .queryParameters(queryParameters)
                .GET()
                .build();
        return client.sendAsync(request, HttpResponse.BodyHandlers.ofString());
    }

    private void handleResponse(HttpResponse<String> response) {
        String responseBody = response.body();
        // Update UI based on the response
        uiUpdater.updateUI(responseBody);
    }

    private void handleException(Throwable throwable) {
        // Handle errors and exceptions
        if (throwable instanceof IOException || throwable instanceof InterruptedException) {
            // Network error or timeout
            logError("Network error: " + throwable.getMessage());
        } else if (throwable instanceof HttpResponseException) {
            // API error
            HttpResponseException exception = (HttpResponseException) throwable;
            int statusCode = exception.statusCode();
            String errorMessage = exception.body();
            logError("API error: Status code " + statusCode + ", Message: " + errorMessage);
        } else {
            // Data parsing issue or unexpected error
            logError("Unexpected error: " + throwable.getMessage());
        }
    }

    private void logError(String message) {
        // Log the error using a logging framework (e.g., Log4j, Java Util Logging)
    }
}

