#include <openssl/ssl.h>
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    SSL_CTX *ctx;
} CipherData;

CipherData* create_cipher(const char* command) {
    CipherData* data = (CipherData*)malloc(sizeof(CipherData));

    if(command != NULL && strcmp(command, "encrypt") == 0) {
        SSL_library_init();
        data->ctx = SSL_CTX_new(TLS_client);
    } else if(command != NULL && strcmp(command, "decrypt") == 0) {
        SSL_library_init();
        data->ctx = SSL_CTX_new(TLS_server);
    } else {
        printf("Invalid command\n");
        free(data);
        return NULL;
    }

    return data;
}
