function updateClinicStatus($clinic_id, $new_status, $last_modified_ip, $is_delete) {
    // Initialize Redis client for rate limiting
    $redis = new Redis();
    $redis->connect('localhost');

    // Set rate limit (5 updates per minute)
    $rate_limit = 5;
    $time_window = 60; // seconds

    // Check if IP is within allowed update frequency
    $ip_updates = $redis->hget($last_modified_ip, 'updates');
    if ($ip_updates === null) {
        $ip_updates = 0;
    }
    $redis_time = $redis->time();
    $window_start = $redis_time[0] - (int) ($time_window / 60);
    if ($ip_updates >= $rate_limit || $redis_time[1] < $window_start * 1000 + $time_window * 1000) {
        return 'Rate limit exceeded. Please try again after a few minutes.';
    }

    // Start distributed transaction
    $db = new PDO('mysql:host=localhost;dbname=clinics', 'root', '');
    $db->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
    $transaction = $db->beginTransaction();

    try {
        // Prepare update statement
        $stmt = $db->prepare("UPDATE clinics SET status = :new_status, last_modified_date = NOW(), last_modified_ip = :last_modified_ip " .
            ($is_delete ? ", deleted_at = NOW()" : '') . " WHERE clinic_id = :clinic_id");

        // Bind parameters and execute update
        $stmt->bindParam(':new_status', $new_status);
        $stmt->bindParam(':last_modified_ip', $last_modified_ip);
        $stmt->bindParam(':clinic_id', $clinic_id);

        if ($is_delete) {
            $stmt->execute();
        } else {
            $stmt->execute();
        }

        // Log success or error to ELK Stack
        $log_level = $is_delete ? 'warning' : 'info';
        $log_message = $is_delete ? "Clinic #$clinic_id soft-deleted." : "Clinic #$clinic_id status updated.";
        $log_data = json_encode(['error' => null, 'message' => $log_message]);
        $elasticsearch = new Elasticsearch();
        $elasticsearch->index('logs', ['level' => $log_level, 'data' => $log_data]);

        // Commit transaction
        $transaction->commit();

        return 'Update successful.';
    } catch (PDOException $e) {
        // Rollback transaction on failure
        $transaction->rollBack();
        $error_message = 'Error updating clinic: ' . $e->getMessage() . '. Clinic status may be inconsistent.';
        $log_level = 'error';
        $log_data = json_encode(['error' => $e, 'message' => $error_message]);
        $elasticsearch->index('logs', ['level' => $log_level, 'data' => $log_data]);

        return 'Update failed: ' . $error_message;
    } finally {
        // Release Redis client
        $redis->disconnect();
    }
}
