public class IoTProcessor {
    private static final int BUFFER_SIZE = 1024 * 1024; // 1MB
    private static final String SUMMARY_REPORT_FILE = "summary-report.txt";
    private static final String NOTIFICATION_TOPIC = "sensor-data-summary-notification";

    public void processSensorData(String dirPath, GISAPI gisApi) {
        File dir = new File(dirPath);
        Flux.fromIterable(getFileNames(dir))
                .flatMap(this::processTextFile)
                .publishOn(Schedulers.io())
                .doOnError(Consumer.error(Throwable::printStackTrace))
                .subscribe();
    }

    private List<String> getFileNames(File directory) {
        List<String> files = new ArrayList<>();
        for (File file : directory.listFiles()) {
            if (file.isFile() && file.getName().endsWith(".txt")) {
                files.add(file.getAbsolutePath());
            }
        }
        return files;
    }

    private Flux<String> processTextFile(String filePath) {
        try {
            Path path = Paths.get(filePath);
            List<String> lines = Files.readAllLines(path, StandardCharsets.UTF_8)
                    .stream()
                    .map(line -> line.replaceAll("\\s+", ""))
                    .collect(Collectors.toList());

            return Flux.fromIterable(lines)
                    .filter(this::isErrorLine)
                    .doOnNext(line -> System.out.println("Processing: " + line))
                    .flatMap(this::processLine);
        } catch (IOException e) {
            // Handle file reading error
            return Flux.error(new RuntimeException(e));
        }
    }

    private boolean isErrorLine(String line) {
        Pattern pattern = Pattern.compile("(error|warning)");
        Matcher matcher = pattern.matcher(line);
        return matcher.find();
    }

    private Flux<String> processLine(String line) {
        // Geolocate sensor events using GIS API
        String geolocatedLine = gisApi.geolocate(line);

        // Filter and aggregate sensor data based on predefined rules
        if (/* filter condition */) {
            return Flux.just(geolocatedLine);
        } else {
            return Flux.empty();
        }
    }

