```java
import java.util.HashMap;
import java.util.Map;

public class DistributedCacheService {

    private Map<String, String> cacheMap = new HashMap<>();
    private RedisClient redisClient;
    private MemcachedClient memcachedClient;
    private int cacheSize;
    private long timeout;

    public DistributedCacheService(RedisClient redisClient, MemcachedClient memcachedClient) {
        this.redisClient = redisClient;
        this.memcachedClient = memcachedClient;
        this.cacheSize = 10000; // initial cache size
        this.timeout = 300000; // initial timeout in milliseconds
    }

    public void put(String key, String value) {
        if (cacheMap.size() >= cacheSize) {
            // resize cache map based on cache hits and misses
            cacheMap = new HashMap<>();
        }
        cacheMap.put(key, value);
        // serialize data to disk for persistence across application restarts
    }

    public String get(String key) {
        return cacheMap.getOrDefault(key, null);
    }

    public void update(String key, String value) {
        put(key, value);
    }

    public boolean containsKey(String key) {
        return cacheMap.containsKey(key);
    }
}
