    int num_databases;
    char **database_addresses;
    char **database_usernames;
    char **database_passwords;
    int *database_port_numbers;
} Config;

// Database connection structure
typedef struct {
    char *address;
    char *username;
    char *password;
    int port_number;
    // Other database-specific fields (e.g., timeout)
} DatabaseConnection;

// Thread-safe data aggregation service
void* aggregate_data(void* config) {
    Config* c = (Config*)config;
    // Initialize databases and connections
    DatabaseConnection** databases = (DatabaseConnection**)malloc(c->num_databases * sizeof(DatabaseConnection*));
    for (int i = 0; i < c->num_databases; i++) {
        databases[i] = (DatabaseConnection*)malloc(sizeof(DatabaseConnection));
        strcpy(databases[i]->address, c->database_addresses[i]);
        strcpy(databases[i]->username, c->database_usernames[i]);
        strcpy(databases[i]->password, c->database_passwords[i]);
        databases[i]->port_number = c->database_port_numbers[i];
    }

    // Process data from multiple sources
    pthread_t threads[c->num_databases];
    for (int i = 0; i < c->num_databases; i++) {
        pthread_create(&threads[i], NULL, process_data, databases[i]);
    }
    for (int i = 0; i < c->num_databases; i++) {
        pthread_join(threads[i], NULL);
    }

    // Store data in databases
    for (int i = 0; i < c->num_databases; i++) {
        store_data(databases[i]);
    }

    // Free resources
    for (int i = 0; i < c->num_databases; i++) {
        free(databases[i]);
    }
    free(databases);
}

