typedef struct {
    // Define your structure here
} NFAPI_CRC_INDICATION_PDU_T;

int populateNfarCrcIndications(NFAPI_CRC_INDICATION_PDU_T **crcList, size_t *listSize, int maxStructures, const char *logFilePath) {
    int errCode = 0;
    FILE *logFile = NULL;

    // Initialize the logging system
    if (logFilePath != NULL) {
        logFile = fopen(logFilePath, "a");
        if (logFile == NULL) {
            errCode = -1;
            fprintf(stderr, "Error opening log file: %s\n", logFilePath);
        }
    }

    // Initialize the random number generator
    srand(time(NULL));

    *listSize = 0;

    // Populate the list of NFAPI_CRC_INDICATION_PDU_T structures
    for (int i = 0; i < maxStructures && errCode == 0; i++) {
        NFAPI_CRC_INDICATION_PDU_T *structPtr = NULL;
        size_t structSize = sizeof(NFAPI_CRC_INDICATION_PDU_T);

        // Check if there is enough memory available to allocate a new structure
        if (*listSize >= maxStructures) {
            errCode = -1;
            fprintf(logFile, "Error: Insufficient memory for allocating structures\n");
        } else {
            structPtr = (NFAPI_CRC_INDICATION_PDU_T *)malloc(structSize);
            if (structPtr == NULL) {
                errCode = -1;
                fprintf(logFile, "Error: Memory allocation failed for structure %d\n", i);
            } else {
                // Initialize the structure with random values
                structPtr->RX_UE_INFORMATION_TAG = rand();
                structPtr->RNTI = rand();

                if (structPtr->RX_UE_INFORMATION_TAG == structPtr->RNTI) {
                    free(structPtr);
                    errCode = -1;
                    fprintf(logFile, "Error: Duplicate RX_UE_INFORMATION_TAG and RNTI values in structure %d\n", i);
                } else {
                    // Append the new structure to the list
                    *crcList = (NFAPI_CRC_INDICATION_PDU_T **)realloc(*crcList, (*listSize + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
                    if (*crcList == NULL) {
                        errCode = -1;
                        fprintf(logFile, "Error: Memory allocation failed for structure %d\n", i);
                    } else {
                        (*crcList)[*listSize] = structPtr;
                        (*listSize)++;
                    }
                }
            }
        }
    }

    // Close the log file
    if (logFile != NULL) {
        fclose(logFile);
    }

    return errCode;
}
