using System;
using System.Threading;

namespace AdvancedRandomGenerator
{
    public enum DistributionType { Uniform, Normal, Exponential }

    public class AdvancedRandomGenerator
    {
        private Random _random;
        private int? _minValue;
        private int? _maxValue;
        private double? _meanValue;
        private double? _lambdaValue;
        private DistributionType _distributionType;
        private bool _isSeedSet;

        public AdvancedRandomGenerator()
        {
            Reset();
        }

        public void SetSeed(int seed)
        {
            if (_random == null || !_isSeedSet) _random = new Random(seed);
            else
            {
                _random = new Random();
                _random.Next(0, 10000); // Reset to the same seed
            }
            _isSeedSet = true;
        }

        public int? MinValue { get => _minValue; set => _minValue = value; }
        public int? MaxValue { get => _maxValue; set => _maxValue = value; }
        public double? MeanValue { get => _meanValue; set => _meanValue = value; }
        public double? LambdaValue { get => _lambdaValue; set => _lambdaValue = value; }
        public DistributionType DistributionType { get => _distributionType; set => _distributionType = value; }

        public void Reset()
        {
            _random = new Random();
            _isSeedSet = false;
            MinValue = null;
            MaxValue = null;
            MeanValue = null;
            LambdaValue = null;
            DistributionType = DistributionType.Uniform;
        }

        public int NextInt(int min, int max)
        {
            if (!ValidateRange(min, max))
                throw new ArgumentException("Invalid range. Must be a valid integer range.", nameof(max));

            return _random.Next(min, max + 1);
        }

        public double NextDouble(double min, double max)
        {
            if (!ValidateRange(min, max))
                throw new ArgumentException("Invalid range. Must be a valid floating-point range.", nameof(max));

            return _random.NextDouble(min, max);
        }

        public int[] GenerateIntSequence(int count, int min = 0, int max = int.MaxValue)
        {
            var result = new int[count];
            for (int i = 0; i < count; i++)
                result[i] = NextInt(min, max);

            return result;
        }

        public double[] GenerateDoubleSequence(int count, double min = 0.0, double max = 1.0)
        {
            var result = new double[count];
            for (int i = 0; i < count; i++)
                result[i] = NextDouble(min, max);

            return result;
        }

        public void LogRandomGeneration()
        {
            // Implement logging mechanism here
        }
    }
}
