#include <iostream>

class Database {
public:
    void store(const std::forward_list<std::string>& list) {
        // implementation details omitted for brevity
    }
};

void insertAfterSearch(std::forward_list<std::string>& list, const std::string& search, const std::string& insertion, int maxInsertions, Database& db) {
    size_t pos = 0;
    while (pos != std::distance(list.begin(), list.end()) && maxInsertions--) {
        if (list[pos].find(search) != std::string::npos) {
            list.insert_after(list.before_begin() + pos, insertion);
            return; // search found, break loop
        }
        pos++;
    }
    if (pos == 0) {
        list.push_front(insertion); // no match, insert at the beginning
    } else {
        list.push_back(insertion); // no match, insert at the end
    }

    // truncate strings to 100 characters and store in database
    for (auto& str : list) {
        if (str.length() > 100) {
            str = str.substr(0, 99);
        }
    }
    db.store(list);

    // handle exceptions
    try {
        // further processing or logging
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }
}
