// Cipher modes: ECB, EDE, EDE3, CFB

typedef enum {
    CBC_MODE_ECB,
    CBC_MODE_EDE,
    CBC_MODE_EDE3,
    CBC_MODE_CFB
} CipherMode;

CipherMode get_cipher_mode(int argc, char *argv[]) {
    if (argc < 2) {
        // Default mode: ECB
        return CBC_MODE_ECB;
    }

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-mode") == 0 || strcmp(argv[i], "--cipher-mode") == 0) {
            if (i + 1 >= argc) {
                // Invalid mode
                LOG_ERROR("Invalid cipher mode");
                return CBC_MODE_ECB;
            }

            if (strcmp(argv[i + 1], "ECB") == 0) {
                return CBC_MODE_ECB;
            } else if (strcmp(argv[i + 1], "EDE") == 0 || strcmp(argv[i + 1], "ede") == 0) {
                return CBC_MODE_EDE;
            } else if (strcmp(argv[i + 1], "EDE3") == 0 || strcmp(argv[i + 1], "ede3") == 0) {
                return CBC_MODE_EDE3;
            } else if (strcmp(argv[i + 1], "CFB") == 0 || strcmp(argv[i + 1], "cfb") == 0) {
                return CBC_MODE_CFB;
            }

            // Invalid mode
            LOG_ERROR("Invalid cipher mode");
            return CBC_MODE_ECB;
        }
    }

    // Default mode: ECB
    return CBC_MODE_ECB;
}

