#include <string>
#include <vector>

int convertImagesToPdf(const std::string& inputDir, const std::vector<std::string>& imageFiles, const std::string& outputDir) {
    int successfulConversions = 0;

    for (const auto& file : imageFiles) {
        if (!std::filesystem::is_regular_file(inputDir + "/" + file)) {
            continue;
        }

        try {
            // Load the image
            cv::Mat image = cv::imread(inputDir + "/" + file);

            // Resize the image to a specified width (if desired)
            int width = 1024; // Change this value as needed
            cv::resize(image, image, cv::Size(width, cv::round(static_cast<double>(image.rows) / image.cols * width)));

            // Convert the image to PDF
            std::string pdfFile = outputDir + "/" + file.substr(0, file.find('.')) + ".pdf";
            cv::imwrite(pdfFile, image);

            successfulConversions++;
        } catch (const cv::Exception& e) {
            // Log any conversion errors
            std::cerr << "Error converting " << file << ": " << e.what() << std::endl;
        }
    }

    return successfulConversions;
}
