// Import required libraries
import express from 'express';
import { Cache } from './cache';
import { SocialMediaAPI } from './socialmedia';
import { UserDatabase } from './database';

// Create the Express app
const app = express();

// Define the profile update function
app.patch('/users/:id', (req, res) => {
  const userId = req.params.id;
  const userData = req.body;

  // Check if the user exists in the database
  UserDatabase.getUser(userId)
    .then((user) => {
      // Update the user's profile with the provided data
      Object.assign(user, userData);

      // Cache the updated user profile
      Cache.set(`user:${userId}`, user);

      res.json({ message: 'Profile updated successfully' });
    })
    .catch((error) => {
      if (error.name === 'NotFoundError') {
        res.status(404).send({ error: 'User not found' });
      } else {
        res.status(500).send({ error: 'Internal Server Error' });
      }
    });
});

// Define the social media profile synchronization function
app.post('/users/:id/socialmedia', (req, res) => {
  const userId = req.params.id;
  const userData = req.body;

  // Check if the user exists in the cache
  Cache.get(`user:${userId}`)
    .then((cachedUser) => {
      // Update the user's profile on social media platform
      SocialMediaAPI.updateProfile(userId, userData)
        .then((response) => {
          res.json({
            message: 'Social media profile updated successfully',
            metadata: response.data,
          });
        })
        .catch((error) => {
          if (error.name === 'NetworkError') {
            res.status(503).send({ error: 'Network error' });
          } else {
            res.status(500).send({ error: 'Internal Server Error' });
          }
        });
    })
    .catch((error) => {
      if (error.name === 'NotFoundError') {
        res.status(404).send({ error: 'User not found in cache' });
      } else {
        res.status(500).send({ error: 'Internal Server Error' });
      }
    });
});

// Define the social media profile retrieval function
