import heapq
import logging
import threading
from collections import deque

class SortedMerge:
    def __init__(self, threshold=1000000):
        self.threshold = threshold
        self.lock = threading.Lock()
        self.log = logging.getLogger('SortedMerge')

    def _get_next_elements(self, generators):
        with self.lock:
            next_elements = [(next(gen), gen) for gen in generators if (next(gen) is not None)]
            return heapq.nsmallest(len(next_elements), next_elements)

    def _buffer_elements(self, elements):
        buffer = deque(elements)
        while len(buffer) > self.threshold // 2 and len(buffer) < self.threshold:
            yield buffer.popleft()
        while buffer:
            yield buffer.popleft()

    def merge_sorted_lists(self, *generators):
        try:
            if not generators:
                return []
            merged_list = []
            next_elements = self._get_next_elements(generators)
            with self.lock:
                for element in sorted(next_elements):
                    merged_list.append(element[0])
                    yield from self._buffer_elements(generators)
                    next_elements = self._get_next_elements(generators)
        except Exception as e:
            self.log.error(f'Error during merging: {e}')
            raise

    def _resume_from_last_state(self, *generators):
        try:
            last_merged_list = list(merged_list)
            for element in generators:
                yield from self._buffer_elements(element)
        except Exception as e:
            self.log.error(f'Error during resuming: {e}')
            raise
