            }
        }
    }

    public async Task<string> CalculateSha256HashAsync(string filePath)
    {
        using (var stream = new FileStream(filePath, FileMode.Open))
        {
            using (var sha256 = SHA256.Create())
            {
                var hashBytes = new byte[64];
                var bytesRead = 0;
                while ((bytesRead = await stream.ReadAsync(hashBytes, 0, 64)) > 0)
                {
                    await sha256.ComputeHashAsync(stream);
                }

                return Convert.ToBase64String(sha256.Hash);
            }
        }
    }
