#include <string.h>

int append_slash_if_necessary(char *str, int size_limit) {
    if (strlen(str) <= size_limit) {
        char *new_str = malloc(strlen(str) + 2);
        strcpy(new_str, str);
        free(str);
        str = new_str;
        strcat(str, "/");
    }
    return strlen(str);
}
