    private ApplicationContext applicationContext;

    @PostMapping("/processTransaction")
    public ResponseEntity<TransactionStatus> processTransaction(@RequestBody TransactionRequest request) {
        // Validate transaction request
        if (!validateRequest(request)) {
            return ResponseEntity.badRequest().body(new TransactionStatus(TransactionStatus.Status.INVALID));
        }

        // Get gateway configuration from cache or load from properties file if not cached
        Map<String, String> gatewayConfig = gatewayConfigCache.getIfPresent(getGatewayName(request));
        if (gatewayConfig == null) {
            gatewayConfig = loadGatewayConfigFromProperties();
            gatewayConfigCache.put(getGatewayName(request), gatewayConfig);
        }

        // Process transaction with chosen gateway
        try {
            return processTransactionWithGateway(gatewayConfig, request);
        } catch (Exception e) {
            // Retry failed transactions with exponential backoff and jitter
            int retryCount = 0;
            while (retryCount < 3) {
                try {
                    return processTransactionWithGateway(gatewayConfig, request);
                } catch (Exception e2) {
                    if (e2 instanceof GatewayTimeoutException || e2 instanceof TransactionRollbackException) {
                        // Handle transaction rollback and provide real-time updates
                        return ResponseEntity.badRequest().body(new TransactionStatus(TransactionStatus.Status.ROLLBACK));
                    }
                    // Exponential backoff with jitter
                    int delay = (int) Math.pow(2, retryCount) * 1000;
                    Thread.sleep(delay + new Random().nextInt(delay / 10));
                    retryCount++;
                }
            }
            return ResponseEntity.status(HttpStatus.SERVICE_UNAVAILABLE).body(new TransactionStatus(TransactionStatus.Status.FAILED));
        }
    }

