def process_images(image_files, output_dir, max_width=800, max_height=800, quality=80):
    # Initialize plugin architecture
    plugins = {
        'jpg': JpgProcessor(),
        'png': PngProcessor()
    }

    for file_path in image_files:
        try:
            # Validate and read the input file
            if not os.path.exists(file_path) or not validate_file(file_path):
                logging.warning(f"Invalid or missing file: {file_path}. Skipping.")
                continue

            img = Image.open(file_path)

            # Resize and compress the image
            processed_img = plugins[img.format].process(img, max_width, max_height, quality)

            # Save the processed image to the output directory
            with open(os.path.join(output_dir, os.path.basename(file_path)), 'wb') as f:
                processed_img.save(f, format=img.format)

        except Exception as e:
            logging.error(f"Error processing {file_path}: {str(e)}")

    # Cache recently processed images for faster retrieval
    cache_images(image_files, output_dir)

def validate_file(file_path):
    return os.path.exists(file_path) and os.path.isfile(file_path)

class JpgProcessor:
    def process(self, img, max_width, max_height, quality):
        # Resize the image to fit within the specified dimensions
        width_ratio = max_width / float(img.width)
        height_ratio = max_height / float(img.height)
        if width_ratio > height_ratio:
            new_width = int(img.width * height_ratio)
            new_height = max_height
        else:
            new_width = max_width
            new_height = int(img.height * width_ratio)

        img.thumbnail((new_width, new_height))

        # Compress the image to the specified quality level
        buffered_img = BytesIO()
        img.save(buffered_img, 'JPEG', quality=quality)
        return Image.open(buffered_img)

class PngProcessor:
