#include <forward_list>
#include <threadpool>

void insertAfter(int target, int value, std::forward_list<int>& list, bool async = false) {
    auto it = list.begin();
    while (it != list.end() && *it != target) {
        ++it;
    }

    if (async) {
        // Use thread pool to perform insertion asynchronously
        std::threadpool tp(5); // Create a thread pool with 5 threads

        // Wrap the insertion operation in a lambda function to capture 'it' and 'list'
        auto task = [&, it, &list]() {
            list.insert_after(it, value);
        };

        // Enqueue the task
        tp.enqueue(task);
    } else {
        // Perform synchronous insertion
        while (it != list.end() && *it != target) {
            ++it;
        }
        if (it != list.end()) {
            list.insert_after(it++, value);
        } else {
            list.append(value);
        }
    }
}
