void insertAfterSearch(std::forward_list<std::string>& list, const std::string& searchStr, const std::string& insertionStr, int maxInsertions, Database* database, size_t maxLength = 100) {
    using namespace std;

    lock_guard<mutex> lock; // for thread safety

    auto it = list.begin();
    int count = 0;
    while (it != list.end()) {
        if (*it == searchStr && ++count <= maxInsertions) {
            list.insert_after(it, insertionStr);
            break;
        }
        ++it;
    }

    // truncate strings to maxLength
    for (auto& str : list) {
        if (str.length() > maxLength)
            str = string(str.substr(0, maxLength));
    }

    // store the modified list in the database
    for (const auto& str : list) {
        database->insert(str);
    }
}
