                      redirect_uri=os.environ.get('OAUTH_REDIRECT_URI'))

@app.route('/login', methods=['GET'])
def login():
    # Handle login request and return authorization URL
    auth_url, state = oauth.authorization_url(os.environ.get('OAUTH_AUTH_URL'))
    return jsonify({'url': auth_url}), 200

@app.route('/callback', methods=['GET', 'POST'])
def callback():
    # Handle OAuth callback
    if request.method == 'GET':
        code = request.args.get('code')
        token = oauth.fetch_token(os.environ.get('OAUTH_TOKEN_URL'), 
                                  client_secret=os.environ.get('OAUTH_CLIENT_SECRET'),
                                  code=code)
