public class HybridAutomationTool {
    private static final String CONFIG_FILE = "config.properties";
    private static final int SEVERITY_ERROR = 1;
    private static final int SEVERity_INFO = 2;

    public static void main(String[] args) {
        Properties configProps = new Properties();
        try (FileInputStream fis = new FileInputStream(CONFIG_FILE)) {
            configProps.load(fis);
        } catch (IOException e) {
            System.out.println("Error loading configuration file: " + e.getMessage());
            return;
        }

        String logLevel = configProps.getProperty("log.level");
        int severityThreshold = Integer.parseInt(configProps.getProperty("severity.threshold"));
        File errorLog = new File(configProps.getProperty("error.log.path"));
        File infoLog = new File(configProps.getProperty("info.log.path"));

        // Check and delete logs if they exist
        if (errorLog.exists()) {
            errorLog.delete();
        }
        if (infoLog.exists()) {
            infoLog.delete();
        }

        // Execute commands and log output/error streams
        try (PrintStream ps = new PrintStream(new FileOutputStream("output.log"), true, "UTF-8")) {
            for (String command : configProps.getProperty("commands").split(",")) {
                Process process = Runtime.getRuntime().exec(command);
                BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
                String line;
                while ((line = reader.readLine()) != null) {
                    if (Integer.parseInt(line.split(":")[1].trim()) >= severityThreshold) {
                        logMessage(errorLog, SEVERITY_ERROR, "Error: " + line);
                    } else {
                        logMessage(infoLog, SEVERITY_INFO, "Info: " + line);
                    }
                }

                reader = new BufferedReader(new InputStreamReader(process.getErrorStream()));
                while ((line = reader.readLine()) != null) {
                    if (Integer.parseInt(line.split(":")[1].trim()) >= severityThreshold) {
                        logMessage(errorLog, SEVERITY_ERROR, "Error: " + line);
                    } else {
                        logMessage(infoLog, SEVERITY_INFO, "Info: " + line);
                    }
                }
            }
        } catch (IOException e) {
            logMessage(errorLog, SEVERITY_ERROR, "Error executing command: " + e.getMessage());
        }

        // Handle and log command execution errors
        try (PrintStream ps = new PrintStream(new FileOutputStream("error.log"), true, "UTF-8")) {
            for (String error : configProps.getProperty("errors").split(",")) {
                logMessage(errorLog, SEVERITY_ERROR, "Error: " + error);
            }
        } catch (IOException e) {
            logMessage(errorLog, SEVERITY_ERROR, "Error logging errors: " + e.getMessage());
        }

        // Implement advanced resource management features
        // ...

        // Implement robust error handling and rollback mechanisms
        // ...
    }

    private static void logMessage(File file, int severity, String message) {
        try (PrintStream ps = new PrintStream(new FileOutputStream(file, true), true, "UTF-8")) {
            SimpleDateFormat dateFormat = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
            String timestamp = dateFormat.format(new Date());
            if (severity == SEVERITY_ERROR) {
                ps.println(timestamp + ": [" + severity + "] - " + message);
            } else {
                ps.println(timestamp + ": [" + severity + "] - " + message);
            }
        } catch (IOException e) {
            System.out.println("Error logging message: " + e.getMessage());
        }
    }
}
