const { Worker } = require('worker_threads');
const crypto = require('crypto');
const fetch = require('node-fetch');

class WebSocketStreamReducer {
  constructor({
    config,
    financialApiService
  }) {
    this.config = config;
    this.financialApiService = financialApiService;
    this.workers = [];
  }

  async start() {
    try {
      const workerPoolSize = await this.getConfiguredWorkerPool();
      for (let i = 0; i < workerPoolSize; i++) {
        this.workers.push(new Worker(this.getWorkerScript()));
      }
      await Promise.all(this.workers.map((worker) => worker.on('message', (data) => this.onMessage(data))));
    } catch (error) {
      console.error('Error starting WebSocketStreamReducer:', error);
    }
  }

  async getConfiguredWorkerPool() {
    // implementation of getting the configured worker pool size
  }

  getWorkerScript() {
    return `
      const crypto = require('crypto');
      const fetch = require('node-fetch');

      self.on('message', (data) => {
        try {
          const { transactionId, amount } = data;
          if (!transactionId || !amount || typeof amount !== 'number') {
            self.postMessage({ error: 'Invalid transaction data' });
            return;
          }

          fetchTransactionAmount(transactionId)
            .then((amount) => {
              self.postMessage({ amount });
            })
            .catch((error) => {
              self.postMessage({ error: 'Failed to fetch transaction amount' });
            });
        } catch (error) {
          self.postMessage({ error: 'Error processing transaction data' });
        }
      });

      async function fetchTransactionAmount(transactionId) {
        try {
          const response = await this.financialApiService.getTransactionAmount(transactionId);
          if (!response.ok) {
            throw new Error('Failed to fetch transaction amount');
          }
          return (await response.json()).amount;
        } catch (error) {
          // handle exponential backoff and retries
        }
      }
    `;
  }

  async onMessage(data) {
    try {
      const { error, amount } = data;
      if (error) {
        console.error('Error processing transaction:', error);
      } else {
        this.config.encryptedTransactions.push({ id: crypto.createHash('sha256').update(String(amount)).digest().toString(), amount: amount });
      }
    } catch (error) {
      console.error('Error handling message:', error);
    }
  }

  async reduce() {
    try {
      const encryptedTransactions = this.config.encryptedTransactions;
      if (!encryptedTransactions.length) {
        return;
      }

      const iv = crypto.randomBytes(16);
      const encryptionKey = crypto.pbkdf2Sync(this.config.key, this.config.salt, 100000, 32, 'sha256');
      const encryptedAmounts = encryptedTransactions.map((transaction) => {
        try {
          return crypto.createCipheriv('aes-256-cbc', encryptionKey, iv).update(String(transaction.amount), 'utf8', 'hex');
        } catch (error) {
          console.error('Error encrypting transaction amount:', error);
          throw new Error('Encryption failed');
        }
      });

      this.config.encryptedAmounts = encryptedAmounts;
    } catch (error) {
      console.error('Error reducing transactions:', error);
    } finally {
      // close financial API connections
      await this.financialApiService.closeConnections();
    }
  }

  async pause() {
    try {
      for (const worker of this.workers) {
        await new Promise((resolve) => worker.postMessage({ type: 'pause' }));
      }
    } catch (error) {
      console.error('Error pausing WebSocketStreamReducer:', error);
    }
  }

  async resume() {
    try {
      for (const worker of this.workers) {
        await new Promise((resolve) => worker.postMessage({ type: 'resume' }));
      }
    } catch (error) {
      console.error('Error resuming WebSocketStreamReducer:', error);
    }
  }
}

module.exports = WebSocketStreamReducer;
