public class CommandExecutor {

    private static final int MAX_RETRIES = 3;

    public static void main(String[] args) throws Exception {
        // Check and delete configuration file if it exists
        File configFile = new File("config.json");
        if (configFile.exists()) {
            configFile.delete();
        }

        // Load configuration from external system
        String configStr = loadConfigFromExternalSystem();
        JSONObject configJson = new JSONObject(configStr);

        // Execute commands and log output/error streams
        for (String command : configJson.getJSONArray("commands").toArray(new String[]{})) {
            executeCommand(command);
        }
    }

    private static void executeCommand(String command) throws Exception {
        int retries = 0;
        long lastRetryTime = System.currentTimeMillis();
        while (retries < MAX_RETRIES) {
            try {
                Process process = Runtime.getRuntime().exec(new String[]{command});
                BufferedReader outputReader = new BufferedReader(new InputStreamReader(process.getInputStream()));
                BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));

                // Read and log output/error streams
                logMessage(errorReader, "ERR");
                logMessage(outputReader, "OUT");

                int exitValue = process.waitFor();
                if (exitValue != 0) {
                    retries++;
                    long sleepTime = (long) Math.pow(2, retries);
                    Thread.sleep(sleepTime);

                    // Log failure
                    logMessage(null, "ERR", "Command failed: " + command);
                } else {
                    break;
                }
            } catch (InterruptedException e) {
                // Handle interrupt exception
                logMessage(null, "ERR", "Interrupted while executing command: " + command);
                Thread.currentThread().interrupt();
            } catch (IOException e) {
                // Handle IO exception
                logMessage(null, "ERR", "IO error while executing command: " + command);
            }
        }

        // Log final status
        logMessage(null, "STAT", "Command executed with " + (retries > 0 ? "failures" : "success"));
    }

    private static void logMessage(BufferedReader reader, String type) {
        logMessage(reader, type, null);
    }

    private static void logMessage(BufferedReader reader, String type, String message) {
        if (reader != null) {
            try {
                StringBuilder sb = new StringBuilder();
                String line;
                while ((line = reader.readLine()) != null) {
                    sb.append(line).append("\n");
                }
                message = sb.toString() + message;
            } catch (IOException e) {
                // Handle IO exception
                logMessage(null, "ERR", "IO error while reading output/error stream: " + type);
            }
        }

        if (message != null) {
            System.out.println(type + ": " + message);
        }
    }

    private static String loadConfigFromExternalSystem() throws IOException {
        // Implement logic to load configuration from external system
        return "{}";
    }
}

