#include <boost/asio.hpp>
#include <boost/thread.hpp>
#include <iostream>
#include <string>
#include <vector>

// Define a struct to represent a connection configuration
struct ConnectionConfig {
    std::string host;
    int port;
};

// Define a class for managing connections to servers
class ServerConnectionManager {
public:
    ServerConnectionManager(const std::vector<ConnectionConfig>& configs) 
        : io_service_(new boost::asio::io_service), 
          thread_pool_(new boost::thread_group),
          connection_configs_(configs) {}

    // Start the server connections in a separate thread
    void start() {
        for (const auto& config : connection_configs_) {
            // Create a new ASIO context for each connection
            boost::asio::io_service io_service_copy(*io_service_);
            boost::thread t([this, &io_service_copy]() {
                connect(config.host, config.port);
            });
            thread_pool_->add(t);
        }
    }

private:
    void connect(const std::string& host, int port) {
        // Establish a TCP connection to the server
        boost::asio::ip::tcp::socket socket(*io_service_);
        boost::asio::connect(socket, boost::asio::ip::tcp::endpoint(boost::asio::ip::tcp::v4(), port));

        // Send and receive data on the connection
    }

    boost::shared_ptr<boost::asio::io_service> io_service_;
    boost::shared_ptr<boost::thread_group> thread_pool_;
    std::vector<ConnectionConfig> connection_configs_;
};

int main() {
    // Define a vector of connection configurations
    std::vector<ConnectionConfig> configs = {
        {"server1", 8080},
        {"server2", 8081},
        {"server3", 8082}
    };

    // Create an instance of the ServerConnectionManager class
    ServerConnectionManager server_manager(configs);

    // Start the server connections in a separate thread
    server_manager.start();

    return 0;
}
```

