#include <semaphore.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define SEM_NAME "SemaphoreExample"

int semaphore_create(int value, int timeout) {
    sem_t* semaphore;
    if ((semaphore = sem_open(SEM_NAME, O_CREAT | O_EXCL, 0644, value)) == SEM_FAILED) {
        perror("sem_open failed");
        return -1;
    }
    // Set the acquire timeout
    sem_timedwait(semaphore, (struct timespec){.tv_sec = timeout / 1000, .tv_nsec = (timeout % 1000) * 1000000});
    return 0;
}

int semaphore_delete() {
    if (sem_close(SEM_NAME)) {
        perror("sem_close failed");
        return -1;
    }
    return 0;
}

void* thread_func(void* arg) {
    int value = *(int*)arg;
    // Perform semaphore operations
    sem_wait(value);
    // Critical section
    printf("Semaphore acquired\n");
    sleep(2); // Simulate some work
    printf("Semaphore released\n");
    sem_post(value);
    return NULL;
}

int main() {
    pthread_t thread1, thread2;
    int value = 5; // Initial semaphore value

    if (semaphore_create(value, 1000) == -1) {
        perror("Semaphore creation failed");
        exit(1);
    }

    pthread_create(&thread1, NULL, &thread_func, &value);
    pthread_create(&thread2, NULL, &thread_func, &value);

    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    if (semaphore_delete() == -1) {
        perror("Semaphore deletion failed");
    }

    return 0;
}

