import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.SQLException;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingDeque;

public class DatabaseConnectionPool {

    private static final int INITIAL_POOL_SIZE = 5;
    private static final int MAX_POOL_SIZE = 20;
    private static final int MIN_IDLE_CONNS = 2;
    private static final String CONFIG_SERVICE_URL = "https://config-service.com/config";

    private ConnectionPool connectionPool;
    private ConfigService configService;
    private Map<String, Object> queryConfigurations;

    public DatabaseConnectionPool() {
        this.connectionPool = new ConnectionPool(INITIAL_POOL_SIZE);
        this.configService = new ConfigService(CONFIG_SERVICE_URL);
        this.queryConfigurations = new HashMap<>();
    }

    public void manageConnectionPool() {
        try {
            int idleConns = connectionPool.getIdleConnections();
            if (idleConns < MIN_IDLE_CONNS) {
                connectionPool.extendPool(idleConns + (MAX_POOL_SIZE - idleConns));
            } else if (idleConns > MIN_IDLE_CONNS * 2) {
                connectionPool.shrinkPool(idleConns - (MIN_IDLE_CONNS * 2));
            }
        } catch (Exception e) {
            log.error("Error managing connection pool: " + e.getMessage());
        }
    }

    public void updateQueryConfigurations() {
        try {
            Map<String, Object> remoteConfigs = configService.fetchConfigs();
            validateConfigs(remoteConfigs);
            queryConfigurations.putAll(remoteConfigs);
        } catch (Exception e) {
            log.error("Error updating query configurations: " + e.getMessage());
        }
    }

    public Connection getConnection() {
        try {
            return connectionPool.borrowConnection();
        } catch (SQLException e) {
            log.error("Error getting connection from pool: " + e.getMessage());
            return null;
        }
    }

    public void releaseConnection(Connection con) {
        try {
            connectionPool.returnConnection(con);
        } catch (SQLException e) {
            log.error("Error releasing connection to pool: " + e.getMessage());
        }
    }

    private class ConnectionPool {

        private BlockingQueue<Connection> connections;
        private int initialSize;

        public ConnectionPool(int size) {
            this.initialSize = size;
            this.connections = new LinkedBlockingDeque<>(size);
        }

        public int getIdleConnections() {
            return connections.size();
        }

        public void extendPool(int newSize) {
            for (int i = 0; i < newSize - initialSize; i++) {
                try {
                    connections.put(createConnection());
                } catch (SQLException e) {
                    log.error("Error creating new connection: " + e.getMessage());
                }
            }
        }

        public void shrinkPool(int newSize) {
            for (int i = 0; i > newSize - initialSize; i--) {
                try {
                    connections.take();
                } catch (InterruptedException e) {
                    log.error("Error shrinking pool: " + e.getMessage());
                }
            }
        }

        private Connection createConnection() throws SQLException {
            // Create a new database connection
            return DriverManager.getConnection("jdbc:mysql://localhost:3306/mydb", "username", "password");
        }
    }

    private class ConfigService {

        private String url;

        public ConfigService(String url) {
            this.url = url;
        }

        public Map<String, Object> fetchConfigs() throws Exception {
            // Fetch updated query configurations from the remote API
            return null; // Replace with actual implementation
        }
    }
}

