# Jenkinsfile
pipeline {
    agent any
    stages([
        stage('Build') {
            steps {
                sh 'npm install'
                sh 'npm run build'
            }
        },
        stage('Test') {
            steps {
                sh 'npm test'
            }
        },
        stage('Docker Build') {
            steps {
                sh 'docker build -t my-app .'
            }
        },
        stage('Kubernetes Deploy') {
            steps {
                sh 'kubectl apply -f deployment.yaml'
            }
        },
        stage('Monitor and Rollback') {
            steps {
                def health = sh(script: 'kubectl get pods -o jsonpath={.items[0].status.containerStatuses[0].state.running}', returnStdout: true).trim()
                if (health != 'true') {
                    echo 'Application not healthy, rolling back'
                    sh 'kubectl rollout undo deployment/my-app'
                }
            }
        }
    ])
    post {
        always {
            archiveArtifacts artifacts: 'target/*', onlyIfSuccessful: true
        }
    }
}

