```
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

#define RECORDS_SIZE 1000000
#define INITIAL_RANGE 10000

typedef struct {
    int key;
    long offset;
} record_t;

record_t* records = NULL;
int num_records = 0;
int capacity = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_records(int initial_range) {
    capacity = (initial_range + RECORDS_SIZE - 1) / RECORDS_SIZE * RECORDS_SIZE;
    records = (record_t*)malloc(capacity * sizeof(record_t));
}

void* get_initial_values(void* ptr) {
    int i, j;
    FILE* f = fopen("config.txt", "r");
    if(f == NULL) return NULL;
    char str[20];
    for(i = 0; i < capacity; i++) {
        fgets(str, sizeof(str), f);
        records[i].key = atoi(strtok(str, ",")) % INITIAL_RANGE;
        records[i].offset = (long)(rand() * (double)RAND_MAX / RAND_MAX);
    }
    fclose(f);
    return NULL;
}

void add_record(int key, long offset) {
    pthread_mutex_lock(&mutex);
    if(num_records >= capacity) {
        // Rebalance storage nodes based on user-defined policies
    } else {
        records[num_records].key = key;
        records[num_records].offset = offset;
        num_records++;
    }
    pthread_mutex_unlock(&mutex);
}

void delete_record(int key) {
    pthread_mutex_lock(&mutex);
    for(int i = 0; i < num_records; i++) {
        if(records[i].key == key) {
            // Shift remaining records and update offsets
            memmove(&records[i], &records[i+1], (num_records - i - 1) * sizeof(record_t));
            num_records--;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void* get_record(int key, void* ptr) {
    for(int i = 0; i < num_records; i++) {
        if(records[i].key == key) {
            // Retrieve offset value
            return &records[i];
        }
    }
    return NULL;
}

void persist_records() {
    FILE* f = fopen("persistent_storage.txt", "w");
    for(int i = 0; i < num_records; i++) {
        fprintf(f, "%d,%ld\n", records[i].key, records[i].offset);
    }
    fclose(f);
}

int main() {
    pthread_t thread;
    pthread_create(&thread, NULL, get_initial_values, NULL);
    pthread_join(thread, NULL);

    // Initialize storage nodes and authenticate users
    initialize_records(INITIAL_RANGE);

    // Handle RESTful API operations for file management
    while(1) {
        char op[10];
        fgets(op, sizeof(op), stdin);
        if(strcmp(op, "upload") == 0) {
            int key;
            long offset;
            // Read user input and add record
            add_record(key, offset);
        } else if(strcmp(op, "download") == 0) {
            int key;
            void* ptr = get_record(key, NULL);
            // Retrieve offset value and handle errors
        } else if(strcmp(op, "delete") == 0) {
            int key;
            delete_record(key);
        }
    }

    persist_records();
    return 0;
}
