use std::time::{Instant, Duration};
use std::sync::mpsc;
use crate::dom;

fn dbCommandExecutor(root: &dom::Node, selector: &str, test_func: Option<fn(&dom::Node) -> String>) -> Result<String, String> {
    let start_time = Instant::now();

    // Validate input root as a valid DOM node
    if !root.is_valid() {
        return Err("Invalid root DOM node".to_string());
    }

    // Execute command on the matched elements
    let mut results: Vec<String> = vec![];
    for node in root.find(selector) {
        match test_func.as_ref().map(|f| f(&node)) {
            Some(result) => results.push(result),
            None => {}
        }
    }

    let elapsed_time = start_time.elapsed();
    if elapsed_time > Duration::from_millis(5000) { // 5 seconds
        return Err("Command execution took too long".to_string());
    }

    Ok(results.join(", "))
}

