#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>
#include <unistd.h>

char* constructFilePath(char *path, int bufferSize, bool isAbsolute, char **errorMsg) {
    // Initialize error message and buffer
    *errorMsg = NULL;
    char *buffer = (char *)malloc((bufferSize + 1) * sizeof(char));

    // Check if the path exceeds the maximum buffer size
    size_t len = strlen(path);
    if (len >= bufferSize) {
        // Set error message and free memory
        *errorMsg = strdup("Path exceeds maximum buffer size.");
        free(buffer);
        return NULL;
    }

    // Replace environment variables with actual paths
    char temp[bufferSize + 1];
    strcpy(temp, path);

    // Optimize for performance: minimize string operations and system calls
    int i = 0;
    while (i < len) {
        if (temp[i] == '~') {
            // Resolve home directory
            const char *homeDir = getenv("HOME");
            size_t homeLen = strlen(homeDir);
            if (homeDir != NULL && !strncasecmp(temp + i, "~", 1)) {
                strncpy(buffer, homeDir, bufferSize);
                buffer[homeLen] = '/';
                i += homeLen + 1;
                len -= homeLen + 1;
                continue;
            }
        }
        // Handle Windows-style paths
        if (temp[i] == '\\') {
            temp[i] = '/';
            continue;
        }

        buffer[i] = temp[i];
        i++;
    }
    buffer[len] = '\0';

    // Check for absolute path and append working directory if necessary
    if (!isAbsolute) {
        // Get the current working directory
        char cwd[bufferSize + 1];
        getcwd(cwd, bufferSize);
        // Append the current working directory to the file path
        size_t cwdLen = strlen(cwd);
        if (cwdLen + len + 1 > bufferSize) {
            // Set error message and free memory
            *errorMsg = strdup("Path exceeds maximum buffer size.");
            free(buffer);
            return NULL;
        }
        sprintf(buffer + len, "/%s", cwd + strlen(cwd));
    }

    return buffer;
}
