import asyncio
from aiohttp import ClientSession

async def process_transactions(users):
    async with ClientSession() as session:
        tasks = []
        for user in users:
            task = fetch_user_transactions(session, user)
            tasks.append(task)

        results = await asyncio.gather(*tasks)

        total_amounts = {}
        for result in results:
            if isinstance(result, dict):
                total_amounts.update(result)
            else:
                total_amounts[user] = result

        return total_amounts

async def fetch_user_transactions(session, user):
    try:
        api_response = await session.get(f"https://api.example.com/transactions/{user}")
        data = await api_response.json()

        total_amount = 0
        for transaction in data:
            total_amount += transaction['amount']

        return {user: total_amount}
    except asyncio.TimeoutError as e:
        print(f"Timeout error fetching transactions for user {user}: {e}")
        return None
    except Exception as e:
        print(f"Error fetching transactions for user {user}: {e}")
        return None

async def main():
    users = ['user1', 'user2', ..., 'user1000000']  # replace with your dataset
    try:
        result = await process_transactions(users)
        print(result)
    except Exception as e:
        print(f"Error processing transactions: {e}")

asyncio.run(main())
