import com.amazonaws.services.kms.AWSKMS;
import com.amazonaws.services.kms.model.GenerateDataKeyRequest;
import com.amazonaws.services.kms.model.GenerateDataKeyResult;
import com.fasterxml.jackson.databind.ObjectMapper;
import io.jsonwebtoken.JwtBuilder;
import io.jsonwebtoken.Jwts;
import redis.clients.jedis.Jedis;
import redis.clients.jedis.JedisPool;

import java.io.*;
import java.util.*;

public class JwtMicroservice {
    private final AWSKMS awsKms;
    private final JedisPool jedisPool;
    private final ObjectMapper mapper;

    public JwtMicroservice(AWSKMS awsKms, JedisPool jedisPool) {
        this.awsKms = awsKms;
        this.jedisPool = jedisPool;
        this.mapper = new ObjectMapper();
    }

    public void generateJwt(String username, String[] permissions, List<String> roles) throws Exception {
        // Generate data key from KMS
        GenerateDataKeyRequest request = new GenerateDataKeyRequest()
                .withKeySpec("AES_256");
        GenerateDataKeyResult result = awsKms.generateDataKey(request);
        byte[] encryptedPrivateKey = result.getPublicKey().getBytes();

        // Deserialize user preferences from binary file
        File preferencesFile = new File("user_preferences.bin");
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(preferencesFile))) {
            UserPreferences userPrefs = mapper.readValue(ois, UserPreferences.class);
        } catch (Exception e) {
            // Handle deserialization error
        }

        // Create JWT with username, permissions, and roles
        JwtBuilder builder = Jwts.builder()
                .setSubject(username)
                .claim("permissions", permissions)
                .claim("roles", roles);

        // Add private key to JWT
        builder.signWith(new RS256Signer(encryptedPrivateKey));

        // Serialize JWT as JSON string
        String jsonToken = builder.compact();

        // Cache JWT in Redis for later use
        Jedis jedis = jedisPool.getResource();
        try {
            jedis.setex("jwt:" + username, 3600, jsonToken); // cache token for 1 hour
        } finally {
            jedis.close();
        }
    }

    public void insertStringAfter(String target, String insertion, List<String> list) {
        int index = list.indexOf(target);
        if (index >= 0) {
            list.add(index + 1, insertion);
        } else {
            list.add(insertion);
        }
    }
}

class RS256Signer implements SignatureAlgorithm {
    private final byte[] privateKey;

    public RS256Signer(byte[] privateKey) {
        this.privateKey = privateKey;
    }

    @Override
    public void sign(JwtBuilder builder, String subject, Map<String, Object> claims) {
        // Sign JWT with private key
    }
}

