# Define the API endpoint for updating and deleting resources
@app.route('/resources/<string:resource_id>', methods=['PUT', 'DELETE'])
@CacheBypass()
def update_delete_resource(resource_id):
    if request.method == 'PUT':
        # Handle partial updates by only modifying specific fields
        resource = db.Resource.query.get_or_404(resource_id)
        updated_data = json.loads(request.data.decode('utf-8'))
        for key, value in updated_data.items():
            setattr(resource, key, value)
        db.session.commit()
        return jsonify({'message': 'Resource updated successfully'})

    elif request.method == 'DELETE':
        # Cascade deletion of related resources
        resource = db.Resource.query.get_or_404(resource_id)
        if not resource:
            return jsonify({'error': 'Resource not found'}), 404

        # Remove any related resources before deleting the current one
        for related_resource in resource.related_resources:
            db.session.delete(related_resource)

        try:
            db.session.delete(resource)
            db.session.commit()
        except Exception as e:
            return jsonify({'error': str(e)}), 500

        # Send notification to stakeholders upon successful deletion
        notify_service.send_notification(f"Resource {resource_id} and its related resources have been deleted")

        # Return a new resource with default values if the cascaded deletion is successful
        return jsonify({'message': 'Resources successfully deleted', 'new_resource': {'id': 'NEW_ID'}}})

    else:
        return jsonify({'error': 'Invalid request method'}), 405

