            # Decrease product quantity in inventory
            update_inventory(session, product_id, -quantity)

            # Process payment
            if not process_payment(session, order_id):
                raise PaymentProcessingError

    except (PaymentProcessingError, InventoryException) as e:
        # Retry payment processing up to 3 times
        for _ in range(3):
            try:
                if process_payment(session, order_id):
                    break
            except PaymentProcessingError:
                pass
        else:
            return f"Payment processing failed: {e}"

