    {
        _logger = logger;
        _httpClient = httpClient;
        _apiUrls = apiUrls;
    }

    public async Task<byte[]> DecryptAndUpdateUserProfile(byte[] ciphertext, byte[] encryptionKey, byte[] iv)
    {
        using (Aes aes = Aes.Create())
        {
            aes.Key = encryptionKey;
            aes.IV = iv;

            using (MemoryStream ms = new MemoryStream())
            {
                using (CryptoStream cs = new CryptoStream(ms, aes.CreateDecryptor(), CryptoStreamMode.Write))
                {
                    cs.Write(ciphertext, 0, ciphertext.Length);
                    ciphertext = ms.ToArray();
                }
            }
        }

        // Update user profile
        foreach (string apiUrl in _apiUrls)
        {
            try
            {
                using (HttpRequestMessage request = new HttpRequestMessage(HttpMethod.Put, apiUrl))
                {
                    string json = JsonConvert.SerializeObject(ciphertext);
                    request.Content = new StringContent(json, Encoding.UTF8, "application/json");

                    using (HttpResponseMessage response = await _httpClient.SendAsync(request))
                    {
                        response.EnsureSuccessStatusCode();
                    }
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error updating user profile");
            }
        }

        // Send notifications
        foreach (string apiUrl in _apiUrls)
        {
            try
            {
                using (HttpRequestMessage request = new HttpRequestMessage(HttpMethod.Post, $"{apiUrl}/notify"))
