                    using (HttpResponseMessage response = await _httpClient.SendAsync(request))
                    {
                        response.EnsureSuccessStatusCode();
                    }
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error sending notifications");
            }
        }

        return ciphertext;
    }
}
