#include <stdio.h>
#include <stdarg.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_LOG_MESSAGE_LENGTH 1024
#define LOG_LEVEL_ERROR 0
#define LOG_LEVEL_WARNING 1
#define LOG_LEVEL_INFO 2
#define LOG_LEVEL_DEBUG 3

typedef enum { DEBUG, INFO, WARNING, ERROR } LogLevel;

LogLevel logLevel = ERROR;
pthread_mutex_t logMutex = PTHREAD_MUTEX_INITIALIZER;

void logCondition(LogLevel minLevel, const char *format, ...) {
    pthread_mutex_lock(&logMutex);

    if (minLevel >= logLevel) {
        int length = snprintf(NULL, 0, format, va_arg va_format);

        if (length < MAX_LOG_MESSAGE_LENGTH) {
            char* message = malloc(length + 1);
            vsnprintf(message, length + 1, format, va_arg va_format);
            message[length] = '\0';

            fprintf(stderr, "%s\n", message);
            free(message);
        }
    }

    pthread_mutex_unlock(&logMutex);
}

void setLogLevel(LogLevel level) {
    logLevel = level;
}
