                        }
                    }
                    catch (Exception ex)
                    {
                        // Handle XML parsing errors
                        Console.WriteLine($"Error parsing XML document: {ex.Message}");
                    }
                }
            }
            catch (Exception ex)
            {
                // Handle network failures, XML parsing errors, and database connectivity issues
