    std::unordered_map<std::string, std::variant<int, double, std::string, bool>> configMap;

    try {
        json configFile = nlohmann::json::parse(filePath);
        for (const auto& [settingName, value] : configFile.items()) {
            if (!expectedSchema.count(settingName)) {
                logError(settingName, typeid(void));
                continue;
            }
            std::variant<int, double, std::string, bool> validatedValue = validateType(value, expectedSchema.at(settingName));
            configMap[settingName] = validatedValue;
        }
    } catch (const json::exception& e) {
        logError("JSON parsing error", typeid(void));
    }

    return configMap;
}
