import reactor.core.publisher.Flux;
import reactor.core.publisher.Mono;

import java.time.Duration;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicInteger;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.context.ConfigurableApplicationContext;
import org.springframework.data.mongodb.MongoDbFactory;
import org.springframework.data.mongodb.core.ReactiveMongoTemplate;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RestController;

import io.netty.handler.codec.mqtt.MqttPublishMessage;

@SpringBootApplication
public class SensorDataApp {

    @Autowired
    private ReactiveMongoTemplate mongoTemplate;

    @GetMapping("/sensor-data")
    public Flux<MqttPublishMessage> sensorData() {
        return Flux.interval(Duration.ofSeconds(1)).flatMap(i -> 
            Mono.just(new MqttPublishMessage("Sensor " + i, "Location: (42.0, 72.0)"))
        );
    }

    @GetMapping("/sensor-data/{id}")
    public Mono<MqttPublishMessage> getSensorData(@PathVariable String id) {
        return mongoTemplate
                .getCollection("sensors", MqttPublishMessage.class)
                .find(Map.of("id", id))
                .next();
    }

    public static void main(String[] args) {
        ConfigurableApplicationContext context = SpringApplication.run(SensorDataApp.class, args);
        // Start the application
        AtomicInteger counter = new AtomicInteger(0);

        while (counter.getAndIncrement() < 100000) {
            System.out.println("Processing event: " + counter);
            try {
                Thread.sleep(1); // Simulating processing time
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }

        context.stop();
    }
}
