import requests
import json
import yaml
import xml.etree.ElementTree as ET
from flask import Flask, render_template_string, request, jsonify
from flask_caching import Cache
from functools import wraps
from datetime import datetime, timedelta
from os.path import splitext

app = Flask(__name__)
cache = Cache(app, config={"CACHE_TYPE": "SimpleCache"})

def async_load_config(config_url):
    @wraps(async_load_config)
    def wrapper(*args, **kwargs):
        def load_config():
            try:
                response = requests.get(config_url)
                if response.status_code == 200:
                    format_extension = splitext(response.url)[1][1:]
                    config_format = None
                    if format_extension in ["json"]:
                        config_format = "json"
                    elif format_extension in ["yml", "yaml"]:
                        config_format = "yaml"
                    elif format_extension in ["xml"]:
                        config_format = "xml"

                    if config_format == "json":
                        return json.loads(response.content.decode("utf-8"))
                    elif config_format == "yaml":
                        return yaml.safe_load(response.content)
                    elif config_format == "xml":
                        root = ET.fromstring(response.content)
                        config = {}
                        for elem in root:
                            config[elem.tag] = elem.text
                        return config

                    cache.set("config", response.json(), timeout=300)  # Set the cache for 5 minutes
                else:
                    raise Exception(f"Failed to load configuration: {response.status_code}")
            except requests.exceptions.RequestException as e:
                print(f"Request failed: {e}")
            except json.JSONDecodeError as e:
                print(f"Invalid JSON response: {e}")
            except yaml.YAMLError as e:
                print(f"Invalid YAML response: {e}")
            except ET.ParseError as e:
                print(f"Invalid XML response: {e}")

        return cache.get_or_create("config", load_config)

    return wrapper()

@app.route("/configure")
def configure():
    return render_template_string("""
        <h1>Configuration Settings</h1>
        <form action="/update_config" method="post">
            <label for="config_url">API URL:</label><br />
            <input type="text" id="config_url" name="config_url"><br />
            <input type="submit" value="Update Config">
        </form>
    """)

@app.route("/update_config", methods=["POST"])
def update_config():
    config_url = request.form["config_url"]
    config_data = async_load_config(config_url)
    return jsonify({"status": "Config updated successfully!"})

if __name__ == "__main__":
    app.run(debug=True)
