using System;
using System.IO;
using System.Net;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class WebsiteDeployer
{
    public string DeployWebsite(string directoryPath, string siteName, string deploymentPackage)
    {
        if (!Directory.Exists(directoryPath))
        {
            throw new DirectoryNotFoundException($"The directory '{directoryPath}' does not exist.");
        }

        if (!File.Exists(Path.Combine(directoryPath, "web.config")))
        {
            LogError("No web.config file found in the specified directory. Deployment cannot proceed.");
            return "ERROR";
        }

        string packageHash;
        try
        {
            packageHash = CalculateMd5Hash(deploymentPackage);
        }
        catch (Exception e)
        {
            LogError($"An error occurred while calculating the MD5 hash: {e.Message}");
            return "ERROR";
        }

        if (!VerifyChecksum(packageHash, deploymentPackage))
        {
            LogError("The deployment package has been tampered with or is corrupted. Deployment cannot proceed.");
            return "ERROR";
        }

        try
        {
            DeploySite(directoryPath, siteName, deploymentPackage);
        }
        catch (Exception e)
        {
            LogError($"An error occurred while deploying the website: {e.Message}");
            return "ERROR";
        }

        return "SUCCESS";
    }

    private string CalculateMd5Hash(string packagePath)
    {
        using (var md5 = MD5.Create())
        {
            byte[] buffer = new byte[chunkSize];
            int bytesRead;
            long totalBytesRead = 0;

            using (var stream = File.OpenRead(packagePath))
            {
                while ((bytesRead = stream.Read(buffer, 0, buffer.Length)) > 0)
                {
                    md5.TransformBlock(buffer, 0, bytesRead);
                    totalBytesRead += bytesRead;
                }

                md5.TransformFinalBlock(buffer, 0, buffer.Length - bytesRead);
                byte[] hashValue = md5.Hash.Value;

                return BitConverter.ToString(hashValue).Replace("-", "").ToLower();
            }
        }
    }

    private bool VerifyChecksum(string packageHash, string deploymentPackage)
    {
        try
        {
            using (var md5 = MD5.Create())
            {
                byte[] buffer = new byte[chunkSize];
                int bytesRead;
                long totalBytesRead = 0;

                using (var stream = File.OpenRead(deploymentPackage))
                {
                    while ((bytesRead = stream.Read(buffer, 0, buffer.Length)) > 0)
                    {
                        md5.TransformBlock(buffer, 0, bytesRead);
                        totalBytesRead += bytesRead;
                    }

                    md5.TransformFinalBlock(buffer, 0, buffer.Length - bytesRead);
                    byte[] hashValue = md5.Hash.Value;

                    return BitConverter.ToString(hashValue).Replace("-", "").ToLower() == packageHash;
                }
            }
        }
        catch (Exception e)
        {
            LogError($"An error occurred while verifying the checksum: {e.Message}");
            return false;
        }
    }

