#include <openssl/aes.h>
#include <openssl/err.h>
#include <openssl/hmac.h>
#include <stdlib.h>
#include <string.h>

// Function to initialize an AES-256-GCM cipher
int init_aes_cipher(char *password, char *salt, unsigned char **iv, EVP_CIPHER_CTX **ctx) {
    // Initialize the PBKDF2 key derivation function
    PKCS5_PBKDF2_CTX pkcs5_ctx;
    int ret = PKCS5_PBKDF2_init(&pkcs5_ctx, NULL);
    if (ret != 1) return -1;

    // Derive the encryption key from the password and salt using PBKDF2 with SHA-256
    unsigned char key[EVP_MAX_KEY_LENGTH];
    ret = PKCS5_PBKDF2(password, strlen(password), salt, strlen(salt), 10000, 32, key);
    if (ret != 1) return -1;

    // Initialize the AES-GCM cipher context
    *ctx = EVP_CIPHER_CTX_new();
    if (*ctx == NULL) return -1;
    EVP_CIPHER_CTX_set_key_length(*ctx, 32);

    // Set the IV length to 96 bits as required by GCM
    unsigned char iv_val[12];
    RAND_bytes(iv_val, 12);
    *iv = malloc(12);
    memcpy(*iv, iv_val, 12);

    // Initialize the AES-GCM cipher with the derived key and IV
    EVP_EncryptInit_ex(*ctx, EVP_aes_256_gcm(), NULL, key, *iv);
    EVP_CIPHER_CTX_set_padding(*ctx, 0);

    return 1;
}

// Function to clean up and disable the cipher when it is no longer needed
void cleanup_aes_cipher(EVP_CIPHER_CTX *ctx) {
    // Disable the cipher context
    EVP_CIPHER_CTX_free(ctx);
}

int main() {
    // Example usage:
    char *password = "my_secret_password";
    char *salt = "my_salt_value";
    unsigned char *iv;
    EVP_CIPHER_CTX *ctx;

    int ret = init_aes_cipher(password, salt, &iv, &ctx);
    if (ret != 1) {
        ERR_error_string(ERR_get_error(), NULL);
        return -1;
    }

    // Use the cipher context for encryption or decryption
    // ...

    cleanup_aes_cipher(ctx);

    return 0;
}
