```java
import java.util.*;
import org.springframework.cache.annotation.Cacheable;
import org.springframework.cache.annotation.CacheConfig;

public class SessionManager {
    private final Map<String, Session> cache = new HashMap<>();
    private final ExternalSessionService externalSessionService;
    private final int DEFAULT_SESSION_TIMEOUT_IN_MINUTES;
    private final int SESSION_EXTENSION_WINDOW_IN_MINUTES;

    public SessionManager(ExternalSessionService externalSessionService) {
        this.externalSessionService = externalSessionService;
        this.DEFAULT_SESSION_TIMEOUT_IN_MINUTES = 30; // default session timeout in minutes
        this.SESSION_EXTENSION_WINDOW_IN_MINUTES = 10; // window to extend the session
    }

    @Cacheable(value = "session-cache", key = "#sessionKey")
    public Session getSession(String sessionKey) {
        return cache.get(sessionKey);
    }

    public void createSession(String userId, String data) {
        try {
            String sessionId = externalSessionService.createSession(userId, data);
            cache.put(sessionId, new Session(userId, data));
        } catch (Exception e) {
            // handle exception
        }
    }

    public void updateSession(String sessionKey, String data) {
        try {
            externalSessionService.updateSession(sessionKey, data);
            cache.get(sessionKey).setData(data);
        } catch (Exception e) {
            // handle exception
        }
    }

    public void deleteSession(String sessionKey) {
        try {
            externalSessionService.deleteSession(sessionKey);
            cache.remove(sessionKey);
        } catch (Exception e) {
            // handle exception
        }
    }

    public boolean extendSession(String sessionKey, String data) {
        try {
            long expirationTime = externalSessionService.extendSession(sessionKey, data);
            Session session = cache.get(sessionKey);
            if (session != null && System.currentTimeMillis() < expirationTime) {
                return true;
            } else {
                return false; // session not found or expired
            }
        } catch (Exception e) {
            // handle exception
        }
    }

    public boolean isValidSession(String sessionKey) {
        try {
            long expirationTime = externalSessionService.getExpirationTime(sessionKey);
            Session session = cache.get(sessionKey);
            if (session != null && System.currentTimeMillis() < expirationTime) {
                return true;
            } else {
                return false; // session not found or expired
            }
        } catch (Exception e) {
            // handle exception
        }
    }

    public void manageSessionTimeouts() {
        try {
            externalSessionService.manageSessionTimeouts(DEFAULT_SESSION_TIMEOUT_IN_MINUTES, SESSION_EXTENSION_WINDOW_IN_MINUTES);
        } catch (Exception e) {
            // handle exception
        }
    }

    private class Session {
        String userId;
        String data;

        public Session(String userId, String data) {
            this.userId = userId;
            this.data = data;
        }
    }
}

@CacheConfig(cacheManager = "caffeineCache")
public interface ExternalSessionService {
    String createSession(String userId, String data);
    void updateSession(String sessionKey, String data);
    void deleteSession(String sessionKey);
    long getExpirationTime(String sessionKey);
    void manageSessionTimeouts(int defaultTimeoutInMinutes, int extensionWindowInMinutes);
}
```

