    private async Task UploadFileAsync(byte[] decryptedFileContent, string bucketName, string filePath)
    {
        try
        {
            // Upload the file to AWS S3, Azure Blob Storage, or Google Cloud Storage
            if (bucketName.Contains("s3", StringComparison.OrdinalIgnoreCase))
            {
                using (AmazonS3Client s3 = new AmazonS3Client())
                {
                    PutObjectRequest request = new PutObjectRequest(bucketName, filePath, decryptedFileContent);
                    await s3.PutObjectAsync(request);
                }
            }
            else if (bucketName.Contains("blob", StringComparison.OrdinalIgnoreCase))
            {
                using (AzureBlobService service = new AzureBlobService())
                {
                    BlobClient blob = service.GetBlobClient(bucketName, filePath);
                    await blob.UploadAsync(new MemoryStream(decryptedFileContent), override: true);
                }
            }
            else
            {
                // Upload to Google Cloud Storage
                using (GoogleCloudStorage storage = new GoogleCloudStorage())
                {
                    await storage.UploadObjectAsync(bucketName, filePath, decryptedFileContent);
                }
            }

            return;
        }
        catch (Exception ex)
        {
            throw;
        }
    }
