#include <fstream>
#include <iostream>
#include <stdexcept>

size_t safeFileAppend(const char* filePath, const char* buffer) {
    if (!filePath || strlen(filePath) >= 4096) {
        std::cerr << "Invalid file path: " << filePath << std::endl;
        return -1;
    }

    std::ofstream file(filePath, std::ios_base::app);
    if (!file) {
        std::cerr << "Failed to open file for appending: " << filePath << std::endl;
        return -1;
    }

    size_t bytesWritten = 0;
    try {
        bytesWritten = file.write(buffer, strlen(buffer));
    } catch (const std::ios_base::failure& e) {
        std::cerr << "Error writing to file: " << e.what() << std::endl;
        return -1;
    }

    file.close();
    if (!file) {
        std::cerr << "Failed to close file after appending: " << filePath << std::endl;
        return -1;
    }

    return bytesWritten;
}
