const { promisify } = require('util');
const fs = require('fs');
const path = require('path');
const api = require('external-file-management-api');

// Define a promise wrapper for the file read operation
const readFileAsync = promisify(fs.readFile);

// Define the function to process files asynchronously
async function processFiles(dirPath) {
  if (!fs.existsSync(dirPath)) {
    return Promise.reject(new Error(`Directory ${dirPath} does not exist`));
  }

  const apiFetch = promisify(api.fetchFileMetadata).bind(api);
  let results = [];

  // Traverse the directory recursively and process files
  async function traverseDir(currentDir) {
    try {
      const dirContents = await fs.readdir(currentDir);

      for (const file of dirContents) {
        const filePath = path.join(currentDir, file);
        const stats = await fs.stat(filePath);

        if (stats.isDirectory()) {
          // Recursively process subdirectories
          await traverseDir(filePath);
        } else {
          try {
            // Validate the file extension and skip invalid files
            const fileExt = path.extname(file).toLowerCase();
            if (!fileExt || !['.txt', '.md', '.json'].includes(fileExt)) {
              console.error(`Invalid file extension: ${file}`);
              continue;
            }

            // Read the file contents asynchronously
            const fileContent = await readFileAsync(filePath, 'utf8');

            try {
              // Fetch metadata about the file using the external API
              const metaData = await apiFetch(filePath);
              if (!metaData) {
                console.error(`Failed to fetch metadata for ${file}`);
              }

              // Process the file content and metadata together
              results.push({ filePath, fileContent, ...metaData });
            } catch (err) {
              console.error(`Error processing file: ${file} - ${err.message}`);
            }
          } catch (err) {
            console.error(`Error reading file: ${filePath} - ${err.message}`);
          }
        }
      }
    } catch (err) {
      console.error(`Error traversing directory: ${currentDir} - ${err.message}`);
    }
  }

  await traverseDir(dirPath);

  return results;
}
