    public function getProfile($user_id) {
        // Check if user profile is cached
        if ($cached_profile = $this->cache->get($user_id)) {
            return $cached_profile;
        }

        // Fetch latest profile from database
        $profile_data = // query database for user profile data

        // Cache the fetched profile
        $this->cache->set($user_id, $profile_data);

        return $profile_data;
