    public function updateProfile(array $profile) {
        // Handle nested updates (e.g., addresses or phone numbers)
        foreach ($profile as $key => $value) {
            if (is_array($value)) {
                foreach ($value as $sub_key => $sub_value) {
                    $profile[$key][$sub_key] = $sub_value;
