const { Kafka } = require('kafkadriver');
const { BlobServiceClient } = require('@azure/storage-blob');
const { Pool } = require('pg');

// Initialize Kafka consumer
const kafka = new Kafka({
  clientId: 'data-pipeline',
  brokers: ['localhost:9092'],
});

// Initialize Azure Blob Storage client
const blobServiceClient = new BlobServiceClient(
  `https://<storage_account>.blob.core.windows.net`,
);

// Initialize PostgreSQL database connection pool
const dbPool = new Pool({
  user: '<database_username>',
  host: '<database_host>',
  database: '<database_name>',
  password: '<database_password>',
  port: 5432,
});

// Define data processing pipeline function
async function processStream(stream) {
  try {
    // Read and concatenate data chunks from the stream
    const chunks = [];
    for await (const chunk of stream) {
      chunks.push(chunk.toString());
    }
    const concatenatedData = chunks.join('');

    // Store data in PostgreSQL database
    await dbPool.query(`INSERT INTO data_stream VALUES ($1, $2)`, [stream.name, concatenatedData]);

    // Upload data to Azure Blob Storage
    const blobClient = blobServiceClient.getBlockBlobClient(stream.name);
    await blobClient.uploadData(concatenatedData);

  } catch (error) {
    console.error('Error processing stream:', error);
  }
}

// Define Kafka consumer group and process incoming data streams
kafka.consumer({
  groupId: 'data-pipeline-group',
}).subscribe({
  topics: [
    {
      topic: 'iot-data-streams',
      partition: 0,
    },
  ],
}, (error, messages) => {
  if (error) {
    console.error('Error consuming Kafka messages:', error);
  } else {
    for (const message of messages) {
      processStream(message.value);
    }
  }
});

// Define error handling mechanism
kafka.on('error', (error) => {
  console.error('Kafka error:', error);
});

dbPool.on('error', (error) => {
  console.error('PostgreSQL error:', error);
});

blobServiceClient.on('error', (error) => {
  console.error('Azure Blob Storage error:', error);
});
