                    var bytesRead = fs.Read(buffer, 0, buffer.Length);
                    while (bytesRead > 0)
                    {
                        var cryptoTransform = decryptor.TransformFinalBlock(buffer, 0, bytesRead);
                        bytesRead = fs.Read(buffer, 0, buffer.Length);
                    }
                }
            }

            // Upload decrypted file to cloud storage
            using (var uploadStream = new MemoryStream())
            {
                var buffer = new byte[1024 * 1024]; // Adjust chunk size as needed
                var bytesRead = 0;
                while ((readBytes = uploadStream.Read(buffer, 0, buffer.Length)) > 0)
                {
                    await uploadStream.WriteAsync(buffer, 0, readBytes);
