```rust
use std::path::{Path, PathBuf};
use std::fs::File;
use std::io::Write;
use log::{info, warn};

// External dependencies for lexer and parser
extern crate lexer;
extern crate parser;

// LLVM IR generation and optimization
use llvm_ir::LLVMIR;
use optimize::{optimize_ast, apply_passes};

// Command-line interface
use clap::{App, Arg};

fn main() {
    // CLI options
    let matches = App::new("Compiler")
        .version("1.0")
        .author("Your Name")
        .about("Generates LLVM IR code from a given file path")
        .arg(
            Arg::with_name("input")
                .help("Input file path")
                .required(true)
                .index(1),
        )
        .arg(
            Arg::with_name("output-format")
                .help("Output format (e.g., verbose, compact)")
                .short("o")
                .takes_value(true),
        )
        .arg(
            Arg::with_name("debug-mode")
                .help("Enable debug mode for detailed logging and tracing")
                .short("d")
                .takes_value(false),
        )
        .get_matches();

    // Get the input file path
    let input_file = PathBuf::from(matches.value_of("input").unwrap());

    // Initialize the lexer, parser, and optimization pipeline
    let mut lexer = lexer::Lexer::new(input_file);
    let mut parser = parser::Parser::new(&mut lexer);
    let ast = parser.parse();
    let optimized_ast = optimize_ast(ast);

    // Apply custom passes for optimization (if enabled)
    if matches.is_present("debug-mode") {
        apply_passes(&optimized_ast, &["pass1", "pass2"]);
    }

    // Generate LLVM IR code
    let llvm_ir = LLVMIR::new();
    let output = match matches.value_of("output-format") {
        Some("verbose") => llvm_ir.generate_verbose(optimized_ast),
        Some("compact") => llvm_ir.generate_compact(optimized_ast),
        _ => panic!("Invalid output format"),
    };

    // Write the generated LLVM IR code to a file
    let output_file = Path::new("output.ll");
    File::create(output_file).unwrap().write_all(&output).unwrap();

    info!("Compilation complete. Output written to {}.", output_file.display());
}

