<?php

class OAuthClient {
    private $clientId;
    private $clientSecret;
    private $redirectUri;
    private $tokenEndpoint;
    private $userinfoEndpoint;

    public function __construct($clientId, $clientSecret, $redirectUri, $tokenEndpoint, $userinfoEndpoint) {
        $this->clientId = $clientId;
        $this->clientSecret = $clientSecret;
        $this->redirectUri = $redirectUri;
        $this->tokenEndpoint = $tokenEndpoint;
        $this->userinfoEndpoint = $userinfoEndpoint;
    }

    public function authenticate($code, $state) {
        if ($state !== $_SESSION['state']) {
            throw new Exception('Invalid state');
        }

        $authUrl = 'https://example.com/oauth/authorize';
        $tokenUrl = $this->tokenEndpoint;

        try {
            $tokenResponse = json_decode(file_get_contents($tokenUrl . '?grant_type=authorization_code&code=' . $code . '&redirect_uri=' . $this->redirectUri), true);
            if (isset($tokenResponse['access_token'])) {
                $_SESSION['access_token'] = $tokenResponse['access_token'];
                return $this->getuserinfo();
            }
        } catch (Exception $e) {
            // log error
            throw $e;
        }

        return null;
    }

    public function getuserinfo() {
        if (!isset($_SESSION['access_token'])) {
            return null;
        }

        try {
            $response = json_decode(file_get_contents($this->userinfoEndpoint . '?access_token=' . $_SESSION['access_token']), true);
            if (isset($response['recent_activity_logs']) && isset($response['preferences'])) {
                return array('logs' => $response['recent_activity_logs'], 'preferences' => $response['preferences']);
            }
        } catch (Exception $e) {
            // log error
            throw $e;
        }

        return null;
    }

    public function refreshToken() {
        if (!isset($_SESSION['access_token'])) {
            return null;
        }

        try {
            $tokenResponse = json_decode(file_get_contents($this->tokenEndpoint . '?grant_type=refresh_token&refresh_token=' . $_SESSION['access_token']), true);
            if (isset($tokenResponse['access_token'])) {
                $_SESSION['access_token'] = $tokenResponse['access_token'];
                return $this->getuserinfo();
            }
        } catch (Exception $e) {
            // log error
            throw $e;
        }

        return null;
    }

    public function handleTokenExpiration() {
        if (!isset($_SESSION['access_token'])) {
            return;
        }

        try {
            $tokenResponse = json_decode(file_get_contents($this->tokenEndpoint . '?grant_type=refresh_token&refresh_token=' . $_SESSION['access_token']), true);
            if (isset($tokenResponse['access_token'])) {
                $_SESSION['access_token'] = $tokenResponse['access_token'];
            }
        } catch (Exception $e) {
            // log error
            throw $e;
        }
    }

    public function getThirdPartyData() {
        try {
            $response = json_decode(file_get_contents('https://example.com/third-party-api'), true);
            return array('logs' => $response['recent_activity_logs'], 'preferences' => $response['preferences']);
        } catch (Exception $e) {
            // log error
            throw $e;
        }
    }
}

$oauthClient = new OAuthClient(
    'your_client_id',
