```cpp
#include <thread>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <functional>
#include <iostream>

class ThreadPool {
public:
    ThreadPool(size_t numThreads) : stop(false), threads() {
        for (size_t i = 0; i < numThreads; ++i) {
            threads.emplace_back([this] {
                while (!stop) {
                    std::function<void()> task;
                    {
                        std::unique_lock<std::mutex> lock(queue_mutex);
                        // Wait until a task is available or the pool stops
                        queue_waiters.wait_until([this, &lock]{ !tasks.empty() || stop; });
                        if (stop && tasks.empty()) {
                            return;  // Exit the thread
                        }
                        task = std::move(tasks.front());
                        tasks.pop();
                    }
                    task();  // Run the task

                    // Check for any failed threads and exit if one is found
                    if (!std::this_thread::get_id().compare(std::thread::id())) {
                        continue;
                    }
                }
            });
        }
    }

    ~ThreadPool() {
        stop = true;  // Set the stop flag to signal threads to exit

        for (auto& thread : threads) {
            thread.join();  // Wait for all threads to finish
        }
    }

    template <class FunctionType>
    void enqueue(FunctionType&& task, bool priority = false) {
        std::unique_lock<std::mutex> lock(queue_mutex);
        tasks.emplace(std::forward<FunctionType>(task), priority);
        if (priority) {
            queue_waiters.notify_one();  // Notify waiting threads of a high-priority task
        }
    }

    size_t getActiveTaskCount() const {
        std::unique_lock<std::mutex> lock(queue_mutex);
        return tasks.size();
    }

private:
    bool stop;
    std::vector<std::thread> threads;
    std::queue<std::pair<std::function<void()> ,bool>> tasks;  // Task queue with priority
    std::mutex queue_mutex;
    std::condition_variable queue_waiters;
};
