        int attempts = 0;
        while (attempts < RETRY_ATTEMPTS) {
            try {
                // implement retry logic here
                break;
            } catch (Exception rethrowable) {
                if (attempts >= RETRY_ATTEMPTS - 1) {
                    throw rethrowable; // exhaust all retries and rethrow the exception
                }
                attempts++;
                long backoff = BACKOFF_MILLIS * (long) Math.pow(2, attempts);
                try {
                    Thread.sleep(backoff);
                } catch (InterruptedException ie) {
                    Thread.currentThread().interrupt();
                }
            }
        }
