import json
import smtplib
from email.mime.multipart import MIMEMultipart
from email.mime.text import MIMEText
from email.mime.application import MIMEApplication
import logging
from concurrent.futures import ThreadPoolExecutor, as_completed
import time

class NotificationService:
    def __init__(self, config_file):
        self.config = json.load(open(config_file))
        self.smtp_server = smtplib.SMTP(self.config['smtp_host'], self.config['smtp_port'])
        self.sender_credentials = (self.config['sender_email'], self.config['sender_password'])

    def send_notification(self, email_config):
        message = MIMEMultipart()
        message['From'] = self.sender_credentials[0]
        message['To'] = email_config['recipient']
        message['Subject'] = email_config.get('subject', 'No subject provided')

        body_text = MIMEText(email_config['body'], 'plain')
        message.attach(body_text)

        if 'attachment' in email_config:
            attachment = MIMEApplication(email_config['attachment'])
            attachment.add_header('Content-Disposition', 'attachment', filename=email_config['attachment'].name)
            message.attach(attachment)

        try:
            self.smtp_server.sendmail(*self.sender_credentials, message.as_string())
        except Exception as e:
            logging.error(f"Failed to send notification: {e}")

    def send_notification_async(self, email_config):
        with ThreadPoolExecutor(max_workers=10) as executor:
            future = executor.submit(self.send_notification, email_config)
            try:
                result = future.result(timeout=30)
            except Exception as e:
                logging.error(f"Failed to send notification: {e}")

    def rate_limit(self):
        if 'rate_limit' in self.config and self.config['rate_limit']:
            last_send_time = self.config.get('last_send_time')
            if last_send_time is not None and time.time() - last_send_time < 60:
                logging.info("Rate limit reached, waiting for 1 minute before sending again")
                time.sleep(60)
        else:
            return

    def retry(self):
        max_retries = self.config.get('max_retries', 3)
        retries = 0
        while retries < max_retries:
            try:
                self.send_notification(email_config)
                break
            except Exception as e:
                logging.error(f"Failed to send notification: {e}")
                retries += 1
                if retries == max_retries:
                    logging.error("Maximum number of retries reached, skipping notification")
                    return

if __name__ == "__main__":
    service = NotificationService('config.json')
    email_config = {'recipient': 'recipient@example.com', 'body': 'Notification body'}
    service.send_notification_async(email_config)
