// Set up Climate API client
const climateApiClient = new climateApi({ apikey: 'YOUR_API_KEY' });

// Route for weather data
app.get('/weather', async (req, res) => {
  const location = req.query.location;
  try {
    const currentWeather = await openWeatherMapClient.currentWeather(location);
    const forecast = await openWeatherMapClient.forecast(location, { days: 7 });
    res.json({ currentWeather, forecast });
  } catch (error) {
    console.error(error);
    res.status(500).send('Error fetching weather data');
  }
});

// Route for climate data
app.get('/climate', async (req, res) => {
  const location = req.query.location;
  try {
    const climateData = await climateApiClient.climateData(location);
    res.json(climateData);
  } catch (error) {
    console.error(error);
    res.status(500).send('Error fetching climate data');
  }
});

// Route for historical climate events
app.get('/climate-events', async (req, res) => {
  const location = req.query.location;
  try {
    const events = await climateApiClient.climateEvents(location);
    res.json(events);
  } catch (error) {
    console.error(error);
    res.status(500).send('Error fetching climate events');
  }
});

// Route for statistics
app.get('/statistics', async (req, res) => {
  const location = req.query.location;
  try {
    const stats = await climateApiClient.statistics(location, { months: 12 });
    res.json(stats);
  } catch (error) {
    console.error(error);
    res.status(500).send('Error fetching statistics');
  }
});

// Error handling and logging
app.use((err, req, res, next) => {
  console.error(err);
  res.status(500).send('Error occurred');
});

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    const opensslStatus = await opensslLib.check();
    if (!opensslStatus) {
      throw new Error('OpenSSL library not initialized');
    }
    res.json({ status: 'ok' });
  } catch (error) {
    console.error(error);
    res.status(500).send('Error checking health');
  }
});

// Start server
const port = 3000;
app.listen(port, () => {
  console.log(`Server started on port ${port}`);
});
