#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>
#include <unistd.h>
#include <sys/types.h>
#include <fcntl.h>

#include "magickWand/magickWand.h"
#include "magickWand/decorateImage.h"

#define MAX_DIR 256
#define MAX_FILE_NAME 1024

int main(int argc, char **argv) {
    const char *inputDir = "images";
    const char *outputDir = "output";
    int maxImagesPerPDF = 10;
    int numWorkerThreads = 2;

    // Parse command-line arguments
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-i") == 0) inputDir = argv[i + 1];
        else if (strcmp(argv[i], "-o") == 0) outputDir = argv[i + 1];
        else if (strcmp(argv[i], "-m") == 0) maxImagesPerPDF = atoi(argv[i + 1]);
        else if (strcmp(argv[i], "-t") == 0) numWorkerThreads = atoi(argv[i + 1]);
    }

    // Initialize MagickWand
    MagickWandGenesis();
    Image *images[10];
    int imagesCount = 0;

    DIR *dir;
    struct dirent *ent;
    struct stat sb;

    dir = opendir(inputDir);
    if (dir != NULL) {
        while ((ent = readdir(dir)) != NULL) {
            if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0)
                continue;
            char filePath[MAX_DIR + MAX_FILE_NAME];
            sprintf(filePath, "%s/%s", inputDir, ent->d_name);
            if (stat(filePath, &sb) != -1 && S_ISREG(sb.st_mode)) {
                images[imagesCount] = NewImage();
                ReadImageFile(images[imagesCount], filePath);
                imagesCount++;
            }
        }
        closedir(dir);
    }

    // Convert and merge images to PDF
    for (int i = 0; i < imagesCount; i++) {
        // Add image to the list of images in the current page
        if ((i + 1) % maxImagesPerPDF == 0 || i == imagesCount - 1) {
            // Flush the last page and create a new one
            MagickMorphImages();
            Image *page = NewImage();
            for (int j = i; j >= 0 && j >= i - maxImagesPerPDF; j--)
                CompositeImage(page, images[j]);
            WriteImageFile(page, outputDir);
        }
    }

    // Free resources and clean up
    for (int i = 0; i < imagesCount; i++) {
        DestroyImage(images[i]);
    }
    MagickWandTerminus();

    return 0;
}
