struct SensorData {
    float value;
    int deviceID;
};

class MinMaxAlgorithm {
public:
    void findMinMax(std::vector<SensorData>& data, float& minVal, float& maxVal) {
        if (data.empty()) return;

        minVal = data[0].value;
        maxVal = data[0].value;

        for (const auto& datum : data) {
            if (datum.value < minVal) minVal = datum.value;
            if (datum.value > maxVal) maxVal = datum.value;
        }
    }
};

class Logger {
public:
    void log(const std::string& message) {
        // Log to file or database for auditing purposes
    }

