    if (!file.is_open()) {
        Logger().error("File not found");
        return -1;
    }

    MinMaxAlgorithm minMax;
    float minVal, maxVal;

    while (file >> minVal >> maxVal) { // process data in-place
        std::vector<SensorData> sensorData;  // assuming custom file format has deviceID and value

        for (; file >> minVal >> maxVal;) {
            SensorData datum = {minVal, 0};  // assuming 0 as default deviceID
            sensorData.push_back(datum);
        }

        if (sensorData.empty()) break;

        minMax.findMinMax(sensorData, minVal, maxVal);

        // write statistics to another file
    }

    return 0;
}
