    private Map<String, Configuration> cache = new HashMap<>();
    private static final String CONFIGURATION_SCHEMA = "schema.txt";
    private static final int MAX_CACHE_SIZE = 100;
    private static final int FILE_READ_BUFFER_SIZE = 1024;

    public Configuration loadConfiguration(String filePath) {
        if (cache.containsKey(filePath)) {
            return cache.get(filePath);
        }

        File file = new File(filePath);

        if (!file.exists()) {
            System.out.println("File not found: " + filePath);
            return null;
        }

        try (
                ObjectInputStream ois = new ObjectInputStream(new FileInputStream(file));
                ) {

            Configuration config = (Configuration) ois.readObject();
            validateConfiguration(config, filePath);

            cache.put(filePath, config);
            if (cache.size() > MAX_CACHE_SIZE) {
                cache.remove(cache.keySet().iterator().next());
            }

            return config;

        } catch (Exception e) {
            System.out.println("Error loading configuration: " + e.getMessage());
            return null;
        }
