```java
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.atomic.AtomicInteger;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.web.reactive.function.BodyInserters;
import org.springframework.web.reactive.function.client.WebClient;

@Configuration
public class PokemonServiceConfig {

    @Bean
    public WebClient webClient() {
        return WebClient.builder()
                .baseUrl("https://pokeapi.co/api/v2/")
                .build();
    }

    @Bean
    public Map<String, Pokemon> pokemonCache() {
        return new HashMap<>();
    }

    @Bean
    public AtomicInteger concurrentRequestCount() {
        return new AtomicInteger(0);
    }
}

import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;

public class PokemonController {

    private final WebClient webClient;
    private final Map<String, Pokemon> pokemonCache;
    private final AtomicInteger concurrentRequestCount;

    @Autowired
    public PokemonController(WebClient webClient, Map<String, Pokemon> pokemonCache, AtomicInteger concurrentRequestCount) {
        this.webClient = webClient;
        this.pokemonCache = pokemonCache;
        this.concurrentRequestCount = concurrentRequestCount;
    }

    @GetMapping("/pokemon/{id}")
    public ResponseEntity<PokemonDetails> getPokemon(@PathVariable String id) {
        if (!pokemonCache.containsKey(id)) {
            incrementConcurrentRequestCount();
            Pokemon pokemon = webClient.get().uri("pokemon/{0}", id)
                    .retrieve()
                    .bodyToMono(Pokemon.class)
                    .block();

            // Process and store Pokemon details
            PokemonDetails pokemonDetails = new PokemonDetails(pokemon);
            pokemonCache.put(id, pokemon);

            return ResponseEntity.status(HttpStatus.OK).body(pokemonDetails);
        } else {
            incrementConcurrentRequestCount();
            return ResponseEntity.status(HttpStatus.OK).body(new PokemonDetails(pokemonCache.get(id)));
        }
    }

    private void incrementConcurrentRequestCount() {
        concurrentRequestCount.incrementAndGet();
    }
}

