Here is the C# code for the function that securely computes MD5 hash of a file, verifies it against an external API, handles errors, and provides progress reporting:
```csharp
using System;
using System.IO;
using System.Net;
using System.Security.Cryptography;
using System.Threading;
using System.Threading.Tasks;

public class FileHasher
{
    private readonly IExternalApiVerifier _apiVerifier;
    private readonly IFileDownloader _fileDownloader;
    private readonly ICredentialsProvider _credentialsProvider;
    private readonly IProgressReporter _progressReporter;

    public FileHasher(IExternalApiVerifier apiVerifier, IFileDownloader fileDownloader, ICredentialsProvider credentialsProvider, IProgressReporter progressReporter)
    {
        _apiVerifier = apiVerifier;
        _fileDownloader = fileDownloader;
        _credentialsProvider = credentialsProvider;
        _progressReporter = progressReporter;
    }

    public async Task<FileHashResult> ComputeAndVerifyHashAsync(string filePathOrUrl, int minFileSizeLimit, int maxFileSizeLimit, DateTime? modifiedDateRangeStart, DateTime? modifiedDateRangeEnd)
    {
        FileHashResult result = new FileHashResult();

        // Check file size and last modified date
        if (IsFileExcluded(filePathOrUrl, minFileSizeLimit, maxFileSizeLimit, modifiedDateRangeStart, modifiedDateRangeEnd))
            return result;

        try
        {
            // Download file from SFTP/FTP or read local file
            Stream fileStream = await _fileDownloader.DownloadFileAsync(filePathOrUrl);

            // Compute MD5 hash in chunks to handle large files efficiently
            using (var md5 = MD5.Create())
            {
                byte[] buffer = new byte[1024 * 16];
                int bytesRead;
                long fileSize = fileStream.Length;

                using (var ms = new MemoryStream())
                {
                    while ((bytesRead = fileStream.Read(buffer, 0, buffer.Length)) > 0)
                    {
                        md5.TransformBlock(buffer, 0, bytesRead);
                        ms.Write(buffer, 0, bytesRead);
                    }

                    // Finish the hash computation
                    byte[] hashBytes = md5.Hash;
                    string hashString = BitConverter.ToString(hashBytes).Replace("-", "").ToLower();

                    result.FileHash = hashString;

                    // Verify hash against API
                    if (await _apiVerifier.VerifyHashAsync(hashString))
                    {
                        result.VerificationStatus = VerificationStatus.Success;
                    }
                    else
                    {
                        result.VerificationStatus = VerificationStatus.Failure;
                    }
                }
            }

            fileStream.Dispose();
        }
        catch (Exception ex)
        {
            // Log error and notify user
            _progressReporter.LogError(ex);
            result.ErrorOccurred = true;
        }

        return result;
    }

    private bool IsFileExcluded(string filePathOrUrl, int minFileSizeLimit, int maxFileSizeLimit, DateTime? modifiedDateRangeStart, DateTime? modifiedDateRangeEnd)
    {
        // Check file size and last modified date
        FileInfo fileInfo = new FileInfo(filePathOrUrl);

        if (fileInfo.Length < minFileSizeLimit || fileInfo.Length > maxFileSizeLimit)
            return true;

        if (modifiedDateRangeStart.HasValue && fileInfo.LastAccessTime < modifiedDateRangeStart.Value)
            return true;

        if (modifiedDateRangeEnd.HasValue && fileInfo.LastAccessTime > modifiedDateRangeEnd.Value)
            return true;

        return false;
    }
}

public class FileHashResult
{
    public string FileHash { get; set; }
    public VerificationStatus VerificationStatus { get; set; }
    public bool ErrorOccurred { get; set; }
}

public enum VerificationStatus { Success, Failure }
```
