use async_trait::async_trait;

#[derive(Debug)]
enum Request {
    Get { url: String },
    Post { url: String, data: Vec<u8> },
}

#[async_trait]
trait API {
    async fn send(&self, request: &Request) -> Result<String, String>;
}

struct APIHandler<T>(T)
where
    T: 'static + Send + Sync + API;

impl<T> API for APIHandler<T>
where
    T: 'static + Send + Sync + API,
{
    async fn send(&self, request: &Request) -> Result<String, String> {
        self.0.send(request).await
    }
}

struct Cache(HashMap<String, Vec<u8>>);

impl Cache {
    async fn new() -> Self {
        Self(HashMap::new())
    }

    async fn get(&mut self, key: &str) -> Option<&Vec<u8>> {
        self.0.get(key).cloned()
    }

    async fn put(&mut self, key: &str, data: Vec<u8>) {
        self.0.insert(key.to_string(), data);
    }
}

