from flask_caching import Cache
from flask_marshmallow import Marshmallow
from flask_httpauth import HTTPBasicAuth

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:////tmp/test.db'
db = SQLAlchemy(app)
cache = Cache(app, config={'CACHE_TYPE': 'SimpleCache'})
marshmallow = Marshmallow(app)

auth = HTTPBasicAuth()

class Department(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(100), nullable=False)
    employees = db.relationship('Employee', backref='department')
    projects = db.relationship('Project', backref='department')

class Employee(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(100), nullable=False)
    department_id = db.Column(db.Integer, db.ForeignKey('department.id'))
    projects = db.relationship('Project', backref='employee')

class Project(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(100), nullable=False)
    department_id = db.Column(db.Integer, db.ForeignKey('department.id'))
    employee_id = db.Column(db.Integer, db.ForeignKey('employee.id'))

class DepartmentSchema(marshmallow.Schema):
    class Meta:
        fields = ('id', 'name')

class EmployeeSchema(marshmallow.Schema):
    class Meta:
        fields = ('id', 'name')

class ProjectSchema(marshmallow.Schema):
    class Meta:
        fields = ('id', 'name')

@app.route('/departments', methods=['GET'])
@auth.login_required
def get_departments():
    departments = Department.query.all()
    return jsonify(DepartmentSchema(many=True).dump(departments))

@app.route('/departments/<int:department_id>', methods=['GET'])
@auth.login_required
def get_department(department_id):
    department = Department.query.get_or_404(department_id)
    return jsonify(DepartmentSchema().dump(department))

@app.route('/employees', methods=['GET'])
@auth.login_required
def get_employees():
    employees = Employee.query.all()
    return jsonify(EmployeeSchema(many=True).dump(employees))

@app.route('/projects', methods=['GET'])
@auth.login_required
def get_projects():
    projects = Project.query.all()
    return jsonify(ProjectSchema(many=True).dump(projects))

@app.route('/departments/<int:department_id>', methods=['PUT'])
@auth.login_required
def update_department(department_id):
    department = Department.query.get_or_404(department_id)
    data = request.get_json()
    department.name = data['name']
    db.session.commit()
    return jsonify(DepartmentSchema().dump(department))

@app.route('/employees/<int:employee_id>', methods=['PUT'])
@auth.login_required
def update_employee(employee_id):
    employee = Employee.query.get_or_404(employee_id)
    data = request.get_json()
    if 'name' in data:
        employee.name = data['name']
    db.session.commit()
    return jsonify(EmployeeSchema().dump(employee))

@app.route('/projects/<int:project_id>', methods=['PUT'])
@auth.login_required
def update_project(project_id):
    project = Project.query.get_or_404(project_id)
    data = request.get_json()
    if 'name' in data:
        project.name = data['name']
    db.session.commit()
    return jsonify(ProjectSchema().dump(project))

@app.route('/departments/<int:department_id>', methods=['DELETE'])
@auth.login_required
def delete_department(department_id):
    department = Department.query.get_or_404(department_id)
    if not department.projects:
        db.session.delete(department)
        db.session.commit()
        return jsonify({'message': 'Department deleted successfully'})
    else:
        return jsonify({'error': 'Cannot delete department with active projects'}), 400

@app.route('/employees/<int:employee_id>', methods=['DELETE'])
@auth.login_required
def delete_employee(employee_id):
    employee = Employee.query.get_or_404(employee_id)
    db.session.delete(employee)
    db.session.commit()
    return jsonify({'message': 'Employee deleted successfully'})

@app.route('/projects/<int:project_id>', methods=['DELETE'])
