import requests
from cachetools import TTLCache
from datetime import datetime, timedelta
from pytz import timezone, localize

# Set the time zone for the application
TIME_ZONE = 'US/Eastern'

# Define a list of companies to fetch stock data for
COMPANIES = ['AAPL', 'GOOGL', 'AMZN']

# Create a cache with a maximum size and time-to-live (TTL)
API_CACHE = TTLCache(maxsize=100, ttl=60)  # 1 minute TTL

def get_stock_data(company):
    api_url = f'https://api.example.com/{company}/stock'
    try:
        response = requests.get(api_url)
        if response.status_code == 200:
            return response.json()
        else:
            raise Exception('Failed to fetch stock data')
    except requests.exceptions.RequestException as e:
        print(f'Error fetching {company} stock data: {e}')
        return None

def get_localized_time():
    tz = timezone(TIME_ZONE)
    now = datetime.now(tz)
    return localize(now, is_dst=True)

def main():
    total_api_requests = 0
    cache_hits = 0
    cache_misses = 0

    for company in COMPANIES:
        start_time = get_localized_time()

        if company not in API_CACHE or API_CACHE.get(company)['last_updated'] < start_time - timedelta(minutes=1):
            # Fetch stock data from the API and store it in the cache
            stock_data = get_stock_data(company)
            total_api_requests += 1

            if stock_data is None:
                continue

            API_CACHE[company] = {'data': stock_data, 'last_updated': start_time}
            cache_misses += 1
        else:
            # Retrieve stock data from the cache
            cache_hits += 1

        print(f'Company: {company}, Stock Data: {API_CACHE.get(company)["data"]}')

    print(f'Total API requests: {total_api_requests}')
    print(f'Cache hits: {cache_hits}')
    print(f'Cache misses: {cache_misses}')

if __name__ == '__main__':
    main()
