```java
import io.jsonwebtoken.Jwt;
import io.jsonwebtoken.JwtException;
import io.jsonwebtoken.Jwts;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.annotation.Bean;
import org.springframework.security.authentication.AuthenticationManager;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.authority.SimpleAuthorityTuple;
import org.springframework.security.core.userdetails.UserDetails;
import org.springframework.security.core.userdetails.UserDetailsService;
import org.springframework.security.oauth2.common.OAuth2AccessToken;
import org.springframework.security.oauth2.provider.AuthenticationProvider;
import org.springframework.security.oauth2.provider.OAuth2Authentication;
import org.springframework.security.oauth2.provider.token.TokenStore;
import org.springframework.web.bind.annotation.*;
import java.util.ArrayList;
import java.util.List;

@RestController
@RequestMapping("/api/v1/auth")
public class AuthenticationController {

    private final TokenStore tokenStore;
    private final UserDetailsService userDetailsService;
    private final AuthenticationManager authenticationManager;

    @Autowired
    public AuthenticationController(TokenStore tokenStore, UserDetailsService userDetailsService, AuthenticationManager authenticationManager) {
        this.tokenStore = tokenStore;
        this.userDetailsService = userDetailsService;
        this.authenticationManager = authenticationManager;
    }

    @PostMapping("/login")
    public OAuth2Authentication login(@RequestBody LoginRequest request) throws Exception {
        UsernamePasswordAuthenticationToken authenticationToken = new UsernamePasswordAuthenticationToken(request.getUsername(), request.getPassword());
        Authentication authenticate = authenticationManager.authenticate(authenticationToken);
        return (OAuth2Authentication) tokenStore.createAccessToken(authenticate);
    }

    @PostMapping("/register")
    public User register(@RequestBody RegisterRequest request) throws Exception {
        // Create a new user and generate a verification code
        String verificationCode = UUID.randomUUID().toString();
        User user = userService.createUser(request.getUsername(), request.getEmail(), verificationCode);

        // Send the verification code to the user via email or SMS
        notificationService.sendVerificationCode(user, verificationCode);

        return user;
    }

    @PostMapping("/verify")
    public void verify(@RequestBody VerifyRequest request) throws Exception {
        User user = userService.getUserByUsername(request.getUsername());
        if (user != null && user.getVerificationCode().equals(request.getVerificationCode())) {
            // Verify the user
            userService.activateUser(user);
        } else {
            throw new Exception("Invalid verification code");
        }
    }

    @PostMapping("/forgot-password")
    public void forgotPassword(@RequestBody ForgotPasswordRequest request) throws Exception {
        User user = userService.getUserByUsername(request.getUsername());
        if (user != null) {
            // Send a password reset link to the user via email
            notificationService.sendPasswordResetLink(user);
        } else {
            throw new Exception("User not found");
        }
    }

    @PostMapping("/reset-password")
    public void resetPassword(@RequestBody ResetPasswordRequest request) throws Exception {
        User user = userService.getUserByUsername(request.getUsername());
        if (user != null) {
            // Update the user's password
            userService.updateUserPassword(user, request.getNewPassword());
        } else {
            throw new Exception("User not found");
        }
    }

    @GetMapping("/logout")
    public void logout(@RequestHeader OAuth2AccessToken accessToken) throws Exception {
        tokenStore.removeToken(accessToken.getValue());
    }
}

