import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.regex.Pattern;
import java.util.concurrent.*;

public class FileProcessor {
    private static final Logger logger = LoggerFactory.getLogger(FileProcessor.class);
    private static final int THREAD_POOL_SIZE = 5;

    public void processFiles(String directoryPath, List<String> keywords, String reportFormat) throws InterruptedException, ExecutionException {
        // Create a thread pool
        ExecutorService executor = Executors.newFixedThreadPool(THREAD_POOL_SIZE);

        // Get the files in the directory and sort them by modification time
        File[] files = new File(directoryPath).listFiles();
        Arrays.sort(files, Comparator.comparingLong(File::lastModified));

        // Process each file asynchronously
        List<Future<String>> futures = new ArrayList<>();
        for (File file : files) {
            if (!file.isFile()) continue;
            Future<String> future = executor.submit(() -> processFile(file, keywords, reportFormat));
            futures.add(future);
        }

        // Wait for all tasks to complete and get the results
        List<String> results = new ArrayList<>();
        for (Future<String> future : futures) {
            try {
                results.add(future.get());
            } catch (InterruptedException | ExecutionException e) {
                logger.error("Error processing file", e);
            }
        }

        // Close the thread pool
        executor.shutdown();

        // Upload the reports to the API and send notifications
        uploadReportsAndNotify(results);
    }

    private String processFile(File file, List<String> keywords, String reportFormat) throws InterruptedException {
        try (BufferedReader reader = Files.newBufferedReader(Paths.get(file.getAbsolutePath()))) {
            StringBuilder content = new StringBuilder();
            for (String line; (line = reader.readLine()) != null;) {
                if (matchesKeywords(line, keywords)) {
                    content.append(line).append("\n");
                }
            }

            // Generate the report
            String report = generateReport(content.toString(), reportFormat);

            return report;
        } catch (IOException e) {
            logger.error("Error reading file: " + file.getAbsolutePath(), e);
            return null;
        }
    }

    private boolean matchesKeywords(String line, List<String> keywords) {
        for (String keyword : keywords) {
            if (Pattern.matches(keyword, line)) {
                return true;
            }
        }
        return false;
    }

    private String generateReport(String content, String reportFormat) {
        // Implement your reporting API integration here
        // ...
    }

    private void uploadReportsAndNotify(List<String> reports) {
        // Upload the reports to the API and send notifications
        for (String report : reports) {
            // ...
        }
    }
}
