#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Record {
    int unique_id;
    double offset;
    char* key;
} Record;

Record* read_file(const char* filename, int* count) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        return NULL;
    }

    *count = 0;
    Record* records = NULL;

    while (1) {
        Record record;
        fscanf(file, "%d %lf %s\n", &record.unique_id, &record.offset, &record.key);
        record.key = (char*)malloc(strlen(record.key) + 1);
        strcpy(record.key, record.key);

        if (!records) {
            records = (Record*)malloc(sizeof(Record));
            *count = 1;
        } else {
            Record* temp = (Record*)malloc(sizeof(Record));
            temp->unique_id = record.unique_id;
            temp->offset = record.offset;
            temp->key = (char*)malloc(strlen(record.key) + 1);
            strcpy(temp->key, record.key);

            records = (Record*)realloc(records, sizeof(Record) * (*count + 1));
            records[*count - 1] = record;
            records[*count] = temp;
            (*count)++;
        }

        if (feof(file)) {
            break;
        }
    }

    fclose(file);
    return records;
}

double calculate_average_offset_key(Record* records, int count) {
    double total_offset = 0.0;
    double total_key = 0.0;

    for (int i = 0; i < count; i++) {
        total_offset += records[i].offset;
        total_key += strlen(records[i].key);
    }

    return (total_offset + total_key) / (count * 2);
}
