```php
<?php

function read_file($filename, &$records_count) {
    $file = fopen($filename, "r");
    if (!$file) {
        return array();
    }

    $records_count = 0;
    $records = array();

    while (1) {
        $record = new Record();
        fscanf($file, "%d %lf %s\n", $record->unique_id, $record->offset, $record->key);
        $record->key = strval($record->key);

        if (!isset($records[0])) {
            $records[] = array("unique_id" => $record->unique_id, "offset" => $record->offset, "key" => $record->key);
            $records_count = 1;
        } else {
            $temp = array("unique_id" => $record->unique_id, "offset" => $record->offset, "key" => $record->key);
            $records[] = $temp;

            $records_count++;
        }

        if (feof($file)) {
            break;
        }
    }

    fclose($file);
    return $records;
}

function calculate_average_offset_key($records) {
    $total_offset = 0.0;
    $total_key = 0.0;

    foreach ($records as $record) {
        $total_offset += $record["offset"];
        $total_key += strlen($record["key"]);
    }

    return ($total_offset + $total_key) / (count($records) * 2);
}

class Record {
    public $unique_id;
    public $offset;
    public $key;
}

?>
