```csharp
using UnityEngine;

public class DynamicValueGenerator : MonoBehaviour
{
    private int distributionType;
    private float[] parameters;

    public void SetDistribution(int type, float[] params)
    {
        distributionType = type;
        parameters = params;
    }

    public float GenerateRandomFloat(float min, float max)
    {
        switch (distributionType)
        {
            case 0:
                return UnityEngine.Random.Range(min, max);
            case 1: // Gaussian
                float mean = parameters[0];
                float stddev = parameters[1];
                return NormalDistribution(min, max, mean, stddev);
            case 2: // Uniform
                float range = max - min;
                return min + (range * UnityEngine.Random.value);
            case 3: // Exponential
                float lambda = parameters[0];
                return -Mathf.Log(UnityEngine.Random.value) / lambda + min;
            default:
                throw new ArgumentException("Invalid distribution type");
        }
    }

    public int GenerateRandomInt(int min, int max)
    {
        switch (distributionType)
        {
            case 0:
                return UnityEngine.Random.Range(min, max).ToInt();
            case 1: // Gaussian
                float mean = parameters[0];
                float stddev = parameters[1];
                return (int)NormalDistribution(min, max, mean, stddev);
            case 2: // Uniform
                float range = max - min;
                return Mathf.Round((range * UnityEngine.Random.value) + min).ToInt();
            case 3: // Exponential
                float lambda = parameters[0];
                return Mathf.Floor(-Mathf.Log(UnityEngine.Random.value) / lambda + min);
            default:
                throw new ArgumentException("Invalid distribution type");
        }
    }

    private float NormalDistribution(float min, float max, float mean, float stddev)
    {
        float u1 = UnityEngine.Random.value;
        float u2 = UnityEngine.Random.value;
        float r = Mathf.Sqrt(-2.0f * Mathf.Log(u1)) * Mathf.Cos(2.0f * Mathf.PI * u2);
        return mean + r * stddev;
    }
}
