int processNfarCrcIndications(NFAPI_CRC_INDICATION_PDU_T ***crcList, size_t *listSize, int maxStructures, FILE *logFile, RAN_SYS_API_T *ranSysApi) {
    int result = 0;
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    while (1) {
        // Fetch new CRC indication PDUs from the RAN system
        NFAPI_CRC_INDICATION_PDU_T **newPdus = ranSysApi->fetch_crc_indications();

        if (!newPdus) {
            break;  // No more PDUs, exit the loop
        }

        size_t newLength = sizeof(NFAPI_CRC_INDICATION_PDU_T) * maxStructures;
        NFAPI_CRC_INDICATION_PDU_T **pduList = realloc(*crcList, (maxStructures + *listSize) * newLength);

        if (!pduList) {
            result = -1;  // Memory allocation failure
            break;
        }

        *crcList = pduList;

        for (size_t i = 0; i < maxStructures && i < *listSize; i++) {
            // Process and validate CRC indication PDUs from the RAN system
            ranSysApi->process_crc_indications(&pduList[*listSize + i]);
        }

        pthread_mutex_lock(&lock);
        *listSize += maxStructures;
        pthread_mutex_unlock(&lock);
    }

    if (result == -1) {
        // Log error and exit
        fprintf(logFile, "Memory allocation failure.\n");
        return -1;
    } else {
        return 0;  // Successful processing of CRC indication PDUs
    }
}
