using System;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Threading.Tasks;

namespace FileComparator
{
    public class FileComparator
    {
        private readonly string[] _excludedFileExtensions = { ".txt", ".docx" };

        public Dictionary<string, (string leftChecksum, string rightChecksum)> CompareDirectories(string leftDirectoryPath, string rightDirectoryPath)
        {
            var result = new Dictionary<string, (string leftChecksum, string rightChecksum)>();

            var leftFiles = Directory.GetFiles(leftDirectoryPath);
            var rightFiles = Directory.GetFiles(rightDirectoryPath);

            Parallel.ForEach(leftFiles, file =>
            {
                if (_excludedFileExtensions.Any(ext => Path.GetExtension(file) == ext))
                    return;

                try
                {
                    string leftChecksum = CalculateFileChecksum(file);
                    result.Add(file, (leftChecksum, null));
                }
                catch (IOException)
                {
                    // Handle I/O exceptions
                }
            });

            Parallel.ForEach(rightFiles, file =>
            {
                if (_excludedFileExtensions.Any(ext => Path.GetExtension(file) == ext))
                    return;

                try
                {
                    string rightChecksum = CalculateFileChecksum(file);
                    foreach (var pair in result)
                    {
                        if (pair.Key == file)
                            pair.Value = (pair.Value.leftChecksum, rightChecksum);
                    }
                }
                catch (IOException)
                {
                    // Handle I/O exceptions
                }
            });

            return result;
        }

        public string CalculateFileChecksum(string filePath)
        {
            using var stream = File.OpenRead(filePath);
            using var hashAlgorithm = SHA256.Create();
            byte[] checksumBytes = new byte[hashAlgorithm.HashSize / 8];
            using var memoryStream = new MemoryStream();
            CopyTo(stream, memoryStream);
            memoryStream.Position = 0;
            byte[] buffer = new byte[4096];
            int bytesRead;
            while ((bytesRead = memoryStream.Read(buffer, 0, buffer.Length)) > 0)
            {
                hashAlgorithm.ComputeBlock(buffer, 0, bytesRead);
            }
            hashAlgorithm.WaitForPendingOperations();
            return BitConverter.ToString(hashAlgorithm.HashValue).Replace("-", string.Empty);
        }

        private void CopyTo(Stream input, Stream output)
        {
            var buffer = new byte[4096];
            int bytesRead;
            while ((bytesRead = input.Read(buffer, 0, buffer.Length)) > 0)
            {
                output.Write(buffer, 0, bytesRead);
            }
        }
    }
}
