import aiohttp
from typing import List, Dict, Any

async def process_images(image_urls: List[str], 
                          initial_status: str = 'pending', 
                          callback: callable = None,
                          max_retries: int = 3) -> Dict[str, str]:
    if not isinstance(image_urls, list):
        raise ValueError("Invalid input. Please provide a list of image URLs.")
    if not all(isinstance(url, str) for url in image_urls):
        raise ValueError("All elements in the input list must be strings.")

    async def process_image(session: aiohttp.ClientSession, 
                             image_url: str) -> Dict[str, str]:
        try:
            async with session.get(image_url) as response:
                if response.status == 200:
                    return {'status': 'success', 'image_url': image_url}
                else:
                    raise Exception(f"Failed to process {image_url}. Status code: {response.status}")
        except (aiohttp.ClientError, Exception):
            for _ in range(max_retries):
                try:
                    async with session.get(image_url) as response:
                        if response.status == 200:
                            return {'status': 'success', 'image_url': image_url}
                        else:
                            raise
                except (aiohttp.ClientError, Exception):
                    pass
            return {'status': 'failed', 'image_url': image_url}

    async with aiohttp.ClientSession() as session:
        tasks = [process_image(session, url) for url in image_urls]
        results = await asyncio.gather(*tasks)
        processed_status = {}
        for result in results:
            if isinstance(result, dict):
                processed_status.update({url: status['status'] 
                                         for url, status in zip(image_urls, results) 
                                         if status == result})
            else:
                processed_status[url] = 'failed'
        return processed_status
