import os
import hashlib
from concurrent.futures import ThreadPoolExecutor
from cloudstorageapi import CloudStorageService
from datetime import datetime

class ImageProcessor:
    def __init__(self, directory_path, cloud_storage_service):
        self.directory_path = directory_path
        self.cloud_storage_service = cloud_storage_service
        self.cache = {}

    def process_directory(self):
        with ThreadPoolExecutor() as executor:
            futures = {executor.submit(self.process_image, os.path.join(self.directory_path, f)) for f in os.listdir(self.directory_path)}
            for future in futures:
                future.result()

    def process_image(self, file_path):
        if not self.cloud_storage_service.authenticate():
            raise Exception("Authentication failed")

        image_hash = self.compute_sha256_hash(file_path)
        metadata = {
            "file_name": os.path.basename(file_path),
            "file_size": os.path.getsize(file_path),
            "last_modified_date": datetime.fromtimestamp(os.path.getmtime(file_path)).isoformat()
        }

        if image_hash not in self.cache:
            self.cache[image_hash] = {}
            self.cache[image_hash]["metadata"] = metadata
            self.upload_to_cloud_storage(image_hash, metadata)

    def compute_sha256_hash(self, file_path):
        with open(file_path, 'rb') as f:
            return hashlib.sha256(f.read()).hexdigest()

    def upload_to_cloud_storage(self, image_hash, metadata):
        while True:
            try:
                self.cloud_storage_service.upload(image_hash, metadata)
                break
            except Exception as e:
                if e.code == 429:  # Rate limit exceeded
                    time.sleep(1)  # Wait for 1 second before retrying
                else:
                    raise e

    def filter_images(self):
        return lambda file_path: True  # Default filtering mechanism

    def run(self, filter_function=None):
        if filter_function is None:
            filter_function = self.filter_images()

        with ThreadPoolExecutor() as executor:
            futures = {executor.submit(self.process_image, os.path.join(self.directory_path, f)) for f in os.listdir(self.directory_path) if filter_function(os.path.join(self.directory_path, f))}
            for future in futures:
                future.result()
