import os
import json
import requests
from flask import Flask, request, jsonify
from flask_caching import Cache

app = Flask(__name__)
cache = Cache(app, config={'CACHE_TYPE': 'SimpleCache'})

class RealTimeStockMiddleware:
    def __init__(self):
        self.stocks = {}
        self.news = {}
        self.cached_quotes = cache.cache.get('cached_quotes', {})
        self.cached_news = cache.cache.get('cached_news', {})

    def get_quote(self, symbol):
        if symbol in self.cached_quotes:
            return self.cached_quotes[symbol]
        response = requests.get(f'https://api.alphavantage.co/query?function=GLOBAL_QUOTE&symbol={symbol}&apikey=YOUR_API_KEY')
        quote = json.loads(response.text)['Global Quote']
        self.cached_quotes[symbol] = quote
        cache.set('cached_quotes', self.cached_quotes, timeout=3600)
        return quote

    def get_news(self, symbol):
        if symbol in self.cached_news:
            return self.cached_news[symbol]
        response = requests.get(f'https://newsapi.org/v2/top-headlines?country=us&category=business&apikey=YOUR_API_KEY')
        news = json.loads(response.text)['articles']
        self.cached_news[symbol] = news
        cache.set('cached_news', self.cached_news, timeout=3600)
        return news

    def update_quote(self, symbol):
        response = requests.post(f'https://api.alphavantage.co/query?function=REALTIME_QUOTE&symbol={symbol}&apikey=YOUR_API_KEY')
        quote = json.loads(response.text)['Realtime Quote']
        self.stocks[symbol] = quote
        return quote

    def get_stock(self, symbol):
        if symbol in self.stocks:
            return self.stocks[symbol]
        response = requests.get(f'https://www.quandl.com/api/v3/datasets/FINRA/DSH.{}.json?start_date=2020-01-01&end_date=2022-12-31&limit=100&order=asc&hydrate=quote,candlestick&api_key=YOUR_API_KEY')
        stock = json.loads(response.text)['dataset']
        self.stocks[symbol] = stock
        return stock

    def __str__(self):
        status = 'OK'
        if len(self.cached_quotes) > 10:
            status = 'WARNING: Cache is getting large, consider clearing it soon.'
        elif len(self.cached_news) > 5:
            status = 'WARNING: News cache is getting large, consider clearing it soon.'
        return f'RealTimeStockMiddleware ({status}) - Stock quotes: {len(self.stocks)} - Cached quotes: {len(self.cached_quotes)} - News: {len(self.cached_news)}'

@app.route('/stock_quote', methods=['GET'])
def get_stock_quote():
    symbol = request.args.get('symbol')
    if not symbol:
        return jsonify({'error': 'Symbol is required'}), 400
    quote = middleware.get_quote(symbol)
    return jsonify(quote)

@app.route('/news', methods=['GET'])
def get_news():
    symbol = request.args.get('symbol')
    if not symbol:
        return jsonify({'error': 'Symbol is required'}), 400
    news = middleware.get_news(symbol)
    return jsonify(news)

@app.route('/update_quote', methods=['POST'])
def update_stock_quote():
    symbol = request.form.get('symbol')
    if not symbol:
        return jsonify({'error': 'Symbol is required'}), 400
    quote = middleware.update_quote(symbol)
    return jsonify(quote)

if __name__ == '__main__':
    middleware = RealTimeStockMiddleware()
    app.run(debug=True)
