        {
            // Retrieve user validation rules from the external API
            var rules = _configService.GetConfig();

            // Cache the retrieved rules for a configurable time-to-live (TTL)
            _cacheService.SetCacheExpiration(rules, 300); // 5 minutes

            return Ok(rules);
        }

