import java.util.*;
import java.io.IOException;
import java.net.*;

public class RealTimeDataSync {
    private static final int DEFAULT_SYNC_INTERVAL = 1000; // default sync interval in milliseconds
    private static final int MAX_CACHE_SIZE = 100000; // maximum cache size in bytes
    private static final int CACHE_EXPIRATION_SECONDS = 300; // default cache expiration time in seconds

    private volatile Map<String, String> cache = new ConcurrentHashMap<>();
    private ScheduledExecutorService scheduler;
    private RestApiClient restApiClient;

    public RealTimeDataSync(int syncInterval, int cacheSize) {
        this.scheduler = Executors.newScheduledThreadPool(1);
        this.restApiClient = new RestApiClient();

        // configure data synchronization interval
        if (syncInterval > 0) {
            DEFAULT_SYNC_INTERVAL = syncInterval;
        }

        // configure cache size and expiration time
        if (cacheSize > 0 && cacheSize < MAX_CACHE_SIZE) {
            MAX_CACHE_SIZE = cacheSize;
        }
        if (CACHE_EXPIRATION_SECONDS > 0) {
            CACHE_EXPIRATION_SECONDS = cacheSize;
        }
    }

    public void start() {
        scheduler.scheduleWithFixedDelay(() -> syncData(), 0, DEFAULT_SYNC_INTERVAL, TimeUnit.MILLISECONDS);
    }

    private void syncData() {
        // retrieve data from external API
        String data = restApiClient.getData();

        // process and cache the data
        if (data != null && !data.isEmpty()) {
            for (String key : data.split(",")) {
                String value = ...; // process the data here
                cache.put(key, value);
            }
        }

        // update cache expiration time based on data freshness and frequency of updates
        long now = System.currentTimeMillis();
        for (Map.Entry<String, String> entry : cache.entrySet()) {
            if (now - Long.parseLong(entry.getValue().split(":")[1]) > CACHE_EXPIRATION_SECONDS * 1000) {
                cache.remove(entry.getKey());
            }
        }
    }

    public static void main(String[] args) {
        RealTimeDataSync app = new RealTimeDataSync(DEFAULT_SYNC_INTERVAL, MAX_CACHE_SIZE);
        app.start();
    }
}
