using System;
using System.IO;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.Logging;

namespace MiddlewareComponent
{
    public class CompressionMiddleware
    {
        private readonly RequestDelegate _next;
        private readonly ILogger<CompressionMiddleware> _logger;
        private readonly IHttpClientFactory _httpClientFactory;
        private readonly ICacheService _cacheService;
        private readonly IRateLimiter _rateLimiter;

        public CompressionMiddleware(RequestDelegate next, 
                                      ILogger<CompressionMiddleware> logger,
                                      IHttpClientFactory httpClientFactory,
                                      ICacheService cacheService,
                                      IRateLimiter rateLimiter)
        {
            _next = next;
            _logger = logger;
            _httpClientFactory = httpClientFactory;
            _cacheService = cacheService;
            _rateLimiter = rateLimiter;
        }

        public async Task InvokeAsync(HttpContext context)
        {
            if (context.Request.Method == "POST")
            {
                string body = await new StreamReader(context.Request.Body).ReadToEndAsync();
                byte[] bytes = Encoding.UTF8.GetBytes(body);

                // Compress data using selected algorithm
                CompressionAlgorithm compressionAlgorithm;
                try
                {
                    compressionAlgorithm = _cacheService.GetCompressionAlgorithm();
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Failed to retrieve compression algorithm");
                    return;
                }

                byte[] compressedBytes = await CompressData(bytes, compressionAlgorithm);

                // Send compressed data to remote server
                try
                {
                    using var client = _httpClientFactory.CreateClient();
                    using var request = new HttpRequestMessage(HttpMethod.Post, "https://remoteserver.com/api/update")
                    {
                        Content = new ByteArrayContent(compressedBytes)
                    };

                    await _rateLimiter.WaitAndExecute(() => client.SendAsync(request));
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Failed to send compressed data");
                }
            }

            await _next(context);
        }

        private async Task<byte[]> CompressData(byte[] bytes, CompressionAlgorithm algorithm)
        {
            // Implement compression logic using selected algorithm
        }
    }

    public enum CompressionAlgorithm { GZIP, DEFLATE, LZ4 };

    public interface ICacheService
    {
