import json
from typing import List, Dict
import boto3

def bulk_user_operations(request_payload: List[Dict], auth_service: str):
    dynamodb = boto3.resource('dynamodb').Table('user_profiles')

    response_list = []

    for user in request_payload:
        sub_action = user.get('sub_action', 'create')

        if sub_action == 'delete':
            try:
                user_id = int(user['user_id'])
                dynamodb.delete_item(Key={'id': user_id})
                response_list.append({'status': 'success', 'message': f"User profile {user_id} deleted successfully"})
            except KeyError as e:
                response_list.append({'status': 'error', 'message': f"'user_id' key missing in request: {e}"})
            except Exception as e:
                response_list.append({'status': 'error', 'message': f"Error deleting user profile: {e}"})
        else:
            try:
                if 'user_id' not in user or user['user_id'] is None:
                    # Create new user
                    try:
                        auth_service.verify_user(user)
                        dynamodb.put_item(Item=user)
                        response_list.append({'status': 'success', 'message': f"User profile created successfully"})
                    except Exception as e:
                        response_list.append({'status': 'error', 'message': f"Error creating user profile: {e}"})
                else:
                    # Update existing user
                    try:
                        auth_service.verify_user(user)
                        dynamodb.update_item(Key={'id': int(user['user_id'])}, UpdateExpression="set first_name = :fn, last_name = :ln", ExpressionAttributeValues={":fn": user.get('first_name', ''), ":ln": user.get('last_name', '')})
                        response_list.append({'status': 'success', 'message': f"User profile updated successfully"})
                    except KeyError as e:
                        response_list.append({'status': 'error', 'message': f"'user_id' key missing in request: {e}"})
                    except Exception as e:
                        response_list.append({'status': 'error', 'message': f"Error updating user profile: {e}"})
            except Exception as e:
                response_list.append({'status': 'error', 'message': f"Error processing user profile: {e}"})

    return json.dumps(response_list)
