    {
        using (var ms = new MemoryStream())
        {
            var bestCompression = BestCompressionAlgorithm(data);
            using (var compressionStream = bestCompression.Streams[0])
            {
                compressionStream.SetLength(0);
                using (var cs = new Compression(compressionStream))
                {
                    cs.Write(data, 0, data.Length);
                    cs.Flush();
                }
                var encryptedData = EncryptDataAsync(bestCompression.CompressedBytes, timeout).Result;
                using (var ns = new NetworkStream())
                {
                    try
                    {
