    private CompressionAlgorithm BestCompressionAlgorithm(byte[] data)
    {
        var algorithms = new List<CompressionAlgorithm>();
        algorithms.Add(new GZip());
        algorithms.Add(new Deflate());
        algorithms.Add(new BZip2());

        var bestRatio = double.MinValue;
        var bestAlgorithm = default(CompressionAlgorithm);

        foreach (var algorithm in algorithms)
        {
            using (var ms = new MemoryStream())
            {
                using (var cs = new Compression(ms))
                {
                    cs.Write(data, 0, data.Length);
                    cs.Flush();
                }
                if (ms.Length < bestRatio * data.Length)
                {
                    bestRatio = (double)ms.Length / data.Length;
                    bestAlgorithm = algorithm;
                }
            }
        }

        return bestAlgorithm;
    }

    public enum CompressionAlgorithm
    {
        GZip,
        Deflate,
        BZip2
    }
