def log_message(message, level='INFO'):
    if environ.get('LOG_SYSTEM') == 'syslog':
        logging.getLogger().addHandler(SysLogHandler(address=('localhost', 514)))
    elif environ.get('LOG_SYSTEM') == 'fluentd':
        logging.getLogger().addHandler(FluentdHandler())
    elif environ.get('LOG_SYSTEM') == 'elasticsearch':
        logging.getLogger().addHandler(ElasticsearchHandler(index='your_index'))
    logger = logging.getLogger()
    if level == 'INFO':
        logger.info(message)
    elif level == 'ERROR':
