use std::fs::{self, File};
use std::io::{Read, Write};
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};
use std::time::Instant;
use rustc_driver::{catch_with_exit_code, Driver};
use synclazy::SyncLazy;

struct CompilationReport {
    compilation_time: u128,
    resident_set_size_before: usize,
    resident_set_size_after: usize,
    warnings_and_errors: Vec<String>,
    ice_hook_status: Vec<SyncLazyResult>,
}

impl std::fmt::Debug for CompilationReport {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        writeln!(f, "Compilation Report:\n")?;
        writeln!(f, "  Compilation time: {} ms\n", self.compilation_time as f64 / 1e6)?;
        writeln!(f, "  Resident set size before: {}\n", self.resident_set_size_before)?;
        writeln!(f, "  Resident set size after: {}\n", self.resident_set_size_after)?;
        writeln!(f, "  Warnings and errors:\n")?;
        for warning_or_error in &self.warnings_and_errors {
            writeln!(f, "    {}", warning_or_error)?;
        }
        writeln!(f, "  Ice hook status:\n")?;
        for (index, result) in self.ice_hook_status.iter().enumerate() {
            writeln!(f, "    Hook #{}: {:?}", index + 1, result)?;
        }
        Ok(())
    }
}

async fn compile_and_install_ice_hooks(
    paths: Vec<PathBuf>,
    ice_hooks: Vec<SyncLazy<String>>,
) -> CompilationReport {
    let mut compilation_report = CompilationReport {
        compilation_time: 0,
        resident_set_size_before: ruamel::sys::get_rss(),
        warnings_and_errors: vec![],
        ice_hook_status: vec![],
    };

    for path in paths {
        let mut file = File::open(&path).unwrap();
        let mut contents = String::new();
        file.read_to_string(&mut contents).unwrap();

        let start = Instant::now();
        match rustc_driver::catch_with_exit_code(|driver| {
            driver.compile_file(&contents, &["-Z", "unstable"], None);
        }) {
            Ok(()) => {
                compilation_report.compilation_time += (start.elapsed().as_millis() as u128);
                compilation_report.resident_set_size_after = ruamel::sys::get_rss();
            }
            Err(err) => {
                compilation_report.warnings_and_errors.push(format!("Compilation failed with error: {err}"));
            }
        }

        for ice_hook in &ice_hooks {
            match SyncLazy::new(ice_hook.clone()) {
                Ok(_) => {
                    compilation_report.ice_hook_status.push("Success");
                }
                Err(err) => {
                    compilation_report.ice_hook_status.push(format!("Failure: {err}"));
                }
            }
        }
    }

    compilation_report
}

#[tokio::main]
async fn main() {
    let paths = vec!["path/to/file1.rs", "path/to/file2.rs", /* ... */];
    let ice_hooks = vec![
        SyncLazy::new("ice-hook-1".to_string()),
        SyncLazy::new("ice-hook-2".to_string()),
        // ...
    ];

    let report = compile_and_install_ice_hooks(paths, ice_hooks).await;
    println!("Compilation Report:\n{}", report);
}
