    public class DynamicLogAnalyzer
    {
        private readonly BlockingCollection<LogEntry> _logEntries = new BlockingCollection<LogEntry>();
        private readonly ConcurrentDictionary<string, DistributionConfig> _distributions = new ConcurrentDictionary<string, DistributionConfig>();
        private readonly ConcurrentQueue<LogEntry> _filteredLogEntries = new ConcurrentQueue<LogEntry>();
        private readonly object _syncLock = new object();
        private string _currentDistribution;
        private double _currentThreshold;

        public DynamicLogAnalyzer(string logFilePath)
        {
            _logFilePath = logFilePath;
        }

        public async Task AnalyzeAsync()
        {
            using var reader = File.OpenRead(_logFilePath);
            using var streamReader = new StreamReader(reader.BaseStream);

            while (await streamReader.ReadLineAsync() != null)
            {
                var logEntry = ParseLogEntry(streamReader);
                _logEntries.Add(logEntry);
            }

            foreach (var logEntry in _logEntries.GetConsumingEnumerable())
            {
                if (_distributions.TryGetValue(_currentDistribution, out var distributionConfig))
                {
                    if (distributionConfig.Distribution(distributionConfig.Parameter) < _currentThreshold)
                    {
                        _filteredLogEntries.Enqueue(logEntry);
                    }
                }
            }

            foreach (var logEntry in _filteredLogEntries.GetConsumingEnumerable())
            {
                Console.WriteLine(logEntry);
            }
        }

