            lock (_syncLock)
            {
                if (!_distributions.TryGetValue(distributionName, out var distributionConfig))
                {
                    throw new ArgumentException($"Unsupported distribution: {distributionName}");
                }

                _currentDistribution = distributionName;
                _currentThreshold = threshold;
