#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* modifyFileName(const char* originalFilename) {
    int len = strlen(originalFilename);

    // Check if the input filename is valid
    if (len == 0 || !isalnum(originalFilename, len)) {
        return "Invalid filename. Please enter a valid file name.";
    }

    // Extract the base name and the original extension from the filename
    char* basePath = strtok(originalFilename, ".");
    const char* ext = strrchr(originalFilename, '.');

    if (!ext) {
        // If no extension is found, set it to an empty string
        ext = "";
    } else {
        // Move the pointer back to the start of the extension
        ext--;
    }

    int numDigits = 0;
    for (int i = 0; i < len && numDigits <= 4; ++i) {
        if (isdigit(originalFilename[i])) {
            ++numDigits;
        } else {
            break;
        }
    }

    // Determine the new extension dynamically
    char* newExt = "txt";
    if (numDigits == 3) {
        newExt = "jpg";
    } else if (numDigits == 4) {
        newExt = "png";
    } else if (numDigits > 0) {
        // Truncate the filename to keep only the first 5 digits and append "bmp"
        char* truncatedPath = malloc((len - numDigits + strlen("bmp") + 1) * sizeof(char));
        sprintf(truncatedPath, "%.*s.bmp", len - numDigits, originalFilename);
        free(basePath);
        basePath = truncatedPath;
    }

    // Create the new filename
    char* modifiedFilename = malloc((len + strlen(newExt) + 1) * sizeof(char));
    if (basePath) {
        sprintf(modifiedFilename, "%s.%s", basePath, newExt);
    } else {
        strcpy(modifiedFilename, newExt);
    }

    // Free the original memory
    free(basePath);

    return modifiedFilename;
}

// Helper function to check if a string contains only allowed characters (alphanumeric)
int isalnum(const char* str, int len) {
    for (int i = 0; i < len; ++i) {
        if (!isalnum((unsigned char)str[i])) {
            return 0;
        }
    }
    return 1;
}
