import xml.etree.ElementTree as ET
import time
import logging
from collections import defaultdict

def fileParserAndProcessor(file_path, namespace_dict=None):
    start_time = time.time()

    try:
        tree = ET.parse(file_path)
        root = tree.getroot()

        if namespace_dict is not None:
            for ns, uri in namespace_dict.items():
                ET.register_namespace(ns, uri)

        data_processor = defaultdict(list)

        def process_node(node):
            if node.text and node.text.strip():
                data_processor['text'].append(node.text.strip())
            if node.attrib:
                data_processor['attrs'].extend([f"{key}={value}" for key, value in node.attrib.items()])
            for child in node:
                process_node(child)

        def validate_node(node):
            # Add your custom validation logic here
            return True

        def match_xpath(node, xpath_expr):
            try:
                return ET.XPath(xpath_expr)(node)
            except ET.XPathEvalError:
                return False

        def process_xml_node(node):
            if node is None:
                return
            if namespace_dict is not None:
                for ns in ET.ElementTree(root).find_namespace_info():
                    node.set(f"{{{ns}}}namespace", f"http://{ns}")

            if match_xpath(node, "//node[@match='true']") and validate_node(node):
                data_processor['nodes'].append({
                    'tag': node.tag,
                    'text': ''.join([child.text for child in node]),
                    'attrs': dict(node.attrib)
                })

        process_xml_node(root)

    except ET.ParseError as e:
        logging.error(f"Error parsing XML file: {e}")
    except Exception as e:
        logging.error(f"An error occurred: {e}")

    end_time = time.time()
    logging.info(f"Processing took {end_time - start_time} seconds.")

    return list(data_processor.values())
