public class FileProcessor {
    private static final int MAX_CONTENT_LENGTH = 500;
    private static final int RETRY_COUNT = 3;

    public void processFileQueue(ConcurrentLinkedQueue<String> fileQueue) throws Exception {
        for (String filePath : fileQueue) {
            try {
                if (!fileExists(filePath)) continue; // Skip non-existent files

                // Create a new linked list node
                MetadataNode metadataNode = createMetadataNode(new File(filePath));
                BackwardLinkedList backwardList = new BackwardLinkedList();

                int retryCount = 0;
                while (true) {
                    try {
                        byte[] fileContent = getFileContent(filePath);
                        String content = new String(fileContent, "UTF-8");

                        // Truncate the content if it's too long
                        if (content.length() > MAX_CONTENT_LENGTH) {
                            content = content.substring(content.length() - MAX_CONTENT_LENGTH);
                        }

                        backwardList.insert(new FileNode(content, metadataNode));
                        break; // Successfully processed the file
                    } catch (Exception e) {
                        if (++retryCount >= RETRY_COUNT) {
                            throw new Exception("Failed to process file after " + RETRY_COUNT + " retries: " + filePath);
                        }

                        // Retry failed operation
                        try {
                            Thread.sleep(1000); // Pause for 1 second before retrying
                        } catch (InterruptedException ex) {
                            // Handle interrupt exception
                        }
                    }
                }
            } catch (Exception e) {
                throw new Exception("Error processing file queue: " + e.getMessage());
            }
        }
