fn compile_file(path: &str) -> i32 {
    let start = Instant::now();
    let mut command = Command::new("rustc");
    command.arg("-Zcustom-logging-hook");

    let output = command.output().expect("Failed to execute process");

    let exit_code = output.status.code().unwrap_or(-1);
    let duration = start.elapsed();

    println!("{} compiled in {:.2?}", path, duration);

    if let Some(max_rss) = max_rss() {
        let current_rss = rss();
        if current_rss > max_rss {
            eprintln!("Ress exhausted, terminating process");
            return -1;
        }
    }

    let server_api = get_build_server_api();
    report_compilation_status(&server_api, path, exit_code);

