using System;
using System.IO;
using System.Runtime.Serialization.Formatters.Binary;
using System.Threading;

namespace BinaryFileLoader
{
    public class CustomDataStructure
    {
        // Define the custom data structure here
    }

    public class BinaryFileLoader
    {
        private readonly object _lock = new object();
        private readonly Dictionary<string, CustomDataStructure> _cache = new Dictionary<string, CustomDataStructure>();

        public void LoadAndDeserialize(string filePath)
        {
            try
            {
                if (!_cache.ContainsKey(filePath))
                {
                    lock (_lock)
                    {
                        if (!_cache.ContainsKey(filePath))
                        {
                            using (FileStream fileStream = File.OpenRead(filePath))
                            {
                                BinaryFormatter formatter = new BinaryFormatter();
                                CustomDataStructure dataStructure = (CustomDataStructure)formatter.Deserialize(fileStream);
                                _cache.Add(filePath, dataStructure);
                            }
                        }
                    }
                }

                // Log the load and deserialize operation
                Logger.Log("Loaded and deserialized data from file: " + filePath);
            }
            catch (Exception ex)
            {
                // Handle exceptions and log error messages
                Logger.LogError("Error loading and deserializing data from file: " + filePath, ex);
            }
        }
    }

    public class Logger
    {
        public static void Log(string message) => Console.WriteLine(message);

        public static void LogError(string message, Exception exception) => Console.WriteLine(message + ": " + exception.Message);
    }
}
