```
const { Transform, PassThrough } = require('stream');
const { once } = require('events');

function copyData(chunks, byteCount) {
  const totalByteCount = Buffer.byteLength(new Uint8Array(byteCount));
  const availableMemory = process.memoryUsage().heapUsed;
  if (totalByteCount > availableMemory) {
    console.error(`Total byte count (${totalByteCount}) exceeds available memory (${availableMemory}).`);
    return null;
  }

  class CopyDataTransform extends Transform {
    constructor() {
      super({ objectMode: true, highWaterMark: byteCount });
      this.chunks = chunks;
      this.byteCount = byteCount;
      this.totalCopied = 0;
      this.errorHandler = new PassThrough();
    }

    _transform(chunk, encoding, callback) {
      const chunkByteCount = Buffer.byteLength(new Uint8Array(chunk));
      if (this.totalCopied + chunkByteCount > this.byteCount) {
        return callback(new Error(`Chunk exceeds byte count limit`));
      }
      let bytesRead = 0;
      while (readChunk()) {
        bytesRead += readChunk().length;
        if (bytesRead >= this.byteCount) break;
      }
      const copiedChunk = Buffer.concat([...this.chunks.map((c) => c.slice(0, bytesRead))]);
      this.totalCopied = bytesRead;
      callback(null, copiedChunk);
    }

    _flush(callback) {
      callback();
    }

    _error(error) {
      if (this.errorHandler.writable) {
        this.errorHandler.write(`Error: ${error.message}`);
      }
    }
  }

  function readChunk() {
    const chunk = chunks.shift();
    if (!chunk) return null;
    if (chunk.length <= 0) return null;
    return chunk.slice(0, Math.min(chunk.length, byteCount - this.totalCopied));
  }

  const copyDataTransform = new CopyDataTransform();

  return new Promise((resolve, reject) => {
    once(copyDataTransform.on('error'), (err) => {
      if (this.errorHandler.writable) {
        this.errorHandler.write(`Error: ${err.message}`);
      }
      reject(err);
    });
    copyDataTransform.on('finish', () => resolve());
  }).then(() => {
    const result = Buffer.concat([...copyDataTransform._writableState.writeBuffer]);
    if (this.errorHandler.writable) {
      this.errorHandler.write(`Copied data: ${result.length} bytes`);
    }
    return result;
  });
}

