<?php

function updateClinicStatus($clinicId, $status) {
    try {
        // Validate input clinic ID
        if (!$clinicId || !is_numeric($clinicId)) {
            throw new Exception('Invalid clinic ID');
        }

        // Connect to database
        $db = new PDO('mysql:host=localhost;dbname=clinics', 'username', 'password');
        $db->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

        // Update clinic status
        $stmt = $db->prepare('UPDATE clinics SET status = :status WHERE id = :id');
        $stmt->execute([':id' => $clinicId, ':status' => $status]);

        // Log update event
        $logEntry = date('Y-m-d H:i:s') . ' Clinic #'.$clinicId.' updated to "'.$status.'"';
        error_log($logEntry);

    } catch (Exception $e) {
        // Handle errors and logging
        echo 'Error updating clinic status: '.$e->getMessage().'\n';
        error_log('Error updating clinic status: '.date('Y-m-d H:i:s').' - '.$e->getMessage());
    }
}

