                // Retrieve clinic ID from request
                int clinicId = request.ClinicId;

                // Connect to database using EF Core
                var dbContext = new ClinicDbContext();
                var clinic = await dbContext.Clinics.FindAsync(clinicId);

                if (clinic == null)
                {
                    throw new Exception("Clinic not found");
                }

                // Update clinic status
                clinic.Status = request.Status;

                // Save changes to database
                await dbContext.SaveChangesAsync();

                // Log update event using Serilog
                var logEvent = new LogEvent(new { ClinicId = clinicId, Status = request.Status });
                _logger.Information(logEvent);

            }
            catch (Exception ex)
            {
                // Handle errors and logging
                return BadRequest(ex.Message);
            }
        }
    }

    public class UpdateClinicStatusRequest
    {
        public string Username { get; set; }
        public string Password { get; set; }
        public int ClinicId { get; set; }
        public string Status { get; set; }
    }
