async function runModuleTests(moduleName, testCases, setUpFunction, tearDownFunction) {
  try {
    // Dynamically load the module using import statement
    const module = await import(`./${moduleName}.js`);

    // Create a new Mocha instance
    const mocha = new Mocha();

    // Run the specified test cases
    for (const testCase of testCases) {
      try {
        await setUpFunction();
        await testCase();
        await tearDownFunction();
      } catch (error) {
        console.error(`Test case "${testCase.name}" failed: ${error}`);
      }
      blueslip.reset();
    }

    // Run the module's tests
    mocha.run();

    // Log test results
    const testResults = await mocha.reporter.getResults();
    for (const result of testResults) {
      if (result.failures.length > 0 || result.errors.length > 0) {
        console.error(`Module "${moduleName}" failed: ${result.failures.map(f => f.message).join(', ')}`);
      } else {
        console.log(`Module "${moduleName}" passed`);
      }
    }
  } catch (error) {
    console.error(`Error running module tests for "${moduleName}": ${error}`);
  }
}
