// Define the Union-Find data structure for disjoint set management
class DisjointSet {
public:
    vector<int> parent;
    vector<int> rank;

    void make_set(int x) {
        parent.resize(parent.size() + 1);
        rank.resize(rank.size() + 1);
        parent[x] = x;
        rank[x] = 0;
    }

    int find(int x) {
        if (parent[x] != x)
            return find(parent[x]);
        return x;
    }

    void union_sets(int x, int y) {
        x = find(x);
        y = find(y);
        if (x == y)
            return;
        if (rank[x] > rank[y])
            parent[y] = x;
        else {
            parent[x] = y;
            if (rank[x] == rank[y])
                rank[y]++;
        }
    }

    bool is_connected(int x, int y) {
        return find(x) == find(y);
    }
};

// Define the profile update function with API integration and rate limiting
