#include "des.h"
#include "sha256.h"

typedef struct {
    char* key;
    int bits_per_sample;
} FileMetadata;

int upload_file(FileMetadata metadata, const char* file_path) {
    // Initialize DES and SHA-256
    DES_context_t des_ctx;
    init_des(&des_ctx);

    FILE* file = fopen(file_path, "rb");
    if (file == NULL) {
        return -1; // Error opening file
    }

    // Validate file metadata
    struct stat statbuf;
    fstat(fileno(file), &statbuf);
    int file_size = statbuf.st_size;

    char* file_name = get_file_name(metadata.key, metadata.bits_per_sample, file_size);
    if (file_name == NULL) {
        fclose(file);
        return -1; // Error calculating file name
    }

    // Calculate SHA-256 hash of the file
    unsigned char* file_hash;
    int hash_size = sha256_file(file, &file_hash);

    if (hash_size < 0) {
        fclose(file);
        free(file_name);
        return -1; // Error calculating hash
    }

    // Check if file already exists in the specified location
    if (check_file_exists(metadata.key, metadata.bits_per_sample, file_name)) {
        printf("File %s already exists.\n", file_name);
        fclose(file);
        free(file_name);
        return 0; // File already exists, skip upload
    }

    // Encrypt and upload the file to cloud storage
    int status = upload_to_cloud_storage(metadata.key, metadata.bits_per_sample, file, file_name);

    if (status < 0) {
        fclose(file);
        free(file_name);
        return -1; // Error uploading file
    }

    // Log successful upload
    printf("File %s uploaded successfully.\n", file_name);

    // Clean up
    fclose(file);
    free(file_name);
    free(file_hash);

    return 0;
}

int main() {
    FileMetadata metadata = {"my_key", 8};
    const char* file_path = "path/to/file";

    int status = upload_file(metadata, file_path);

    if (status < 0) {
        printf("Error uploading file.\n");
    }

    return 0;
}

