    public JsonNode getPokemonWeaknesses(int pokemonId) throws Exception {
        Call<PokemonApi.PokemonResponse> call = api.getPokemon(pokemonId);
        Response<PokemonApi.PokemonResponse> response = call.execute();
        PokemonApi.PokemonResponse pokemonResponse = response.body();

        // check for API errors
        if (response.code() >= 400) {
            return new ObjectMapper().readValue("{\"error\": \"API error\"}", JsonNode.class);
        }

        String pokemonType = pokemonResponse.getTypes().get(0).getType();
        List<String> weaknesses = pokemonResponse.getWeaknesses();

        // store weakness data in Cassandra
        CassandraSession session = CassandraSession.getInstance();
        PreparedStatement stmt = session.prepare("INSERT INTO pokemon_weaknesses (id, type, weaknesses) VALUES (?, ?, ?)");
        PooledPreparedStatement pStmt = session.execute(stmt.bind(pokemonId, pokemonType, weaknesses));
        pStmt.execute();

        // retrieve cached weakness data
        PokemonWeaknesses weaknessData = pokemonWeaknessesCache.getUnchecked(pokemonId);
        return new ObjectMapper().readValue(new Gson().toJson(weaknessData), JsonNode.class);
    }
