import logging
from collections import Counter

def process_log_files(log_file_path):
    try:
        with open(log_file_path, 'r') as log_file:
            logs = [line.strip() for line in log_file.readlines()]

        request_ids = [log.split(',')[0] for log in logs]
        timestamps = [log.split(',')[1] for log in logs]
        metrics = [log.split(',')[2:] for log in logs]

        # calculate common errors and performance bottlenecks
        error_counts = Counter(request_id for log, request_id in zip(logs, request_ids) if 'error' in log)
        bottleneck_metrics = Counter(metric[0] for metric in metrics)

        logging.info(f"Common errors: {error_counts}")
        logging.info(f"Performance bottlenecks: {bottleneck_metrics}")

    except FileNotFoundError:
        logging.error("Log file not found")
    except Exception as e:
        logging.error(f"Error processing log file: {e}")
