public void InsertAfter(string[] list, string valueToInsert, string targetValue)
{
    int index = Array.IndexOf(list, targetValue);
    if (index > -1)
    {
        Array.Insert(index + 1, valueToInsert);
    }
    else
    {
        Array.Resize(ref list, list.Length + 1);
        list[list.Length - 1] = valueToInsert;
    }
