char* validate_and_append_path(const char* path, int max_size, bool is_absolute, const char* cwd) {
    size_t required_size = strlen(path) + 1;
    if (required_size > max_size) {
        // Path exceeds the maximum buffer size
        char* error_msg = malloc(strlen("Path exceeds the maximum buffer size") + 1);
        strcpy(error_msg, "Path exceeds the maximum buffer size");
        free(error_msg);
        return NULL;
    }

    // Resolve environment variables and symbolic links
    char* resolved_path = realpath(path, NULL);
    if (resolved_path == NULL) {
        // Path not properly formatted or encountered issues with environment variable resolution or symbolic link handling
        char* error_msg = malloc(strlen("Path is not properly formatted") + 1);
        strcpy(error_msg, "Path is not properly formatted");
        free(error_msg);
        return NULL;
    }

    if (!is_absolute) {
        // Append the system's current working directory or a custom specified working directory
        size_t cwd_len = strlen(cwd);
        required_size += cwd_len + 1;
        if (required_size > max_size) {
            // Path exceeds the maximum buffer size after appending the current working directory
            char* error_msg = malloc(strlen("Path exceeds the maximum buffer size") + 1);
            strcpy(error_msg, "Path exceeds the maximum buffer size");
            free(error_msg);
            return NULL;
        }

        char* full_path = malloc(required_size);
        sprintf(full_path, "%s/%s", cwd, resolved_path);
        free(resolved_path);
        return full_path;
    }

    // Path is already absolute, just return it
    return strdup(resolved_path);
}

