function checkPasswordAndConnect(passwordInfo, conn, callbackFn) {
  if (!passwordInfo.password || passwordInfo.password.length === 0) {
    return 'Error: Password cannot be empty or NULL';
  }
  if (!conn.title) {
    return 'Error: Connection title not set';
  }
  if (!callbackFn) {
    return 'Error: Callback function is NULL';
  }

  // Load and execute the JavaScript file
  const script = document.createElement('script');
  script.src = passwordInfo.file;
  script.onload = () => {
    try {
      eval(script.textContent);
    } catch (err) {
      console.error(err);
    } finally {
      callbackFn();
    }
  };
  script.onerror = () => {
    console.error(`Error loading JavaScript file: ${passwordInfo.file}`);
    callbackFn();
  };
  document.head.appendChild(script);
}

