    private final Map<String, List<String>> fileLinesMap = new ConcurrentHashMap<>();
    private final List<File> files = new ArrayList<>();
    private final Pattern keywordPattern;

    public DistributedCache(String directoryPath) throws FileNotFoundException {
        File directory = new File(directoryPath);
        for (File file : directory.listFiles()) {
            if (file.isFile()) {
                files.add(file);
            }
        }
        keywordPattern = Pattern.compile("(?i:error|warning)");
    }

    public void updateCache() {
        // implement distributed algorithm to update cache
    }

    public List<String> readFilesAsync() {
        List<String> lines = new ArrayList<>();
        for (File file : files) {
            try (FileReader reader = new FileReader(file)) {
                int character;
                while ((character = reader.read()) != -1) {
                    lines.add(String.valueOf((char) character));
                }
            } catch (FileNotFoundException e) {
                // handle file not found exception
            }
        }
        return lines;
    }

    public List<String> searchCacheLines(String keyword) {
        List<String> matchingLines = new ArrayList<>();
        for (Map.Entry<String, String> entry : cacheMap.entrySet()) {
            Matcher matcher = keywordPattern.matcher(entry.getValue());
            while (matcher.find()) {
                matchingLines.add(entry.getKey() + ": " + matcher.group());
            }
        }
        return matchingLines;
    }

