// Structure to hold semaphore name and initial value
typedef struct {
    char *name;
    int initialValue;
} SemaphoreConfig;

// Function to create a semaphore with the specified initial value from a configuration file
sem_t* createSemaphore(SemaphoreConfig config) {
    sem_t *sem = sem_open(config.name, O_CREAT | O_RDWR, 0644, config.initialValue);
    if (sem == SEM_FAILED) {
        // Handle error and log it
        perror("Error creating semaphore");
        return NULL;
    }
    return sem;
}

// Function to delete a semaphore
int destroySemaphore(sem_t *sem) {
    int status = sem_close(sem);
    if (status != 0) {
        // Handle error and log it
        perror("Error closing semaphore");
        return -1;
    }
    status = sem_unlink(sem->sem_perm.name);
    if (status != 0) {
        // Handle error and log it
        perror("Error unlinking semaphore");
        return -1;
    }
    return 0;
}

// Function to acquire the semaphore
int acquireSemaphore(sem_t *sem) {
    int status = sem_wait(sem);
    if (status == -1) {
        // Handle error and log it
        perror("Error acquiring semaphore");
        return -1;
    }
    return 0;
}

// Function to release the semaphore
int releaseSemaphore(sem_t *sem) {
    int status = sem_post(sem);
    if (status == -1) {
        // Handle error and log it
        perror("Error releasing semaphore");
        return -1;
    }
    return 0;
}

// Function to get the current value of the semaphore
int getCurrentValue(sem_t *sem) {
    int status = sem_getvalue(sem, &value);
    if (status == -1) {
