    manageSemaphorePriorities(sem, 5);

    // Track the number of times the semaphore was acquired and released for monitoring purposes, including reporting these metrics to a remote logging server
    logSemaphoreMetrics(config);

    // Handle semaphore creation and deletion failures gracefully, logging appropriate error messages
    int status = destroySemaphore(sem);
    if (status != 0) {
