// Define the load balancing algorithm
void distribute_load(int workload) {
    // Calculate the average server workload
    int avg_workload = workload / MAX_SERVERS;

    // Distribute the load evenly among available servers
    for (int i = 0; i < MAX_SERVERS; i++) {
        Server* server = &servers[i];
        pthread_mutex_lock(&server->lock);
        if (server->available) {
            // Assign a portion of the workload to this server...
            server->available -= avg_workload;
        }
        pthread_mutex_unlock(&server->lock);
    }
}

