void insertAfterFirstOccurrence(std::forward_list<std::string>& list, const std::string& target, const std::string& value) {
    auto it = list.begin();
    bool found = false;

    while (it != list.end()) {
        if (*it == target) {
            found = true;
            break;
        }
        ++it;
    }

    if (!found) {
        list.append(value);
        return;
    }

    auto it_value = list.insert_after(it, value);
}
