using System;
using System.Collections.Generic;
using System.Threading;
using UnityEngine;

public class DynamicValueGenerator : IDisposable
{
    private readonly Dictionary<string, Distribution> _distributions = new();
    private readonly ConcurrentDictionary<string, Distribution> _cache = new();
    private string _currentDistribution;
    private float[] _params;

    public void SetDistribution(string distributionName, float[] paramsArray)
    {
        _currentDistribution = distributionName;
        _params = paramsArray;
    }

    public float GetRandomFloat(float min, float max) => _distributions[_currentDistribution].GetRandom(min, max);

    public int GetRandomInt(int min, int max) => (int)_distributions[_currentDistribution].GetRandom((float)min, (float)max);

    public override string ToString()
    {
        return $"Range: [{_params[0]}, {_params[1]}], Distribution: {_currentDistribution}";
    }

    public void Dispose()
    {
        _cache.Clear();
    }
}

public interface IDistribution
{
    float GetRandom(float min, float max);
}

public class UniformDistribution : IDistribution
{
    private float _min;
    private float _max;

    public UniformDistribution(float min, float max)
    {
        _min = min;
        _max = max;
    }

    public float GetRandom(float min, float max) => UnityEngine.Random.Range(_min, _max);
}

public class GaussianDistribution : IDistribution
{
    private float _mean;
    private float _stddev;

    public GaussianDistribution(float mean, float stddev)
    {
        _mean = mean;
        _stddev = stddev;
    }

    public float GetRandom(float min, float max) => Mathf.Round((UnityEngine.Random.Gaussian(_mean, _stddev) + _mean) * (max - min) / (_stddev * 2f)) + min;
}

public class ExponentialDistribution : IDistribution
{
    private float _lambda;

    public ExponentialDistribution(float lambda)
    {
        _lambda = lambda;
    }

    public float GetRandom(float min, float max) => Mathf.Round((UnityEngine.Random.Epsilon(_lambda)) * (max - min) / (_lambda)) + min;
}

public static class DistributionFactory
{
    public static IDistribution CreateDistribution(string distributionName, float[] paramsArray)
    {
        switch (distributionName.ToLower())
        {
            case "uniform":
                return new UniformDistribution(paramsArray[0], paramsArray[1]);
            case "gaussian":
                return new GaussianDistribution(paramsArray[0], paramsArray[1]);
            case "exponential":
                return new ExponentialDistribution(paramsArray[0]);
            default:
                throw new ArgumentException("Unsupported distribution type", nameof(distributionName));
        }
    }
}

public static class Logging
{
    public static void LogError(string message)
    {
        Debug.LogError(message);
    }

    public static void LogConfigChange(string configurationName, string previousValue, string currentValue)
    {
        Debug.Log($"Configuration '{configurationName}' changed from {previousValue} to {currentValue}");
    }
}

public class DistributionManager
{
    private readonly Dictionary<string, IDistribution> _distributions = new();
    private readonly DynamicValueGenerator _generator;

    public DistributionManager(DynamicValueGenerator generator)
    {
        _generator = generator;
    }

    public void RegisterDistribution(string distributionName, float[] paramsArray)
    {
        _distributions.Add(distributionName, DistributionFactory.CreateDistribution(distributionName, paramsArray));
        _generator.SetDistribution(distributionName, paramsArray);
    }
}

public class Configuration
{
    private readonly Dictionary<string, string> _config = new();
    private readonly Dictionary<string, float[]> _distributionParams = new();

    public void UpdateConfig(string key, string value)
    {
        if (!_config.ContainsKey(key))
            throw new ArgumentException("Unknown configuration key", nameof(key));

        _config[key] = value;
        LogConfigChange(key, _config[key], value);
    }

    public float[] GetDistributionParams(string distributionName) => _distributionParams[distributionName];
}
