import java.io.File;
import java.io.FileReader;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

import org.apache.commons.io.input.TailInputStream;
import org.apache.commons.regex.RegEx;

public class LogProcessor {
    private static final int THREAD_POOL_SIZE = 10;
    private static final String REPORT_DIR = "reports";
    private static final String LOG_DIR = "logs";
    private static final String CACHE_DIR = "cache";

    private ExecutorService executor;
    private RegEx keywordRegEx;
    private Reporter reporter;

    public LogProcessor() {
        executor = Executors.newFixedThreadPool(THREAD_POOL_SIZE);
        keywordRegEx = new RegEx();
        reporter = new Reporter();
    }

    public void startProcessing(String[] remoteServers) {
        for (String server : remoteServers) {
            executor.submit(() -> processServer(server));
        }
    }

    private void processServer(String server) {
        try (TailInputStream in = new TailInputStream(new File(LOG_DIR, server + ".log"))) {
            String line;
            while ((line = in.readLine()) != null) {
                if (keywordRegEx.matches(line)) {
                    // Process error/warning lines
                    reporter.report(line);
                }
            }
        } catch (IOException e) {
            // Log and handle exception
        }
    }

    public void generateReports() {
        executor.submit(() -> {
            try {
                File reportDir = new File(REPORT_DIR);
                if (!reportDir.exists()) {
                    reportDir.mkdirs();
                }

                List<String> reports = new ArrayList<>();
                for (File file : reportDir.listFiles()) {
                    String report = file.getName().replace(".txt", "");
                    reports.add(report);
                }

                // Generate summary reports
                for (String report : reports) {
                    File summaryReport = new File(REPORT_DIR, report + "_summary.txt");
                    reporter.generateSummary(summaryReport);

                    // Execute shell command to generate detailed insights
                    try (Process process = Runtime.getRuntime().exec("bash -c 'generate_detailed_insights.sh " + report + "'")) {
                        process.waitFor();
                    } catch (IOException e) {
                        // Log and handle exception
                    }
                }

            } catch (Exception e) {
                // Log and handle exception
            }
        });
    }

    public void startScheduledTasks() {
        executor.submit(() -> {
            try {
                File cacheDir = new File(CACHE_DIR);
                if (!cacheDir.exists()) {
                    cacheDir.mkdirs();
                }

                // Schedule report generation tasks
                scheduler.schedule(() -> generateReports(), 60 * 1000, TimeUnit.MILLISECONDS); // Generate reports every minute

                // Start caching mechanism to store frequently accessed reports
                CacheManager cacheManager = new CacheManager(cacheDir);
                cacheManager.start();

            } catch (Exception e) {
                // Log and handle exception
            }
        });
    }

    public static void main(String[] args) {
        LogProcessor logProcessor = new LogProcessor();
        logProcessor.startProcessing(new String[]{"server1", "server2"});
        logProcessor.generateReports();
        logProcessor.startScheduledTasks();
    }
}
