import os
import hashlib
from PIL import Image
from io import BytesIO
import requests
import concurrent.futures

def process_and_store_images(image_paths, bucket_name, directory_path):
    def process_image(image_path):
        image = Image.open(image_path)
        if image.width > 1000 or image.height > 1500:
            image.thumbnail((1000, 1500))
        bytes_io = BytesIO()
        image.save(bytes_io, 'JPEG')
        md5_hash = hashlib.md5(bytes_io.getvalue()).hexdigest()

        if requests.head(f's3://{bucket_name}/{directory_path}/{md5_hash}.jpg').status_code == 200:
            print(f"Image {image_path} is already uploaded. Skipping upload.")
            return

        try:
            with open(image_path, 'rb') as file:
                response = requests.put(f's3://{bucket_name}/{directory_path}/', files={'file': ('image.jpg', file.read(), 'image/jpeg')})
            if response.status_code == 200:
                print(f"Image {image_path} uploaded successfully.")
            else:
                print(f"Error uploading image {image_path}. Status code: {response.status_code}")
        except Exception as e:
            print(f"An error occurred while processing the image {image_path}: {str(e)}")

    with concurrent.futures.ThreadPoolExecutor() as executor:
        futures = {executor.submit(process_image, path): path for path in image_paths}
        for future in concurrent.futures.as_completed(futures):
            future.result()
