#include <random>
#include <map>
#include <mutex>

namespace RandomGenerator {
class MT19937Generator {
public:
    MT19937Generator(int seed) : gen_(std::mt19937(seed)), cache_() {}
    ~MT19937Generator() = default;

    int generateInt(int min, int max) {
        std::uniform_int_distribution<int> dist(min, max);
        return dist(gen_);
    }

    double generateDouble(double min, double max) {
        std::uniform_real_distribution<double> dist(min, max);
        return dist(gen_);
    }

    void configureNormalDistribution(double mean, double stddev) {
        normal_dist_.reset(new std::normal_distribution<>(mean, stddev));
    }

    double generateNormal() {
        if (!normal_dist_) {
            throw std::runtime_error("Normal distribution not configured");
        }
        return *normal_dist_(gen_);
    }

    void configureExponential(double rate) {
        exponential_dist_.reset(new std::exponential_distribution<>(rate));
    }

    double generateExponential() {
        if (!exponential_dist_) {
            throw std::runtime_error("Exponential distribution not configured");
        }
        return *exponential_dist_(gen_);
    }

    int generateStreamInt(int min, int max) {
        return generateInt(min, max);
    }

    double generateStreamDouble(double min, double max) {
        return generateDouble(min, max);
    }

    void saveSeedToDatabase(const std::string& streamName) {
        // Implement database integration
    }

    bool loadSeedFromDatabase(const std::string& streamName, int& seed) {
        // Implement database integration
        return false;
    }

private:
    std::mt19937 gen_;
    std::map<std::string, int> cache_;
    std::unique_ptr<std::normal_distribution<double>> normal_dist_;
    std::unique_ptr<std::exponential_distribution<double>> exponential_dist_;
};
}
