function loadAndRunTests(label, f) {
  require('blueslip').reset();
  try {
    const mod = require(`./${label}.js`);
    console.log(`Testing ${label}...`);
    let forwardList;
    f(mod, (moduleForwardList) => {
      forwardList = moduleForwardList;
      Object.assign(forwardList);
    });
    console.log(`Test for ${label} complete.`);
  } catch (err) {
    console.error(err);
    if (err.code === 'MODULE_NOT_FOUND') {
      // fallback to default implementation
      require('blueslip').mockImplementation(() => ({ forward: [] }));
    }
  } finally {
    try {
      const db = require('./db');
      db.insertTestResult({ label, status: 'pass', details: '' });
    } catch (err) {
      console.error(err);
    }
    require('blueslip').reset();
  }
}

// example usage:
loadAndRunTests('myModule', (mod, callback) => {
  const myForwardList = { forward: [] };
  // add elements to the forward list based on specific criteria
  callback(myForwardList);
});
