import os
import subprocess
import logging
from threading import Lock, Semaphore
from queue import Queue

class CommandExecutor:
    def __init__(self):
        self.log = logging.getLogger('CommandExecutor')
        self.lock = Lock()
        self.semaphore = Semaphore(value=10)  # max concurrent processes
        self.command_queue = Queue()

    def execute_command(self, command: str):
        with self.lock:
            if self.semaphore.acquire(blocking=False):  # check availability
                try:
                    process = subprocess.run(command, shell=True, timeout=60)
                    self.log.info(f"Command executed: {command}, Exit code: {process.returncode}")
                except subprocess.TimeoutExpired:
                    self.log.error(f"Command timed out: {command}")
                except Exception as e:
                    self.log.error(f"Error executing command: {command}, Error: {str(e)}")
                finally:
                    self.semaphore.release()  # release semaphore

    def execute_commands(self, commands):
        for command in commands:
            self.command_queue.put(command)
        while not self.command_queue.empty():
            self.execute_command(self.command_queue.get())

class RateLimiter:
    def __init__(self, max_calls_per_second: int):
        self.max_calls_per_second = max_calls_per_second
        self.calls_per_second = 0
        self.time_of_last_call = None

    def rate_limit(self):
        if self.time_of_last_call is not None and (datetime.now() - self.time_of_last_call).total_seconds() < 1 / self.max_calls_per_second:
            raise Exception("Rate limit exceeded")

    def reset(self):
        self.calls_per_second = 0
        self.time_of_last_call = datetime.now()

class CommandChainer:
    def __init__(self, command_executor: CommandExecutor):
        self.command_executor = command_executor

    def chain_commands(self, commands):
        for command in commands:
            try:
                self.command_executor.execute_command(command)
            except Exception as e:
                print(f"Error chaining commands: {str(e)}")

class ExternalMonitoringSystem:
    def __init__(self):
        self.commands_executed = 0
        self.cpu_usage = 0.0

    def track_command_execution(self, command: str, cpu_usage: float):
        self.commands_executed += 1
        self.cpu_usage += cpu_usage

    def get_monitoring_data(self):
        return {"commands_executed": self.commands_executed, "cpu_usage": self.cpu_usage}

class CommandLineInterface:
    def __init__(self, command_executor: CommandExecutor, rate_limiter: RateLimiter, external_monitoring_system: ExternalMonitoringSystem):
        self.command_executor = command_executor
        self.rate_limiter = rate_limiter
        self.external_monitoring_system = external_monitoring_system

    def execute_command(self, command: str):
        try:
            self.rate_limiter.rate_limit()
            self.command_executor.execute_command(command)
            self.external_monitoring_system.track_command_execution(command, cpu_usage=subprocess.get_cpu_usage())
        except Exception as e:
            print(f"Error executing command: {str(e)}")

    def get_monitoring_data(self):
        return self.external_monitoring_system.get_monitoring_data()

if __name__ == "__main__":
    # Initialize framework components
    command_executor = CommandExecutor()
    rate_limiter = RateLimiter(max_calls_per_second=5)
    external_monitoring_system = ExternalMonitoringSystem()
    command_line_interface = CommandLineInterface(command_executor, rate_limiter, external_monitoring_system)

    # Execute commands and track execution
    while True:
        try:
            command = input("Enter a command (or 'quit' to exit): ")
            if command.lower() == "quit":
                break
            command_line_interface.execute_command(command)
            print(f"Monitoring data: {command_line_interface.get_monitoring_data()}")
        except KeyboardInterrupt:
            print("\nExiting...")
            break

