import mysql.connector
from psycopg2 import Error as PgError
from pymongo import MongoClient
import hashlib
import asyncio
from aiohttp import ClientSession

class DatabaseConnector:
    def __init__(self, db_config):
        self.db_config = db_config
        self.cache = {}
        self.batch_size = 1000
        self.max_retries = 3

    async def connect(self):
        if self.db_config['type'] == 'mysql':
            return mysql.connector.connect(**self.db_config)
        elif self.db_config['type'] == 'postgres':
            try:
                conn = await pg.connect(
                    host=self.db_config['host'],
                    database=self.db_config['database'],
                    user=self.db_config['username'],
                    password=self.db_config['password']
                )
                return conn
            except PgError as e:
                print(f"Postgres connection error: {e}")
        elif self.db_config['type'] == 'mongo':
            return MongoClient(self.db_config['host'], int(self.db_config['port']))

    async def query(self, operation, data):
        if operation not in ['insert', 'update', 'delete']:
            raise ValueError("Invalid operation")

        for _ in range(self.max_retries):
            try:
                conn = await self.connect()
                cursor = conn.cursor()

                if operation == 'insert':
                    await cursor.execute("INSERT INTO table_name SET data = %s", (data,))
                elif operation == 'update':
                    await cursor.execute("UPDATE table_name SET data = %s WHERE id = %s", (data, id))
                elif operation == 'delete':
                    await cursor.execute("DELETE FROM table_name WHERE id = %s", (id,))

                await conn.commit()

                if self.cache:
                    await self.cache_write()

                return "Operation successful"
            except Exception as e:
                print(f"Error: {e}")
        else:
            raise Exception("Failed to connect after max retries")

    async def query_with_checksum(self, operation, data):
        checksum = hashlib.sha256(data.encode()).hexdigest()
        if checksum in self.cache:
            return self.cache[checksum]

        result = await self.query(operation, data)
        self.cache[checksum] = result
        return result

    async def batch_operation(self, operation, data):
        for chunk in [data[i:i + self.batch_size] for i in range(0, len(data), self.batch_size)]:
            await self.query_with_checksum(operation, chunk)

    async def disconnect(self):
        if 'mysql' in self.db_config['type']:
            conn = mysql.connector.connect(**self.db_config)
            conn.close()
        elif 'postgres' in self.db_config['type']:
            conn = pg.connect(
                host=self.db_config['host'],
                database=self.db_config['database'],
                user=self.db_config['username'],
                password=self.db_config['password']
            )
            conn.close()

