DataTransferRequest create_request(char* source_host, int source_port, char* destination_host, int destination_port, enum {INSERT, UPDATE, DELETE} operation, void* data) {
    DataTransferRequest request;
    request.source_host = source_host;
    request.source_port = source_port;
    request.destination_host = destination_host;
    request.destination_port = destination_port;
    request.operation = operation;
