```csharp
using System;
using System.Xml;
using System.Net.Http;
using System.Threading;
using Serilog;

public class XmlParser
{
    private readonly HttpClient _httpClient;
    private readonly ILogger _logger;

    public XmlParser(HttpClient httpClient, ILogger logger)
    {
        _httpClient = httpClient;
        _logger = logger;
    }

    public XElement GetFirstElement(string url, string elementName)
    {
        try
        {
            HttpResponseMessage response = _httpClient.GetAsync(url).Result;
            if (!response.IsSuccessStatusCode)
            {
                _logger.Error("Failed to retrieve XML from {url}", url);
                return null;
            }

            XmlDocument document = new XmlDocument();
            document.LoadXml(response.Content.ReadAsStringAsync().Result);

            XmlNodeList nodes = document.SelectNodes("//" + elementName);
            if (nodes == null || nodes.Count == 0)
            {
                _logger.Debug("No elements found with name {elementName}", elementName);
                return null;
            }
            else if (nodes.Count > 1)
            {
                _logger.Warning("Multiple elements found with name {elementName}. Returning the first one.", elementName);
            }

            return new XElement(nodes[0].OuterXml);
        }
        catch (Exception ex)
        {
            _logger.Error(ex, "Error parsing XML");
            throw;
        }
    }
}

public class ILogger
{
    public void Error(string message, Exception exception = null) { }
    public void Warning(string message) { }
    public void Debug(string message) { }
}
