```java
import java.io.*;
import java.util.*;
import java.text.SimpleDateFormat;
import org.apache.commons.lang3.StringUtils;

public class LogMessage {
    public static void main(String[] args) {
        // Configuration file setup
        Properties props = new Properties();
        try (InputStream input = new FileInputStream("config.properties")) {
            props.load(input);
        } catch (IOException ex) {
            ex.printStackTrace();
        }

        String logLevel = props.getProperty("log.level");
        String errorLogFile = props.getProperty("error.log.file");
        String infoLogFile = props.getProperty("info.log.file");

        // Log setup
        SimpleDateFormat dateFormat = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
        SimpleDateFormat timestampFormat = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
        Date date = new Date();
        String currentTimestamp = timestampFormat.format(date);

        // Execute commands and log their output and errors
        Runtime runtime = Runtime.getRuntime();

        try {
            Process process = runtime.exec("your command 1", null, new File("/path/to/command/"));
            BufferedReader outputReader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));

            while (true) {
                String line = outputReader.readLine();
                if (line == null) break;
                logMessage(line, "INFO", infoLogFile);
            }

            while (true) {
                String line = errorReader.readLine();
                if (line == null) break;
                logMessage(line, "ERROR", errorLogFile);
            }
        } catch (IOException ex) {
            // Handle command execution errors
            logMessage("Command execution failed: " + ex.getMessage(), "ERROR", errorLogFile);
        }

        // Close the streams and processes
        outputReader.close();
        errorReader.close();
    }

    public static void logMessage(String message, String logLevel, String logFile) {
        if (logLevel.equals("INFO")) {
            try (PrintWriter writer = new PrintWriter(new FileOutputStream(logFile, true), true)) {
                writer.println(currentTimestamp + " - INFO - " + message);
            } catch (IOException ex) {
                // Handle logging errors
                System.out.println("Error logging info message: " + ex.getMessage());
            }
        } else if (logLevel.equals("ERROR")) {
            try (PrintWriter writer = new PrintWriter(new FileOutputStream(logFile, true), true)) {
                writer.println(currentTimestamp + " - ERROR - " + message);
            } catch (IOException ex) {
                // Handle logging errors
                System.out.println("Error logging error message: " + ex.getMessage());
            }
        }
    }
}
