#include <openssl/err.h>
#include <openssl/pbkdf2.h>
#include <openssl/aes.h>

// Function to derive key and IV from password and salt using PBKDF2
int derive_key_and_iv(const unsigned char* password, const unsigned char* salt,
                       unsigned char* derived_key, size_t derived_key_len,
                       unsigned char* iv, size_t iv_len) {
    EVP_PBEKeySpec* pbeKeySpec = EVP_PKCS5_PBKDF2_Init();
    if (!pbeKeySpec) return -1;

    // Set up PBKDF2 parameters
    pbeKeySpec->salt = salt;
    pbeKeySpec->key_length = derived_key_len;

    unsigned char* derived_key_ptr = derived_key;
    int rv = EVP_PKCS5_PBKDF2(password, strlen((char*)password), 
                              &pbeKeySpec->salt[0], 16, 1000, 
                              derived_key_len, derived_key_ptr);

    if (rv != 1) {
        ERR_error_string(ERR_get_error(), NULL);
        return -1;
    }

    // Derive IV using PBKDF2
    unsigned char* iv_ptr = iv;
    rv = EVP_PKCS5_PBKDF2(password, strlen((char*)password), 
                          &pbeKeySpec->salt[0], 16, 1000, 
                          iv_len, iv_ptr);

    if (rv != 1) {
        ERR_error_string(ERR_get_error(), NULL);
        return -1;
    }

    EVP_PBEKeySpec_free(pbeKeySpec);

    return 1;
}

// Function to initialize AES-256-CBC cipher with derived key and IV
int init_aes_cipher(const unsigned char* derived_key, size_t derived_key_len,
                     const unsigned char* iv, size_t iv_len) {
    // Set up AES context
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return -1;

    // Set the cipher algorithm and its parameters
    int rv = EVP_CipherInit_ex(ctx, EVP_aes_256_cbc(), NULL, derived_key, 
                                derived_key_len, iv, iv_len);

    if (rv != 1) {
        ERR_error_string(ERR_get_error(), NULL);
        return -1;
    }

    // Enable CBC mode
    rv = EVP_CipherStart(ctx);

    if (rv != 1) {
        ERR_error_string(ERR_get_error(), NULL);
        return -1;
    }

    // Get the initialized cipher context
    AES_cbc_ctx* aes_ctx = (AES_cbc_ctx*)ctx;

    EVP_CIPHER_CTX_free(ctx);

    return (int)aes_ctx;
}

// Function to clean up and disable the cipher when it is no longer needed
void cleanup_cipher(AES_cbc_ctx* aes_ctx) {
    if (!aes_ctx) return;

    // Disable CBC mode
    EVP_CipherStop(aes_ctx);

    // Clean up the AES context
    EVP_CIPHER_CTX_free((EVP_CIPHER_CTX*)aes_ctx);
}

// Example usage:
int main() {
    unsigned char password[] = "my_secret_password";
    unsigned char salt[] = "my_secret_salt";
    unsigned char derived_key[32];
    unsigned char iv[16];

    int rv = derive_key_and_iv(password, salt, derived_key, 32, iv, 16);

    if (rv != 1) {
        printf("Error deriving key and IV\n");
        return -1;
    }

    AES_cbc_ctx* aes_ctx = init_aes_cipher(derived_key, 32, iv, 16);

    if (!aes_ctx) {
        printf("Error initializing AES cipher\n");
        return -1;
    }

    // Use the cipher for encryption or decryption
    ...

    cleanup_cipher(aes_ctx);

    return 0;
}
