using System;
using System.Collections.Concurrent;
using System.Net.Http;
using System.Threading.Tasks;

public class AvatarManager
{
    private readonly ConcurrentDictionary<string, Avatar> _avatarCache = new ConcurrentDictionary<string, Avatar>();
    private readonly HttpClient _httpClient = new HttpClient();
    private readonly ILogger _logger = LogManager.GetLogger<AvatarManager>();

    public async Task UpdateAvatarAsync(string userId)
    {
        if (_avatarCache.TryGetValue(userId, out var cachedAvatar))
        {
            // Avatar is already in cache, update user profile information accordingly
            await UpdateUserProfileAsync(userId, cachedAvatar);
            return;
        }

        try
        {
            // Retrieve avatar from external service
            var request = new HttpRequestMessage(HttpMethod.Get, $"https://avatar-service.com/{userId}?resolution=medium");
            var response = await _httpClient.SendAsync(request);

            if (!response.IsSuccessStatusCode)
            {
                throw new Exception($"Failed to retrieve avatar for user {userId}: {response.StatusCode}");
            }

            // Store retrieved avatar in cache
            var avatar = await response.Content.ReadAsByteArrayAsync();
            _avatarCache.TryAdd(userId, new Avatar(avatar));

            // Update user profile information with the new avatar
            await UpdateUserProfileAsync(userId, avatar);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error updating avatar for user {userId}", userId);
        }
    }

    public async Task ClearOutdatedAvatarsAsync()
    {
        var outdatedAvatars = _avatarCache.Where(x => x.Value.LastUpdated < DateTime.Now.AddDays(-7)).Select(x => x.Key).ToList();
        foreach (var userId in outdatedAvatars)
        {
            try
            {
                // Remove outdated avatar from cache and update user profile information
                if (_avatarCache.TryRemove(userId, out var _))
                {
                    await UpdateUserProfileAsync(userId, null);
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error clearing outdated avatar for user {userId}", userId);
            }
        }
    }

    public async Task ServeAvatarAsync(string userId, int resolution)
    {
        if (_avatarCache.TryGetValue(userId, out var cachedAvatar))
        {
            // Avatar is already in cache, serve the requested resolution
            return await ServeAvatarFromCacheAsync(cachedAvatar, resolution);
        }

        try
        {
            // Retrieve avatar from external service with specified resolution
            var request = new HttpRequestMessage(HttpMethod.Get, $"https://avatar-service.com/{userId}?resolution={resolution}");
            var response = await _httpClient.SendAsync(request);

            if (!response.IsSuccessStatusCode)
            {
                throw new Exception($"Failed to retrieve avatar for user {userId} at resolution {resolution}: {response.StatusCode}");
            }

            // Store retrieved avatar in cache
            var avatar = await response.Content.ReadAsByteArrayAsync();
            _avatarCache.TryAdd(userId, new Avatar(avatar));

            // Serve the retrieved avatar with the requested resolution
            return await ServeAvatarFromCacheAsync(new Avatar(avatar), resolution);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error serving avatar for user {userId} at resolution {resolution}", userId, resolution);
        }
    }

    private async Task UpdateUserProfileAsync(string userId, byte[] avatar)
    {
        // Implement logic to update user profile information with the new avatar
    }

    private async Task<byte[]> ServeAvatarFromCacheAsync(Avatar cachedAvatar, int resolution)
    {
        // Implement logic to serve the requested avatar resolution from cache
    }
