```
import concurrent.futures
import hashlib
import os
import requests
import time
from typing import List

class FileHashingUtility:
    def __init__(self):
        self.api_endpoint = None
        self.thread_pool_size = 5
        self.chunk_size = 1024 * 1024  # 1MB chunks

    def set_api_endpoint(self, endpoint: str) -> None:
        self.api_endpoint = endpoint

    def set_thread_pool_size(self, size: int) -> None:
        self.thread_pool_size = size

    def set_chunk_size(self, chunk_size: int) -> None:
        self.chunk_size = chunk_size

    def hash_file(self, file_path: str) -> dict:
        with open(file_path, 'rb') as file:
            file_size = os.path.getsize(file_path)
            chunks = [file.read(self.chunk_size) for _ in range((file_size + self.chunk_size - 1) // self.chunk_size)]
            chunk_hashes = []
            with concurrent.futures.ThreadPoolExecutor(max_workers=self.thread_pool_size) as executor:
                futures = {executor.submit(self.hash_chunk, chunk): i for i, chunk in enumerate(chunks)}
                for future in concurrent.futures.as_completed(futures):
                    chunk_index = futures[future]
                    try:
                        hash_value = future.result()
                    except Exception as e:
                        print(f"Error hashing file '{file_path}': {str(e)}")
                        continue
                    chunk_hashes.append((chunk_index, hash_value))
            return {'file_path': file_path, 'hash_value': hashlib.sha256(b''.join(chunk for _, chunk in chunk_hashes)).hexdigest()}

    def hash_chunk(self, chunk: bytes) -> str:
        md5 = hashlib.md5()
        md5.update(chunk)
        return md5.hexdigest()

    def store_hash(self, file_path: str, hash_value: str) -> None:
        if self.api_endpoint is not None:
            try:
                response = requests.post(self.api_endpoint, json={'file_path': file_path, 'hash_value': hash_value})
                response.raise_for_status()
            except (requests.exceptions.RequestException, ConnectionError):
                print(f"Failed to store hash for '{file_path}': {response.text if response else 'Unknown error'}")
        else:
            print(f"No API endpoint set. Skipping storing hash for '{file_path}'")

    def retrieve_hash(self, file_path: str) -> str:
        if self.api_endpoint is not None:
            try:
                response = requests.get(self.api_endpoint + f"?file_path={file_path}")
                response.raise_for_status()
                return response.json()['hash_value']
            except (requests.exceptions.RequestException, ConnectionError):
                print(f"Failed to retrieve hash for '{file_path}': {response.text if response else 'Unknown error'}")
        else:
            print(f"No API endpoint set. Skipping retrieving hash for '{file_path}'")

def main():
    utility = FileHashingUtility()

    import sys
    if len(sys.argv) != 4:
        print("Usage: python file_hashing_utility.py <input_files> <thread_pool_size> <api_endpoint>")
        return

    input_files = sys.argv[1].split(',')
    thread_pool_size = int(sys.argv[2])
    api_endpoint = sys.argv[3]

    utility.set_thread_pool_size(thread_pool_size)
    utility.set_api_endpoint(api_endpoint)

    for file in input_files:
        hash_result = utility.hash_file(file)
        print(f"Hashed '{file}': {hash_result['hash_value']}")
        utility.store_hash(file, hash_result['hash_value'])

if __name__ == "__main__":
    main()
```

