#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

// Define a struct for a linked list node
typedef struct Node {
    int value;
    struct Node* next;
} Node;

// Function to insert an element at the end of the linked list
void insert(Node** head, int value) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->value = value;
    newNode->next = NULL;

    if (*head == NULL) {
        *head = newNode;
    } else {
        Node* last = *head;
        while (last->next != NULL) {
            last = last->next;
        }
        last->next = newNode;
    }
}

// Function to search for the maximum value in the linked list
int findMax(Node* head) {
    int max = INT_MIN;

    Node* current = head;
    while (current != NULL) {
        if (current->value > max) {
            max = current->value;
        }
        current = current->next;
    }

    return max;
}

// Function to free the allocated resources
void freeList(Node** head) {
    Node* current = *head;
    Node* next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

int main() {
    int limitMB = 1024; // Set a reasonable memory limit in MB
    size_t limitBytes = limitMB * 1048576;

    Node* head = NULL;
    int max = INT_MIN;

    FILE* input = fopen("stdin", "r");
    if (input == NULL) {
        printf("Error opening standard input.\n");
        return -1;
    }

    char buffer[64];
    size_t bytesRead = 0;

    while (fread(buffer, 1, 64, input) > 0 && bytesRead < limitBytes) {
        for (int i = 0; i < 64; ++i) {
            if (buffer[i] == '\n' || buffer[i] == '\r') {
                break;
            }
            int value = atoi(buffer);
            if (value != INT_MAX) { // Check for non-integer values
                insert(&head, value);
                bytesRead += 64 - i - 1; // Update bytes read
            } else {
                printf("Invalid input. Aborting.\n");
                fclose(input);
                freeList(&head);
                return -2;
            }
        }
    }

    if (ferror(input) || ftell(input) != 0) { // Handle interruptions during input
        printf("Error reading standard input.\n");
        fclose(input);
        freeList(&head);
        return -3;
    }

    max = findMax(head);

    printf("Maximum value in the linked list: %d\n", max);

    freeList(&head);
    fclose(input);
    return 0;
}
