size_t dynamicStringCopy(const char *src, char *dest, size_t destSize) {
    size_t srcLength = strlen(src);
    size_t copyLength = (srcLength < destSize) ? srcLength : destSize - 1;

    if (copyLength > 0) {
        memcpy(dest, src, copyLength);
        dest[copyLength] = '\0'; // Ensure null-termination
    } else {
        // Log error and truncated length information if necessary
        log_error("String truncation occurred. Original length: %zu, Truncated length: %zu", srcLength, copyLength);
