#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <dirent.h>

// Function to trim a string
char* trim(char* str) {
    size_t start = 0;
    size_t end = strlen(str);

    while (start <= end && isspace(str[start])) {
        start++;
    }

    while (end > start && isspace(str[end - 1])) {
        end--;
    }

    char* trimmed = malloc((end - start + 1) * sizeof(char));
    strncpy(trimmed, str + start, end - start);
    trimmed[end - start] = '\0';
    return trimmed;
}

// Function to append slash to string if size limit not exceeded
char* add_slash_if_necessary(const char* str, int size_limit) {
    if (strlen(str) <= size_limit) {
        char* new_str = malloc((size_limit + 2) * sizeof(char));
        strcpy(new_str, str);
        strcat(new_str, "/");
        return new_str;
    } else {
        return NULL;
    }
}

// Asynchronous function to read and validate log files
int64_t process_log_files(const char* dir_path) {
    DIR* dir = opendir(dir_path);
    if (!dir) {
        perror("Failed to open directory");
        return -1;
    }

    struct dirent* ent;
    int file_count = 0;

    while ((ent = readdir(dir)) != NULL) {
        const char* file_name = ent->d_name;
        size_t len = strlen(file_name);

        if (len > 4 && !strcmp(&file_name[len - 4], ".log") ||
            len > 5 && !strcmp(&file_name[len - 5], ".json") ||
            len > 3 && !strcmp(&file_name[len - 3], ".csv")) {
            file_count++;
        }
    }

    closedir(dir);

    if (file_count == 0) {
        printf("No log files found.\n");
        return -1;
    }

    int64_t total_lines = 0;

    for (int i = 0; i < file_count; i++) {
        char* file_path = malloc((strlen(dir_path) + len + 2) * sizeof(char));
        sprintf(file_path, "%s/%s", dir_path, ent->d_name);

        FILE* file = fopen(file_path, "r");
        if (!file) {
            perror("Failed to open file");
            continue;
        }

        char line[1024];
        while (fgets(line, sizeof(line), file)) {
            total_lines++;
        }

        fclose(file);
        free(file_path);
    }

    return total_lines;
}
