using System;
using System.Xml.XPath;

public class XmlParser
{
    public string GetFirstElement(string xml, string name)
    {
        XPathDocument doc = new XPathDocument(xml);
        XPathNavigator nav = doc.CreateNavigator();
        XPathExpression expr = nav.Compile("//" + name);
        XPathNodeIterator iter = nav.Select(expr);

        if (!iter.MoveNext())
            throw new Exception("No element found with the given name");

        string result = iter.Current.GetElementsByTagName("*").Item(0).Value;
        return result;
    }
}

public class StringTrimmer
{
    public string Trim(string input, int sizeLimit)
    {
        if (input.Length <= sizeLimit)
            return input + "/";
        else
            return null;
    }
}
