public class ClinicStatusUpdaterApplication {

    @Bean
    public IntegrationFlow getInboundAdapter() {
        return IntegrationFlow.from(JdbcInboundChannelAdapter.jdbctemplate(DataSource.create())
                .channelName("CLINIC_STATUS_UPDATER_INBOUND")
                .query("SELECT * FROM clinics WHERE status IS NULL OR status <> 'UPDATING'")
                .update("UPDATE clinics SET status = ? WHERE clinic_id = ? AND status IS NULL OR status <> 'UPDATING'")
                .args("{0}, {1}")
                .method("UPDATE")
                .get());
    }

    @Bean
    public IntegrationFlow getOutboundAdapter() {
        return IntegrationFlow.from(MessageSource.get())
                .enrichHeaders(headers -> headers.correlationId().correlationName())
                .transform(payload -> payload.toString())
                .channelName("CLINIC_STATUS_UPDATER_OUTBOUND")
                .get());
    }

    @Bean
    public JpaOutboundGateway getJpaGateway() {
        return JpaOutboundGateway.create()
                .entityManagerFactory(entityManagerFactory.get())
                .query("UPDATE clinics SET status = ? WHERE clinic_id = ? AND status IS NULL OR status <> 'UPDATING'")
                .args("{0}, {1}")
                .method("UPDATE")
                .get());
    }

    @Bean
    public MessageHistory getMessageHistory() {
        return new MessageHistory();
    }

    @Bean
    public RetryAdvice getRetryAdvice() {
