```java
import java.util.Arrays;
import java.util.Random;

public class DisjointPairCounter {
    private static class UnionFindNode {
        int value;
        UnionFindNode parent;
        long timestamp;

        public UnionFindNode(int value) {
            this.value = value;
            this.parent = this;
            this.timestamp = System.nanoTime();
        }
    }

    private static class UnionFind {
        UnionFindNode[] nodes;
        boolean lazyUnionEnabled;
        boolean pathCompressionEnabled;

        public UnionFind(int size) {
            nodes = new UnionFindNode[size];
            for (int i = 0; i < size; i++) {
                nodes[i] = new UnionFindNode(i);
            }
        }

        public void union(int a, int b) {
            if (!lazyUnionEnabled) {
                UnionFindNode rootA = find(a);
                UnionFindNode rootB = find(b);

                if (rootA != rootB) {
                    rootA.parent = rootB;
                    rootB.timestamp = Math.min(rootA.timestamp, System.nanoTime());
                }
            } else {
                UnionFindNode rootA = find(a);
                UnionFindNode rootB = find(b);

                if (rootA != rootB) {
                    if (pathCompressionEnabled) {
                        while (rootA.parent != rootA) {
                            rootA = rootA.parent;
                        }
                    }

                    rootA.parent = rootB;
                    rootB.timestamp = Math.min(rootA.timestamp, System.nanoTime());
                }
            }
        }

        public boolean areDisjoint(int a, int b) {
            return find(a) != find(b);
        }

        private UnionFindNode find(int value) {
            if (nodes[value].parent != nodes[value]) {
                nodes[value] = nodes[value].parent;
                nodes[value].timestamp = System.nanoTime();
            }
            return nodes[value];
        }

        public int countDisjointPairs() {
            int count = 0;

            for (int i = 0; i < nodes.length; i++) {
                for (int j = i + 1; j < nodes.length; j++) {
                    long start = System.nanoTime();
                    if (!areDisjoint(i, j)) {
                        count++;
                    }
                    long end = System.nanoTime();
                    System.out.println("Checking disjointness of (" + i + ", " + j + ") took " + (end - start) + " milliseconds");
                }
            }

            return count;
        }

        public static void main(String[] args) {
            int size = 100000; // adjust this to test with different array sizes
            UnionFind unionFind = new UnionFind(size);

            Random random = new Random();

            for (int i = 0; i < size; i++) {
                int a = random.nextInt(size);
                int b = random.nextInt(size);
                while (a == b) {
                    b = random.nextInt(size);
                }
                unionFind.union(a, b);
            }

            int disjointPairs = unionFind.countDisjointPairs();

            System.out.println("Number of disjoint pairs: " + disjointPairs);
        }
    }
