#include <nlohmann/json.hpp>
#include <fstream>
#include <string>
#include <unordered_map>
#include <variant>
#include <mutex>

using namespace nlohmann;
using namespace std;

// Resource manager to track concurrent JSON file reads
class ResourceManager {
public:
    ResourceManager(size_t maxConcurrentReads) : maxConcurrentReads(maxConcurrentReads), currentReads(0) {}

    bool tryAcquire() {
        lock_guard<mutex> lock(mutex);
        if (currentReads < maxConcurrentReads) {
            currentReads++;
            return true;
        }
        return false;
    }

    void release() {
        lock_guard<mutex> lock(mutex);
        currentReads--;
    }

private:
    size_t maxConcurrentReads, currentReads;
    mutex mutex;
};

// Configuration reader function
std::unordered_map<std::string, std::variant<int, double, std::string, bool>> readConfigurations(const string& path, const string& environment) {
    ResourceManager resourceManager(10); // Set the maximum concurrent reads to 10

    if (!resourceManager.tryAcquire()) {
        throw runtime_error("Failed to acquire resource: Maximum concurrent reads exceeded");
    }

    try {
        json config;
        ifstream file(path);
        file >> config;

        unordered_map<string, variant<int, double, string, bool>> settings;

        // Caching mechanism
        cache_t cachedConfig = make_shared<cache_t>(config);

        // Reload configuration when it changes
        if (file.peek() == ifstream::traits_type::eof) {
            return settings;
        }

        // Merge configurations for different environments
        json mergedConfig = mergeConfigs(cachedConfig, environment);
        config = mergedConfig;

        // Validate configuration against schema
        validateConfig(config);

        // Flatten nested JSON structures
        flattenConfig(config);

        // Load configuration settings into map
        for (auto& pair : config.items()) {
            string key = pair.key;
            variant<int, double, string, bool> value;

            try {
                if (pair.value.is_object()) {
                    json subConfig = pair.value;
                    value = loadSettings(subConfig);
                } else {
                    value = pair.value;
                }
            } catch (exception& e) {
                throw runtime_error("Failed to load configuration: " + e.what());
            }

            settings[key] = move(value);
        }
    } catch (const exception& e) {
        // Log error and release resource
        logger::error("Failed to read configurations: " + e.what());
        resourceManager.release();
        throw;
    }

    // Release resource
    resourceManager.release();

    return settings;
}

