import asyncio
import logging
from aiohttp import ClientSession
import datetime as dt

class PaymentProcessor:
    def __init__(self):
        self.api_url = 'https://api.example.com/transactions'
        self.max_concurrent_requests = 5
        self.backoff_factor = 2
        self.jitter_factor = .1

    async def fetch_transactions(self, session: ClientSession, user_id: str) -> dict:
        try:
            async with session.get(f'{self.api_url}?user_id={user_id}') as response:
                if response.status == 200:
                    transactions = await response.json()
                    return {t['timestamp']: t['amount'] for t in transactions}
                else:
                    raise Exception(f'Failed to fetch transactions: {response.status}')
        except (asyncio.TimeoutError, ConnectionError):
            logging.error('Connection error fetching transactions')
            return {}
        except Exception as e:
            logging.error(f'Error processing transactions: {e}')
            return {}

    async def process_transactions(self, user_id: str) -> dict:
        with ClientSession() as session:
            tasks = []
            for start in range(0, 30 * 24 * 60 * 60, 3600):  # last 30 days
                end = start + 3600  # one hour
                task = asyncio.create_task(self.fetch_transactions(session, user_id))
                tasks.append((task, start, end))

            results = await asyncio.gather(*[t[0] for t in tasks], return_exceptions=True)
            transactions = {}
            for i, result in enumerate(results):
                if isinstance(result, dict):  # successful fetch
                    for timestamp, amount in result.items():
                        if start <= int(timestamp) < end:
                            if user_id not in transactions:
                                transactions[user_id] = 0
                            transactions[user_id] += amount

            return transactions

    async def process_dataset(self, session: ClientSession, dataset: dict) -> dict:
        tasks = []
        for user_id, _ in dataset.items():
            task = asyncio.create_task(self.process_transactions(user_id))
            tasks.append(task)

        results = await asyncio.gather(*tasks, return_exceptions=True)
        aggregated_transactions = {}
        for result in results:
            if isinstance(result, dict):  # successful processing
                for user_id, amount in result.items():
                    if user_id not in aggregated_transactions:
                        aggregated_transactions[user_id] = 0
                    aggregated_transactions[user_id] += amount

        return aggregated_transactions

    async def main(self):
        dataset = {
            'user1': {'2022-01-01': 10.99, '2022-02-15': 5.50},
            'user2': {'2022-01-05': 7.99, '2022-03-25': 12.99}
        }
        results = await self.process_dataset(None, dataset)
        print(results)

if __name__ == '__main__':
    asyncio.run(PaymentProcessor().main())
