import asyncio
import aiohttp
import json
from logging import Logger
from functools import lru_cache

class EnvironmentConfig:
    def __init__(self, base_url: str, timeout: int, headers: dict):
        self.base_url = base_url
        self.timeout = timeout
        self.headers = headers

@lru_cache(maxsize=None)
async def load_config(env_config: EnvironmentConfig) -> dict:
    async with aiohttp.ClientSession() as session:
        try:
            async with session.get(env_config.base_url, timeout=env_config.timeout, headers=env_config.headers) as response:
                if response.status == 200:
                    return await response.json()
                else:
                    raise Exception(f"Failed to load config: {response.status}")
        except aiohttp.ClientError as e:
            Logger().error("Error loading config:", exc_info=e)
            # Fallback mechanism, use local config or default values
            return {}
        finally:
            session.close()

def validate_config(config: dict) -> None:
    if not isinstance(config, dict):
        raise Exception("Invalid config format")

    for key in ["base_url", "timeout", "headers"]:
        if key not in config:
            raise Exception(f"Missing config key: {key}")

        value = config[key]
        if key == "base_url":
            if not isinstance(value, str):
                raise Exception("Invalid base URL format")
        elif key == "timeout":
            if not isinstance(value, int) or value <= 0:
                raise Exception("Invalid timeout value")
        elif key == "headers":
            for header in value.values():
                if not isinstance(header, str):
                    raise Exception("Invalid header format")

def configure_logging(log_level: str = 'INFO') -> Logger:
    # Initialize logging system
    logger = Logger()
    logger.setLevel(getattr(Logger, log_level.upper()))
    return logger

# Usage example:
env_config = EnvironmentConfig("https://example.com/api/config", 10, {"Authorization": "Bearer some_token"})
config = load_config(env_config)
validate_config(config)

# For production use, consider implementing a more robust logging system and adding error handling for the fallback mechanism.
