#include <unistd.h>
#include <sys/wait.h>
#include <signal.h>
#include <errno.h>

#define MAX_PROCESSES 1000
#define MAX_COMMANDS 100
#define LOG_FILE "log.txt"
#define CONFIG_FILE "config.txt"

int maxProcesses = MAX_PROCESSES;
int numRunning = 0;
pid_t processes[MAX_PROCESSES];
FILE *logFile;

void sigchldHandler(int signum) {
    pid_t pid;
    while ((pid = waitpid(-1, NULL, WNOHANG)) > 0) {
        for (int i = 0; i < numRunning; i++) {
            if (processes[i] == pid) {
                processes[i] = processes[--numRunning];
                break;
            }
        }
    }
}

void init() {
    logFile = fopen(LOG_FILE, "w");
    signal(SIGCHLD, sigchldHandler);
}

int startCommand(char *command) {
    if (numRunning >= maxProcesses) {
        return -1; // process limit reached
    }

    pid_t pid = fork();
    if (pid == 0) {
        system(command);
        exit(0); // child process exits after command execution
    } else {
        processes[numRunning++] = pid;
    }
    return 0;
}

int main() {
    init();

    FILE *configFile = fopen(CONFIG_FILE, "r");
    if (!configFile) {
        printf("Error opening config file\n");
        return -1; // unable to open config file
    }

    char command[MAX_COMMANDS][256];
    int numCommands = 0;
    while (fscanf(configFile, "%255s", command[numCommands++]) == 1 && numCommands < MAX_COMMANDS) {
        for (int i = 0; i < numCommands - 1; i++) {
            if (!strcmp(command[i], command[numCommands - 1])) {
                printf("Error: duplicate command\n");
                return -1;
            }
        }
    }

    fclose(configFile);

    int i;
    for (i = 0; i < numCommands; i++) {
        startCommand(command[i]);
    }

    while (numRunning > 0) {
        sleep(1); // wait for child processes to finish
    }

    fclose(logFile);
    return 0;
}

