import hashlib
import os
from typing import Callable
from queue import Queue
from threading import Thread, Lock

class _ChunkProcessor(Thread):
    def __init__(self, chunks: Queue, callback: Callable[[int], None]):
        super().__init__()
        self.chunks = chunks
        self.callback = callback
        self.lock = Lock()

    def run(self) -> None:
        while not self.chunks.empty():
            chunk = self.chunks.get()
            with self.lock:
                try:
                    if isinstance(chunk, bytes):
                        md5_hash = hashlib.md5(chunk).hexdigest()
                        self.callback(md5_hash)
                    else:
                        raise ValueError("Invalid chunk type")
                except Exception as e:
                    print(f"Error processing chunk: {e}")
                finally:
                    self.chunks.task_done()

def calculate_file_md5(file_path: str, callback: Callable[[str], None] = lambda x: print(x), chunk_size: int = 4096) -> str:
    try:
        md5_hash = hashlib.md5()
        chunks = Queue()

        def process_chunk(chunk):
            with open(file_path, 'rb') as f:
                if chunk is not None:
                    f.seek(int(chunk))
                    chunk_data = f.read(chunk_size)
                else:
                    f.seek(0)
                    chunk_data = f.read()

                if isinstance(chunk_data, bytes):
                    md5_hash.update(chunk_data)
                else:
                    raise ValueError("Invalid chunk type")

        with open(file_path, 'rb') as f:
            for _ in range(os.path.getsize(file_path) // chunk_size + 1):
                process_chunk(None)

        if callback is not None and isinstance(callback, callable):
            callback(md5_hash.hexdigest())

    except Exception as e:
        print(f"Error calculating MD5 hash: {e}")

    finally:
        # Close file resources
        try:
            f.close()
        except NameError:
            pass

def main():
    calculate_file_md5('path_to_your_file.txt')

if __name__ == "__main__":
    main()

