int handleRanCrcIndications(NFAPI_CRC_INDICATION_PDU_T ***crcList, size_t *listSize, int maxStructures, FILE *logFile, RAN_SYS_API_T *ranSysApi, int concurrencyLevel)
{
    pthread_t threads[concurrencyLevel];
    sem_t semaphore;
    size_t currentSize = 0;

    if (sem_open(&semaphore, O_CREAT, 0644, 1) == -1) {
        return -1;
    }

    for (int i = 0; i < concurrencyLevel; i++) {
        pthread_create(&threads[i], NULL, processCrcIndications, &semaphore);
    }

    while (currentSize < maxStructures) {
        // Fetch new CRC indication PDUs from external data source
        NFAPI_CRC_INDICATION_PDU_T *pdu = ranSysApi->getNewPdu();
        if (pdu == NULL) {
            // Error fetching PDU, log and continue
            fprintf(logFile, "Error fetching CRC indication PDU.\n");
            sleep(1);
            continue;
        }

        // Add PDU to the list
        if (*listSize >= maxStructures) {
            // List is full, wait for available space or thread termination
            sem_wait(&semaphore);
        }
        *crcList = realloc(*crcList, sizeof(NFAPI_CRC_INDICATION_PDU_T *) * (*listSize + 1));
        (*crcList)[*listSize] = pdu;
        (*listSize)++;

        // Process CRC indication PDUs concurrently
        if (currentSize < maxStructures - concurrencyLevel) {
            for (int i = 0; i < concurrencyLevel; i++) {
                pthread_create(&threads[i], NULL, processCrcIndications, &semaphore);
            }
        }

        currentSize++;
    }

    // Wait for all threads to finish
    for (int i = 0; i < concurrencyLevel; i++) {
        pthread_join(threads[i], NULL);
    }

    sem_close(&semaphore);

    return 0;
}

void *processCrcIndications(void *arg) {
    sem_t *semaphore = arg;

    while (1) {
        size_t currentSize = *(size_t *)listSize;
        if (currentSize >= maxStructures) {
            // List is full, wait for available space
            sem_wait(semaphore);
        }

        // Process CRC indication PDUs from the list
        for (int i = 0; i < currentSize; i++) {
            NFAPI_CRC_INDICATION_PDU_T *pdu = (*crcList)[i];
            if (ranSysApi->validatePdu(pdu) == -1) {
                // Error validating PDU, log and continue
                fprintf(logFile, "Error validating CRC indication PDU.\n");
                continue;
            }

            // Handle the PDU according to its contents
            handlePduContents(pdu);

            // Release the semaphore for other threads
            sem_post(semaphore);
        }
    }
}
