int append_slash(char *str, int size_limit) {
    if (strlen(str) <= size_limit && str[size_limit - 1] != '/') {
        char *new_str = malloc((size_limit + 2) * sizeof(char));
        strcpy(new_str, str);
        strcat(new_str, "/");
        free(str);
        return new_str;
    }
    return str;
}
