public class ImageProcessingUtility {
    private static final int THREAD_POOL_SIZE = 10;

    public void convertBetweenFormats(String inputDir, String outputDir) throws InterruptedException, ExecutionException {
        ExecutorService executor = Executors.newFixedThreadPool(THREAD_POOL_SIZE);
        List<Future<?>> futures = new ArrayList<>();

        for (File file : new File(inputDir).listFiles()) {
            if (!file.isFile() || !isValidImage(file)) continue;

            Future<?> future = executor.submit(() -> {
                try {
                    String extension = getExtension(file.getName());
                    String outputExtension = getOutputExtension(extension);

                    ImageReadAndWrite reader = getImageReader(extension);
                    BufferedImage image = reader.read(file.getAbsolutePath());

                    File outputFile = new File(outputDir, file.getName().replace(extension, outputExtension));
                    ImageWriteContext.write(image, reader.getWriter(outputExtension), outputFile.getAbsolutePath(), true, false);
                } catch (Exception e) {
                    // handle exceptions
                }
            });

            futures.add(future);
        }

        for (Future<?> future : futures) {
            future.get();
        }

        executor.shutdown();
