from flasgger import SwaggerDoc

app = Flask(__name__)
app.config["DEBUG"] = True
cache = Cache(app, config={"CACHE_TYPE": "SimpleCache"})
swagger = SwaggerDoc(app)

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

def retry_on_failure(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        for i in range(3):
            try:
                return func(*args, **kwargs)
            except requests.exceptions.RequestException as e:
                logger.error(f"Failed to update profile {e}. Retrying...")
                if i == 2:
                    raise
    return wrapper

def handle_rate_limit(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        while True:
            try:
                return func(*args, **kwargs)
            except requests.exceptions.RequestException as e:
                if "rate limit exceeded" in str(e):
                    logger.warning("Rate limit exceeded. Retrying after 1 minute...")
                    time.sleep(60)
                else:
                    raise
    return wrapper

@retry_on_failure
@handle_rate_limit
def update_profile(api_config: Dict, user_id: int) -> requests.Response:
    api_url = api_config["url"]
    method = api_config["method"]
    auth_config = api_config.get("auth", None)

    if auth_config:
        response = requests.request(method, api_url, auth=auth_config)
    else:
        response = requests.request(method, api_url)

    return response

@app.route("/update-profiles", methods=["POST"])
def update_profiles():
    data = request.get_json()
    updated_count = 0

    for profile in data:
        user_id = profile["id"]
        api_configs = profile["apis"]

        for api_config in api_configs:
            try:
                response = update_profile(api_config, user_id)
                response.raise_for_status()
                updated_count += 1
            except Exception as e:
                logger.error(f"Failed to update profile {e}")

    return jsonify({"updated_count": updated_count})

if __name__ == "__main__":
    app.run(debug=True)

