    public class UpdateUserProfile
    {
        private readonly HttpClient _httpClient;
        private readonly ILogger _logger;
        private readonly IConfigProvider _configProvider;

        public UpdateUserProfile(HttpClient httpClient, ILogger logger, IConfigProvider configProvider)
        {
            _httpClient = httpClient;
            _logger = logger;
            _configProvider = configProvider;
        }

        public async Task UpdateProfilesAsync(string configFile, List<string> userIds, UserProfileDetails profileDetails)
        {
            // Load configuration from file
            var config = _configProvider.LoadConfig(configFile);

            // Validate user IDs and directory paths
            foreach (var userId in userIds)
            {
                if (!ValidateUserId(userId))
                {
                    throw new ArgumentException("Invalid user ID");
                }
            }

            // Prioritize critical updates based on predefined rules
            var prioritizedUpdates = profileDetails.GetPrioritizedUpdates();

            // Send notifications after updating each profile
            foreach (var update in prioritizedUpdates)
            {
                await UpdateProfileAsync(config, userIds, profileDetails, update);
                await NotifyStakeholdersAsync(update);
            }
        }

        private async Task UpdateProfileAsync(IConfiguration config, List<string> userIds, UserProfileDetails profileDetails, ProfileUpdate update)
        {
            // Get tenant-specific API settings from configuration
            var apiSettings = _configProvider.GetApiSettings(config);

            // Validate and encrypt sensitive data (email address and phone number)
            var encryptedData = EncryptSensitiveData(update);

            // Make concurrent API calls to update user profiles
            await Task.WhenAll(
                userIds.Select(userId => UpdateProfileAsync(apiSettings, config, userId, profileDetails, encryptedData))
            );
        }

        private async Task UpdateProfileAsync(ApiSettings apiSettings, IConfiguration config, string userId, UserProfileDetails profileDetails, EncryptedData encryptedData)
        {
            // Make API call to update user profile
            await _httpClient.PostAsync($"{apiSettings.ProfileUpdateApi}/users/{userId}", new StringContent(JsonConvert.SerializeObject(encryptedData)));

            // Log action and error (if any) for auditing and debugging
            _logger.LogInformation($"Updated user profile {userId}");
        }

        private async Task NotifyStakeholdersAsync(ProfileUpdate update)
        {
            // Get notification settings from configuration
            var notificationSettings = _configProvider.GetNotificationSettings(config);

            // Send notifications to relevant stakeholders via email or SMS
            foreach (var stakeholder in notificationSettings.Stakeholders)
            {
                await SendNotificationAsync(stakeholder, update);
            }
        }

        private async Task SendNotificationAsync(Stakeholder stakeholder, ProfileUpdate update)
        {
            // Make API call to send notification
            await _httpClient.PostAsync($"{stakeholder.NotificationApi}/notifications", new StringContent(JsonConvert.SerializeObject(update)));

            // Log action and error (if any) for auditing and debugging
            _logger.LogInformation($"Sent notification to {stakeholder.Name}");
        }
    }

