```csharp
using System;
using UnityEngine;

public class DynamicValueGenerator : IDisposable
{
    private static readonly object _lock = new object();
    private readonly ThreadSafeDictionary<int, DistributionCache> _distributionCaches;

    public enum DistributionType { Uniform, Gaussian, Exponential }

    public struct DistributionParameters
    {
        public float Min;
        public float Max;
        public DistributionType Type;
    }

    public class DistributionCache : IDisposable
    {
        private readonly ThreadSafeDictionary<float, (float, float)> _cache;

        public DistributionCache()
        {
            _cache = new ThreadSafeDictionary<float, (float, float)>();
        }

        public void Add(float value, (float, float) parameters)
        {
            lock (_lock)
            {
                _cache.Add(value, parameters);
            }
        }

        public (float, float) Get(float value)
        {
            lock (_lock)
            {
                return _cache.GetOrDefault(value, default((float, float)));
            }
        }

        public void Dispose()
        {
            _cache.Clear();
        }
    }

    public DynamicValueGenerator()
    {
        _distributionCaches = new ThreadSafeDictionary<int, DistributionCache>();
    }

    public (float, float) GenerateRandomValue(DistributionParameters parameters)
    {
        lock (_lock)
        {
            if (!_distributionCaches.ContainsKey(parameters.GetHashCode()))
            {
                _distributionCaches.Add(parameters.GetHashCode(), CreateDistributionCache(parameters));
            }
            return _distributionCaches[parameters.GetHashCode()].Get(Random.value * (parameters.Max - parameters.Min) + parameters.Min);
        }
    }

    private DistributionCache CreateDistributionCache(DistributionParameters parameters)
    {
        switch (parameters.Type)
        {
            case DistributionType.Uniform:
                return new UniformDistributionCache();
            case DistributionType.Gaussian:
                return new GaussianDistributionCache();
            case DistributionType.Exponential:
                return new ExponentialDistributionCache();
            default:
                throw new InvalidOperationException("Unsupported distribution type");
        }
    }

    public void Dispose()
    {
        foreach (var cache in _distributionCaches.Values)
        {
            cache.Dispose();
        }
    }
}

public class UniformDistributionCache : DynamicValueGenerator.DistributionCache
{
    public override (float, float) Get(float value)
    {
        return ((value - 0.5f) * 2.0f, (value - 0.5f) * 2.0f);
    }
}

public class GaussianDistributionCache : DynamicValueGenerator.DistributionCache
{
    private readonly Random _random;

    public GaussianDistributionCache()
    {
        _random = new Random();
    }

    public override (float, float) Get(float value)
    {
        var x = _random.NextGaussian();
        return ((x - 0.5f) * 2.0f, (x - 0.5f) * 2.0f);
    }
}

public class ExponentialDistributionCache : DynamicValueGenerator.DistributionCache
{
    private readonly Random _random;

    public ExponentialDistributionCache()
    {
        _random = new Random();
    }

    public override (float, float) Get(float value)
    {
        var x = _random.NextExponential();
        return ((x - 0.5f) * 2.0f, (x - 0.5f) * 2.0f);
    }
}

public static class RandomExtensions
{
    public static int NextGaussian(this Random random)
    {
        var v1 = 0.463647609;
        var v2 = 0.276698399;

        while (true)
        {
            var u1 = (double)random.NextDouble();
            var u2 = 1 - u1;

            if ((u1 > 0.5f && u2 < 0.5f) || (u1 < 0.5f && u2 > 0.5f))
                return Convert.ToInt32(v1 * (Math.Sqrt(2.0) - 1.0) * Math.Sqrt(-2.0 * Math.Log(u1)) + v2);
        }
    }

    public static int NextExponential(this Random random)
    {
        var x = double.MaxValue;

        while (true)
        {
            x = -Math.Log((double)random.NextDouble());
            if (x > 5.0f)
                return Convert.ToInt32(x);
        }
    }
}
