pipeline {
    agent any

    environment {
        GITHUB_TOKEN = 'your-github-token'
        DOCKER_USERNAME = 'your-docker-username'
        DOCKER_PASSWORD = 'your-docker-password'
        KUBERNETES_CLUSTER = 'your-kubernetes-cluster'
        JENKINS_URL = 'http://your-jenkins-url:8080'
    }

    stages {
        stage('Source Code') {
            steps {
                git 'https://github.com/your-github-repo.git', branch: 'main'
            }
        }

        stage('Build and Package') {
            steps {
                sh 'docker build -t your-service-image .'
                sh 'docker tag your-service-image your-docker-username/your-service-image:latest'
                sh 'docker push your-docker-username/your-service-image:latest'
            }
        }

        stage('Deploy to Kubernetes') {
            steps {
                kubernetesDeploy {
                    configurations = ['dev', 'test', 'prod']
                    namespace = 'default'
                    resourceFilters = ['pod']
                }
            }
        }

        stage('Test and Validate') {
            steps {
                sh 'munit -t 10 -s your-service-test-suite.xml'
            }
        }

        stage('Deploy to Environment') {
            steps {
                environment {
                    name: 'dev'
                    namespace: 'default'
                    replicas: 2
                }
                kubernetesDeploy {
                    configurations = ['dev']
                    namespace = 'default'
                    resourceFilters = ['pod']
                }
            }
        }

        stage('Rollback') {
            when {
                expression { 
                    errorCount > 0 || buildResult == 'FAILURE' 
                } 
            }
            steps {
                kubernetesDeploy {
                    configurations = ['dev']
                    namespace = 'default'
                    resourceFilters = ['pod']
                    rollback: true
                }
            }
        }

        stage('Artifact Storage') {
            steps {
                artifactStore {
                    name: 'your-artifact-store'
                    url: 'http://your-artifact-store-url.com/artifacts'
                }
            }
        }

        stage('Monitoring and Logging') {
            steps {
                prometheus {
                    url: 'http://your-prometheus-url.com/prometheus'
                    port: 9090
                }
                grafana {
                    url: 'http://your-grafana-url.com/grafana'
                    username: 'your-grafana-username'
                    password: 'your-grafana-password'
                }
            }
        }

        stage('Error Handling and Reporting') {
            steps {
                emailSender {
                    recipients: ['your-email-address@example.com']
                    subject: 'Pipeline Failure'
                }
            }
        }

        stage('Integration Testing') {
            steps {
                sh 'munit -t 10 -s your-service-integration-test-suite.xml'
            }
        }

        stage('Cleanup') {
            steps {
                cleanWs()
            }
        }
    }
}

rules {
    step([$class: 'WorkflowRule', name: 'Manual Trigger'])
}
