And here is the Rust function for generating LLVM IR code:
```rust
extern crate llvm;
use std::fs::File;
use std::io::{Read, Write};
use std::path::Path;
use lexer::{Lexer, Token};
use parser::{Parser, ASTNode};

fn generate_llvm_ir(file_path: &str) -> Result<String, String> {
    let mut file = File::open(Path::new(file_path))?;
    let mut content = String::new();
    file.read_to_string(&mut content)?;

    let lexer = Lexer::new(&content);
    let parser = Parser::new(&lexer);

    let ast = match parser.parse() {
        Ok(node) => node,
        Err(err) => return Err(err.to_string()),
    };

    let mut ir = String::new();
    writeln!(ir, "#include \"llvm-c/IR.h\"")?;
    writeln!(ir, "void main() {{")?;

    for node in ast {
        match node {
            ASTNode::Decl(decl) => writeln!(ir, "{}", decl)?,
            _ => println!("Unknown AST node"),
        }
    }

    writeln!(ir, "}}")?;

    Ok(ir)
}
```

