import reactor.core.publisher.Flux;
import reactor.util.function/slick.Functional;

public class SensorDataProcessor {
    private final FluxSink fluxSink;
    private final reactiveConfigRepository;
    private final GisApi;
    private final NoSqlDatabase;
    private final DistributedCacheSystem;
    private final DynamicConfigurationService;
    private final CryptographicService;
    private final ValidationService;
    private final WebInterface;

    public SensorDataProcessor(FluxSink fluxSink, reactiveConfigRepository, GisApi, NoSqlDatabase, DistributedCacheSystem, DynamicConfigurationService, CryptographicService, ValidationService, WebInterface) {
        this.fluxSink = fluxSink;
        this.reactiveConfigRepository = reactiveConfigRepository;
        this.GisApi = GisApi;
        this.NoSqlDatabase = NoSqlDatabase;
        this.DistributedCacheSystem = DistributedCacheSystem;
        this.DynamicConfigurationService = DynamicConfigurationService;
        this.CryptographicService = CryptographicService;
        this.ValidationService = ValidationService;
        this.WebInterface = WebInterface;
    }

    public void processSensorData(Flux<SensorEvent> sensorEvents) {
        FluxSink fluxSink = this.fluxSink.sink();
        sensorEvents
                .flatMap(event -> 
                        GisApi.getGeolocation(event.getLatitude(), event.getLongitude())
                                .map(location -> new SensorDataEvent(event, location))
                                .doOnNext(event -> NoSqlDatabase.storeEvent(event))
                                .doOnNext(event -> DistributedCacheSystem.storeEvent(event))
                                .onErrorResume(throwable -> {
                                    // handle errors
                                    return Flux.error(throwable);
                                }))
                .flatMap(event -> 
                        CryptographicService.signAndVerify(event)
                                .map(signature -> new SignedSensorDataEvent(event, signature)))
                .flatMap(event -> 
                        ValidationService.validate(event))
                .doOnNext(event -> WebInterface.visualizeData(event))
                .subscribe(fluxSink);
    }
}
