    private ExecutorService apiThreadPool;

    public APIListenerThread(ExecutorService apiThreadPool) {
        this.apiThreadPool = apiThreadPool;
    }

    @Override
    public void run() {
        while (true) {
            // Listen for new API connections and process messages
            apiThreadPool.submit(new APIConnectionProcessor());
        }
    }
