import subprocess
import tempfile
import os
from cryptography.fernet import Fernet
from getpass import getpass
from pathlib import Path

def validate_placeholders(placeholders):
    required_placeholders = ["password", "os"]
    for placeholder, value in placeholders.items():
        if placeholder not in required_placeholders:
            raise ValueError(f"Invalid placeholder: {placeholder}")
        if placeholder == "password":
            if not isinstance(value, str):
                raise ValueError("Password must be a string")
        elif placeholder == "os":
            if not isinstance(value, str):
                raise ValueError("OS must be a string")

def modify_kickstart_file(input_file, placeholders, output_dir):
    with open(input_file, 'r') as file:
        content = file.read()

    with tempfile.NamedTemporaryFile(mode='w', delete=False) as temp_file:
        for line in content.splitlines():
            if any(placeholder in line for placeholder in placeholders.keys()):
                temp_file.write(line.replace(placeholder, str(placeholders[placeholder]) + '\n'))
            else:
                temp_file.write(line + '\n')

    encrypt_password(placeholders["password"], output_dir)

    new_file_path = os.path.join(output_dir, Path(input_file).name)
    subprocess.run(f"mv {temp_file.name} {new_file_path}", shell=True)

def encrypt_password(password, output_dir):
    key = Fernet.generate_key()
    cipher_suite = Fernet(key)
    encrypted_password = cipher_suite.encrypt(password.encode())

    with open(os.path.join(output_dir, 'password'), 'wb') as file:
        file.write(encrypted_password)

def main():
    input_file_path = input("Enter Kickstart file path: ")
    output_dir_path = input("Enter output directory path: ")
    placeholders = {}

    while True:
        placeholder = input("Enter placeholder name (or 'done' if finished): ")
        if placeholder.lower() == 'done':
            break
        value = getpass(f"Enter {placeholder} value: ")
        placeholders[placeholder] = value

    validate_placeholders(placeholders)
    modify_kickstart_file(input_file_path, placeholders, output_dir_path)

if __name__ == "__main__":
    main()
