            rss = os.popen('pmap -x ' + repo_path).read().split('\n')[1].split()[1]
            print(f"RSS: {rss} MB")
        except Exception as e:
            print(f"Error monitoring resource usage: {e}")

def handle_errors():
    while True:
        try:
            response = requests.get('https://example.com/issue-tracking-system')
            if response.status_code == 200:
                print("Issue tracking system is up!")
            else:
                print(f"Issue tracking system is down! Status code: {response.status_code}")
        except Exception as e:
            print(f"Error handling errors: {e}")

def main():
    url = input("Enter the GitHub repository URL: ")
    cloner = Cloner(url)
    cloner.clone()

    pipeline_configs = [
        {'lang': 'python', 'test_framework': 'unittest'},
        {'lang': 'java', 'test_framework': 'junit'}
    ]

    with ThreadPoolExecutor() as executor:
        for config in pipeline_configs:
            pipeline = CICDPipeline(cloner.repo_name)
            executor.submit(pipeline.build_and_test, config)

    monitor_thread = threading.Thread(target=monitor_resource_usage, args=(cloner.repo_name,))
    monitor_thread.start()

    error_handler_thread = threading.Thread(target=handle_errors)
    error_handler_thread.start()

if __name__ == "__main__":
    main()
