// Caching mechanism
class PaymentCache {
public:
    static const size_t CacheExpirationTime = 30; // seconds

    std::unordered_map<std::string, std::pair<int, bool>> cache;
    std::mutex mtx;

    void addPayment(const std::string& paymentId, int timestamp, bool processed) {
        if (timestamp > CacheExpirationTime) {
            cache.erase(paymentId);
        } else {
            std::lock_guard<std::mutex> lock(mtx);
            cache[paymentId] = {timestamp, processed};
        }
    }

    bool isPaymentProcessed(const std::string& paymentId) {
        auto it = cache.find(paymentId);
        if (it != cache.end()) {
            return it->second.second;
        }
        return false;
    }
};

