use {
    std::process::{Command, ExitCode},
    std::time::{Instant, Duration},
    lazy_static::sync_lazy,
};

fn compile_with_logging(path: &str) -> Result<i32, String> {
    let start = Instant::now();

    let mut command = Command::new("rustc");
    command.arg("-Zshow-output");
    command.arg("--sysroot=/tmp/").arg(path);

    let mut child = command.spawn()?;
    let output = child.wait()?;

    let duration = start.elapsed().as_secs() as i32;
    println!("Compile time: {} seconds", duration);

    let rss_start = std::process::info().rusage().ru_maxrss;
    let rss_end = std::process::info().rusage().ru_maxrss;

    if rss_end > 200 * 1024 * 1024 {
        return Err("Memory limit exceeded".to_string());
    }

    Ok(output.code())
}

