const require = require('require');
const blueslip = require('blueslip');

function runTests(tests, initial, callback) {
  let results = initial;

  tests.reduce((prev, current, index) => {
    const { label, testFunction } = current;

    if (!label || typeof label !== 'string') {
      console.error(`Invalid test label at index ${index}: ${label}`);
      return prev;
    }

    try {
      blueslip.reset();
      const result = testFunction();

      // Perform reduction operation
      results = callback(results, result, label);

      if (result) {
        console.log(`Test "${label}" passed`);
      } else {
        console.error(`Test "${label}" failed`);
      }
    } catch (error) {
      console.error(`Error running test "${label}": ${error}`);
    }

    return results;
  }, initial);

  return results;
}

// Example usage:
const tests = [
  { label: 'test1', testFunction: () => Promise.resolve(true) },
  { label: 'test2', testFunction: () => Promise.reject(new Error('Test failed')) },
  { label: 'test3', testFunction: () => Promise.resolve(false) }
];

runTests(tests, 0, (acc, result, label) => acc + result).then((finalResult) => {
  console.log(`Final test result: ${finalResult}`);
});
