using System;
using UnityEngine;

public class DynamicValueGenerator
{
    private readonly object _lock = new object();
    private readonly Cache<RandomDistribution> _cache;
    private RandomDistribution _currentDistribution;

    public DynamicValueGenerator(ConfigurationSystem config)
    {
        _cache = new Cache<RandomDistribution>(10); // Initial cache size
        LoadDefaultDistributions(config);
    }

    public float GenerateFloat(float min, float max)
    {
        lock (_lock) return _currentDistribution.Generate(min, max, true);
    }

    public int GenerateInt(int min, int max)
    {
        lock (_lock) return _currentDistribution.Generate(min, max, false);
    }

    public override string ToString()
    {
        if (_currentDistribution == null) return "No distribution set";
        return $"Range: [{_currentDistribution.Min} {_currentDistribution.Max}], Distribution: {_currentDistribution.Type}";
    }

    public void SetDistribution(string type, float[] parameters)
    {
        lock (_lock) _currentDistribution = (RandomDistribution)_cache.GetOrAdd(type, () => CreateDistribution(type, parameters));
    }

    private RandomDistribution CreateDistribution(string type, float[] parameters)
    {
        switch (type.ToLower())
        {
            case "gaussian":
                return new GaussianDistribution(parameters);
            case "uniform":
                return new UniformDistribution(parameters);
            case "exponential":
                return new ExponentialDistribution(parameters);
            default:
                // Fallback to uniform distribution
                return new UniformDistribution();
        }
    }

    private void LoadDefaultDistributions(ConfigurationSystem config)
    {
        // Load pre-defined distributions from configuration system
        foreach (var definition in config.GetDistributions())
        {
            _cache.Add(definition.Type, () => CreateDistribution(definition.Type, definition.Parameters));
        }
    }

    public void GenerateMultiDimensionalValues(int dimensions, float[] values, out float[] result)
    {
        lock (_lock)
        {
            var distribution = (RandomDistribution)_cache.GetOrAdd("multi-dimensional", () => new MultiDimensionalDistribution(_currentDistribution));
            result = distribution.Generate(dimensions, values);
        }
    }

    public void LogGeneration()
    {
        // Log each random value generation
        UnityEngine.Logger.LogInfo($"Generated random value: {GenerateFloat(0f, 1f)}");
    }
}

public class Cache<T>
{
    private readonly int _capacity;
    private readonly Dictionary<string, T> _cache;

    public Cache(int capacity)
    {
        _capacity = capacity;
        _cache = new Dictionary<string, T>();
    }

    public T GetOrAdd(string key, Func<T> factory)
    {
        if (_cache.TryGetValue(key, out var value))
            return value;

        lock (_lock) // For thread safety
        {
            if (_cache.Count >= _capacity)
                EvictLeastRecentlyUsed();

            value = factory();
            _cache.Add(key, value);
            return value;
        }
    }

    private object _lock = new object();

    private void EvictLeastRecentlyUsed()
    {
        // Implement LRU cache eviction strategy
    }
}

