use log4rs;
use hyper::{Client, Request, Body};

struct MyHttpClient {
    client: Client<hyper::client::HttpConnector>,
}

impl MyHttpClient {
    fn new() -> Self {
        let client = Client::new(hyper::client::HttpConnector::new());
        MyHttpClient { client }
    }

    async fn send_request(&self, request: Request<Body>) {
        match self.client.request(request).await {
            Ok(response) => {
                info!("Request sent and response received");
                // Handle the response
            },
            Err(err) => {
                error!("Error sending request: {}", err);
            }
        }
    }
}

struct MyFileOperator {
    dir_path: String,
}

impl MyFileOperator {
    fn new(dir_path: &str) -> Self {
        MyFileOperator { dir_path: dir_path.to_string() }
    }

    async fn write_file(&self, file_name: &str, content: &str) {
        // Write the file
        match tokio::fs::write(self.dir_path.clone() + "/" + file_name, content.as_bytes()).await {
            Ok(_) => info!("File written successfully"),
            Err(err) => error!("Error writing file: {}", err),
        }
    }

    async fn read_file(&self, file_name: &str) -> String {
        // Read the file
        match tokio::fs::read(self.dir_path.clone() + "/" + file_name).await {
            Ok(content) => content.to_string(),
            Err(err) => error!("Error reading file: {}", err),
        }
    }
}

struct MyLogger {
    log_level: log4rs::log_level::Level,
    formatter: Box<dyn log4rs::core::Format>,
}

impl MyLogger {
    fn new(log_level: log4rs::log_level::Level, formatter: Box<dyn log4rs::core::Format>) -> Self {
        MyLogger { log_level, formatter }
    }

    async fn log(&self, level: &log4rs::log_level::Level, message: &str) {
        match level {
            log4rs::log_level::Level::INFO => info!("{}", message),
            log4rs::log_level::Level::WARN => warn!("{}", message),
            log4rs::log_level::Level::ERROR => error!("{}", message),
        }
    }
}

