```csharp
using System;
using System.Xml;
using System.IO;
using System.Linq;
using System.Collections.Generic;

public class ElementNotFoundException : Exception { }
public class MultipleElementsFoundException : Exception { }

public static class XmlProcessor
{
    private static readonly Dictionary<string, XmlDocument> _cache = new();

    public static object GetFirstMatchingElement(string xml, string xpathExpression)
    {
        ValidateXmlDocument(xml);

        if (_cache.TryGetValue(xml, out var cachedDoc))
            return GetFirstMatchingElement(cachedDoc, xpathExpression);

        try
        {
            var xmlDoc = new XmlDocument();
            xmlDoc.Load(new StringReader(xml));
            var nodes = xmlDoc.SelectNodes(xpathExpression);
            if (nodes == null || nodes.Count == 0)
                throw new ElementNotFoundException("No element found matching the given XPath expression.");
            else if (nodes.Count > 1)
                throw new MultipleElementsFoundException($"Multiple elements found ({nodes.Count})");

            return nodes[0];
        }
        finally
        {
            _cache[xml] = xmlDoc;
        }
    }

    private static void ValidateXmlDocument(string xml)
    {
        using var stream = new MemoryStream();
        using var writer = new StreamWriter(stream);
        writer.Write(xml);
        writer.Flush();
        stream.Position = 0;

        try
        {
            XmlDocument document = new XmlDocument();
            document.Load(stream);
        }
        catch (XmlException)
        {
            throw new ArgumentException("Invalid XML document.", nameof(xml));
        }
    }
}
