#include <random>
#include <iostream>
#include <fstream>
#include <string>
#include <stdexcept>

namespace RandomGenerator {
    class MT19937Generator {
        public:
            MT19937Generator(int seed) : mt(seed), min_(0), max_(10000) {}

            int getRandomNumber() {
                std::uniform_int_distribution<int> dist(min_, max_);
                return dist(mt);
            }

            void setRange(int min, int max) {
                if (min > max) {
                    throw std::runtime_error("Invalid range");
                }
                min_ = min;
                max_ = max;
            }

            void storeSeed(int seed) {
                std::ofstream file("seed.txt");
                file << seed;
                file.close();
            }

            int retrieveSeed() {
                std::ifstream file("seed.txt");
                if (!file) {
                    return 1; // default seed
                }
                int seed;
                file >> seed;
                return seed;
            }

        private:
            std::mt19937 mt;
            int min_;
            int max_;
    };
}
