import com.example.transcoding.module.TranscodingModule;

public class VideoTranscoder {

    public List<TranscodingStatus> transcodeVideos(String inputDirPath, String outputDirPath) throws Exception {
        TranscodingModule transcodingModule = new TranscodingModule();

        // Initialize the transcoding queue
        List<File> filesToTranscode = getVideoFiles(inputDirPath);
        List<TranscodingTask> transcodingQueue = new ArrayList<>();

        // Iterate over each file and add it to the transcoding queue
        for (File file : filesToTranscode) {
            TranscodingTask task = getTranscodingTask(file, transcodingModule);
            transcodingQueue.add(task);
        }

        // Sort the transcoding queue by duration and size
        transcodingQueue.sort((task1, task2) -> {
            if (task1.getDuration() < task2.getDuration()) return -1;
            else if (task1.getDuration() > task2.getDuration()) return 1;
            else if (task1.getSize() < task2.getSize()) return -1;
            else return 1;
        });

        // Start transcoding and logging progress
        List<TranscodingStatus> statuses = new ArrayList<>();
        for (TranscodingTask task : transcodingQueue) {
            TranscodingStatus status = transcodingModule.transcode(task);
            statuses.add(status);

            if (!status.isSuccess()) {
                // Handle errors or timeouts
                handleTranscodingError(status);
            }
        }

        return statuses;
    }

    private List<File> getVideoFiles(String inputDirPath) throws Exception {
