        EVP_DecryptInit_ex(EVP_get_ciphers()[3], NULL, NULL);
    } else if (strcmp(mode, "ede") == 0) {
        EVP_DecryptInit_ex(EVP_get_ciphers()[4], NULL, NULL);
    } else if (strcmp(mode, "ede3") == 0) {
        EVP_DecryptInit_ex(EVP_get_ciphers()[5], NULL, NULL);
    } else if (strcmp(mode, "cfb") == 0) {
        EVP_DecryptInit_ex(EVP_get_ciphers()[6], NULL, NULL);
    } else if (strcmp(mode, "NULL") == 0) {
        // Do nothing for null encryption
    } else {
        printf("Invalid cipher mode\n");
        return NULL;
    }
    return ctx;
}
