import csv
import datetime as dt
from io import StringIO
from typing import Dict, List

class TransactionProcessor:
    def __init__(self):
        self.api_connection = None

    def process_transactions(self, 
                             input_file: str, 
                             date_range: tuple, 
                             transaction_types: List[str], 
                             currencies: List[str], 
                             output_file: str) -> Dict:
        summaries = {}

        with open(input_file, 'r') as file:
            reader = csv.DictReader(file)

            for row in reader:
                if self._validate_date(row['date'], date_range):
                    if any(type in row['type'] for type in transaction_types):
                        if any(currency == row['currency'] for currency in currencies):
                            self._process_transaction(row, summaries)

        with open(output_file, 'w') as file:
            writer = csv.writer(file)
            writer.writerow(['date', 'daily_summary', 'weekly_summary', 'monthly_summary'])

            for date, summary in summaries.items():
                writer.writerow([date, summary['daily'], summary['weekly'], summary['monthly']])

        return self._fetch_exchange_rates(currencies)

    def _validate_date(self, date: str, date_range: tuple) -> bool:
        start_date, end_date = date_range
        target_date = dt.datetime.strptime(date, '%Y-%m-%d')

        if start_date <= target_date <= end_date:
            return True

        return False

    def _process_transaction(self, row: Dict, summaries: Dict) -> None:
        date = dt.datetime.strptime(row['date'], '%Y-%m-%d').strftime('%Y-%m')

        if date not in summaries:
            summaries[date] = {'daily': 0, 'weekly': 0, 'monthly': 0}

        if row['type'] == 'deposit':
            summaries[date]['daily'] += float(row['amount'])
        elif row['type'] == 'withdrawal':
            summaries[date]['daily'] -= float(row['amount'])

    def _fetch_exchange_rates(self, currencies: List[str]) -> Dict:
        if not self.api_connection:
            self.api_connection = self._establish_api_connection()

        rates = {}

        for currency in currencies:
            response = self.api_connection.get(f'exchange_rate/{currency}')

            if response.status_code == 200:
                rate = response.json()['rate']

                if currency not in rates:
                    rates[currency] = {'daily': 0, 'weekly': 0, 'monthly': 0}

                rates[currency]['daily'] += rate
                rates[currency]['weekly'] += rate
                rates[currency]['monthly'] += rate

        return rates

    def _establish_api_connection(self) -> None:
        # Establish connection with the API
        pass

if __name__ == '__main__':
    processor = TransactionProcessor()
    input_file = 'input.csv'
    date_range = ('2020-01-01', '2021-12-31')
    transaction_types = ['deposit', 'withdrawal']
    currencies = ['USD', 'EUR', 'JPY']
    output_file = 'output.json'

    processor.process_transactions(input_file, date_range, transaction_types, currencies, output_file)
