    *offsetValues = 0;
    for (int i = 0; i < featureSize; i++) {
        *(offsetValues + i) = i;
    }

    for (int i = 0; i < initialLeafNodes; i++) {
        *(keys + i) = i;
    }

    // Initialize records
    *records = (Record*) malloc(dataCapacity * sizeof(Record));
