#include <boost/asio.hpp>
#include <boost/thread.hpp>
#include <iostream>
#include <map>
#include <set>
#include <queue>

// Request parsing module
struct Request {
    std::string method;
    std::string url;
    std::map<std::string, std::string> headers;
    std::string body;
};

// Thread pool for managing concurrent connections
class ThreadPool {
public:
    ThreadPool(size_t numThreads) : stop(false), threads(numThreads) {
        for (size_t i = 0; i < numThreads; ++i)
            threads.emplace_back([this] { this->run(); });
    }

    template<typename Function>
    void post(Function&& function) {
        {
            std::unique_lock<std::mutex> lock(queue_mutex);
            queue.push(std::forward<Function>(function));
        }
        condition.notify_one();
    }

    void stop() {
        {
            std::unique_lock<std::mutex> lock(queue_mutex);
            stop = true;
        }
        condition.notify_all();
        for (std::thread & thread : threads)
            thread.join();
    }

private:
    std::vector<std::thread> threads;
    std::condition_variable condition;
    std::queue<Function> queue;
    mutable std::mutex queue_mutex;
    bool stop;

    void run() {
        while (!stop) {
            Function f;
            {
                std::unique_lock<std::mutex> lock(queue_mutex);
                if (queue.empty())
                    condition.wait(lock);
                f = std::move(queue.front());
                queue.pop();
            }
            f();
        }
    }
};

