import json
import xml.etree.ElementTree as ET
import asyncio
from aiopg import create_pool
import logging
import requests
import re
import datetime

logging.basicConfig(level=logging.INFO)

class SensorDataValidator:
    def __init__(self, schema_file):
        self.schema = json.load(open(schema_file))

    async def validate_json(self, data):
        try:
            if not isinstance(data, dict) or 'data' not in data:
                return {'error': 'Invalid JSON format'}
            data['timestamp'] = datetime.datetime.now().isoformat()
            await self.validate_against_schema(data)
            return data
        except Exception as e:
            logging.error(f"Error validating JSON: {str(e)}")
            return {'error': str(e)}

    async def validate_xml(self, data):
        try:
            root = ET.fromstring(data.encode())
            if not self.schema['type'] == 'xml' or self.schema['elements'][0]['name'] != root.tag:
                return {'error': 'Invalid XML format'}
            await self.validate_against_schema(root.attrib)
            return {k: v for k, v in root.attrib.items()}
        except Exception as e:
            logging.error(f"Error validating XML: {str(e)}")
            return {'error': str(e)}

    async def validate_against_schema(self, data):
        try:
            if not self.schema['type'] == 'json':
                raise ValueError('Invalid schema type')
            for k, v in self.schema['elements'][0]['properties'].items():
                if k not in data or not isinstance(data[k], type(v)):
                    raise ValueError(f"Invalid property '{k}'")
        except Exception as e:
            logging.error(f"Error validating against schema: {str(e)}")
            raise ValueError(str(e))

class SensorDataProcessor:
    def __init__(self, db_pool, sensor_validator):
        self.db_pool = db_pool
        self.sensor_validator = sensor_validator

    async def process_data(self, data):
        try:
            if 'data' not in data or not isinstance(data['data'], (dict, bytes)):
                return {'error': 'Invalid data format'}
            if isinstance(data['data'], dict):
                await self.process_json(data)
            elif isinstance(data['data'], bytes):
                await self.process_binary(data)
        except Exception as e:
            logging.error(f"Error processing data: {str(e)}")
            return {'error': str(e)}

    async def process_json(self, data):
        try:
            if not data['timestamp']:
                raise ValueError('Timestamp is required')
            await self.sensor_validator.validate_json(data)
            await self.store_data_in_db(data)
            return {'message': 'Data processed successfully'}
        except Exception as e:
            logging.error(f"Error processing JSON: {str(e)}")
            return {'error': str(e)}

    async def process_binary(self, data):
        try:
            if not data['timestamp']:
                raise ValueError('Timestamp is required')
            await self.sensor_validator.validate_xml(data)
            await self.store_data_in_db(data)
            return {'message': 'Data processed successfully'}
        except Exception as e:
            logging.error(f"Error processing binary: {str(e)}")
            return {'error': str(e)}

    async def store_data_in_db(self, data):
        try:
            conn = await self.db_pool.acquire()
            cursor = await conn.cursor()
            query = "INSERT INTO sensor_data (timestamp, data) VALUES (%s, %s)"
            await cursor.execute(query, (data['timestamp'], json.dumps(data)))
            await conn.commit()
            await self.db_pool.release(conn)
        except Exception as e:
            logging.error(f"Error storing data in DB: {str(e)}")
            raise ValueError(str(e))

async def main():
    db_pool = create_pool(host='localhost', database='sensor_data', user='user', password='password')
    sensor_validator = SensorDataValidator('schema.json')
    processor = SensorDataProcessor(db_pool, sensor_validator)

    while True:
        data = await get_sensor_data()
        if not data or 'data' not in data:
            continue
        result = await processor.process_data(data)
        logging.info(f"Result: {result}")

