```cpp
#include <iostream>
#include <vector>
#include <string>
#include <mutex>
#include <thread>

class KDTree {
private:
    struct Point {
        double x;
        double y;
        // Add more dimensions as needed
    };

    struct Node {
        Point point;
        int axis; // 0 for x-axis, 1 for y-axis
        Node* left;
        Node* right;
    };

    void insert(Node*& root, const Point& point) {
        if (root == nullptr) {
            root = new Node();
            root->point = point;
            return;
        }

        int axis = 0; // Start with x-axis

        while (true) {
            if (point.x < root->point.x) {
                if (root->left == nullptr) {
                    root->left = new Node();
                    root->left->point = point;
                    break;
                }
                root = root->left;
            } else {
                if (root->right == nullptr) {
                    root->right = new Node();
                    root->right->point = point;
                    break;
                }
                root = root->right;
            }

            axis = (axis + 1) % 2; // Switch to y-axis
        }
    }

    void remove(Node*& root, const Point& point) {
        if (root == nullptr || root->point.x != point.x || root->point.y != point.y)
            return;

        Node* temp = nullptr;
        if (root->left && root->right) {
            if (temp == nullptr) {
                temp = new Node();
                *temp = *root;
            }

            // Find the replacement node
            int axis = 0; // Start with x-axis
            while (true) {
                if (point.x < root->point.x) {
                    if (root->left && root->right) {
                        if (root->left->point.y <= root->right->point.y) {
                            root = root->left;
                            axis = 0; // Switch to x-axis
                        } else {
                            root = root->right;
                            axis = 1; // Switch to y-axis
                        }
                    } else {
                        if (root->axis == 0) {
                            root = root->left;
                            axis = 0; // Switch to x-axis
                        } else {
                            root = root->right;
                            axis = 1; // Switch to y-axis
                        }
                    }
                } else {
                    if (root->left && root->right) {
                        if (root->left->point.y <= root->right->point.y) {
                            root = root->left;
                            axis = 0; // Switch to x-axis
                        } else {
                            root = root->right;
                            axis = 1; // Switch to y-axis
                        }
                    } else {
                        if (root->axis == 0) {
                            root = root->left;
                            axis = 0; // Switch to x-axis
                        } else {
                            root = root->right;
                            axis = 1; // Switch to y-axis
                        }
                    }
                }

                if (!root || !temp)
                    return;

                if (axis == 0) {
                    temp->point.x = root->point.x;
                    temp->left = root->left;
                    temp->right = root->right;
                } else {
                    temp->point.y = root->point.y;
                    temp->left = root->left;
                    temp->right = root->right;
                }
            }

            if (temp) {
                delete root;
                root = temp;
            }
        } else {
            if (root)
                delete root;
            root = nullptr;
        }
    }

    Point nearestNeighbor(Node* node, const Point& queryPoint) {
        if (!node)
            return Point();

        int axis = 0; // Start with x-axis

        if (queryPoint.x < node->point.x) {
            Node* left = node->left;
            Node* right = node->right;

            while (true) {
                if (!left && !right)
                    break;
                else if (!right || queryPoint.y <= right->point.y) {
                    right = nullptr;
                    axis = 1; // Switch to y-axis
                } else {
                    left = nullptr;
                    axis = 0; // Switch to x-axis
                }
            }
        } else if (queryPoint.x > node->point.x) {
            Node* left = node->left;
            Node* right = node->right;

            while (true) {
                if (!left && !right)
                    break;
                else if (!right || queryPoint.y <= right->point.y) {
                    right = nullptr;
                    axis = 1; // Switch to y-axis
                } else {
                    left = nullptr;
                    axis = 0; // Switch to x-axis
                }
            }
        } else {
            int distanceLeft = (queryPoint.x - node->point.x);
            int distanceRight = (queryPoint.y - node->point.y);

            if (distanceLeft <= distanceRight) {
                Node* left = node->left;
                Node* right = node->right;

                while (true) {
                    if (!left && !right)
                        break;
                    else if (!right || queryPoint.y <= right->point.y) {
                        right = nullptr;
                        axis = 1; // Switch to y-axis
                    } else {
                        left = nullptr;
                        axis = 0; // Switch to x-axis
                    }
                }
            } else {
                Node* left = node->left;
                Node* right = node->right;

                while (true) {
                    if (!left && !right)
                        break;
                    else if (!right || queryPoint.y <= right->point.y) {
                        right = nullptr;
                        axis = 1; // Switch to y-axis
                    } else {
                        left = nullptr;
                        axis = 0; // Switch to x-axis
                    }
                }
            }
        }

        return node->point;
    }

public:
    KDTree(int numInitialPoints, int dimensions) : root(nullptr) {
        for (int i = 0; i < numInitialPoints; i++) {
            Point point;
            // Initialize the point coordinates here...
            insert(root, point);
        }
    }

    ~KDTree() {
        deleteNodeRecursive(root);
    }

    void insert(const Point& point) {
        insert(root, point);
        if (root->left && root->right)
            rebalance();
    }

    void remove(const Point& point) {
        remove(root, point);
        rebalance();
    }

    Point nearestNeighbor(const Point& queryPoint) {
        return nearestNeighbor(root, queryPoint);
    }

    // For persisting the k-d tree
    void saveToDatabase() {
        // Implement database operations here...
    }

    // For loading the k-d tree from a database
    void loadFromDatabase() {
        // Implement database operations here...
    }

private:
    void deleteNodeRecursive(Node* node) {
        if (node == nullptr)
            return;

        if (node->left)
            deleteNodeRecursive(node->left);

        if (node->right)
            deleteNodeRecursive(node->right);

        delete node;
    }

    void rebalance() {
        // Implement the tree balancing algorithm here...
    }
};
