```rust
use reqwest::blocking as rb;
use reqwest::proxy::{Proxy, Tunnel};
use reqwest::tls::Config as TlsConfig;
use std::fs::remove_file;
use std::io;
use std::path::Path;

struct Logger {
    level: String,
    format: String,
}

impl Logger {
    fn new(level: &str, format: &str) -> Self {
        Logger {
            level: level.to_string(),
            format: format.to_string(),
        }
    }

    fn log(&self, message: &str) {
        if self.level.eq_ignore_case("info") {
            println!("{}", message);
        } else if self.level.eq_ignore_case("error") && message.contains("error") {
            eprintln!("{}", message);
        }
    }
}

fn create_https_client(tls_config: TlsConfig, proxy: Option<Proxy>) -> rb::Client {
    let mut client = rb::blocking::get().unwrap();
    client.proxy(proxy).unwrap();
    client.tls_config(tls_config)
}

fn main() {
    let tls_config = TlsConfig::new()
        .root_certificates_path("path/to/root/certificates")
        .client_cert_chain("path/to/client/cert/pem", "path/to/private/key")
        .build();
    let proxy = Some(Proxy::http("https://my-proxy.com").port(8080));
    let client = create_https_client(tls_config, proxy);

    let url = "https://example.com/path";
    if Path::new("output.txt").exists() {
        remove_file("output.txt").unwrap();
    }

    match client.get(url) {
        Ok(mut res) => {
            if let io::WriteGuard<writer> = &mut res.writer() {
                writer.write_all(b"This is a test message.").unwrap();
            }
            let mut body = String::new();
            res.read_to_string(&mut body).unwrap();
            println!("{}", body);
        },
        Err(e) => match e {
            rb::Error::Tls(tls_err) => Logger { level: "error".to_string(), format: "%s" }.log(&format!("TLS error: {}", tls_err)),
            _ => Logger { level: "error".to_string(), format: "%s" }.log(&format!("Request error: {}", e)),
        },
    }
}
