import java.io.File;
import java.util.ArrayList;
import java.util.List;

public class ImageProcessor {

    public static void main(String[] args) {
        // Parse command-line arguments
        String outputFileName = "output.pdf";
        String inputDirectoryPath = "/path/to/images";
        boolean watermark = false;

        if (args.length > 0) {
            outputFileName = args[0];
        }
        if (args.length > 1) {
            inputDirectoryPath = args[1];
        }
        if (args.length > 2) {
            watermark = Boolean.parseBoolean(args[2]);
        }

        // Initialize image metadata service
        ImageMetadataService metadataService = new ImageMetadataService();

        // Process images in the specified directory
        try (DirectoryStream<File> stream = Files.newInputStream(Path.of(inputDirectoryPath), StandardOpenOption.READ)) {
            List<ImageFileInfo> imageFiles = new ArrayList<>();
            for (File file : stream) {
                if (!file.isFile()) continue;
                String filePath = file.getAbsolutePath();
                ImageFileInfo info = metadataService.getImageFileInfo(filePath);
                imageFiles.add(new ImageFileInfo(file.getName(), info.getResolution(), info.getColorDepth(), file.length()));
            }

            // Generate PDF document
            try (PDDocument pdfDocument = new PDDocument()) {
                int index = 0;
                for (ImageFileInfo imageFile : imageFiles) {
                    PDPage page = pdfDocument.addPage(new PDPage());
                    BufferedImage image = ImageIO.read(new File(filePath));
                    if (watermark) {
                        // Add watermark to the image
                        BufferedImage watermarkImage = ImageIO.read(new File("/path/to/watermark.png"));
                        Graphics2D graphics = image.createGraphics();
                        graphics.drawImage(watermarkImage, 0, 0, null);
                        graphics.dispose();
                    }
                    PDJPEGImage img = new PDJPEGImage(image);
                    page.add(img);
                    index++;
                }

                // Save the PDF document
                pdfDocument.save(new File(outputFileName));
            } catch (IOException e) {
                System.out.println("Error generating PDF: " + e.getMessage());
            }
        } catch (IOException e) {
            System.out.println("Error processing directory: " + e.getMessage());
        }

        System.exit(watermark ? 0 : 1);
    }
}

