#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int value;
    char* message;
} record;

record** initArrays(int min, int max) {
    // Initialize arrays with default size and realloc as needed.
    int initialSize = 10;
    int* offsets = (int*)malloc(initialSize * sizeof(int));
    int keyCount = 0;
    record** records = (record**)malloc(initialSize * sizeof(record*));

    for (int i = 0; i < initialSize; i++) {
        records[i] = (record*)malloc(sizeof(record));
        // Initialize with random values
        offsets[i] = min + rand() % (max - min);
        // Allocate space for message and initialize it.
        records[i]->message = (char*)malloc(100 * sizeof(char));
        strcpy(records[i]->message, "Initial message");
        records[i]->value = 0;
    }

    // Save the data to a file
    FILE* file = fopen("data.txt", "w+");
    if (!file) {
        printf("Failed to open file.\n");
        return NULL;
    }

    for (int i = 0; i < initialSize; i++) {
        fprintf(file, "%d %s\n", offsets[i], records[i]->message);
    }

    fclose(file);

    // Reallocate arrays if needed
    int reallocatedSize = initialSize * 2;
    int* newOffsets = (int*)malloc(reallocatedSize * sizeof(int));
    record** newRecords = (record**)malloc(reallocatedSize * sizeof(record*));

    for (int i = 0; i < reallocatedSize; i++) {
        if (i < initialSize) {
            // Copy existing data
            newOffsets[i] = offsets[i];
            newRecords[i] = records[i];
        } else {
            // Initialize with random values
            newOffsets[i] = min + rand() % (max - min);
            newRecords[i] = (record*)malloc(sizeof(record));
            // Allocate space for message and initialize it.
            newRecords[i]->message = (char*)malloc(100 * sizeof(char));
            strcpy(newRecords[i]->message, "Initial message");
            newRecords[i]->value = 0;
        }
    }

    // Free original data
    free(offsets);
    for (int i = 0; i < initialSize; i++) {
        free(records[i]->message);
        free(records[i]);
    }
    free(records);

    return newRecords;
}
