import asyncio
from dcosservice_mesh import TransactionManager
from payments import PaymentGateway, CreditCardPaymentMethod, PayPalPaymentMethod, CryptocurrencyPaymentMethod
from inventory import InventoryService
from order import OrderService
from logging import Logger
from prometheus_client import start_http_server, gauge, Counter

class PaymentProcessor:
    def __init__(self):
        self.transaction_manager = TransactionManager()
        self.payment_gateway = PaymentGateway()
        self.inventory_service = InventoryService()
        self.order_service = OrderService()
        self.logger = Logger('payment_processor')
        self.prometheus_metrics = {
            'transactions_total': Counter('transactions_total', 'Total transactions'),
            'transactions_error': Counter('transactions_error', 'Error transactions'),
            'retries_total': Counter('retries_total', 'Total retries'),
            'retries_error': Counter('retries_error', 'Error retries')
        }

    async def process_payment_transaction(self, order_id, payment_amount, payment_method, customer_ip, max_retry_attempts):
        transaction_id = self.transaction_manager.start_transaction()

        try:
            if payment_method == 'credit_card':
                payment_gateway_response = await self.payment_gateway.process_credit_card_payment(order_id, payment_amount)
            elif payment_method == 'paypal':
                payment_gateway_response = await self.payment_gateway.process_paypal_payment(order_id, payment_amount)
            elif payment_method == 'cryptocurrency':
                payment_gateway_response = await self.payment_gateway.process_cryptocurrency_payment(order_id, payment_amount)

            if payment_gateway_response['status'] == 'success':
                # Update order status and inventory levels
                await self.order_service.update_order_status(order_id, 'paid')
                await self.inventory_service.update_inventory_levels(order_id)
                self.prometheus_metrics['transactions_total'].inc()

                return f"Payment for order {order_id} successful"

            else:
                raise Exception('Payment failed')

        except Exception as e:
            self.logger.error(f'Error processing payment transaction: {e}')
            self.prometheus_metrics['transactions_error'].inc()

            if max_retry_attempts > 0:
                await asyncio.sleep(2 ** (max_retry_attempts - 1))  # Exponential backoff
                try:
                    return await self.process_payment_transaction(order_id, payment_amount, payment_method, customer_ip, max_retry_attempts - 1)
                except Exception as e:
                    self.logger.error(f'Error retrying payment transaction: {e}')
                    self.prometheus_metrics['retries_error'].inc()
            else:
                self.prometheus_metrics['retries_total'].inc()

        finally:
            self.transaction_manager.commit_transaction(transaction_id)

    def start_prometheus_server(self):
        start_http_server(8000)
