    public static Map<String, String> mapPokemonWeakness(List<Pokemon> pokemonList) {
        Map<String, String> weaknessMap = new HashMap<>();

        for (Pokemon pokemon : pokemonList) {
            String pokemonName = pokemon.getName();
            Weaknesses weaknesses;

            synchronized (lock) {
                if (!cache.containsKey(pokemonName)) {
                    try {
                        weaknesses = retrieveWeaknessFromAPI(pokemonName);
                        cache.put(pokemonName, weaknesses);
                    } catch (IOException e) {
                        logError(e);
                        weaknesses = getLastKnownGoodWeaknesses(pokemonName);
                    }
                } else {
                    weaknesses = cache.get(pokemonName);
                }

                if (!cache.containsKey(pokemonName)) {
                    // Cache expiration or invalidation
                    try {
                        Thread.sleep(EXPIRATION_TIME_MILLISECONDS); // simulate periodic update from API
                        weaknesses = retrieveWeaknessFromAPI(pokemonName);
                        cache.put(pokemonName, weaknesses);
                    } catch (InterruptedException | IOException e) {
                        logError(e);
                    }
                }
            }

            weaknessMap.put(pokemonName, getCombinedWeaknesses(weaknesses));
