#include <thread>

class PaymentProcessor {
public:
    PaymentProcessor(int chunkSize, int retryAttempts) 
        : chunkSize_(chunkSize), retryAttempts_(retryAttempts) {}

    void processPaymentTransaction(const std::string& paymentMetadata) {
        // Validate payment metadata
        if (!validateMetadata(paymentMetadata)) {
            return;
        }

        // Check if transaction is already processed
        if (isProcessed(paymentMetadata)) {
            return;
        }

        // Handle caching for up to 30 seconds
        auto cacheTimer = std::chrono::steady_clock::now() + std::chrono::seconds(30);
        while (cacheTimer > std::chrono::steady_clock::now()) {
            // Wait for caching expiration or retry attempts exceed
            if (!retryAttempts_) {
                return;
            }
            retryAttempts_--;
        }

        // Process transaction with payment gateway
        auto paymentGateway = getPaymentGateway();
        if (!paymentGateway->processTransaction(paymentMetadata)) {
            // Handle failed transaction and exponential backoff
            int delay = 1;
            while (retryAttempts_) {
                std::this_thread::sleep_for(std::chrono::seconds(delay));
                if (paymentGateway->processTransaction(paymentMetadata)) {
                    return;
                }
                delay *= 2;
            }
        }
    }

private:
