#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <zlib.h>
#include <pthread.h>

typedef struct {
    char* filename;
    char* compression_format;
    int size;
} Bundle;

typedef struct {
    Bundle* bundle;
    pthread_mutex_t lock;
    int ref_count;
} BundleHandle;

void* load_bundle(const char* filename, const char* compression_format) {
    // Load the bundle from the file
    FILE* f = fopen(filename, "rb");
    if (!f) return NULL;

    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    rewind(f);

    Bundle* bundle = malloc(sizeof(Bundle));
    bundle->filename = strdup(filename);
    bundle->compression_format = strdup(compression_format);
    bundle->size = size;

    // Decompress the bundle
    unsigned char* data = malloc(size);
    if (!data) {
        fclose(f);
        free(bundle);
        return NULL;
    }

    fread(data, 1, size, f);
    fclose(f);

    // Store the bundle in a cache
    BundleHandle* handle = malloc(sizeof(BundleHandle));
    handle->bundle = bundle;
    pthread_mutex_init(&handle->lock, NULL);
    handle->ref_count = 0;

    return (void*) handle;
}

int unload_bundle(void* handle) {
    BundleHandle* h = (BundleHandle*) handle;
    if (!h) return -1;

    // Release any resources held by the bundle
    free(h->bundle->filename);
    free(h->bundle->compression_format);
    free(h->bundle);

    pthread_mutex_destroy(&h->lock);

    int refs = --h->ref_count;
    if (refs == 0) {
        free(h);
        return 1;
    } else {
        return 0;
    }
}

void* get_bundle(void* handle) {
    BundleHandle* h = (BundleHandle*) handle;
    pthread_mutex_lock(&h->lock);
    int refs = ++h->ref_count;
    pthread_mutex_unlock(&h->lock);

    // Return the bundle
    return h->bundle;
}

int main() {
    void* bundle1 = load_bundle("bundle1.zip", "zlib");
    void* bundle2 = load_bundle("bundle2.gz", "gzip");

    BundleHandle* handle1 = (BundleHandle*) bundle1;
    BundleHandle* handle2 = (BundleHandle*) bundle2;

    // Use the bundles
    Bundle* b1 = get_bundle(bundle1);
    Bundle* b2 = get_bundle(bundle2);

    // Unload the bundles when done
    int status1 = unload_bundle(handle1);
    int status2 = unload_bundle(handle2);

    return 0;
}
