import requests
from jsonschema import validate as json_validate
from jsonschema.exceptions import ValidationError
from logging import getLogger
import time
import concurrent.futures

logger = getLogger()

def update_profile(user_data, api_config):
    profile_schema = {
        "type": "object",
        "properties": {
            "email": {"type": "string", "format": "email"},
            "phone_number": {"type": "string", "pattern": r"^\d{10}$"}
        },
        "required": ["email", "phone_number"]
    }

    def update_api(api_url, data):
        try:
            response = requests.put(api_url, json=data)
            response.raise_for_status()
        except (requests.exceptions.RequestException) as e:
            logger.error(f"Error updating {api_url}: {e}")
            return False
        else:
            return True

    def update_user_profile(user_data):
        api_urls = {
            "authentication": "https://auth-api.com/update",
            "billing": "https://billing-api.com/profile",
            "notification": "https://notify-api.com/user"
        }

        for service, url in api_urls.items():
            try:
                json_validate(user_data, profile_schema)
            except ValidationError as e:
                logger.error(f"Invalid user data: {e}")
                return False

            if not update_api(url, user_data):
                return False
            logger.info(f"Updated {service} successfully")

        return True

    def retry_update(api_url, data):
        max_retries = 3
        delay = 5
        for _ in range(max_retries):
            if update_api(api_url, data):
                return True
            time.sleep(delay)
        logger.error(f"Failed to update {api_url} after {max_retries} retries")
        return False

    with concurrent.futures.ThreadPoolExecutor() as executor:
        futures = []
        for service, url in api_urls.items():
            future = executor.submit(retry_update, url, user_data)
            futures.append(future)

        for future in concurrent.futures.as_completed(futures):
            result = future.result()
            if not result:
                logger.error("Update failed")
                return False

    logger.info("Profile updated successfully")

    return True
