        this.id = id;
    }
}

interface DatabaseService {
    void storeNode(String nodeId);
    void deleteNode(String nodeId);
    void storeEdge(String sourceNodeId, String targetNodeId);
    void deleteEdge(String sourceNodeId, String targetNodeId);
}

interface MessagingService {
    void publishUpdate(String updateType, String nodeId);
}
