const { Transform } = require('stream');
const { createLogger, format, transports } = require('winston');

class StreamDataProcessor {
  constructor({
    loggerOptions,
    throttlingInterval,
  }) {
    this.logger = createLogger({
      format: format.json(),
      transports: [new transports.Console()],
      ...loggerOptions,
    });

    this.throttlingInterval = throttlingInterval;
  }

  async processStreams(streams, byteCount) {
    const chunks = [];
    const totalBytesCopied = new Set();

    function handleStreamError(stream) {
      stream.on('error', (err) => {
        this.logger.error(`Error processing stream ${stream.id}:`, err);
      });
    }

    streams.forEach((stream) => {
      handleStreamError(stream);

      const transformer = new Transformer({
        readable: true,
        writable: true,
      });

      stream.pipe(transformer).on('data', (chunk) => {
        if (!totalBytesCopied.has(byteCount)) {
          chunks.push(chunk);
        }
      });
    });

    return Promise.all(chunks.map((chunk) => {
      const output = Buffer.from('');
      let bytesCopied = 0;

      chunk.on('data', (data) => {
        try {
          output.write(data);
          bytesCopied += data.length;
        } catch (err) {
          this.logger.error(`Error copying data:`, err);
        }
      });

      return new Promise((resolve, reject) => {
        setTimeout(() => {
          if (bytesCopied >= byteCount) {
            resolve(output.slice(0, byteCount));
          } else if (chunks.length > 1 && bytesCopied + chunk.length > byteCount) {
            const remainingBytes = byteCount - bytesCopied;
            output.write(chunk.slice(0, remainingBytes));
            resolve(output);
          } else {
            chunk.on('end', () => {
              resolve(output);
            });
            chunk.on('error', (err) => {
              reject(err);
            });
          }
        }, this.throttlingInterval);
      });
    }));
  }
}

class Transformer extends Transform {
  _transform(chunk, encoding, callback) {
    try {
      const output = Buffer.from('');
      let bytesCopied = 0;

      chunk.on('data', (data) => {
        try {
          output.write(data);
          bytesCopied += data.length;
        } catch (err) {
          this.emit('error', err);
        }
      });

      callback(null, new Buffer(output));
    } catch (err) {
      callback(err);
    }
  }

  _flush(callback) {
    callback();
  }
}

module.exports = StreamDataProcessor;

