```
bool updateForwardList(std::forward_list<std::string>& list, const std::string& key, const std::string& value) {
    auto it = list.begin();
    while (it != list.end()) {
        if (*it == key) {
            if (!value.empty()) {
                *it = value;
                return true;
            } else {
                auto newNode = list.emplace_after(it, value);
                *newNode = std::move(*it);
                it = newNode;
                return true;
            }
        }
        ++it;
    }
    if (!value.empty()) {
        list.append(value);
    }
    return false;
}
