        {
            _next = next;
            _logger = logger;
        }

        public async Task InvokeAsync(HttpContext context)
        {
            if (context.Request.Method != HttpMethods.Post)
            {
                await _next(context);
                return;
            }

            var clinicId = context.Request.Form["clinicId"];
            var newStatus = context.Request.Form["newStatus"];
            var lastModifiedIP = context.Request.Form["lastModifiedIP"];
            var lastModifiedByUserId = int.Parse(context.Request.Form["lastModifiedByUserId"]);
            var language = context.Request.Form["language"];

            try
            {
                // Fetch and apply updated clinic status from multiple CMS providers
                // ...

                // Apply rate limiter
                await RateLimitAsync(context);

                // Update database with new clinic status
                using (var dbContext = new ClinicStatusDbContext())
                {
                    dbContext.ClinicStatuses.Update(new ClinicStatus { ClinicId = int.Parse(clinicId), NewStatus = newStatus });
                    dbContext.SaveChanges();
                }

                // Log successful update
                _logger.LogInformation("Clinic status updated successfully for clinic ID {clinicId} with new status {newStatus}", clinicId, newStatus);

                // Send email notification to clinic administrators
                await SendEmailNotificationAsync(clinicId, lastModifiedByUserId, language);
            }
            catch (Exception ex)
            {
                // Handle network errors, authentication failures, and invalid input gracefully
                _logger.LogError(ex, "Error updating clinic status");

                // Log error
                _logger.LogError("Failed to update clinic status for clinic ID {clinicId} with new status {newStatus}", clinicId, newStatus);

                // Return error response
                context.Response.StatusCode = 500;
            }
        }

        private async Task RateLimitAsync(HttpContext context)
        {
            var ipAddress = context.Request.HttpContext.Connection.RemoteIpAddress.ToString();
            var rateLimits = new Dictionary<string, int> { { "updatesPerMinute", 5 } };

            if (rateLimits.TryGetValue(ipAddress, out var count))
            {
                await Task.Delay(TimeSpan.FromMinutes(1));
                rateLimits[ipAddress] = count + 1;
            }
        }

