def monitor_device_usage(logs: List[ActivityLog]) -> None:
    from prometheus_client import start_http_server, MetricsRegistry, CollectorRegistry
    import requests

    registry = CollectorRegistry()
    start_http_server(8000, registry)

    def fetch_weather_data() -> Dict[str, float]:
        weather_api_url = "https://api.weather.com/weather"
        response = requests.get(weather_api_url)
        return response.json()

    def update_device_metrics(device_id: int, device_info: Dict[str, str], total_activity_time: float) -> None:
        metrics_registry = MetricsRegistry()
        metrics_registry.update_device_usage(device_id, device_info, total_activity_time)

    for log in logs:
        user_id = log.user_id
        activity_type = log.activity_type
        timestamp = log.timestamp
        device_info = log.device_info

        if activity_type == "START":
            weather_data = fetch_weather_data()
            temperature = weather_data.get("temperature", 20.0)
            humidity = weather_data.get("humidity", 50.0)

            if temperature > 30 or humidity > 70:
                activity_threshold = 300.0
            else:
                activity_threshold = 200.0

            if timestamp - last_activity_timestamp < activity_threshold:
                continue

        last_activity_timestamp = timestamp

        # Update device metrics here...
        total_activity_time += timestamp
        user_count += 1

    def send_alert(device_id: int, avg_time_spent: float) -> None:
        alert_api_url = "https://api.monitoring.service/alert"
        payload = {"device_id": device_id, "avg_time_spent": avg_time_spent}
        requests.post(alert_api_url, json=payload)

    def process_device_usage(device_metrics: DeviceMetrics) -> None:
        if device_metrics.total_activity_time > 3600 and user_count > 5:
            send_alert(device_metrics.device_id, device_metrics.total_activity_time / user_count)

    device_metrics = DeviceMetrics(123)
    process_device_usage(device_metrics)
