#include <dirent.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the maximum number of threads
#define MAX_THREADS 16

// Define the structure for thread data
typedef struct {
    pthread_t thread_id;
    char *input_dir;
    char *output_dir;
    size_t max_pages_per_pdf;
    int output_resolution;
} ThreadData;

int batchConvertImagesToPdf(const char *inputDir, const char *outputDir, size_t maxPagesPerPdf, int outputResolution, size_t numThreads, int timeoutSecs, const char *configFile, const char *excludeListFile, const char *metadataFile) {
    // Initialize the return code
    int retCode = 0;

    // Check if the input directory exists
    if (!access(inputDir, F_OK)) {
        DIR *dir;
        struct dirent *ent;
        dir = opendir(inputDir);
        if (dir != NULL) {
            while ((ent = readdir(dir)) != NULL) {
                char filePath[PATH_MAX];
                sprintf(filePath, "%s/%s", inputDir, ent->d_name);

                // Check the file type
                size_t len = strlen(ent->d_name);
                if (len > 4 && strcmp(&ent->d_name[len - 4], ".jpg") == 0 || strcmp(&ent->d_name[len - 4], ".png") == 0) {
                    // Create a new thread for each file
                    ThreadData *threadData = (ThreadData *)malloc(sizeof(ThreadData));
                    threadData->input_dir = inputDir;
                    threadData->output_dir = outputDir;
                    threadData->max_pages_per_pdf = maxPagesPerPdf;
                    threadData->output_resolution = outputResolution;

                    pthread_create(&threadData->thread_id, NULL, convertFileToPdf, threadData);

                    // Add the thread to the pool
                    pthreadpool_add_thread();
                }
            }
            closedir(dir);
        } else {
            retCode = 1;
        }
    } else {
        retCode = 1;
    }

    return retCode;
}

void *convertFileToPdf(void *data) {
    ThreadData *threadData = (ThreadData *)data;

    // Convert the file to PDF
    system("third-party-tool -input-file path -output-file path -max-pages-per-pdf size -output-resolution resolution");

    return NULL;
}
