#include <openssl/evp.h>
#include <openssl/des.h>

EVP_CIPHER_CTX* des_cipher(EVP_Cipher_Method method) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    switch (method) {
        case EVP_Cipher_METHOD_ecb:
            EVP_EncryptInit_ex(ctx, EVP_des_ecb(), NULL, NULL, NULL);
            break;
        case EVP_Cipher_METHOD_ede:
            EVP_EncryptInit_ex(ctx, EVP_des_ede_cbc(), NULL, NULL, NULL);
            break;
        case EVP_Cipher_METHOD_ede3:
            EVP_EncryptInit_ex(ctx, EVP_des_ede3_cbc(), NULL, NULL, NULL);
            break;
        case EVP_Cipher_METHOD_cfb64:
            EVP_EncryptInit_ex(ctx, EVP_des_cfb64(), NULL, NULL, NULL);
            break;
    }
    return ctx;
}
