And here is the Python script that calculates the SHA-256 hash of a file:

```python
import os
import hashlib

def calculate_sha256_hash(file_path):
    sha256_hash = hashlib.sha256()

    if not os.path.exists(file_path):
        return "Error: File does not exist"

    with open(file_path, 'rb') as file:
        while True:
            chunk = file.read(4096)
            if not chunk:
                break
            sha256_hash.update(chunk)

    checksum = sha256_hash.hexdigest()
    return checksum

def verify_sha256_hash(file_path, checksum):
    calculated_checksum = calculate_sha256_hash(file_path)
    if calculated_checksum == checksum:
        return "Checksum verified successfully"
    else:
        return "Checksum mismatch: " + calculated_checksum
