const { load } = require('module');
const { resolve } = require('path');
const { readFileSync } = require('fs');

let moduleQueue = [];
let loadedModules = {};

function loadModule(moduleName) {
  if (!loadedModules[moduleName]) {
    try {
      const modulePath = resolve(__dirname, moduleName);
      const moduleCode = readFileSync(modulePath, 'utf8');
      const { exports } = load(moduleCode, modulePath);
      loadedModules[moduleName] = exports;
      moduleQueue.push(moduleName);
    } catch (error) {
      console.error(`Failed to load module ${moduleName}: ${error}`);
    }
  }
}

