loadModule('module2');
loadModule('module3');

// Execute loaded modules in sequence
moduleQueue.forEach((moduleName) => {
  if (loadedModules[moduleName]) {
    try {
      loadedModules[moduleName].init();
    } catch (error) {
      console.error(`Failed to execute module ${moduleName}: ${error}`);
