import java.io.ByteArrayInputStream;
import java.io.ObjectInputStream;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;

public class SerializationHelper {
    private static final Logger LOGGER = LoggerFactory.getLogger(SerializationHelper.class);
    private static final BlockingQueue<PutObjectRequest> requestQueue =
            new LinkedBlockingQueue<>();

    public static Object deserialize(byte[] byteData) throws Exception {
        ByteArrayInputStream bais = new ByteArrayInputStream(byteData);
        ObjectInputStream ois;
        try {
            ois = new ObjectInputStream(bais);
            Object deserializedObject = ois.readObject();
            // Handle the object here
            return deserializedObject;
        } catch (ClassNotFoundException e) {
            throw new RuntimeException("Failed to deserialize due to missing class",
                    e);
        } catch (IOException e) {
            throw new RuntimeException("Failed to deserialize due to malformed input",
                    e);
        }
    }

    private static void uploadData(Object deserializedObject) throws Exception {
        // Use a connection pool for uploading data
        ConnectionPool connectionPool = new ConnectionPool(requestQueue);
        PutObjectRequest putObjectRequest = new PutObjectRequest();
        // Handle the object here and create a request to be uploaded
        connectionPool.execute(putObjectRequest);
    }

    private static void logDeserializationEvent(String message) {
        LOGGER.info(message);
    }
}
