import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.File;
import java.io.FileReader;
import java.io.FileWriter;
import java.io.IOException;
import java.util.HashMap;
import java.util.Map;

public class Main {

    public static Map<String, String> safeCommandExecutor(String command, File workingDir) {
        Map<String, String> result = new HashMap<>();

        // Check if the target file exists and delete it if necessary
        File outputTempFile = new File("output.txt");
        if (outputTempFile.exists()) {
            try {
                FileReader fileReader = new FileReader(outputTempFile);
                BufferedReader reader = new BufferedReader(fileReader);
                String line;
                StringBuilder originalOutput = new StringBuilder();
                while ((line = reader.readLine()) != null) {
                    originalOutput.append(line).append("\n");
                }
                fileReader.close();
                outputTempFile.delete();
            } catch (IOException e) {
                // handle exception
            }
        }

        try (
            Process process = Runtime.getRuntime().exec(command.split(" "), new String[0], workingDir);
            BufferedReader stdout = new BufferedReader(new InputStreamReader(process.getInputStream()));
            BufferedReader stderr = new BufferedReader(new InputStreamReader(process.getErrorStream()))
        ) {

            // Execute the command
            StringBuilder output = new StringBuilder();
            String line;
            while ((line = stdout.readLine()) != null) {
                output.append(line).append("\n");
            }
            stdout.close();

            StringBuilder error = new StringBuilder();
            while ((line = stderr.readLine()) != null) {
                error.append(line).append("\n");
            }
            stderr.close();

            // Log the execution process
            System.out.println("Command executed: " + command);
            System.out.println("Standard output:\n" + output.toString());
            System.out.println("Standard error:\n" + error.toString());

            result.put("output", output.toString());
            result.put("error", error.toString());
        } catch (IOException e) {
            // handle exception
        }

        return result;
    }

}

