#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_INTS 1000000
#define SEM_NAME "my_semaphore"

int ints[MAX_INTS];
sem_t *sem;

void* read_ints(void* arg) {
    int i = *((int*)arg);
    while (1) {
        sem_wait(sem);
        // Read and process the integer here
        printf("%d\n", ints[i]);
        sem_post(sem);
        i++;
    }
}

int main() {
    pthread_t threads[10];
    int num_threads = 5;
    int chunk_size = MAX_INTS / num_threads;

    sem = sem_open(SEM_NAME, O_CREAT | O_RDWR, S_IRUSR | S_IWUSR, 1);

    for (int i = 0; i < num_threads; i++) {
        pthread_create(&threads[i], NULL, read_ints, &i);
    }

    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    sem_close(sem);
    sem_unlink(SEM_NAME);

    return 0;
}
